(window.CLAVE_TODO=window.CLAVE_TODO||{})[8]=[{"a":"Artículo 35 ✱","q":[{"i":"8-262","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Demarcación judicial. La demarcación judicial, que determinará la circunscripción territorial de los órganos judiciales, se establecerá:","o":["Por real decreto o, en los casos expresamente contemplados en esta norma, por ley, conforme al procedimiento que reglamentariamente se establezca.","Por ley orgánica en todo caso, a propuesta del Consejo General del Poder Judicial.","Por acuerdo del Consejo General del Poder Judicial, previo informe del Gobierno.","Por ley o, en los casos expresamente contemplados en esta norma, por real decreto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por ley o, en los casos expresamente contemplados en esta norma, por real decreto</mark></span>El <span class=\"ref-norma\">art. 35.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. La demarcación judicial, que determinará la circunscripción territorial de los órganos judiciales, se establecerá por ley o, en los casos expresamente contemplados en esta norma, por real decreto.\"</span>"},{"i":"8-ia-8182","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Demarcación judicial. La demarcación judicial, que determinará la circunscripción territorial de los órganos judiciales, se establecerá por ley o, en los casos expresamente contemplados en esta norma:","o":["por orden ministerial.","por real decreto.","por acuerdo del Consejo General del Poder Judicial.","por decreto de la comunidad autónoma."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por real decreto</mark></span>El <span class=\"ref-norma\">art. 35.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se establecerá por ley o, en los casos expresamente contemplados en esta norma, por real decreto\"</span>. La alternativa a la ley es el real decreto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-45","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sobre la Demarcación Judicial. El Ministerio de Justicia, vistas las propuestas de las Comunidades Autónomas, redactará la correspondiente disposición normativa, que será informada por el Consejo General del Poder Judicial:","o":["En el plazo de cuatro meses.","En el plazo de seis meses.","En el plazo de dos meses.","En el plazo de un mes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En el plazo de dos meses</mark></span>Son dos meses, no un mes. Según el <span class=\"ref-norma\">art. 35.3 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"El Ministerio de Justicia, vistas las propuestas de las Comunidades Autónomas, redactará la correspondiente disposición normativa, que será informada por el Consejo General del Poder Judicial en el plazo de dos meses\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8183","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Demarcación judicial. En el procedimiento de elaboración de la demarcación judicial, el Ministerio de Justicia, vistas las propuestas de las Comunidades Autónomas, redactará la correspondiente disposición normativa, que será informada por el Consejo General del Poder Judicial:","o":["en el plazo de dos meses.","en el plazo de un mes.","en el plazo de tres meses.","en el plazo de quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en el plazo de dos meses</mark></span>El <span class=\"ref-norma\">art. 35.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"que será informada por el Consejo General del Poder Judicial en el plazo de dos meses\"</span>. El plazo legal es de dos meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-152","p":"(LOPJ) El mandato de los Vocales del Consejo General del Poder Judicial tiene una duración de:","o":["4 años.","5 años.","6 años.","10 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">5 años.</mark></span><span class=\"ref-norma\">Art. 568.1 · Del Consejo General del Poder Judicial</span>. El artículo 568.1 de la LOPJ establece que el Consejo General del Poder Judicial se renovará en su totalidad cada cinco años."},{"i":"8-ia-8184","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Demarcación judicial. La demarcación judicial será revisada cada cinco años o antes si las circunstancias lo aconsejan:","o":["mediante real decreto a propuesta de las Comunidades Autónomas, en los términos que establezca la ley orgánica.","mediante acuerdo del Consejo General del Poder Judicial.","mediante orden del Ministerio de Justicia.","mediante ley elaborada conforme al procedimiento anteriormente establecido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">mediante ley elaborada conforme al procedimiento anteriormente establecido</mark></span>El <span class=\"ref-norma\">art. 35.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La demarcación judicial será revisada cada cinco años o antes si las circunstancias lo aconsejan, mediante ley elaborada conforme al procedimiento anteriormente establecido\"</span>. La revisión se hace por ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-278","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales de Instancia. Con carácter general, en los Tribunales de Instancia, las Secciones Civiles o las Civiles y de Instrucción que constituyan una Sección Única extenderán su jurisdicción a:","o":["Una provincia.","Dos o más partidos judiciales de la misma provincia.","Una Comunidad Autónoma.","Un partido judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un partido judicial</mark></span>El <span class=\"ref-norma\">art. 85 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Con carácter general, en los Tribunales de Instancia, las Secciones Civiles o las Civiles y de Instrucción que constituyan una Sección Única extenderán su jurisdicción a un partido judicial.\"</span>"},{"i":"8-ia-8185","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Capitalidad de los partidos judiciales. La capitalidad de los partidos judiciales la determinarán las Comunidades Autónomas:","o":["por decreto, previo informe del Consejo General del Poder Judicial.","por ley, previo informe del Ministerio de Justicia.","por ley, previo informe del Consejo General del Poder Judicial.","por acuerdo con el Gobierno de la Nación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por ley, previo informe del Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 35.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las Comunidades Autónomas, previo informe del Consejo General del Poder Judicial, determinarán, por ley, la capitalidad de los partidos judiciales\"</span>. Por ley y previo informe del CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8604","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección Civil. Con carácter general, en los Tribunales de Instancia, las Secciones Civiles o las Civiles y de Instrucción que constituyan una Sección Única extenderán su jurisdicción:","o":["a toda la provincia.","a un partido judicial.","a varios partidos judiciales limítrofes.","a la comunidad autónoma."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a un partido judicial</mark></span>El <span class=\"ref-norma\">art. 85 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Con carácter general, en los Tribunales de Instancia, las Secciones Civiles o las Civiles y de Instrucción que constituyan una Sección Única extenderán su jurisdicción a un partido judicial\"</span>. Jurisdicción de un partido judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 51","q":[{"i":"8-210","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién resolverá las cuestiones de competencia entre Juzgados y Tribunales de un mismo orden jurisdiccional?","o":["El Tribunal Supremo.","La Sala de Gobierno del Tribunal Supremo.","El órgano inmediato superior común.","El Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El órgano inmediato superior común</mark></span>Según el <span class=\"ref-norma\">art. 51 de la LOPJ</span>: <span class=\"ref-concepto\">\"Las cuestiones de competencia entre Juzgados y Tribunales de un mismo orden jurisdiccional se resolverán por el órgano inmediato superior común\"</span> (verificado con el texto del temario oficial)."},{"i":"8-ia-8200","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuestiones de competencia. Las cuestiones de competencia entre Juzgados y Tribunales de un mismo orden jurisdiccional se resolverán:","o":["por la Sala de Conflictos del Tribunal Supremo, conforme a esta ley.","por el Consejo General del Poder Judicial, a propuesta del Ministerio Fiscal.","por el Tribunal de superior categoría del orden jurisdiccional correspondiente, conforme al procedimiento que establezcan las leyes procesales.","por el órgano inmediato superior común, conforme a las normas establecidas en las leyes procesales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por el órgano inmediato superior común, conforme a las normas establecidas en las leyes procesales</mark></span>El <span class=\"ref-norma\">art. 51.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se resolverán por el órgano inmediato superior común, conforme a las normas establecidas en las leyes procesales\"</span>. Las cuestiones de competencia las resuelve el órgano inmediato superior común. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 55 ✱","q":[{"i":"8-13","p":". Ley Orgánica 6/1985, del Poder Judicial. De los Tribunales Superiores de Justicia. El Tribunal Superior de Justicia estará integrado por alguna/s de las siguientes Salas:","o":["De lo Civil y Penal.","De lo Contencioso-administrativo.","De lo Social.","Todas las opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas</mark></span>Según el <span class=\"ref-norma\">art. 72 de la LOPJ</span>: <span class=\"ref-concepto\">\"El Tribunal Superior de Justicia estará integrado por las siguientes Salas: de lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social\"</span> (verificado con el texto del temario oficial)."},{"i":"8-42","p":"Ley Orgánica 6/1985 del Poder Judicial. La Sala de la Audiencia Nacional que conocerá de los recursos de apelación que establezca la ley contra las resoluciones de la Sala de lo Penal, será la:","o":["De lo Civil.","De lo Penal.","De lo Contencioso-Administrativo.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas</mark></span>Es la Sala de Apelación, que no está entre las tres opciones. Según el <span class=\"ref-norma\">art. 64 bis de la LOPJ</span>: <span class=\"ref-concepto\">\"La Sala de Apelación de la Audiencia Nacional conocerá de los recursos de esta clase que establezca la ley contra las resoluciones de la Sala de lo Penal\"</span> (verificado con el texto del temario oficial)."},{"i":"8-61","p":"Ley Orgánica 6/1985, del Poder Judicial. El Tribunal Supremo estará integrado por las siguientes Salas: Señale la opción incorrecta.","o":["Primera, de lo Civil.","Segunda, de lo Penal.","Tercera, de lo Contencioso-administrativo.","Cuarta, de lo Militar."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuarta, de lo Militar</mark></span>La Sala Cuarta es la de lo Social; la de lo Militar es la Quinta. Según el <span class=\"ref-norma\">art. 55 de la LOPJ</span>: <span class=\"ref-concepto\">\"El Tribunal Supremo estará integrado por las siguientes Salas: Primera: De lo Civil. Segunda: De lo Penal. Tercera: De lo Contencioso-Administrativo. Cuarta: De lo Social. Quinta: De lo Militar\"</span> (verificado con el texto del temario oficial)."},{"i":"8-62","p":"Ley Orgánica 6/1985, del Poder Judicial. El Tribunal Supremo estará integrado por las siguientes Salas:","o":["De lo Civil, de lo Penal, Mercantil, Social y Militar.","De lo Civil, de lo Penal, Contencioso-administrativo, Mercantil y Militar.","De lo Civil, Penal, Contencioso-administrativo, Social y Militar.","De lo Civil, Penal, Contencioso-administrativo, Mercantil y de lo Militar."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De lo Civil, Penal, Contencioso-administrativo, Social y Militar</mark></span>Según el <span class=\"ref-norma\">art. 55 de la LOPJ</span>: <span class=\"ref-concepto\">\"El Tribunal Supremo estará integrado por las siguientes Salas: Primera: De lo Civil. Segunda: De lo Penal. Tercera: De lo Contencioso-Administrativo. Cuarta: De lo Social. Quinta: De lo Militar\"</span> (verificado con el texto del temario oficial)."},{"i":"8-101","p":"¿Cuál de las siguientes es una de las Salas en las que se estructura el Tribunal Supremo, conforme a la LOPJ?","o":["Sala de lo Civil y Mercantil.","Sala de lo Social.","Sala de lo Marítimo.","Sala de la Propiedad Intelectual."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sala de lo Social</mark></span>Se corrige la opción C (la Sala de lo Militar también es una Sala del TS). Según el <span class=\"ref-norma\">art. 55 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Cuarta: De lo Social. Quinta: De lo Militar\"</span> (verificado con el texto del temario)."},{"i":"8-120","p":"Ley Orgánica 6/1985 del Poder Judicial. La Sala Cuarta del Tribunal Supremo será la correspondiente a:","o":["Lo penal.","Lo Civil.","Lo Contencioso-administrativo.","Ninguna es correcta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ninguna es correcta</mark></span>La Sala Cuarta es la de lo Social. Según el <span class=\"ref-norma\">art. 55 de la LOPJ</span>: <span class=\"ref-concepto\">\"El Tribunal Supremo estará integrado por las siguientes Salas: Primera: De lo Civil. Segunda: De lo Penal. Tercera: De lo Contencioso-Administrativo. Cuarta: De lo Social. Quinta: De lo Militar\"</span> (verificado con el texto del temario oficial)."},{"i":"8-130","p":"Ley Orgánica 6/1985 del Poder Judicial. La Audiencia Nacional estará integrada por las siguientes Salas:","o":["De lo Contencioso-Administrativo.","De Apelación.","De lo Social.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 64 · De la Organización y Planta de Juzgados y Tribunales</span>. La Audiencia Nacional está integrada por las Salas de Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social (art. 64 LOPJ)."},{"i":"8-136","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La Audiencia Nacional estará integrada por las siguientes Salas:","o":["De lo Contencioso-Administrativo.","De Apelación.","De lo Social.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 64 · De la Organización y Planta de Juzgados y Tribunales</span>. Esta pregunta es idéntica a la pregunta 12. La Audiencia Nacional está integrada por las Salas de Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social (art. 64 LOPJ)."},{"i":"8-144","p":"(LOPJ) El Presidente de la Audiencia Nacional es el Presidente nato de:","o":["La Sala de lo Penal y la Sala de lo Contencioso-administrativo.","La Sala de lo Contencioso-administrativo y la Sala de lo Social.","Todas sus Salas.","Solo de la Sala de Apelación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Todas sus Salas.</mark></span><span class=\"ref-norma\">Art. 63.2 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 63.2 de la LOPJ establece que el Presidente de la Audiencia Nacional &quot;es el Presidente nato de todas sus Salas.&quot;"},{"i":"8-263","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Supremo. El Tribunal Supremo estará integrado por las siguientes Salas:","o":["Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Mercantil.","Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Social; Cuarta, de lo Contencioso-Administrativo; y Quinta, de lo Militar.","Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Militar.","Primera, de lo Penal; Segunda, de lo Civil; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Militar."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y Quinta, de lo Militar</mark></span>El <span class=\"ref-norma\">art. 55 (encabezamiento) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Supremo estará integrado por las siguientes Salas: Primera: De lo Civil. Segunda: De lo Penal. Tercera: De lo Contencioso-Administrativo. Cuarta: De lo Social. Quinta: De lo Militar\"</span>"},{"i":"8-271","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Superior de Justicia. El Tribunal Superior de Justicia estará integrado por las siguientes Salas:","o":["De lo Civil, de lo Penal y de lo Contencioso-Administrativo.","De lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social.","De lo Civil y Penal, de lo Contencioso-Administrativo, de lo Social y de Apelación.","De lo Civil y Penal, de lo Contencioso-Administrativo y de lo Mercantil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social</mark></span>El <span class=\"ref-norma\">art. 72.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. El Tribunal Superior de Justicia estará integrado por las siguientes Salas: de lo Civil y Penal, de lo Contencioso-Administrativo y de lo Social.\"</span>"},{"i":"8-298","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencia Nacional. La Audiencia Nacional estará integrada por las siguientes Salas:","o":["De Apelación, de lo Civil, de lo Penal y de lo Contencioso-Administrativo.","De lo Penal, de lo Contencioso-Administrativo, de lo Social y de lo Militar.","De Apelación, de lo Penal, de lo Social y de lo Mercantil.","De Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social</mark></span>El <span class=\"ref-norma\">art. 64.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Audiencia Nacional estará integrada por las siguientes Salas: De Apelación. De lo Penal. De lo Contencioso-Administrativo. De lo Social.\"</span>"},{"i":"8-ia-8304","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Salas del Tribunal Supremo. El Tribunal Supremo estará integrado por las siguientes Salas: Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-Administrativo; Cuarta, de lo Social; y:","o":["Quinta, de lo Mercantil, que se regirá por su legislación específica.","Quinta, de lo Militar, que se regirá por su legislación específica y supletoriamente por la presente Ley.","Quinta, de lo Militar, que se regirá exclusivamente por su legislación específica, salvo que la ley disponga otra cosa.","Quinta, de lo Marítimo, que se regirá por las leyes procesales comunes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Quinta, de lo Militar, que se regirá por su legislación específica y supletoriamente por la presente Ley</mark></span>El <span class=\"ref-norma\">art. 55 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Quinta: De lo Militar, que se regirá por su legislación específica y supletoriamente por la presente Ley y por el ordenamiento común a las demás Salas del Tribunal Supremo\"</span>. La Sala Quinta se rige por su legislación específica y supletoriamente por la LOPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8335","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Salas de la Audiencia Nacional. La Audiencia Nacional estará integrada por las siguientes Salas:","o":["De lo Civil, de lo Penal, de lo Contencioso-Administrativo y de lo Social.","De Apelación, de lo Penal, de lo Contencioso-Administrativo, de lo Social y de lo Militar.","De Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social.","De lo Penal, de lo Contencioso-Administrativo, de lo Social y de lo Mercantil."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social</mark></span>El <span class=\"ref-norma\">art. 64 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Audiencia Nacional estará integrada por las siguientes Salas: De Apelación. De lo Penal. De lo Contencioso-Administrativo. De lo Social\"</span>. No tiene Sala de lo Civil ni de lo Militar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 61 · SALA Y SECCIÓN DE LO CONTENCIOSO-ADMINISTRATIVO DEL TRIBUNAL SUPREMO","q":[{"i":"8-ia-9134","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Gabinete Técnico. La Sala de Gobierno, a propuesta del Presidente del Tribunal Supremo, aprobará:","o":["el presupuesto del Tribunal Supremo.","las normas de funcionamiento del Gabinete Técnico.","el nombramiento de los Presidentes de Sala, conforme al procedimiento que reglamentariamente se establezca.","la plantilla de Magistrados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las normas de funcionamiento del Gabinete Técnico</mark></span>El <span class=\"ref-norma\">art. 61 sexies de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Sala de Gobierno, a propuesta del Presidente del Tribunal Supremo, aprobará las normas de funcionamiento del Gabinete Técnico.\"</span> Normas del Gabinete Técnico."}]},{"a":"ART. 87 LOPJ · SECCIÓN DE LO MERCANTIL · MATERIAS","q":[{"i":"8-3","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 87.10. Se denominará Tribunal de Marca de la Unión Europea, en lo que respecta a los litigios sobre marcas, dibujos y modelos comunitarios, a:","o":["La Sección de lo Mercantil del Tribunal de Instancia de Alicante.","La Sección de lo Mercantil del Tribunal de Instancia de Valencia.","La Sección de lo Mercantil del Tribunal de Instancia de Albacete.","La Sección de lo Mercantil del Tribunal de Instancia de Castellón."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sección de lo Mercantil del Tribunal de Instancia de Alicante</mark></span>Tras la reforma ya no son «Juzgados de lo Mercantil»: es la Sección de lo Mercantil del Tribunal de Instancia de Alicante. Según el <span class=\"ref-norma\">art. 87.10 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"dicha Sección se denominará Tribunal de Marca de la Unión Europea\"</span> (verificado con el texto del temario)."},{"i":"8-91","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Qué organismo conocerá de la determinación del carácter necesario de un bien o derecho para la continuidad de la actividad profesional o empresarial del deudor?","o":["Secciones de lo Penal.","Secciones de lo Mercantil.","Secciones de lo Social.","Secciones Civiles y de Instrucción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Secciones de lo Mercantil</mark></span>Lo conoce el juez del concurso, de la Sección de lo Mercantil. Según el <span class=\"ref-norma\">art. 87.7.a.3.ª de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"3.ª La determinación del carácter necesario de un bien o derecho para la continuidad de la actividad profesional o empresarial de la persona deudora\"</span> (verificado con el texto del temario)."}]},{"a":"ART. 87 LOPJ (cont.) · JURISDICCIÓN EXCLUSIVA Y EXCLUYENTE en materia de concurso de acreedores/as","q":[{"i":"8-ia-8619","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, existirá una Sección de lo Mercantil:","o":["con jurisdicción en el partido judicial de la capital.","con jurisdicción en toda la comunidad autónoma.","con jurisdicción en toda la provincia y sede en su capital.","con jurisdicción en la provincia y sede en la ciudad más poblada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con jurisdicción en toda la provincia y sede en su capital</mark></span>El <span class=\"ref-norma\">art. 87.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, existirá una Sección de lo Mercantil con jurisdicción en toda la provincia y sede en su capital\"</span>. Una por provincia, con sede en la capital. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8620","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. En aquellas provincias donde, por razón de la carga de trabajo, no se constituya una Sección de lo Mercantil, el conocimiento de los asuntos mercantiles corresponderá:","o":["a la Audiencia Provincial de la provincia.","a uno de los jueces o a una de las juezas de la Sección Civil, o Civil y de Instrucción que constituya una Sección Única en el Tribunal de Instancia de la capital de provincia.","a la Sección de lo Mercantil de la comunidad autónoma, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes.","a la Sección Civil de cada partido judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a uno de los jueces o a una de las juezas de la Sección Civil, o Civil y de Instrucción que constituya una Sección Única en el Tribunal de Instancia de la capital de provincia</mark></span>El <span class=\"ref-norma\">art. 87.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"corresponderá a uno de los jueces o a una de las juezas de la Sección Civil, o Civil y de Instrucción que constituya una Sección Única en el Tribunal de Instancia de la capital de provincia\"</span>. A un juez de la Sección Civil de la capital de provincia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8621","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. Por excepción, cuando una provincia tenga una población inferior a 500.000 habitantes, el Gobierno por real decreto podrá extender a esa provincia:","o":["la jurisdicción de la Sección de lo Mercantil de otra provincia limítrofe perteneciente a la misma comunidad autónoma.","la jurisdicción de la Sección de lo Mercantil de la capital de la comunidad, en los términos que establezca la ley orgánica.","la jurisdicción de la Audiencia Provincial más próxima.","la competencia de la Audiencia Nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la jurisdicción de la Sección de lo Mercantil de otra provincia limítrofe perteneciente a la misma comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 87.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrá extender a esa provincia la jurisdicción de la Sección de lo Mercantil de otra provincia limítrofe perteneciente a la misma comunidad autónoma\"</span>. Provincia limítrofe de la misma comunidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8622","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. El umbral de población para que el Gobierno pueda extender a una provincia la jurisdicción de la Sección de lo Mercantil de otra limítrofe, por real decreto a propuesta del Consejo General del Poder Judicial con informe favorable previo de la comunidad autónoma, es de:","o":["menos de 250.000 habitantes.","menos de un millón de habitantes.","menos de 100.000 habitantes.","menos de 500.000 habitantes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">menos de 500.000 habitantes</mark></span>El <span class=\"ref-norma\">art. 87.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando una provincia tenga una población inferior a los 500.000 habitantes\"</span>. 500.000 habitantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8623","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. Cuando un partido judicial cuente con más de 250.000 habitantes y, perteneciendo a la misma provincia, no sea limítrofe con el de su capital, el Gobierno podrá:","o":["crear una Audiencia Provincial desplazada en ese partido judicial, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes.","crear una Sección de lo Penal con jurisdicción provincial.","crear una Sección de lo Mercantil en el Tribunal de Instancia de aquel partido judicial con jurisdicción en él y en aquellos otros partidos judiciales limítrofes que se considere oportuno.","trasladar la capital de la provincia a ese partido."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">crear una Sección de lo Mercantil en el Tribunal de Instancia de aquel partido judicial con jurisdicción en él y en aquellos otros partidos judiciales limítrofes que se considere oportuno</mark></span>El <span class=\"ref-norma\">art. 87.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrá crear una Sección de lo Mercantil en el Tribunal de Instancia de aquel partido judicial con jurisdicción en él y en aquellos otros partidos judiciales limítrofes que se considere oportuno\"</span>. Se trata de una Sección de lo Mercantil con jurisdicción en ese partido y limítrofes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8624","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. En aquellas capitales de provincia en las que exista más de un juez en la Sección de lo Mercantil y menos de cinco, las solicitudes de declaración de concurso de acreedores de persona natural se repartirán:","o":["a dos de ellos, por turno.","a uno solo de ellos.","a todos ellos de forma rotatoria.","al de mayor antigüedad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a uno solo de ellos</mark></span>El <span class=\"ref-norma\">art. 87.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"las solicitudes de declaración de concurso de acreedores de persona natural se repartirán a uno solo de ellos\"</span>. Si hay más de cinco, se reparten a dos o más igualmente determinados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8625","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. Las Secciones de lo Mercantil conocerán de cuantas cuestiones sean de la competencia del orden jurisdiccional civil en materia de propiedad intelectual e industrial; competencia desleal y publicidad; sociedades mercantiles, sociedades cooperativas, agrupaciones de interés económico; transporte terrestre, nacional o internacional; y:","o":["derecho marítimo y derecho aéreo.","derecho de familia y sucesiones.","arrendamientos urbanos y propiedad horizontal.","derecho de consumidores y seguros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">derecho marítimo y derecho aéreo</mark></span>El <span class=\"ref-norma\">art. 87.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"transporte terrestre, nacional o internacional; derecho marítimo y derecho aéreo\"</span>. Incluye derecho marítimo y aéreo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8628","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. Las Secciones de lo Mercantil conocerán de los recursos directos contra las calificaciones negativas de los registradores y las registradoras mercantiles o, en su caso, contra las resoluciones expresas o presuntas de:","o":["la Dirección General de los Registros y del Notariado, conforme al procedimiento que establezcan las leyes procesales.","la Dirección General de Seguridad Jurídica y Fe Pública relativas a esas calificaciones.","el Consejo General del Notariado.","el Registro Mercantil Central."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Dirección General de Seguridad Jurídica y Fe Pública relativas a esas calificaciones</mark></span>El <span class=\"ref-norma\">art. 87.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"o, en su caso, contra las resoluciones expresas o presuntas de la Dirección General de Seguridad Jurídica y Fe Pública relativas a esas calificaciones\"</span>. La Dirección General de Seguridad Jurídica y Fe Pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8629","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil · concursos. Las Secciones de lo Mercantil conocerán, además, de cuantas cuestiones sean de la competencia del orden jurisdiccional civil en materia de concurso de acreedores, cualquiera que sea la condición civil o mercantil de la persona deudora, de los planes de reestructuración y del procedimiento especial para:","o":["microempresas.","pequeñas y medianas empresas.","autónomos y consumidores.","sociedades cooperativas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">microempresas</mark></span>El <span class=\"ref-norma\">art. 87.7 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"de los planes de reestructuración y del procedimiento especial para microempresas, en los términos establecidos por el texto refundido de la Ley Concursal\"</span>. Es el procedimiento especial para microempresas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8631","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción del juez del concurso. La jurisdicción del juez del concurso es exclusiva y excluyente respecto de la declaración de la existencia de sucesión de empresa a efectos laborales y de seguridad social en los casos de:","o":["cese de la actividad empresarial.","fusión o absorción de sociedades cotizadas, sin perjuicio de lo dispuesto en otras leyes.","transmisión de unidad o de unidades productivas.","despido colectivo ya ejecutado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">transmisión de unidad o de unidades productivas</mark></span>El <span class=\"ref-norma\">art. 87.7.a de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La declaración de la existencia de sucesión de empresa a efectos laborales y de seguridad social en los casos de transmisión de unidad o de unidades productivas\"</span>. Transmisión de unidades productivas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8632","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción del juez del concurso. Cuando el deudor o la deudora sea persona natural, la jurisdicción del juez del concurso será también exclusiva y excluyente respecto de la disolución y liquidación:","o":["de la herencia yacente de la persona concursada.","de la sociedad o comunidad conyugal de la persona concursada.","de las sociedades mercantiles en las que participe, en los términos que establezca la ley orgánica.","de la unión de hecho de la persona concursada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de la sociedad o comunidad conyugal de la persona concursada</mark></span>El <span class=\"ref-norma\">art. 87.7.b de LOPJ</span> dispone: <span class=\"ref-concepto\">\"2.ª La disolución y liquidación de la sociedad o comunidad conyugal de la persona concursada\"</span>. Disolución y liquidación de la sociedad o comunidad conyugal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8633","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción del juez del concurso. Cuando el deudor sea persona jurídica, la jurisdicción del juez del concurso será exclusiva y excluyente respecto de las acciones de responsabilidad contra los auditores y auditoras por los daños y perjuicios causados:","o":["antes o después de la declaración judicial de concurso, a la persona jurídica concursada.","únicamente antes de la declaración judicial de concurso.","únicamente después de la declaración judicial de concurso, salvo que la ley disponga otra cosa.","a los acreedores de la persona jurídica concursada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">antes o después de la declaración judicial de concurso, a la persona jurídica concursada</mark></span>El <span class=\"ref-norma\">art. 87.7.c de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las acciones de responsabilidad contra los auditores y auditoras por los daños y perjuicios causados, antes o después de la declaración judicial de concurso, a la persona jurídica concursada\"</span>. Antes o después de la declaración de concurso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8636","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. Las Secciones de lo Mercantil serán competentes para el reconocimiento y ejecución de sentencias y demás resoluciones judiciales extranjeras cuando éstas versen sobre cualquiera de las materias a que se refiere este artículo, salvo que:","o":["el demandado sea persona física.","según los tratados y otras normas internacionales, el conocimiento de esa materia corresponda a otro órgano judicial.","el procedimiento extranjero no haya sido contradictorio.","la resolución proceda de un Estado no miembro de la Unión Europea, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">según los tratados y otras normas internacionales, el conocimiento de esa materia corresponda a otro órgano judicial</mark></span>El <span class=\"ref-norma\">art. 87.8 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"salvo que, según los tratados y otras normas internacionales, el conocimiento de esa materia corresponda a otro órgano judicial\"</span>. Salvo atribución a otro órgano por tratados y normas internacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8637","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Mercantil. Las Secciones de lo Mercantil tendrán competencia exclusiva para conocer en primera instancia de los recursos contra las resoluciones dictadas por la Sección Primera de la Comisión de:","o":["Propiedad Intelectual.","Defensa de la Competencia.","Mercado de Valores.","Telecomunicaciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Propiedad Intelectual</mark></span>El <span class=\"ref-norma\">art. 87.9 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"de los recursos contra las resoluciones dictadas por la Sección Primera de la Comisión de Propiedad Intelectual\"</span>. Es la Comisión de Propiedad Intelectual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8638","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal de Marca de la Unión Europea. La Sección de lo Mercantil del Tribunal de Instancia de Alicante tendrá competencia exclusiva para conocer en primera instancia, con jurisdicción en todo el territorio nacional, de las acciones que se ejerciten al amparo del Reglamento (UE) 2017/1001 sobre la marca de la Unión Europea y del Reglamento (CE) n.º 6/2002 sobre:","o":["las patentes europeas.","las denominaciones de origen protegidas.","los derechos de obtentor de variedades vegetales.","los dibujos y modelos comunitarios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los dibujos y modelos comunitarios</mark></span>El <span class=\"ref-norma\">art. 87.10 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"del Reglamento (CE) n.º 6/2002, del Consejo, de 12 de diciembre de 2001, sobre los dibujos y modelos comunitarios\"</span>. El segundo Reglamento es sobre dibujos y modelos comunitarios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8639","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal de Marca de la Unión Europea. A los solos efectos de la competencia específica en materia de marca de la Unión Europea, la Sección de lo Mercantil de Alicante se denominará Tribunal de Marca de la Unión Europea y tendrá también competencia exclusiva para conocer de aquellas demandas civiles en las que se ejerciten acumuladas acciones relativas a:","o":["marcas de la Unión y a patentes nacionales.","marcas de la Unión y a nombres comerciales.","marcas de la Unión y a marcas nacionales o internacionales idénticas o similares.","marcas de la Unión y a denominaciones sociales, salvo que la ley disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">marcas de la Unión y a marcas nacionales o internacionales idénticas o similares</mark></span>El <span class=\"ref-norma\">art. 87.10 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"tendrá también competencia exclusiva para conocer de aquellas demandas civiles en las que se ejerciten acumuladas acciones relativas a marcas de la Unión y a marcas nacionales o internacionales idénticas o similares\"</span>. Marcas de la Unión y marcas nacionales o internacionales idénticas o similares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 88 LOPJ · SECCIONES DE INSTRUCCIÓN O SECCIONES ÚNICAS Tribunal de Instancia","q":[{"i":"8-6","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 88.1.g. La emisión y la ejecución de los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley, en el orden penal, corresponde, entre otros, a:","o":["El Tribunal Supremo, en todo caso.","Las Secciones de Instrucción y las Secciones Únicas de los Tribunales de Instancia, entre otros órganos.","La Audiencia Nacional, en todo caso.","Las Audiencias Provinciales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las Secciones de Instrucción y las Secciones Únicas de los Tribunales de Instancia, entre otros órganos</mark></span>Según el <span class=\"ref-norma\">art. 88 de la LOPJ</span>: <span class=\"ref-concepto\">\"De la emisión y la ejecución de los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley\"</span> (verificado con el texto del temario oficial)."},{"i":"8-14","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 88.1. Las Secciones de Instrucción de los Tribunales de Instancia conocerán, en el orden penal:","o":["De la instrucción de las causas por delito cuyo enjuiciamiento corresponda a las Audiencias Provinciales y a las Secciones de lo Penal de los Tribunales de Instancia, excepto de la instrucción de aquellas causas que sean competencia de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia.","Del conocimiento y fallo de los juicios por delito leve, salvo los que sean competencia de los jueces y juezas de paz o de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia.","De los procedimientos de habeas corpus.","Todas las opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas</mark></span>Según el <span class=\"ref-norma\">art. 88 de la LOPJ</span>: <span class=\"ref-concepto\">\"d) De los procedimientos de habeas corpus\"</span> (verificado con el texto del temario oficial)."},{"i":"8-34","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 88.1. Las Secciones de Instrucción de los Tribunales de Instancia conocerán, en el orden penal. Señale la incorrecta.","o":["De la instrucción de las causas por delito cuyo enjuiciamiento corresponda a las Audiencias Provinciales y a las Secciones de lo Penal de los Tribunales de Instancia, excepto de aquellas causas que sean competencia de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia.","De los procedimientos de “Habeas corpus”.","Dictar sentencia de conformidad con la acusación en todos los casos, aunque la ley no lo prevea.","De la emisión y ejecución de los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dictar sentencia de conformidad con la acusación en todos los casos, aunque la ley no lo prevea</mark></span>«En los casos establecidos por la ley», no en todos los casos. Según el <span class=\"ref-norma\">art. 88.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Les corresponde asimismo dictar sentencia de conformidad con la acusación en los casos establecidos por la ley y en los procesos por aceptación de decreto\"</span> (verificado con el texto del temario)."},{"i":"8-43","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 88.2. ¿Quién conocerá de la autorización del internamiento de extranjeros en los centros de internamiento? Señale la correcta.","o":["La Sección de Vigilancia Penitenciaria.","Las Secciones de Instrucción y las Secciones Únicas de los Tribunales de Instancia.","Los jueces y las juezas de paz.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las Secciones de Instrucción y las Secciones Únicas de los Tribunales de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 88.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"las Secciones de Instrucción y las Secciones Únicas conocerán de la autorización del internamiento de extranjeros en los centros de internamiento, así como del control de la estancia de éstos en los mismos y en las salas de inadmisión de fronteras\"</span> (verificado con el texto del temario)."},{"i":"8-116","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 88.1. ¿Cuál de las siguientes es una de las funciones de las Secciones de Instrucción de los Tribunales de Instancia?","o":["El enjuiciamiento en única instancia de los juicios sobre delitos leves, sin excepción.","El conocimiento de los recursos de apelación contra las sentencias de las Audiencias Provinciales.","El enjuiciamiento de los delitos castigados con pena privativa de libertad superior a cinco años.","Los procedimientos de habeas corpus."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los procedimientos de habeas corpus</mark></span>Según el <span class=\"ref-norma\">art. 88.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Estas Secciones conocerán, en el orden penal: [...] d) De los procedimientos de habeas corpus\"</span> (verificado con el texto del temario)."}]},{"a":"ART. 89 BIS LOPJ · SECCIÓN DE VIOLENCIA CONTRA LA INFANCIA Y LA ADOLESCENCIA","q":[{"i":"8-22","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 89.5.a. Las Secciones de Violencia sobre la Mujer conocerán, en el orden penal, siempre que se hubiesen cometido contra quien sea o haya sido su esposa:","o":["De la instrucción por delitos de homicidio.","De la instrucción por delitos de lesiones y lesiones al feto.","De la instrucción por delitos contra el honor.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>Según el <span class=\"ref-norma\">art. 89 de la LOPJ</span>: <span class=\"ref-concepto\">\"a) De la instrucción de los procesos para exigir responsabilidad penal por los delitos recogidos en los Títulos del Código Penal relativos a homicidio, aborto, lesiones, lesiones al feto, delitos contra la libertad, delitos contra la integridad moral, contra la libertad e indemnidad sexual, contra la intimidad y el derecho a la propia imagen, contra el honor o cualquier otro delito cometido con violencia o intimidación\"</span> (verificado con el texto del temario oficial)."},{"i":"8-70","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 89.6. Las Secciones de Violencia sobre la Mujer podrán conocer en el orden civil, en todo caso de conformidad con los procedimientos y recursos previstos en la Ley de Enjuiciamiento Civil, de los siguientes asuntos: Indique la INCORRECTA.","o":["Los que versen sobre maternidad, paternidad, filiación y adopción.","Los que tengan por objeto la adopción o modificación de medidas de trascendencia familiar.","Los relativos al matrimonio y a su régimen económico matrimonial.","De la instrucción de los procesos para exigir responsabilidad penal por cualquier delito contra los derechos y deberes familiares."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De la instrucción de los procesos para exigir responsabilidad penal por cualquier delito contra los derechos y deberes familiares</mark></span>Es una competencia penal, no civil. Según el <span class=\"ref-norma\">art. 89 de la LOPJ</span>: <span class=\"ref-concepto\">\"b) De la instrucción de los procesos para exigir responsabilidad penal por cualquier delito contra las relaciones familiares, cuando la víctima sea alguna de las personas señaladas en la letra anterior\"</span> (verificado con el texto del temario oficial)."},{"i":"8-145","p":"(LOPJ) En relación a la competencia civil de las Secciones de Violencia sobre la Mujer, señale la afirmación INCORRECTA:","o":["Los que versen sobre maternidad, paternidad, filiación y adopción.","Los relativos a las relaciones paternofiliales.","Los relativos al matrimonio y a su régimen económico matrimonial.","La instrucción de los procesos por delitos de homicidio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La instrucción de los procesos por delitos de homicidio</mark></span>La instrucción de delitos es competencia penal (art. 89.5), no civil. Según el <span class=\"ref-norma\">art. 89 de la LOPJ</span>: <span class=\"ref-concepto\">\"Las Secciones de Violencia sobre la Mujer podrán conocer en el orden civil, en todo caso de conformidad con los procedimientos y recursos previstos en la Ley 1/2000, de 7 de enero, de Enjuiciamiento Civil, de los siguientes asuntos: a) Los relativos al matrimonio y a su régimen económico matrimonial y los que tengan por objeto la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho. b) Los que versen exclusivamente sobre guarda y custodia de hijos e hijas menores o sobre alimentos reclamados por un progenitor contra el otro en nombre de los hijos e hijas menores. c) Los relativos a modificación de medidas adoptadas en los procesos que versen sobre las materias previstas en las letras anteriores. d) Los que versen sobre maternidad, paternidad, filiación y adopción\"</span> (verificado con el texto del temario oficial)."},{"i":"8-178","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Las Secciones de Violencia sobre la Mujer podrán conocer, entre otros, en el orden civil, en todo caso de conformidad con los procedimientos y recursos previstos en la Ley 1/2000, de 7 de enero, de Enjuiciamiento Civil, de los siguientes asuntos: señale la INCORRECTA.","o":["Los que tengan por objeto la adopción o modificación de medidas de trascendencia familiar.","Los que versen exclusivamente sobre guarda y custodia de hijos e hijas menores o sobre alimentos reclamados por un progenitor contra el otro en nombre de los hijos e hijas menores.","Los que versen sobre maternidad, paternidad, filiación y adopción.","La instrucción de los procesos para exigir responsabilidad penal por delitos de homicidio."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La instrucción de los procesos para exigir responsabilidad penal por delitos de homicidio</mark></span>La instrucción de delitos es competencia penal (art. 89.5), no civil. Según el <span class=\"ref-norma\">art. 89 de la LOPJ</span>: <span class=\"ref-concepto\">\"Las Secciones de Violencia sobre la Mujer podrán conocer en el orden civil, en todo caso de conformidad con los procedimientos y recursos previstos en la Ley 1/2000, de 7 de enero, de Enjuiciamiento Civil, de los siguientes asuntos: a) Los relativos al matrimonio y a su régimen económico matrimonial y los que tengan por objeto la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho. b) Los que versen exclusivamente sobre guarda y custodia de hijos e hijas menores o sobre alimentos reclamados por un progenitor contra el otro en nombre de los hijos e hijas menores. c) Los relativos a modificación de medidas adoptadas en los procesos que versen sobre las materias previstas en las letras anteriores. d) Los que versen sobre maternidad, paternidad, filiación y adopción\"</span> (verificado con el texto del temario oficial)."}]},{"a":"JUZGADOS DE PAZ · arts. 99 a 101","q":[{"i":"8-64","p":"Ley Orgánica 6/1985, del Poder Judicial. De las siguientes opciones sobre los Juzgados de Paz, señale la correcta:","o":["Tendrán jurisdicción en el término municipal correspondiente.","Habrá un Juzgado de Paz en cada municipio donde no exista Tribunal de Instancia.","Conocerán, en el orden penal, en primera instancia de los procesos por delito leve que les atribuya la ley.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 99 de la LOPJ</span>: <span class=\"ref-concepto\">\"En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz\"</span> (verificado con el texto del temario oficial)."}]},{"a":"Artículo 385 ✱ R18","q":[{"i":"8-211","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Se fijará la organización de las unidades de Policía Judicial y los medios de selección y régimen jurídico de sus miembros:","o":["Reglamentariamente.","Por ley.","Por Real Decreto.","Por Orden Ministerial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por ley.</mark></span><span class=\"ref-norma\">Art. 548.2 · De la Oficina Judicial y el Personal al Servicio de la Administración de Justicia</span>. El artículo 548.2 de la LOPJ indica que la organización de estas unidades, los medios de selección y el régimen jurídico de sus miembros se fijarán Por ley."},{"i":"8-225","p":"Ley Orgánica 6/1985 del Poder Judicial. Se establecerán unidades de Policía Judicial que dependerán funcionalmente de las autoridades judiciales y del Ministerio Fiscal en el desempeño de todas las actuaciones que aquéllas les encomienden. ¿Cómo se fijarán los medios de selección y régimen jurídico de los miembros de estas unidades?","o":["Reglamentariamente.","Por ley.","Por Real Decreto.","Por Orden Ministerial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por ley.</mark></span><span class=\"ref-norma\">Art. 548.2 · De la Oficina Judicial y el Personal al Servicio de la Administración de Justicia</span>. La organización de estas unidades, así como los medios de selección y régimen jurídico de sus miembros, se fijarán por ley (Art. 548.2 LOPJ)."}]},{"a":"Artículo 5 ✱","q":[{"i":"8-1","p":". Ley Orgánica 6/1985, del Poder Judicial. Ejercicio de la potestad jurisdiccional. En esta materia, señale la opción incorrecta:","o":["La Constitución es la norma suprema del ordenamiento jurídico, y vincula a todos los Jueces y Tribunales, quienes interpretarán y aplicarán las leyes y los reglamentos según los preceptos y principios constitucionales, conforme a la interpretación de los mismos que resulte de las resoluciones dictadas por el Tribunal Constitucional en todo tipo de procesos.","Cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo, pueda ser contraria a la Constitución, planteará la cuestión ante el Tribunal Constitucional, con arreglo a lo que establezca su Ley Orgánica.","Procederá el planteamiento de la cuestión de inconstitucionalidad cuando por vía interpretativa no sea posible la acomodación de la norma al ordenamiento constitucional.","En todos los casos en que, según la ley, proceda recurso de casación, será suficiente para fundamentarlo la infracción de precepto constitucional. En este supuesto, la competencia para decidir el recurso corresponderá siempre al Tribunal Constitucional, cualquiera que sean la materia, el derecho aplicable y el orden jurisdiccional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En todos los casos en que, según la ley, proceda recurso de casación, será suficiente para fundamentarlo la infracción de precepto constitu…</mark></span>La Ley Orgánica del Poder Judicial (LOPJ) establece que la infracción de precepto constitucional en un recurso de casación es motivo suficiente para fundamentarlo, pero la competencia para conocer de la casación y aplicar la Constitución corresponde al Tribunal Supremo o, en su caso, a los Tribunales Superiores de Justicia, no siempre y exclusivamente al Tribunal Constitucional. El Tribunal Constitucional sólo resuelve las cuestiones de inconstitucionalidad o recursos de amparo."},{"i":"8-166","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. Señale la INCORRECTA:","o":["La Constitución es la norma suprema del ordenamiento jurídico y vincula a todos los Jueces y Tribunales, quienes interpretarán y aplicarán las leyes y los reglamentos según los preceptos y principios constitucionales, conforme a la interpretación de los mismos que resulte de las resoluciones dictadas por el Tribunal Constitucional en todo tipo de procesos.","Cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo, pueda ser contraria a la Constitución, planteará la cuestión ante el Tribunal Supremo con arreglo a lo que establece esta Ley Orgánica.","Procederá el planteamiento de la cuestión de inconstitucionalidad cuando por vía interpretativa no sea posible la acomodación de la norma al ordenamiento constitucional.","En todos los casos en que, según la ley, proceda recurso de casación, será suficiente para fundamentarlo la infracción de precepto constitucional. En este supuesto, la competencia para decidir el recurso corresponderá siempre al Tribunal Supremo, cualquiera que sean la materia, el derecho aplicable y el orden jurisdiccional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo,…</mark></span><span class=\"ref-norma\">Art. 163 · De la Organización y Planta de Juzgados y Tribunales</span>. La afirmación incorrecta es que la cuestión de inconstitucionalidad se planteará ante el Tribunal Supremo. Cuando un órgano judicial (salvo el Tribunal Supremo que puede inaplicarla directamente) considere que una norma con rango de ley es contraria a la Constitución, debe plantear la Cuestión de Inconstitucionalidad ante el Tribunal Constitucional (art. 163 C.E. y art. 35 L.O.P.J.)."},{"i":"8-172","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo, pueda ser contraria a la Constitución, planteará la cuestión ante ___________ con arreglo a lo que establece su Ley Orgánica.","o":["El Tribunal Supremo.","El Tribunal Superior de Justicia.","La Audiencia Nacional.","El Tribunal Constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Tribunal Constitucional.</mark></span><span class=\"ref-norma\">Art. 163 · Poder Judicial</span>. La cuestión de inconstitucionalidad sobre una norma con rango de ley se plantea ante el Tribunal Constitucional (art. 163 C.E. y art. 35 L.O.P.J.)."},{"i":"8-212","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. __________ será suficiente para fundamentar la infracción de precepto constitucional. En este supuesto, la competencia para decidir el recurso corresponderá siempre al Tribunal Supremo, cualquiera que sea la materia, el derecho aplicable y el orden jurisdiccional.","o":["Recurso potestativo de reposición.","Recurso de revisión.","Recurso de alzada.","Recurso de casación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Recurso de casación.</mark></span><span class=\"ref-norma\">Art. 5.4 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 5.4 de la LOPJ establece que, en todos los casos en que, según la ley, proceda recurso de casación, será suficiente para fundamentarlo la infracción de precepto constitucional."},{"i":"8-238","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial Del poder judicial y del ejercicio de la potestad jurisdiccional. En todos los casos en que, según la ley, proceda __________ será suficiente para fundamentarlo la infracción de precepto constitucional.","o":["Recurso de apelación.","Recurso de casación.","Recurso extraordinario de revisión.","Recurso de alzada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Recurso de casación.</mark></span><span class=\"ref-norma\">Art. 477.2 · Poder Judicial</span>. En el recurso de casación (Art. 477.2.3º de la Ley de Enjuiciamiento Civil y leyes procesales), la infracción de un precepto constitucional es un motivo suficiente para interponer dicho recurso, al ser un recurso extraordinario limitado a motivos tasados."},{"i":"8-ia-8008","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Vinculación a la Constitución. La Constitución es la norma suprema del ordenamiento jurídico y vincula a todos los Jueces y Tribunales, quienes interpretarán y aplicarán las leyes y los reglamentos según los preceptos y principios constitucionales, conforme a la interpretación de los mismos que resulte de las resoluciones dictadas:","o":["por el Tribunal Supremo en todo tipo de recursos de casación.","por el Tribunal Constitucional en todo tipo de procesos.","por el Tribunal Constitucional en los procesos de amparo exclusivamente.","por el Tribunal Supremo y el Tribunal Constitucional en los términos de sus leyes orgánicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por el Tribunal Constitucional en todo tipo de procesos</mark></span>El <span class=\"ref-norma\">art. 5.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conforme a la interpretación de los mismos que resulte de las resoluciones dictadas por el Tribunal Constitucional en todo tipo de procesos\"</span>. La interpretación de referencia es la del Tribunal Constitucional «en todo tipo de procesos». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8009","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuestión de inconstitucionalidad. Cuando un órgano judicial considere, en algún proceso, que una norma con rango de ley, aplicable al caso, de cuya validez dependa el fallo, pueda ser contraria a la Constitución:","o":["planteará la cuestión ante el Tribunal Constitucional, con arreglo a lo que establece su Ley Orgánica.","inaplicará la norma y lo comunicará al Tribunal Constitucional para su ratificación.","planteará la cuestión ante el Tribunal Supremo, que resolverá con arreglo a esta ley, salvo que la ley disponga otra cosa.","suspenderá el proceso y lo comunicará al Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">planteará la cuestión ante el Tribunal Constitucional, con arreglo a lo que establece su Ley Orgánica</mark></span>El <span class=\"ref-norma\">art. 5.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"planteará la cuestión ante el Tribunal Constitucional, con arreglo a lo que establece su Ley Orgánica\"</span>. El juez no puede inaplicar la ley: debe plantear la cuestión ante el Tribunal Constitucional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8010","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuestión de inconstitucionalidad. Procederá el planteamiento de la cuestión de inconstitucionalidad cuando:","o":["la norma sea contraria al criterio del Tribunal Supremo aunque pueda interpretarse conforme a la Constitución.","cualquiera de las partes la solicite en el primer escrito de alegaciones.","el órgano judicial considere que la norma pueda ser contraria a la Constitución, con independencia de su interpretación.","por vía interpretativa no sea posible la acomodación de la norma al ordenamiento constitucional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por vía interpretativa no sea posible la acomodación de la norma al ordenamiento constitucional</mark></span>El <span class=\"ref-norma\">art. 5.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Procederá el planteamiento de la cuestión de inconstitucionalidad cuando por vía interpretativa no sea posible la acomodación de la norma al ordenamiento constitucional\"</span>. Solo si no cabe la interpretación conforme a la Constitución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8011","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recurso de casación por infracción constitucional. En todos los casos en que, según la ley, proceda recurso de casación, será suficiente para fundamentarlo la infracción de precepto constitucional. En este supuesto, la competencia para decidir el recurso corresponderá siempre:","o":["al Tribunal Constitucional, cualesquiera que sean la materia y el orden jurisdiccional, conforme al procedimiento que establezcan las leyes procesales.","al Tribunal Superior de Justicia de la comunidad autónoma que corresponda.","al Tribunal Supremo, cualesquiera que sean la materia, el derecho aplicable y el orden jurisdiccional.","a la Sala del Tribunal Supremo del orden jurisdiccional al que pertenezca la materia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Tribunal Supremo, cualesquiera que sean la materia, el derecho aplicable y el orden jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 5.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"la competencia para decidir el recurso corresponderá siempre al Tribunal Supremo, cualesquiera que sean la materia, el derecho aplicable y el orden jurisdiccional\"</span>. Siempre al Tribunal Supremo, sin distinguir materia, derecho aplicable ni orden jurisdiccional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8912","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de plazas. Los jueces afectados por un acuerdo de especialización:","o":["remitirán todos los procesos pendientes a los jueces de la plaza especializada, en los términos que establezca la ley orgánica.","continuarán conociendo hasta su conclusión de todos los procesos que estuvieran pendientes ante los mismos.","dejarán de conocer de los procesos pendientes a los seis meses.","conocerán únicamente de los procesos iniciados con posterioridad al acuerdo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">continuarán conociendo hasta su conclusión de todos los procesos que estuvieran pendientes ante los mismos</mark></span>El <span class=\"ref-norma\">art. 96.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los jueces, las juezas, los magistrados y las magistradas afectados continuarán conociendo hasta su conclusión de todos los procesos que estuvieran pendientes ante los mismos\"</span>. Continúan con los procesos pendientes hasta su conclusión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 ✱","q":[{"i":"8-2","p":". Ley Orgánica 6/1985, del Poder Judicial. Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, para conocer de las pretensiones relativas a las siguientes materias. Señale la opción incorrecta:","o":["Constitución, validez o disolución de sociedades o personas jurídicas que tengan su domicilio en territorio extranjero, así como respecto de los acuerdos y decisiones de sus órganos.","Validez o nulidad de las inscripciones practicadas en un registro español.","Inscripciones o validez de patentes, marcas, diseños o dibujos y modelos y otros derechos sometidos a depósito o registro, cuando se hubiera solicitado o efectuado en España el depósito o el registro.","Reconocimiento y ejecución en territorio español de sentencias y demás resoluciones judiciales, decisiones arbitrales y acuerdos de mediación dictados en el extranjero."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Constitución, validez o disolución de sociedades o personas jurídicas que tengan su domicilio en territorio extranjero, así como respecto de los acuerdos y decisiones de sus órganos</mark></span>La opción A es la falsa: habla de domicilio en territorio EXTRANJERO. Las demás materias figuran en el art. 22. Según el <span class=\"ref-norma\">art. 22 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"b) Constitución, validez, nulidad o disolución de sociedades o personas jurídicas que tengan su domicilio en territorio español, así como respecto de los acuerdos y decisiones de sus órganos\"</span> (verificado con el texto del temario)."},{"i":"8-11","p":". Ley Orgánica 6/1985, del Poder Judicial. De la extensión y límites de la jurisdicción. Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, para conocer de las pretensiones relativas a las siguientes materias:","o":["Validez o nulidad de las inscripciones practicadas en un registro español.","Inscripciones o validez de patentes, marcas, diseños o dibujos y modelos y otros derechos sometidos a depósito o registro, cuando se hubiera solicitado o efectuado en España el depósito o el registro.","Reconocimiento y ejecución en territorio español de sentencias y demás resoluciones judiciales, decisiones arbitrales y acuerdos de mediación dictados en el extranjero.","Todas las opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas</mark></span>Según el <span class=\"ref-norma\">art. 22 de la LOPJ</span>: <span class=\"ref-concepto\">\"c) Validez o nulidad de las inscripciones practicadas en un registro español. d) Inscripciones o validez de patentes, marcas, diseños o dibujos y modelos y otros derechos sometidos a depósito o registro, cuando se hubiera solicitado o efectuado en España el depósito o el registro. e) Reconocimiento y ejecución en territorio español de sentencias y demás resoluciones judiciales, decisiones arbitrales y acuerdos de mediación dictados en el extranjero\"</span> (verificado con el texto del temario oficial)."},{"i":"8-48","p":"Ley Orgánica 6/1985, del Poder Judicial. De la extensión y límites de la jurisdicción y de la planta y organización de los juzgados y tribunales. Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, para conocer de las pretensiones relativas a las siguientes materias:","o":["Constitución, validez, nulidad o disolución de sociedades o personas jurídicas que tengan su domicilio en territorio español, así como respecto de los acuerdos y decisiones de sus órganos.","Validez o nulidad de las inscripciones practicadas en un registro español.","Inscripciones o validez de patentes, marcas, diseños o dibujos y modelos y otros derechos sometidos a depósito o registro, cuando se hubiera solicitado o efectuado en España el depósito o el registro.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 22 de la LOPJ</span>: <span class=\"ref-concepto\">\"b) Constitución, validez, nulidad o disolución de sociedades o personas jurídicas que tengan su domicilio en territorio español, así como respecto de los acuerdos y decisiones de sus órganos. c) Validez o nulidad de las inscripciones practicadas en un registro español. d) Inscripciones o validez de patentes, marcas, diseños o dibujos y modelos y otros derechos sometidos a depósito o registro, cuando se hubiera solicitado o efectuado en España el depósito o el registro.\"</span> (verificado con el texto del temario oficial)."},{"i":"8-249","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia judicial internacional. Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, para conocer de las pretensiones relativas a las siguientes materias:","o":["Contratos de trabajo celebrados en territorio español, entre otras.","Relaciones personales y patrimoniales entre cónyuges residentes en España, entre otras, en los términos que determine la ley orgánica correspondiente.","Delitos cometidos por españoles fuera del territorio nacional, entre otras.","Derechos reales y arrendamientos de bienes inmuebles que se hallen en España, entre otras."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Derechos reales y arrendamientos de bienes inmuebles que se hallen en España, entre otras</mark></span>El <span class=\"ref-norma\">art. 22 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, para conocer de las pretensiones relativas a las siguientes materias:\"</span>"},{"i":"8-ia-8055","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia exclusiva de los Tribunales españoles. Con carácter exclusivo, los Tribunales españoles serán competentes para conocer de las pretensiones relativas a la constitución, validez, nulidad o disolución de sociedades o personas jurídicas:","o":["que tengan su domicilio en territorio español, excepto respecto de los acuerdos y decisiones de sus órganos, salvo que la ley disponga otra cosa.","que desarrollen su actividad principal en territorio español, así como de los acuerdos de sus órganos.","que tengan su domicilio en territorio español, así como respecto de los acuerdos y decisiones de sus órganos.","que estén inscritas en un registro español, así como de las decisiones de sus órganos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">que tengan su domicilio en territorio español, así como respecto de los acuerdos y decisiones de sus órganos</mark></span>El <span class=\"ref-norma\">art. 22.b de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Constitución, validez, nulidad o disolución de sociedades o personas jurídicas que tengan su domicilio en territorio español, así como respecto de los acuerdos y decisiones de sus órganos\"</span>. El criterio es el domicilio en territorio español, e incluye acuerdos y decisiones de sus órganos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8056","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia exclusiva de los Tribunales españoles. Con carácter exclusivo, los Tribunales españoles serán competentes en materia de inscripciones o validez de patentes, marcas, diseños o dibujos y modelos y otros derechos sometidos a depósito o registro:","o":["cuando el titular tenga su domicilio en territorio español.","cuando se hubiera solicitado o efectuado en España el depósito o el registro.","cuando el derecho vaya a ejercerse principalmente en España.","cuando se hubiera solicitado en España o en otro Estado de la Unión Europea, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando se hubiera solicitado o efectuado en España el depósito o el registro</mark></span>El <span class=\"ref-norma\">art. 22.d de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando se hubiera solicitado o efectuado en España el depósito o el registro\"</span>. El criterio es que el depósito o registro se haya solicitado o efectuado en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 23 EXOF EX ✱","q":[{"i":"8-4","p":". Ley Orgánica 6/1985, del Poder Judicial. Los supuestos de delito contra el titular de la Corona, su consorte, su sucesor o el regente, solamente serán perseguibles en España cuando los hechos fueran cometidos fuera de territorio nacional:","o":["Previa interposición de querella por el agraviado.","Previa interposición de querella por el Ministerio Fiscal.","Previa interposición de denuncia por el agraviado o por el Ministerio Fiscal.","Las opciones A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones A y B son correctas</mark></span>Es querella (no denuncia) y la pueden interponer el agraviado o el Ministerio Fiscal. Según el <span class=\"ref-norma\">art. 23.6 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Los delitos a los que se refieren los apartados 3 y 4 solamente serán perseguibles en España previa interposición de querella por el agraviado o por el Ministerio Fiscal\"</span> (verificado con el texto del temario)."},{"i":"8-9","p":". Ley Orgánica 6/1985, del Poder Judicial. Será competente la jurisdicción española para conocer de los hechos cometidos por españoles o extranjeros fuera del territorio nacional susceptibles de tipificarse, según la ley española, como delito de terrorismo, siempre que concurra alguno de los siguientes supuestos:","o":["El delito se haya cometido por cuenta de una persona jurídica con domicilio en España.","La víctima tuviera nacionalidad española en el momento de comisión de los hechos.","El delito haya sido cometido para influir o condicionar de un modo ilícito la actuación de cualquier Autoridad española.","Todas las opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas</mark></span>Según el <span class=\"ref-norma\">art. 23 de la LOPJ</span>: <span class=\"ref-concepto\">\"3.º el delito se haya cometido por cuenta de una persona jurídica con domicilio en España; 4.º la víctima tuviera nacionalidad española en el momento de comisión de los hechos; 5.º el delito haya sido cometido para influir o condicionar de un modo ilícito la actuación de cualquier Autoridad española\"</span> (verificado con el texto del temario oficial)."},{"i":"8-74","p":"Ley Orgánica 6/1985 del Poder Judicial. De la extensión y límites de la jurisdicción. Conocerá la jurisdicción española de los delitos que hayan sido cometidos fuera del territorio nacional, siempre que los criminalmente responsables fueren españoles o extranjeros que hubieran adquirido la nacionalidad española con posterioridad a la comisión del hecho y concurran los siguientes requisitos:","o":["Que el hecho no sea punible en el lugar de ejecución, salvo que en virtud de un Tratado Internacional o de un acto normativo de una Organización internacional de la que España sea parte, no resulte necesario dicho requisito, sin perjuicio de lo dispuesto en los apartados siguientes.","Que el agraviado o el Ministerio Fiscal interpongan querella ante los tribunales españoles.","Que el delincuente haya sido absuelto, indultado o penado en el extranjero.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que el agraviado o el Ministerio Fiscal interpongan querella ante los tribunales españoles</mark></span>A y C están invertidas: el hecho SÍ debe ser punible en el lugar y el delincuente NO debe haber sido absuelto, indultado o penado. Según el <span class=\"ref-norma\">art. 23.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"También conocerá la jurisdicción española de los delitos que hayan sido cometidos fuera del territorio nacional, siempre que los criminalmente responsables fueren españoles [...] y concurrieren los siguientes requisitos: a) Que el hecho sea punible en el lugar de ejecución [...] b) Que el agraviado o el Ministerio Fiscal interpongan querella [...] c) Que el delincuente no haya sido absuelto, indultado o penado en el extranjero\"</span> (verificado con el texto del temario)."},{"i":"8-118","p":"En el orden penal, la jurisdicción española es competente para conocer de los delitos cometidos fuera del territorio nacional de Terrorismo, Genocidio, Piratería y otros. Estos delitos solamente serán perseguibles en España:","o":["Previa interposición de querella por el agraviado o por el Ministerio Fiscal.","Únicamente previa querella del Ministerio Fiscal.","Únicamente si el delincuente es español.","Solo si la víctima es española."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Previa interposición de querella por el agraviado o por el Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 23.6 · De la Extensión y Límites de la Jurisdicción</span>. El artículo 23.6 de la LOPJ establece que los delitos graves cometidos en el extranjero (Genocidio, Terrorismo, etc.) solo serán perseguibles en España previa interposición de querella por el agraviado o por el Ministerio Fiscal."},{"i":"8-151","p":"(LOPJ) El número de Vocales que integran el Consejo General del Poder Judicial es de:","o":["12.","20.","21.","10."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">20.</mark></span><span class=\"ref-norma\">Art. 566 · Del Consejo General del Poder Judicial</span>. El Consejo General del Poder Judicial (CGPJ) se compone de veinte Vocales más el Presidente del Tribunal Supremo, que lo preside (art. 566 LOPJ)."},{"i":"8-252","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción española en el orden penal. En el orden penal corresponderá a la jurisdicción española el conocimiento de las causas por delitos y faltas cometidos en territorio español o cometidos a bordo de buques o aeronaves españoles, sin perjuicio de lo previsto:","o":["En las normas de la Unión Europea sobre cooperación judicial penal únicamente.","En las leyes orgánicas que regulan la jurisdicción militar.","En los convenios bilaterales de extradición suscritos por el Gobierno.","En los tratados internacionales en los que España sea parte."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En los tratados internacionales en los que España sea parte</mark></span>El <span class=\"ref-norma\">art. 23.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. En el orden penal corresponderá a la jurisdicción española el conocimiento de las causas por delitos y faltas cometidos en territorio español o cometidos a bordo de buques o aeronaves españoles, sin perjuicio de lo previsto en los tratados internacionales en los que España sea parte.\"</span>"},{"i":"8-253","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción española en el orden penal. Para que la jurisdicción española conozca de delitos cometidos fuera del territorio nacional por españoles, se exige que el hecho sea punible en el lugar de ejecución, salvo que:","o":["El delito se hubiera cometido contra un español, en cuyo caso el requisito no es exigible, sin perjuicio de lo que establezcan los tratados internacionales, en los términos que determine la ley orgánica correspondiente.","En virtud de un Tratado internacional o de un acto normativo de una Organización internacional de la que España sea parte, no resulte necesario dicho requisito.","El Ministerio Fiscal interponga querella ante los tribunales españoles en cualquier caso.","El agraviado haya obtenido en el extranjero una resolución favorable firme."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En virtud de un Tratado internacional o de un acto normativo de una Organización internacional de la que España sea parte, no resulte necesario dicho requisito</mark></span>El <span class=\"ref-norma\">art. 23.2.a) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Que el hecho sea punible en el lugar de ejecución, salvo que, en virtud de un Tratado internacional o de un acto normativo de una Organización internacional de la que España sea parte, no resulte necesario dicho requisito, sin perjuicio de lo dispuesto en los apartados siguientes.\"</span>"},{"i":"8-254","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal. La jurisdicción española conocerá de los hechos cometidos por españoles o extranjeros fuera del territorio nacional susceptibles de tipificarse, según la ley española, como delitos de:","o":["Terrorismo, siempre que concurra alguno de los supuestos previstos en la ley.","Terrorismo, siempre que el procedimiento se dirija exclusivamente contra un español.","Terrorismo, sin necesidad de que concurra ninguno de los supuestos previstos en la ley.","Terrorismo cometido únicamente contra víctimas de nacionalidad española."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Terrorismo, siempre que concurra alguno de los supuestos previstos en la ley</mark></span>El <span class=\"ref-norma\">art. 23.4.e) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"e) Terrorismo, siempre que concurra alguno de los siguientes supuestos:\"</span>"},{"i":"8-255","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal. La jurisdicción española conocerá de los delitos contra la libertad e indemnidad sexual:","o":["Cometidos sobre cualquier víctima, siempre que el autor sea de nacionalidad española.","Cometidos sobre víctimas menores de dieciséis años, sin otros requisitos.","Cometidos sobre víctimas menores de edad, siempre que concurran los supuestos previstos en la ley.","Cometidos en el extranjero, siempre que el agraviado interponga querella en el plazo de un año, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cometidos sobre víctimas menores de edad, siempre que concurran los supuestos previstos en la ley</mark></span>El <span class=\"ref-norma\">art. 23.4.k) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"k) Delitos contra la libertad e indemnidad sexual cometidos sobre víctimas menores de edad, siempre que:\"</span>"},{"i":"8-296","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción española en el orden penal. También conocerá la jurisdicción española de los delitos que hayan sido cometidos fuera del territorio nacional, siempre que los criminalmente responsables fueren:","o":["Españoles o extranjeros que residan habitualmente en España, aunque no hayan adquirido la nacionalidad, sin perjuicio de lo que establezcan los tratados internacionales.","Españoles, con exclusión de los extranjeros que hubieran adquirido después la nacionalidad española.","Extranjeros que hubieran adquirido la nacionalidad española antes de la comisión del hecho.","Españoles o extranjeros que hubieran adquirido la nacionalidad española con posterioridad a la comisión del hecho."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Españoles o extranjeros que hubieran adquirido la nacionalidad española con posterioridad a la comisión del hecho</mark></span>El <span class=\"ref-norma\">art. 23.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"También conocerá la jurisdicción española de los delitos que hayan sido cometidos fuera del territorio nacional, siempre que los criminalmente responsables fueren españoles o extranjeros que hubieran adquirido la nacionalidad española con posterioridad a la comisión del hecho y concurrieren los siguientes requisitos:\"</span>"},{"i":"8-297","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal. Entre los delitos cometidos fuera del territorio nacional de que conoce la jurisdicción española, se encuentran los de constitución, financiación o integración en grupo u organización criminal, siempre que se trate de grupos que actúen con miras a la comisión en España de un delito castigado con una pena máxima:","o":["Igual o superior a tres años de prisión.","Superior a cinco años de prisión.","Igual o superior a dos años de prisión.","Igual o superior a cuatro años de prisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Igual o superior a tres años de prisión</mark></span>El <span class=\"ref-norma\">art. 23.4.j) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Delitos de constitución, financiación o integración en grupo u organización criminal o delitos cometidos en el seno de los mismos, siempre que se trate de grupos u organizaciones que actúen con miras a la comisión en España de un delito que esté castigado con una pena máxima igual o superior a tres años de prisión.\"</span>"},{"i":"8-ia-8151","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden penal. En el orden penal corresponderá a la jurisdicción española el conocimiento de las causas por delitos y faltas cometidos en territorio español o cometidos a bordo de buques o aeronaves españoles, sin perjuicio de:","o":["lo previsto en los tratados internacionales en los que España sea parte.","lo previsto en las normas de la Unión Europea exclusivamente, en los términos que establezca la ley orgánica.","lo que determine el Tribunal Supremo en cada caso.","las competencias de la jurisdicción militar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">lo previsto en los tratados internacionales en los que España sea parte</mark></span>El <span class=\"ref-norma\">art. 23.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cometidos a bordo de buques o aeronaves españoles, sin perjuicio de lo previsto en los tratados internacionales en los que España sea parte\"</span>. La salvedad es a favor de los tratados internacionales en que España sea parte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8152","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden penal. La jurisdicción española conocerá de los delitos cometidos fuera del territorio nacional siempre que los criminalmente responsables fueren españoles o extranjeros que hubieran adquirido la nacionalidad española con posterioridad a la comisión del hecho y concurrieren determinados requisitos, entre ellos:","o":["que el agraviado interponga denuncia ante la autoridad española competente.","que el hecho sea punible en España y el delincuente resida habitualmente en ella, salvo que la ley disponga otra cosa.","que el Ministerio Fiscal ejercite la acción de oficio en todo caso.","que el agraviado o el Ministerio Fiscal interpongan querella ante los tribunales españoles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">que el agraviado o el Ministerio Fiscal interpongan querella ante los tribunales españoles</mark></span>El <span class=\"ref-norma\">art. 23.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"b) Que el agraviado o el Ministerio Fiscal interpongan querella ante los tribunales españoles\"</span>. Se exige querella del agraviado o del Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8155","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden penal. Entre los delitos de los que conoce la jurisdicción española aunque se hayan cometido fuera del territorio nacional por españoles o extranjeros, figura:","o":["la falsificación de moneda española y su expedición.","la falsificación de moneda de cualquier Estado miembro de la Unión Europea.","el atentado contra autoridades o funcionarios públicos extranjeros.","las defraudaciones contra la Hacienda Pública de otros Estados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la falsificación de moneda española y su expedición</mark></span>El <span class=\"ref-norma\">art. 23.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"e) Falsificación de moneda española y su expedición\"</span>. Solo la moneda española. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8156","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal. La jurisdicción española será competente para conocer de los hechos de genocidio, lesa humanidad o contra las personas y bienes protegidos en caso de conflicto armado, cometidos fuera del territorio nacional, siempre que el procedimiento se dirija contra:","o":["cualquier persona, con independencia de su nacionalidad o residencia.","un español o contra un extranjero que haya cometido el delito contra una víctima española, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","un extranjero que se encuentre en España, aunque no se haya denegado su extradición.","un español o contra un ciudadano extranjero que resida habitualmente en España, o contra un extranjero que se encontrara en España y cuya extradición hubiera sido denegada por las autoridades españolas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un español o contra un ciudadano extranjero que resida habitualmente en España, o contra un extranjero que se encontrara en España y cuya extradición hubiera sido denegada por las autoridades españolas</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que el procedimiento se dirija contra un español o contra un ciudadano extranjero que resida habitualmente en España, o contra un extranjero que se encontrara en España y cuya extradición hubiera sido denegada por las autoridades españolas\"</span>. Se exige vínculo: español, residente habitual o extranjero en España con extradición denegada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8157","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal. Respecto de los delitos de tortura y contra la integridad moral, la jurisdicción española será competente cuando el procedimiento se dirija contra un español o cuando:","o":["la víctima tuviera nacionalidad española en el momento de comisión de los hechos, aunque el imputado se encuentre fuera de España, conforme al procedimiento que establezcan las leyes procesales.","la persona imputada resida habitualmente en España, con independencia de la nacionalidad de la víctima.","la víctima tuviera nacionalidad española en el momento de comisión de los hechos y la persona a la que se impute la comisión del delito se encuentre en territorio español.","el hecho se haya cometido contra una institución española en el extranjero."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la víctima tuviera nacionalidad española en el momento de comisión de los hechos y la persona a la que se impute la comisión del delito se encuentre en territorio español</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"2.º la víctima tuviera nacionalidad española en el momento de comisión de los hechos y la persona a la que se impute la comisión del delito se encuentre en territorio español\"</span>. Además de la nacionalidad de la víctima, el imputado debe encontrarse en territorio español. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8158","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · terrorismo. En materia de terrorismo, la jurisdicción española será competente, entre otros supuestos, cuando el procedimiento se dirija contra un extranjero que resida habitualmente o se encuentre en España o, sin reunir esos requisitos:","o":["sea miembro de una organización terrorista con sede en España.","colabore con un español, o con un extranjero que resida o se encuentre en España, para la comisión de un delito de terrorismo.","haya sido condenado por terrorismo en otro Estado miembro de la Unión Europea, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","haya sido extraditado a España por un delito de terrorismo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">colabore con un español, o con un extranjero que resida o se encuentre en España, para la comisión de un delito de terrorismo</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"o, sin reunir esos requisitos, colabore con un español, o con un extranjero que resida o se encuentre en España, para la comisión de un delito de terrorismo\"</span>. Se trata del supuesto de colaboración con un español o con un extranjero residente o presente en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8161","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · apoderamiento de aeronaves. Respecto de los delitos contenidos en el Convenio para la represión del apoderamiento ilícito de aeronaves, hecho en La Haya el 16 de diciembre de 1970, la jurisdicción española es competente siempre que el delito haya sido cometido por un ciudadano español o:","o":["se haya cometido contra una aeronave que aterrice en territorio español.","la víctima sea de nacionalidad española.","se haya cometido contra una aeronave que navegue bajo pabellón español.","el autor se encuentre en España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se haya cometido contra una aeronave que navegue bajo pabellón español</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"2.º el delito se haya cometido contra una aeronave que navegue bajo pabellón español\"</span>. El criterio es el pabellón español de la aeronave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8162","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · materiales nucleares. Respecto de los delitos contenidos en el Convenio sobre la protección física de materiales nucleares, hecho en Viena y Nueva York el 3 de marzo de 1980, la jurisdicción española es competente siempre que:","o":["el delito se haya cometido contra un ciudadano español.","el delito se haya cometido por un ciudadano español.","el material nuclear se encuentre en territorio español.","el delito se haya cometido por un extranjero residente en España."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el delito se haya cometido por un ciudadano español</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que el delito se haya cometido por un ciudadano español\"</span>. Solo si el autor es ciudadano español. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8163","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · crimen organizado. Respecto de los delitos de constitución, financiación o integración en grupo u organización criminal, la jurisdicción española es competente siempre que se trate de grupos u organizaciones que actúen con miras a la comisión en España de un delito castigado con una pena máxima igual o superior a:","o":["tres años de prisión.","cinco años de prisión.","dos años de prisión.","diez años de prisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tres años de prisión</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"que actúen con miras a la comisión en España de un delito que esté castigado con una pena máxima igual o superior a tres años de prisión\"</span>. El umbral es de tres años de prisión como pena máxima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8164","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · delitos sexuales. Respecto de los delitos contra la libertad e indemnidad sexual cometidos sobre víctimas menores de edad, la jurisdicción española es competente, entre otros supuestos, cuando el procedimiento se dirija contra:","o":["ciudadano extranjero que se encuentre en España con carácter temporal.","un extranjero que haya sido detenido en el extranjero por estos delitos.","un extranjero que haya viajado a España en los últimos cinco años.","ciudadano extranjero que resida habitualmente en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ciudadano extranjero que resida habitualmente en España</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"2.º el procedimiento se dirija contra ciudadano extranjero que resida habitualmente en España\"</span>. Debe residir habitualmente en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8165","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · violencia contra las mujeres. Respecto de los delitos regulados en el Convenio del Consejo de Europa de 11 de mayo de 2011 sobre prevención y lucha contra la violencia contra las mujeres y la violencia doméstica, la jurisdicción española es competente cuando el procedimiento se dirija contra un español, contra un extranjero que resida habitualmente en España o cuando el delito se hubiera cometido contra una víctima que tuviera nacionalidad española o residencia habitual en España, siempre que:","o":["la víctima presente denuncia ante las autoridades españolas.","el Ministerio Fiscal interponga querella ante el Tribunal Supremo, sin perjuicio de lo dispuesto en otras leyes.","la persona a la que se impute la comisión del hecho delictivo se encuentre en España.","el delito esté tipificado también en el Estado donde se cometió."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la persona a la que se impute la comisión del hecho delictivo se encuentre en España</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"tuviera nacionalidad española o residencia habitual en España, siempre que la persona a la que se impute la comisión del hecho delictivo se encuentre en España\"</span>. El imputado debe encontrarse en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8167","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · salud pública. Respecto de los delitos regulados en el Convenio del Consejo de Europa de 28 de octubre de 2011, sobre falsificación de productos médicos y delitos que supongan una amenaza para la salud pública, la jurisdicción española es competente, entre otros supuestos, cuando el delito se haya cometido contra una persona que tuviera:","o":["residencia habitual en España en el momento de comisión de los hechos.","nacionalidad española en el momento de la interposición de la querella.","domicilio fiscal en España en los últimos cinco años.","residencia en España desde al menos seis meses antes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">residencia habitual en España en el momento de comisión de los hechos</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"5.º el delito se haya cometido contra una persona que tuviera residencia habitual en España en el momento de comisión de los hechos\"</span>. Residencia habitual en España en el momento de los hechos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8168","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · tratados. La jurisdicción española será también competente para conocer de los delitos anteriores cometidos fuera del territorio nacional por ciudadanos extranjeros que se encontraran en España y cuya extradición hubiera sido denegada por las autoridades españolas, siempre que:","o":["así lo solicite el Ministerio Fiscal.","se haya interpuesto querella por el agraviado, sin perjuicio de lo dispuesto en otras leyes.","lo autorice la Sala 2.ª del Tribunal Supremo.","así lo imponga un Tratado vigente para España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">así lo imponga un Tratado vigente para España</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que así lo imponga un Tratado vigente para España\"</span>. Solo si lo impone un tratado vigente para España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8169","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Límites a la persecución. Los delitos de jurisdicción extraterritorial por genocidio, lesa humanidad, tortura, terrorismo y demás del catálogo de la ley no serán perseguibles en España cuando se haya iniciado un procedimiento para su investigación y enjuiciamiento:","o":["en cualquier Tribunal extranjero con independencia del Estado, en los términos que establezca la ley orgánica.","en el Tribunal Penal Internacional exclusivamente.","en un Tribunal Internacional constituido conforme a los Tratados y Convenios en que España fuera parte.","en un Estado miembro de la Unión Europea."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en un Tribunal Internacional constituido conforme a los Tratados y Convenios en que España fuera parte</mark></span>El <span class=\"ref-norma\">art. 23.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Cuando se haya iniciado un procedimiento para su investigación y enjuiciamiento en un Tribunal Internacional constituido conforme a los Tratados y Convenios en que España fuera parte\"</span>. Se trata de un Tribunal Internacional constituido conforme a tratados de los que España es parte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8171","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Requisito de procedibilidad. Los delitos cometidos fuera del territorio nacional por los que la jurisdicción española es competente (traición, terrorismo, genocidio y demás de la lista legal) solamente serán perseguibles en España:","o":["previa interposición de querella por el agraviado o por el Ministerio Fiscal.","previa denuncia del agraviado ante cualquier autoridad.","de oficio por el juez de instrucción competente.","previa autorización de la Sala 2.ª del Tribunal Supremo, conforme al procedimiento que establezcan las leyes procesales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">previa interposición de querella por el agraviado o por el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 23.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"solamente serán perseguibles en España previa interposición de querella por el agraviado o por el Ministerio Fiscal\"</span>. Se requiere querella del agraviado o del Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 72 EXOF R13","q":[{"i":"8-5","p":". Ley Orgánica 6/1985, del Poder Judicial. La Sala primera del Tribunal Supremo es:","o":["De lo Civil.","De lo Penal.","De lo Social.","De lo Contencioso-administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De lo Civil.</mark></span>El Tribunal Supremo está dividido en cinco Salas. Según la LOPJ, la Sala Primera es la de lo Civil."}]},{"a":"Artículo 93","q":[{"i":"8-7","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 93 y 95.e. Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia. Señale la opción incorrecta en relación con esta materia:","o":["Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia y con jurisdicción en toda ella, existirá una Sección de lo Contencioso-Administrativo.","También podrán crearse excepcionalmente Secciones de lo Contencioso-Administrativo que extiendan su jurisdicción a más de una provincia dentro de la misma comunidad autónoma.","Cuando el volumen de asuntos lo requiera, se podrán establecer Secciones de lo Contencioso-Administrativo en Tribunales de Instancia que tengan su sede en poblaciones distintas de la capital de provincia, delimitándose en cada caso el ámbito territorial de su jurisdicción.","En la Villa de Madrid, con jurisdicción en todo el territorio nacional, existirá un Tribunal Central de Instancia cuya Sección de lo Contencioso-Administrativo conocerá, en segunda instancia, de los recursos contra actos de las autoridades con competencia en todo el territorio nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En la Villa de Madrid, con jurisdicción en todo el territorio nacional, existirá un Tribunal Central de Instancia cuya Sección de lo Contencioso-Administrativo conocerá, en segunda instancia, de los recursos contra actos de las autoridades con competencia en todo el territorio nacional</mark></span>El Tribunal Central de Instancia conoce en primera o única instancia, no en segunda. Según el <span class=\"ref-norma\">art. 93 y 95.e de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Sección de lo Contencioso-Administrativo, que conocerá, en primera o única instancia, de los recursos contencioso-administrativos contra disposiciones y actos emanados de autoridades, organismos, órganos y entidades públicas con competencia en todo el territorio nacional\"</span> (verificado con el texto del temario)."},{"i":"8-138","p":"(LOPJ) Según la LOPJ, la autorización judicial para la entrada en domicilios y otros lugares constitucionalmente protegidos, cuando proceda para la ejecución forzosa de actos de la Administración, corresponde a:","o":["El Juez de Instrucción.","El Juez de Primera Instancia e Instrucción.","Las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia.","La Audiencia Provincial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 93.5 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"También les corresponde autorizar, mediante auto, la entrada en los domicilios y en los restantes edificios o lugares cuyo acceso requiera el consentimiento de su titular, cuando ello proceda para la ejecución forzosa de actos de la Administración\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8790","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Contencioso-Administrativo. Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, y con jurisdicción en toda ella, existirá:","o":["una Sala de lo Contencioso-Administrativo.","una Sección de lo Contencioso-Administrativo.","una Sección de lo Contencioso-Administrativo por cada partido judicial.","un Juzgado Central de lo Contencioso-Administrativo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una Sección de lo Contencioso-Administrativo</mark></span>El <span class=\"ref-norma\">art. 93.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, y con jurisdicción en toda ella, existirá una Sección de lo Contencioso-Administrativo\"</span>. Una Sección por provincia con sede en la capital. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"RECUERDA del temario · LO 6/1985 del Poder Judicial — R1 a R22 R1 R2 R3 R4 R5 R6 R7 R8 R9 R10 R11 R12 R13 R14 R15 R16 R17 R18 R19 R20 R21 R22","q":[{"i":"8-8","p":". Ley Orgánica 6/1985, del Poder Judicial. Los Jueces de Paz y sus sustitutos serán nombrados por:","o":["La Sala de Gobierno del Tribunal Superior de Justicia correspondiente.","La Sala de Gobierno del Tribunal de Primera Instancia e Instrucción correspondiente.","La Audiencia Provincial.","El Pleno del Ayuntamiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de Gobierno del Tribunal Superior de Justicia correspondiente.</mark></span><span class=\"ref-norma\">Art. 101 · De la Organización y Planta de Juzgados y Tribunales</span>. La LOPJ (art. 101) establece que los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente, a partir de la propuesta del respectivo Ayuntamiento."},{"i":"8-12","p":". Ley Orgánica 6/1985, del Poder Judicial. División territorial en lo judicial. El Estado se organiza territorialmente, a efectos judiciales, en:","o":["Municipios.","Partidos.","Provincias y Comunidades Autónomas.","Todas las opciones anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones anteriores son correctas</mark></span>Según el <span class=\"ref-norma\">art. 30 de la LOPJ</span>: <span class=\"ref-concepto\">\"El Estado se organiza territorialmente, a efectos judiciales, en Municipios, Partidos, Provincias y Comunidades Autónomas\"</span> (verificado con el texto del temario oficial)."},{"i":"8-17","p":". Ley Orgánica 6/1985, del Poder Judicial. El Tribunal Supremo estará integrado por:","o":["Tres Salas.","Cuatro Salas.","Cinco Salas.","Cinco Salas y tres extraordinaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cinco Salas.</mark></span><span class=\"ref-norma\">Art. 55 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 55 de la LOPJ establece que el Tribunal Supremo estará integrado por cinco Salas: de lo Civil (Primera), de lo Penal (Segunda), de lo Contencioso-Administrativo (Tercera), de lo Social (Cuarta) y de lo Militar (Quinta)."},{"i":"8-19","p":"Ley Orgánica 6/1985, de 1 de julio, del poder judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. Señala la incorrecta:","o":["Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios a la Constitución, a la ley o al principio de jerarquía normativa.","Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como el sometimiento de ésta a los fines que la justifican.","Los Juzgados y Tribunales ejercerán su jurisdicción exclusivamente en aquellos casos en que les venga atribuida por esta u otra Ley.","Los Tribunales y Juzgados del orden social conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los Tribunales y Juzgados del orden social conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas…</mark></span><span class=\"ref-norma\">Art. 6 · Poder Judicial</span>. Las opciones (a), (b) y (c) son correctas según los artículos 6, 8 y 9 de la LOPJ. La opción (d) es incorrecta, pues es la Jurisdicción Civil la que se considera residual (Art. 9.5 LOPJ: &quot;Los Juzgados y Tribunales del orden civil conocerán de todas aquellas materias que no estén atribuidas a otro orden jurisdiccional&quot;)."},{"i":"8-23","p":"L.O. 1/1985 del Poder Judicial. El Estado se organiza territorialmente, a efectos judiciales, en: indique la INCORRECTA.","o":["Comarcas.","Partidos.","Provincias.","Comunidades Autónomas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Comarcas</mark></span>La Comarca no figura entre ellos. Según el <span class=\"ref-norma\">art. 30 de la LOPJ</span>: <span class=\"ref-concepto\">\"El Estado se organiza territorialmente, a efectos judiciales, en Municipios, Partidos, Provincias y Comunidades Autónomas\"</span> (verificado con el texto del temario oficial)."},{"i":"8-33","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. En las funciones de investigación penal, la Policía Judicial actuará bajo la dirección de:","o":["Los Juzgados y Tribunales.","Del Ministerio Fiscal.","De sus superiores o mando.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas.</mark></span><span class=\"ref-norma\">Art. 547.2 · De la Oficina Judicial y el Personal al Servicio de la Administración de Justicia</span>. El artículo 547.2 de la LOPJ establece que la Policía Judicial, en las funciones de investigación penal, actuará bajo la dirección de los Juzgados, Tribunales y del Ministerio Fiscal."},{"i":"8-35","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La Audiencia Nacional estará integrada por:","o":["Tres Salas.","Cuatro Salas.","Cinco Salas.","Cinco Salas y una extraordinaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuatro Salas.</mark></span><span class=\"ref-norma\">Art. 64.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 64.1 de la LOPJ establece que la Audiencia Nacional está integrada por cuatro Salas: De Apelación, De lo Penal, De lo Contencioso-Administrativo y De lo Social."},{"i":"8-36","p":"Ley Orgánica 6/1985 del Poder Judicial. Del Tribunal Supremo. ¿Quién nombrará al Director del Gabinete Técnico?","o":["El Presidente del Tribunal Supremo a propuesta vinculante del Pleno del Consejo General del Poder Judicial, debiendo acreditar los requisitos legalmente exigidos para poder acceder a la categoría de Magistrado del Tribunal Supremo, teniendo dicha consideración, a efectos representativos, mientras desempeñe el cargo.","El Pleno del Consejo General del Poder Judicial, a propuesta vinculante del Presidente del Tribunal Supremo, debiendo acreditar los requisitos legalmente exigidos para poder acceder a la categoría de Magistrado del Tribunal Supremo, teniendo dicha consideración, a efectos representativos, mientras desempeñe el cargo.","El Presidente del Tribunal Supremo a propuesta vinculante del Pleno del Consejo General del Poder Judicial, debiendo acreditar los requisitos legalmente exigidos para poder acceder a la carrera judicial, teniendo consideración de Magistrado del Tribunal Supremo, a efectos no representativos, mientras desempeñe el cargo.","El Presidente del Tribunal Supremo a propuesta vinculante del Pleno del Consejo General del Poder Judicial, debiendo acreditar los requisitos legalmente exigidos para poder acceder a la carrera judicial, teniendo consideración de Magistrado del Tribunal Supremo, a efectos representativos, mientras desempeñe el cargo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Pleno del Consejo General del Poder Judicial, a propuesta vinculante del Presidente del Tribunal Supremo, debiendo acreditar los requisi…</mark></span><span class=\"ref-norma\">Art. 58.3 · Del Consejo General del Poder Judicial</span>. De acuerdo con el artículo 58.3 de la LOPJ, el Director del Gabinete Técnico es nombrado por el Pleno del Consejo General del Poder Judicial a propuesta vinculante del Presidente del Tribunal Supremo."},{"i":"8-44","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La Audiencia Nacional se compondrá de:","o":["Su Presidente.","Los Presidentes de Sala.","Los Magistrados que determine la ley para cada una de sus Salas y Secciones.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 64.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 64.1 de la LOPJ establece que la Audiencia Nacional se compondrá de &quot;su Presidente, los Presidentes de Sala y los Magistrados que determine la ley para cada una de sus Salas y Secciones.&quot;"},{"i":"8-46","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Corresponde también a ______________ autorizar, mediante auto, la entrada en los domicilios y en los restantes edificios o lugares cuyo acceso requiera el consentimiento de su titular, cuando ello proceda para la ejecución forzosa de actos de la Administración, salvo que se trate de la ejecución de medidas de protección de menores acordadas por la Entidad Pública competente en la materia.","o":["Los Juzgados de Instrucción.","Los Fiscales de Menores.","Los Jueces de lo Penal.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas.</mark></span><span class=\"ref-norma\">Art. 8.6 · De la Organización y Planta de Juzgados y Tribunales</span>. Esta competencia corresponde a los Juzgados de lo Contencioso-Administrativo, según el artículo 8.6 de la Ley de la Jurisdicción Contencioso-Administrativa (LJCA), por lo que las opciones a), b) y c) son incorrectas."},{"i":"8-50","p":"Ley Orgánica 6/1985, del Poder Judicial. Del Poder Judicial y del ejercicio de la Potestad Jurisdiccional: Señale la opción incorrecta en esta materia:","o":["Los jueces y magistrados no podrán ser separados, suspendidos, trasladados ni jubilados sino por alguna de las causas y con las garantías previstas en esta Ley.","Los jueces y magistrados responderán penal y civilmente en los casos y en la forma determinada en las Leyes, y disciplinariamente de conformidad con lo establecido en esta Ley.","Salvo casos excepcionales, se prohíben los Tribunales de honor en la Administración de Justicia.","Todos están obligados a respetar la independencia de los Jueces y Magistrados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Salvo casos excepcionales, se prohíben los Tribunales de honor en la Administración de Justicia.</mark></span><span class=\"ref-norma\">Art. 12.3 · Poder Judicial</span>. El artículo 12.3 de la LOPJ establece que &quot;Se prohíben los Tribunales de Honor en el ámbito de la Administración de Justicia&quot; de forma absoluta, sin excepción alguna. Por lo tanto, la opción que introduce una salvedad es incorrecta."},{"i":"8-51","p":"Ley Orgánica 6/1985, del Poder Judicial. El Tribunal Superior de Justicia se compondrá de: Señale la opción incorrecta.","o":["De los Presidentes de Sala.","De los Magistrados de Sección.","Un Presidente.","Los Magistrados que determine la ley para cada una de las Salas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De los Magistrados de Sección.</mark></span><span class=\"ref-norma\">Art. 77.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 77.1 de la LOPJ establece que el Tribunal Superior de Justicia se compone de: un Presidente, los Presidentes de Sala y los Magistrados que determine la ley para cada una de las Salas. Los &quot;Magistrados de Sección&quot; no es una categoría que se enumere en la composición general del Tribunal."},{"i":"8-69","p":"Según se establece en la Ley Orgánica 6/1985 del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. Sobre los ciudadanos de nacionalidad española:","o":["Podrán ejercer la acción popular, en los casos y formas establecidos en la ley.","Podrán participar en la administración de Justicia.","Podrán participar en los Tribunales consuetudinarios y tradicionales y en los demás casos previstos en esta Ley.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 19 · Poder Judicial</span>. El artículo 19 LOPJ establece que los ciudadanos españoles pueden (1) ejercer la acción popular y (2) participar en la Administración de Justicia mediante la institución del Jurado, en los Tribunales consuetudinarios y tradicionales y en los demás casos previstos en la Ley. Por lo tanto, todas son correctas."},{"i":"8-79","p":"Ley Orgánica 6/1985, de 1 de julio, del poder judicial. De la inmunidad judicial. Los Jueces y Magistrados en servicio activo solo podrán ser detenidos:","o":["Por orden de juez competente.","En caso de flagrante delito.","Por orden del presidente del tribunal.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas.</mark></span><span class=\"ref-norma\">Art. 398.1 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 398.1 LOPJ establece que los Jueces y Magistrados en servicio activo solo podrán ser detenidos por orden de Juez competente o en caso de flagrante delito."},{"i":"8-90","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la Audiencia Nacional. La Sala de Apelación de la Audiencia Nacional conocerá de los recursos de esta clase que establezca la ley contra las resoluciones de:","o":["Los Juzgados Centrales de lo Penal.","Los Juzgados Centrales de Instrucción.","Los Juzgados Centrales de Vigilancia Penitenciaria.","La Sala de lo Penal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de lo Penal.</mark></span><span class=\"ref-norma\">Art. 65 bis · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 65 bis.1 de la LOPJ indica que la Sala de Apelación de la Audiencia Nacional conocerá de los recursos de esta clase que establezca la ley contra las resoluciones de la Sala de lo Penal de la Audiencia Nacional."},{"i":"8-121","p":"Ley Orgánica 6/1985 del Poder Judicial. Los procedimientos de separación, traslado, jubilación por incapacidad permanente y rehabilitación de Jueces y Magistrados se formarán con audiencia del interesado y se resolverán por:","o":["El Ministerio de Justicia.","El Gobierno.","El Consejo General del Poder Judicial.","El Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial.</mark></span>Corresponde al Consejo General del Poder Judicial resolver los procedimientos sobre situaciones administrativas, ascensos, régimen disciplinario, etc., incluyendo la separación, traslado, jubilación por incapacidad permanente y rehabilitación de Jueces y Magistrados, con audiencia del interesado (arts. 106.1.h) y Título XV de la LOPJ)."},{"i":"8-125","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. El Presidente del Tribunal Superior de Justicia tendrá la consideración de:","o":["Presidente de Sala del Tribunal Supremo.","Magistrado del Tribunal Supremo.","Presidente de Sala de la Audiencia Nacional.","Magistrado de la Audiencia Nacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Magistrado del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 162.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El Presidente del Tribunal Superior de Justicia tendrá la consideración de Magistrado del Tribunal Supremo mientras desempeñe el cargo (art. 162.1 LOPJ)."},{"i":"8-133","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 85. ¿Quién conocerá en el orden civil de los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido?","o":["Juzgados de lo Penal.","Audiencia Nacional.","Audiencia Provincial.","Secciones Civiles de los Tribunales de Instancia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Secciones Civiles de los Tribunales de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 85 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"3.º De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido\"</span> (verificado con el texto del temario)."},{"i":"8-134","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La Audiencia Nacional se compondrá de: Señale la incorrecta.","o":["Presidente.","Vicepresidente.","Presidentes de Sala.","Magistrados que determine la ley para cada una de sus Salas y Secciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Vicepresidente</mark></span>Según el <span class=\"ref-norma\">art. 63 de la LOPJ</span>: <span class=\"ref-concepto\">\"La Audiencia Nacional se compondrá de su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y Secciones\"</span> (verificado con el texto del temario oficial)."},{"i":"8-162","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Gabinete Técnico del Tribunal Supremo. En cada una de las áreas habrá uno o varios Letrados del Gabinete Técnico que asuman funciones de coordinación de los miembros del Gabinete que formen parte de la misma. Serán designados por:","o":["El Presidente del Tribunal Supremo.","La Sala de Gobierno del Tribunal Supremo.","El Ministro de Justicia.","El Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Presidente del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 586.3 · De la Organización y Planta de Juzgados y Tribunales</span>. Los Letrados del Gabinete Técnico del Tribunal Supremo, incluidos los coordinadores de área, son designados por el Presidente del Tribunal Supremo (art. 586.3 de la L.O.P.J.)."},{"i":"8-165","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Cuál es la Sala Segunda del Tribunal Supremo?","o":["De lo Contencioso-administrativo.","De lo Civil.","De lo Penal.","De lo Social."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De lo Penal.</mark></span><span class=\"ref-norma\">Art. 55 · De la Organización y Planta de Juzgados y Tribunales</span>. La Sala Segunda del Tribunal Supremo es la de lo Penal (art. 55 de la L.O.P.J.)."},{"i":"8-175","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Señale la incorrecta sobre los Jueces de Paz.","o":["Los Jueces de Paz y sus sustitutos serán nombrados para un período de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente.","Los Jueces de Paz prestarán juramento ante el Pleno del Ayuntamiento.","En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz.","Los Jueces de Paz serán retribuidos por el sistema y en la cuantía que legalmente se establezca."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Jueces de Paz prestarán juramento ante el Pleno del Ayuntamiento</mark></span>Según el <span class=\"ref-norma\">art. 101 de la LOPJ</span>: <span class=\"ref-concepto\">\"Los Jueces de Paz prestarán juramento ante el Juez de Primera Instancia e Instrucción y tomarán posesión ante quien se hallara ejerciendo la jurisdicción\"</span> (verificado con el texto del temario oficial)."},{"i":"8-179","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los procedimientos de separación de Jueces y Magistrados se formarán con audiencia del interesado e informe del Ministerio Fiscal y de la Sala de Gobierno respectiva, sin perjuicio de las demás justificaciones que procedan, y se resolverán por:","o":["El Consejo de Ministros.","El Consejo General del Poder Judicial.","El Ministro de Justicia.","La Sala de Gobierno del Tribunal Supremo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial.</mark></span>- La LOPJ atribuye al Consejo General del Poder Judicial (CGPJ) la competencia para resolver los procedimientos de separación de Jueces y Magistrados. &amp;lt;hr&amp;gt;"},{"i":"8-182","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la Inmunidad. Señale la INCORRECTA.","o":["Las Autoridades civiles y militares no se abstendrán de detener a los Jueces y Magistrados y de citarlos para que comparezcan a su presencia.","Los Jueces y Magistrados en servicio activo sólo podrán ser detenidos por orden de Juez competente o en caso de flagrante delito.","Cuando una Autoridad civil o militar precise de datos o declaraciones que pueda facilitar un Juez o Magistrado, y que se refieran a su cargo o función, se solicitarán por escrito o se recibirán en el despacho oficial si es legal, previo aviso.","Cuando en la instrucción de una causa penal fuere necesaria la declaración de un Juez o Magistrado, y ésta pudiere prestarse legalmente, no podrá excusarse de hacerlo. Si la Autoridad Judicial que la hubiese de recibir la declaración fuere de categoría inferior, acudirá al despacho oficial del Juez o Magistrado, previo aviso, señalándose día y hora."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Autoridades civiles y militares no se abstendrán de detener a los Jueces y Magistrados y de citarlos para que comparezcan a su presenci…</mark></span>- La LOPJ establece exactamente lo contrario: las Autoridades civiles y militares se abstendrán de detener y citar a comparecer a Jueces y Magistrados (salvo las excepciones previstas en la Ley). &amp;lt;hr&amp;gt;"},{"i":"8-186","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios:","o":["A la Constitución.","A la ley.","Al principio de jerarquía normativa.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 6 · Poder Judicial</span>. - El artículo 6 de la LOPJ establece que los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios a la Constitución, a la ley o al principio de jerarquía normativa. &amp;lt;hr&amp;gt;"},{"i":"8-187","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la inamovilidad de Jueces y Magistrados. La suspensión de los Jueces y Magistrados sólo tendrá lugar en los casos siguientes: señale la INCORRECTA.","o":["Cuando se hubiere declarado haber lugar a proceder contra ellos por delitos cometidos en el ejercicio de sus funciones.","Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento.","Cuando se incoe un expediente disciplinario por la comisión de una falta muy grave, si así lo acuerda la Comisión Disciplinaria del Consejo General del Poder Judicial.","En virtud de expediente de incapacidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando se incoe un expediente disciplinario por la comisión de una falta muy grave, si así lo acuerda la Comisión Disciplinaria del Consejo General del Poder Judicial</mark></span>Según el <span class=\"ref-norma\">art. 383 de la LOPJ</span>: <span class=\"ref-concepto\">\"3.º Cuando se decretare en expediente disciplinario o de incapacidad, ya con carácter provisional, ya definitivo\"</span> (verificado con el texto del temario oficial)."},{"i":"8-191","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los Jueces y Magistrados, en el momento de tomar posesión de su primer destino, prestarán juramento o promesa ante:","o":["El Pleno del Tribunal Superior de Justicia.","El Presidente de la Audiencia Provincial.","La Sala de Gobierno del Tribunal al que pertenezcan.","El Juez o Magistrado más antiguo de la Sala de Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de Gobierno del Tribunal al que pertenezcan.</mark></span>- La LOPJ establece que los Jueces y Magistrados prestarán juramento o promesa ante la Sala de Gobierno del Tribunal al que pertenezcan (o del que dependan). &amp;lt;hr&amp;gt;"},{"i":"8-202","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la Audiencia Nacional. Señale la INCORRECTA:","o":["La Audiencia Nacional, con sede en la villa de Madrid, tiene jurisdicción en toda España.","La Audiencia Nacional se compondrá de su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y, en su caso, Secciones en que las mismas puedan arrullarse.","El Presidente de la Audiencia Nacional, que tendrá la consideración de Presidente de Sala del Tribunal Supremo, es el Presidente nato únicamente de la Sala de lo Penal.","La Audiencia Nacional se estructura en las Salas de Apelación, de lo Penal, de lo Contencioso-Administrativo y de lo Social."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Presidente de la Audiencia Nacional, que tendrá la consideración de Presidente de Sala del Tribunal Supremo, es el Presidente nato únicamente de la Sala de lo Penal</mark></span>Según el <span class=\"ref-norma\">art. 63.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"El Presidente de la Audiencia Nacional, que tendrá la consideración de Presidente de Sala del Tribunal Supremo, es el Presidente nato de todas sus Salas\"</span> (verificado con el texto del temario)."},{"i":"8-204","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la inmunidad judicial. Señale la INCORRECTA:","o":["Los Jueces y Magistrados en servicio activo sólo podrán ser detenidos por orden de Juez competente o en caso de flagrante delito.","De toda detención se dará cuenta, por el medio más rápido, al Presidente del Tribunal o de la Audiencia de quien dependa el Juez o Magistrado.","Las Autoridades civiles y militares se abstendrán de intimar a los Jueces y Magistrados y de citarlos para que comparezcan a su presencia.","Cuando se trate de auxilio o cooperación por razón del cargo o de la función jurisdiccional, se prestará con tardanza, salvo que el acto a ejecutar no esté legalmente permitido o se perjudique la competencia propia del Juez o Tribunal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuando se trate de auxilio o cooperación por razón del cargo o de la función jurisdiccional, se prestará con tardanza, salvo que el acto a …</mark></span><span class=\"ref-norma\">Art. 400 · De la Extensión y Límites de la Jurisdicción</span>. El artículo 400 de la LOPJ establece que el auxilio o cooperación se prestará con premura, no &quot;con tardanza&quot;, siendo esta la afirmación incorrecta."},{"i":"8-213","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Señale la respuesta INCORRECTA en relación con las cuestiones de competencia y las causas en el orden jurisdiccional penal que reservan al conocimiento de los Tribunales Superiores de Justicia los Estatutos de Autonomía:","o":["El conocimiento de las causas penales que los Estatutos de Autonomía reservan al conocimiento de los Tribunales Superiores de Justicia.","Las cuestiones de cesión de jurisdicción en materia penal derivadas del cumplimiento de tratados internacionales en los que España sea parte.","El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes.","La decisión de las cuestiones de competencia entre órganos jurisdiccionales del orden penal con sede en la comunidad autónoma que no tengan otro superior común."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las cuestiones de cesión de jurisdicción en materia penal derivadas del cumplimiento de tratados internacionales en los que España sea parte</mark></span>Las cuestiones de cesión de jurisdicción por tratados no figuran entre ellas. Según el <span class=\"ref-norma\">art. 73 de la LOPJ</span>: <span class=\"ref-concepto\">\"3. Como Sala de lo Penal, corresponde a esta Sala: a) El conocimiento de las causas penales que los Estatutos de Autonomía reservan al conocimiento de los Tribunales Superiores de Justicia. b) La instrucción y el fallo de las causas penales contra jueces, magistrados y miembros del Ministerio Fiscal por delitos o faltas cometidos en el ejercicio de su cargo en la comunidad autónoma, siempre que esta atribución no corresponda al Tribunal Supremo. c) El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes. d) La decisión de las cuestiones de competencia entre órganos jurisdiccionales del orden penal con sede en la comunidad autónoma que no tengan otro superior común\"</span> (verificado con el texto del temario oficial)."},{"i":"8-227","p":"Ley Orgánica 6/1985 del Poder Judicial. La separación de Jueces o Magistrados por haber incurrido en alguna de las causas de incapacidad, salvo que proceda su jubilación, se acordará previo expediente, con intervención:","o":["Del Consejo General del Estado.","Del Consejo de Estado.","Del Ministerio de Justicia.","Del Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Del Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 387.4 · Del Consejo General del Poder Judicial</span>. La separación de Jueces o Magistrados por incapacidad se acuerda por el CGPJ, previo expediente, con la intervención del Ministerio Fiscal (Art. 387.4 LOPJ)."},{"i":"8-229","p":"Ley Orgánica 6/1985 del Poder Judicial. El juicio de responsabilidad penal contra Jueces y Magistrados podrá incoarse: señale la INCORRECTA.","o":["En virtud de querella del perjudicado u ofendido.","Por denuncia del Tribunal competente.","En virtud de querella del Ministerio Fiscal.","Mediante el ejercicio de la acción popular."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por denuncia del Tribunal competente.</mark></span><span class=\"ref-norma\">Art. 407 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. La ley (Art. 407 LOPJ) establece que la incoación puede ser por providencia del Tribunal competente, y por querella del Ministerio Fiscal, del perjudicado u ofendido o mediante el ejercicio de la acción popular. El término &quot;denuncia&quot; no es la forma legal de iniciación por parte del Tribunal."},{"i":"8-240","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción y potestad jurisdiccional. El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente:","o":["A los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales.","A los jueces y magistrados integrantes del Poder Judicial y, supletoriamente, al Ministerio Fiscal en los casos previstos en la ley.","A los Tribunales y a los órganos del Consejo General del Poder Judicial determinados en las leyes orgánicas.","A los jueces y juezas de carrera, sin que puedan ejercerla los Tribunales consuetudinarios y tradicionales reconocidos en la ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales</mark></span>El <span class=\"ref-norma\">art. 2.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales.\"</span>"},{"i":"8-242","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Publicidad y Tribunales de Honor. Se prohíben:","o":["Los Tribunales de Excepción y los Tribunales consuetudinarios y tradicionales en la Administración de Justicia.","Los Tribunales de Honor y los Tribunales militares en tiempo de paz dentro del territorio nacional.","Los Tribunales de Honor en la Administración de Justicia.","Los Tribunales especiales en la Administración de Justicia, salvo el Tribunal del Jurado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Tribunales de Honor en la Administración de Justicia</mark></span>El <span class=\"ref-norma\">art. 16.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2. Se prohíben los Tribunales de Honor en la Administración de Justicia.\"</span>"},{"i":"8-245","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Participación en la Administración de Justicia. Asimismo, podrán participar en la Administración de Justicia mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales:","o":["Cuya pena máxima sea superior a cinco años de prisión.","Que determine el Consejo General del Poder Judicial.","Que se sigan ante la Audiencia Provincial de cada capital.","Que la Ley determine."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Que la Ley determine</mark></span>El <span class=\"ref-norma\">art. 19.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2. Asimismo, podrán participar en la Administración de Justicia: mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la Ley determine; en los Tribunales consuetudinarios y tradicionales y en los demás casos previstos en esta Ley.\"</span>"},{"i":"8-250","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sumisión. En aquellas materias en que una norma expresamente lo permita, los Tribunales españoles serán competentes cuando las partes, con independencia de su domicilio, se hayan sometido:","o":["Expresamente a ellos y por escrito ante notario.","Tácitamente a ellos mediante la sola presentación de la demanda.","Expresa o tácitamente a ellos.","Expresamente a ellos, siempre que alguna tenga su domicilio en España."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Expresa o tácitamente a ellos</mark></span>El <span class=\"ref-norma\">art. 22 bis.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. En aquellas materias en que una norma expresamente lo permita, los Tribunales españoles serán competentes cuando las partes, con independencia de su domicilio, se hayan sometido expresa o tácitamente a ellos.\"</span>"},{"i":"8-260","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Organización territorial. El Estado se organiza territorialmente, a efectos judiciales, en:","o":["Municipios, Comarcas, Provincias y Comunidades Autónomas.","Municipios, Partidos, Provincias y Comunidades Autónomas.","Partidos, Provincias, Comunidades Autónomas y circunscripciones nacionales.","Municipios, Partidos judiciales, Distritos y Comunidades Autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Municipios, Partidos, Provincias y Comunidades Autónomas</mark></span>El <span class=\"ref-norma\">art. 30 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Estado se organiza territorialmente, a efectos judiciales, en Municipios, Partidos, Provincias y Comunidades Autónomas.\"</span>"},{"i":"8-265","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Supremo. Conocerá además cada una de las Salas del Tribunal Supremo de las recusaciones que se interpusieren contra los Magistrados que las compongan, y de las cuestiones de competencia entre Juzgados o Tribunales:","o":["Del propio orden jurisdiccional que no tengan otro superior común.","De cualquier orden jurisdiccional que no tengan otro superior jerárquico.","Del propio orden jurisdiccional, cuando así lo decida la Sala de Gobierno.","De distinto orden jurisdiccional que no tengan otro superior común."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Del propio orden jurisdiccional que no tengan otro superior común</mark></span>El <span class=\"ref-norma\">art. 60.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. Conocerá además cada una de las Salas del Tribunal Supremo de las recusaciones que se interpusieren contra los Magistrados que las compongan, y de las cuestiones de competencia entre Juzgados o Tribunales del propio orden jurisdiccional que no tengan otro superior común.\"</span>"},{"i":"8-266","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencia Nacional. La Audiencia Nacional se compondrá de:","o":["Su Presidente, los Presidentes de Sala y un número fijo de doce magistrados por cada Sala.","Su Presidente, un Vicepresidente y los magistrados que determine el Consejo General del Poder Judicial, en los términos que determine la ley orgánica correspondiente.","Los Presidentes de Sala y los magistrados que determine la ley, sin Presidente propio.","Su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y Secciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y Secciones</mark></span>El <span class=\"ref-norma\">art. 63.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. La Audiencia Nacional se compondrá de su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y Secciones.\"</span>"},{"i":"8-284","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jubilación. Los Jueces y Magistrados sólo podrán ser jubilados:","o":["Por edad o por incapacidad permanente para el ejercicio de sus funciones.","Por edad o por incapacidad temporal prolongada para el ejercicio de sus funciones.","Por edad, por incapacidad permanente o por decisión del Consejo General del Poder Judicial.","Por incapacidad permanente para el ejercicio de sus funciones o por sanción disciplinaria."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por edad o por incapacidad permanente para el ejercicio de sus funciones</mark></span>El <span class=\"ref-norma\">art. 385 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Jueces y Magistrados sólo podrán ser jubilados: 1.º Por edad. 2.º Por incapacidad permanente para el ejercicio de sus funciones.\"</span>"},{"i":"8-289","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidad por parentesco o relaciones. Son incompatibles los Magistrados de cualquier Sala de Justicia, constituya o no sección orgánica, a la que se halle atribuido el conocimiento de los recursos respecto de las resoluciones de un órgano jurisdiccional, con los Jueces o Magistrados de dicho órgano. Se exceptúan de esta incompatibilidad:","o":["Las Salas y Secciones de la Audiencia Nacional.","Las Salas de lo Civil y Penal de los Tribunales Superiores de Justicia.","Las Salas y Secciones del Tribunal Supremo y de la Audiencia Nacional.","Las Salas y Secciones del Tribunal Supremo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las Salas y Secciones del Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 392.1.b) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Se exceptúan de esta incompatibilidad las Salas y Secciones del Tribunal Supremo.\"</span>"},{"i":"8-290","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inmunidad judicial. Los Jueces y Magistrados en servicio activo sólo podrán ser detenidos:","o":["Por orden del Consejo General del Poder Judicial o en caso de flagrante delito.","Por orden de Juez competente, sin excepción, aun en caso de flagrante delito.","Por orden de Juez competente o en caso de flagrante delito.","Por orden del Ministerio Fiscal o en caso de flagrante delito."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por orden de Juez competente o en caso de flagrante delito</mark></span>El <span class=\"ref-norma\">art. 398.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. Los Jueces y Magistrados en servicio activo sólo podrán ser detenidos por orden de Juez competente o en caso de flagrante delito. En este último caso se tomarán las medidas de aseguramiento indispensables y se entregará inmediatamente el detenido al Juez de Instrucción más próximo.\"</span>"},{"i":"8-ia-8002","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ejercicio de la potestad jurisdiccional. El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a:","o":["los jueces, a las juezas y a los Tribunales determinados en la Constitución y en las leyes orgánicas.","los jueces y Magistrados y al Consejo General del Poder Judicial en los términos de la ley.","los Tribunales previstos en la Constitución, sin perjuicio de las potestades de las Comunidades Autónomas.","los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales</mark></span>El <span class=\"ref-norma\">art. 2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"corresponde exclusivamente a los jueces, a las juezas y a los Tribunales determinados en las leyes y en los tratados internacionales\"</span>. La ley menciona «las leyes y los tratados internacionales», no la Constitución ni las leyes orgánicas en exclusiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8028","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Improrrogabilidad de la jurisdicción. En el supuesto de falta de jurisdicción, la resolución del órgano judicial será fundada y se efectuará indicando siempre:","o":["el órgano judicial concreto que se estime competente.","el orden jurisdiccional que se estime competente.","el plazo para presentar la demanda ante el órgano competente.","el recurso que proceda contra la resolución."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el orden jurisdiccional que se estime competente</mark></span>El <span class=\"ref-norma\">art. 9.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En todo caso, esta resolución será fundada y se efectuará indicando siempre el orden jurisdiccional que se estime competente\"</span>. Se indica el orden jurisdiccional, no el órgano concreto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8041","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad. En la Administración de Justicia:","o":["se prohíben los Tribunales de Honor.","se permiten los Tribunales de Honor en el ámbito de la jurisdicción militar.","se regulan los Tribunales de Honor por reglamento del Consejo General del Poder Judicial.","se admiten los Tribunales de Honor para la responsabilidad disciplinaria de Jueces y Magistrados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se prohíben los Tribunales de Honor</mark></span>El <span class=\"ref-norma\">art. 16.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Se prohíben los Tribunales de Honor en la Administración de Justicia\"</span>. Los Tribunales de Honor están prohibidos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8053","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inmunidad de jurisdicción. Los Tribunales civiles españoles no conocerán de las pretensiones formuladas respecto de sujetos o bienes que gocen:","o":["de inmunidad de jurisdicción y de ejecución de conformidad con la legislación española y las normas de Derecho Internacional Público.","de inmunidad diplomática reconocida por la Convención de Viena exclusivamente, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","de inviolabilidad personal reconocida por la Constitución.","de inmunidad de ejecución, aunque no de jurisdicción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de inmunidad de jurisdicción y de ejecución de conformidad con la legislación española y las normas de Derecho Internacional Público</mark></span>El <span class=\"ref-norma\">art. 21.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"no conocerán de las pretensiones formuladas respecto de sujetos o bienes que gocen de inmunidad de jurisdicción y de ejecución de conformidad con la legislación española y las normas de Derecho Internacional Público\"</span>. La inmunidad es de jurisdicción y de ejecución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8057","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sumisión. En aquellas materias en que una norma expresamente lo permita, los Tribunales españoles serán competentes cuando las partes, con independencia de su domicilio:","o":["se hayan sometido expresa o tácitamente a ellos.","se hayan sometido expresamente a ellos por escrito.","residan habitualmente en España en el momento de la demanda.","hayan celebrado el contrato en territorio español."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se hayan sometido expresa o tácitamente a ellos</mark></span>El <span class=\"ref-norma\">art. 22 bis.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"los Tribunales españoles serán competentes cuando las partes, con independencia de su domicilio, se hayan sometido expresa o tácitamente a ellos\"</span>. La sumisión puede ser expresa o tácita. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8160","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · terrorismo. En materia de terrorismo, se entiende por instalación oficial española:","o":["únicamente las embajadas y consulados españoles en el extranjero.","cualquier instalación permanente de la Administración española en el extranjero, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","las instalaciones militares españolas y las sedes diplomáticas.","cualquier instalación permanente o temporal en la que desarrollen sus funciones públicas autoridades o funcionarios públicos españoles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cualquier instalación permanente o temporal en la que desarrollen sus funciones públicas autoridades o funcionarios públicos españoles</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se entiende por instalación oficial española cualquier instalación permanente o temporal en la que desarrollen sus funciones públicas autoridades o funcionarios públicos españoles\"</span>. Es permanente o temporal y de autoridades o funcionarios públicos españoles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8170","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Límites a la persecución. La falta de disposición del Estado que ejerza su jurisdicción para llevar a cabo la investigación, o su incapacidad real para hacerlo, será valorada por:","o":["la Sala de lo Penal de la Audiencia Nacional.","la Sala 2.ª del Tribunal Supremo, a la que elevará exposición razonada el Juez o Tribunal.","el Consejo General del Poder Judicial.","el Ministerio Fiscal, a propuesta del juez instructor, salvo que la ley disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Sala 2.ª del Tribunal Supremo, a la que elevará exposición razonada el Juez o Tribunal</mark></span>El <span class=\"ref-norma\">art. 23.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"y así se valore por la Sala 2.ª del Tribunal Supremo, a la que elevará exposición razonada el Juez o Tribunal\"</span>. La valoración corresponde a la Sala Segunda del Tribunal Supremo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8172","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden contencioso-administrativo. En el orden contencioso-administrativo será competente, en todo caso, la jurisdicción española cuando la pretensión que se deduzca se refiera:","o":["a actos de cualquier Administración que produzcan efectos en España.","a contratos celebrados por la Administración española en el extranjero.","a las disposiciones de carácter general de las Comunidades Autónomas únicamente, sin perjuicio de lo dispuesto en otras leyes.","a disposiciones de carácter general o a actos de las Administraciones Públicas españolas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a disposiciones de carácter general o a actos de las Administraciones Públicas españolas</mark></span>El <span class=\"ref-norma\">art. 24 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"será competente, en todo caso, la jurisdicción española cuando la pretensión que se deduzca se refiera a disposiciones de carácter general o a actos de las Administraciones Públicas españolas\"</span>. Disposiciones generales o actos de las Administraciones Públicas españolas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8181","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Comunidad Autónoma. La Comunidad Autónoma será el ámbito territorial:","o":["de las Audiencias Provinciales, sin perjuicio de lo dispuesto en otras leyes.","de los Tribunales de Instancia.","de los Tribunales Superiores de Justicia.","de la Audiencia Nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de los Tribunales Superiores de Justicia</mark></span>El <span class=\"ref-norma\">art. 34 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Comunidad Autónoma será el ámbito territorial de los Tribunales Superiores de Justicia\"</span>. Las Audiencias Provinciales tienen ámbito provincial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8303","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Composición del Tribunal Supremo. El Tribunal Supremo se compondrá de su Presidente, de los Presidentes de Sala y:","o":["los Magistrados que determine el Consejo General del Poder Judicial para cada una de sus Salas, en los términos que establezca la ley orgánica.","los Vicepresidentes y los Magistrados designados por el Rey.","los Magistrados que determine la ley para cada una de las Salas y, en su caso, Secciones en que las mismas puedan articularse.","los Magistrados que nombre el Pleno del Consejo General del Poder Judicial en cada Sala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los Magistrados que determine la ley para cada una de las Salas y, en su caso, Secciones en que las mismas puedan articularse</mark></span>El <span class=\"ref-norma\">art. 54 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se compondrá de su Presidente, de los Presidentes de Sala y los Magistrados que determine la ley para cada una de las Salas y, en su caso, Secciones en que las mismas puedan articularse\"</span>. Los magistrados los determina la ley, no el CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8314","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Social del Tribunal Supremo. La Sala de lo Social del Tribunal Supremo conocerá de los recursos de casación y revisión y otros extraordinarios que establezca la ley:","o":["en materia de Seguridad Social exclusivamente.","en conflictos colectivos de ámbito superior al de una Comunidad Autónoma.","contra las sentencias de las Salas de lo Social de los Tribunales Superiores de Justicia únicamente.","en materias propias de este orden jurisdiccional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en materias propias de este orden jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 59 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conocerá de los recursos de casación y revisión y otros extraordinarios que establezca la ley en materias propias de este orden jurisdiccional\"</span>. En materias propias del orden jurisdiccional social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8315","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias comunes de las Salas. Conocerá además cada una de las Salas del Tribunal Supremo de las recusaciones que se interpusieren contra los Magistrados que las compongan, y de las cuestiones de competencia entre Juzgados o Tribunales del propio orden jurisdiccional:","o":["que no hayan sido resueltas por el Tribunal Superior de Justicia.","que se planteen entre órganos de distinto orden jurisdiccional.","que no tengan otro superior común.","que afecten a más de una Comunidad Autónoma."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">que no tengan otro superior común</mark></span>El <span class=\"ref-norma\">art. 60 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"y de las cuestiones de competencia entre Juzgados o Tribunales del propio orden jurisdiccional que no tengan otro superior común\"</span>. Solo si no tienen otro superior común. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8327","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Dirección del Gabinete Técnico. La superior dirección del Gabinete Técnico será ejercida por:","o":["el Director del Gabinete Técnico, nombrado por el Pleno del Consejo General del Poder Judicial, conforme al procedimiento que establezcan las leyes procesales.","el Secretario de Gobierno del Tribunal Supremo.","el Presidente del Tribunal Supremo o, en caso de delegación de éste, por el Vicepresidente del Tribunal Supremo.","la Sala de Gobierno del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Presidente del Tribunal Supremo o, en caso de delegación de éste, por el Vicepresidente del Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 61 ter de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La superior dirección del Gabinete Técnico será ejercida por el Presidente del Tribunal Supremo o, en caso de delegación de éste, por el Vicepresidente del Tribunal Supremo\"</span>. La dirección superior la ejerce el Presidente o, por delegación, el Vicepresidente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8332","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Funcionamiento del Gabinete Técnico. Las normas de funcionamiento del Gabinete Técnico las aprobará:","o":["el Pleno del Consejo General del Poder Judicial, a propuesta del Director.","la Sala de Gobierno, a propuesta del Presidente del Tribunal Supremo.","el Presidente del Tribunal Supremo, oído el Pleno de la Sala.","el Ministerio de Justicia, previo informe del Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Sala de Gobierno, a propuesta del Presidente del Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 61 sexies de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Sala de Gobierno, a propuesta del Presidente del Tribunal Supremo, aprobará las normas de funcionamiento del Gabinete Técnico\"</span>. Las aprueba la Sala de Gobierno a propuesta del Presidente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8334","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Composición de la Audiencia Nacional. La Audiencia Nacional se compondrá de su Presidente, los Presidentes de Sala y los magistrados que determine la ley para cada una de sus Salas y Secciones. El Presidente de la Audiencia Nacional:","o":["tendrá la consideración de Magistrado del Tribunal Supremo y presidirá la Sala de Apelación, en los términos que establezca la ley orgánica.","será nombrado por el Rey a propuesta del Gobierno.","tendrá la consideración de Vicepresidente del Tribunal Supremo.","tendrá la consideración de Presidente de Sala del Tribunal Supremo y es el Presidente nato de todas sus Salas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tendrá la consideración de Presidente de Sala del Tribunal Supremo y es el Presidente nato de todas sus Salas</mark></span>El <span class=\"ref-norma\">art. 63 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Presidente de la Audiencia Nacional, que tendrá la consideración de Presidente de Sala del Tribunal Supremo, es el Presidente nato de todas sus Salas\"</span>. Es Presidente nato de todas sus Salas y tiene la consideración de Presidente de Sala del TS. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8349","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo de la Audiencia Nacional. La Sala de lo Contencioso-Administrativo de la Audiencia Nacional conocerá de la solicitud de autorización para la declaración prevista en la disposición adicional quinta de la Ley Orgánica de Protección de Datos Personales, cuando tal solicitud sea formulada por:","o":["la Agencia Española de Protección de Datos.","el Consejo General del Poder Judicial, en los términos que establezca la ley orgánica.","el Defensor del Pueblo.","el Ministerio de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Agencia Española de Protección de Datos</mark></span>El <span class=\"ref-norma\">art. 66 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando tal solicitud sea formulada por la Agencia Española de Protección de Datos\"</span>. Si la formula el CGPJ, corresponde a la Sala Tercera del Tribunal Supremo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8354","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Composición del Tribunal Superior de Justicia. El Tribunal Superior de Justicia se compondrá de un Presidente, que lo será también de su Sala de lo Civil y Penal, y tendrá la consideración de:","o":["Presidente de Sala del Tribunal Supremo mientras desempeñe el cargo.","Vicepresidente del Consejo General del Poder Judicial.","Presidente nato de todas las Salas del Tribunal Superior de Justicia.","Magistrado del Tribunal Supremo mientras desempeñe el cargo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Magistrado del Tribunal Supremo mientras desempeñe el cargo</mark></span>El <span class=\"ref-norma\">art. 72 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Se compondrá de un Presidente, que lo será también de su Sala de lo Civil y Penal, y tendrá la consideración de Magistrado del Tribunal Supremo mientras desempeñe el cargo\"</span>. Tiene la consideración de Magistrado del Tribunal Supremo; el Presidente de la AN, de Presidente de Sala. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8452","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. La Sala de lo Civil y Penal del Tribunal Superior de Justicia conocerá, como Sala de lo Civil, de las funciones de apoyo y control del arbitraje que se establezcan en la ley, así como de las peticiones de exequátur de laudos o resoluciones arbitrales extranjeros, a no ser que:","o":["las partes hayan acordado someterse a un Tribunal de Instancia.","el laudo haya sido dictado por un árbitro de nacionalidad extranjera, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","el Tribunal Supremo haya avocado el conocimiento del asunto.","con arreglo a lo acordado en los tratados o las normas de la Unión Europea, corresponda su conocimiento a otro Juzgado o Tribunal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con arreglo a lo acordado en los tratados o las normas de la Unión Europea, corresponda su conocimiento a otro Juzgado o Tribunal</mark></span>El <span class=\"ref-norma\">art. 73.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a no ser que, con arreglo a lo acordado en los tratados o las normas de la Unión Europea, corresponda su conocimiento a otro Juzgado o Tribunal\"</span>. La excepción son los tratados o normas de la Unión que atribuyan el conocimiento a otro órgano. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8453","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. La Sala de lo Civil y Penal del Tribunal Superior de Justicia conocerá en única instancia de las demandas de responsabilidad civil, por hechos cometidos en el ejercicio de su cargo, contra:","o":["cualquier magistrado de una Audiencia Provincial.","los jueces de instrucción de la comunidad autónoma.","todos o la mayor parte de los magistrados de una Audiencia Provincial o de cualesquiera de sus secciones.","los Presidentes de las Audiencias Provinciales exclusivamente, sin perjuicio de lo dispuesto en otras leyes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todos o la mayor parte de los magistrados de una Audiencia Provincial o de cualesquiera de sus secciones</mark></span>El <span class=\"ref-norma\">art. 73.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En única instancia, de las demandas de responsabilidad civil, por hechos cometidos en el ejercicio de su cargo, contra todos o la mayor parte de los magistrados de una Audiencia Provincial o de cualesquiera de sus secciones\"</span>. Solo contra todos o la mayor parte de los magistrados de una Audiencia Provincial o sus secciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8458","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. Corresponde igualmente a la Sala de lo Civil y Penal del Tribunal Superior de Justicia la decisión de las cuestiones de competencia entre Secciones de Menores de Tribunales de Instancia:","o":["radicados en distintas comunidades autónomas, en los términos que establezca la ley orgánica.","radicados en distintas provincias de la comunidad autónoma.","con sede en la misma provincia.","radicados en la capital de la comunidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">radicados en distintas provincias de la comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 73.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"la decisión de las cuestiones de competencia entre Secciones de Menores de Tribunales de Instancia radicados en distintas provincias de la comunidad autónoma\"</span>. Si están en la misma provincia, lo decide la Audiencia Provincial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8462","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los recursos que se deduzcan en relación con las disposiciones generales emanadas:","o":["de las Entidades locales exclusivamente.","de las comunidades autónomas y de las Entidades locales.","de la Administración General del Estado en el ámbito de la comunidad autónoma.","de las comunidades autónomas y de los Ministerios con competencias transferidas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de las comunidades autónomas y de las Entidades locales</mark></span>El <span class=\"ref-norma\">art. 74.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"b) Las disposiciones generales emanadas de las comunidades autónomas y de las Entidades locales\"</span>. Disposiciones generales de las comunidades autónomas y de las Entidades locales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8482","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Composición de las Audiencias Provinciales. Cuando el escaso número de asuntos de que conozca una Audiencia Provincial lo aconseje, podrá constar su plantilla de uno a dos magistrados, incluido el Presidente. En este caso, la Audiencia Provincial se completará para el enjuiciamiento y fallo con el número de magistrados que se precisen:","o":["de la Audiencia Nacional, mediante turno de reparto.","del Tribunal Superior de Justicia, para lo cual la Sala de Gobierno establecerá un turno para cada año judicial.","del Tribunal Supremo, mediante designación de su Presidente.","de otra Audiencia Provincial, por acuerdo del Consejo General del Poder Judicial, en los términos que establezca la ley orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del Tribunal Superior de Justicia, para lo cual la Sala de Gobierno establecerá un turno para cada año judicial</mark></span>El <span class=\"ref-norma\">art. 81.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se completará para el enjuiciamiento y fallo, y cuando la naturaleza de la resolución a dictar lo exija, con el número de magistrados que se precisen del Tribunal Superior de Justicia. A estos efectos, la Sala de Gobierno establecerá un turno para cada año judicial\"</span>. Magistrados del TSJ, con turno anual de la Sala de Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8489","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias civiles de las Audiencias Provinciales. Para el conocimiento de los recursos contra resoluciones de las Secciones Civiles de los Tribunales de Instancia que se sigan por los trámites del juicio verbal por razón de la cuantía, la Audiencia Provincial se constituirá:","o":["con tres magistrados, designados por el Presidente, salvo que la ley disponga otra cosa.","con la Sección Civil completa.","con un solo magistrado o magistrada, mediante un turno de reparto.","con el Presidente y dos magistrados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con un solo magistrado o magistrada, mediante un turno de reparto</mark></span>El <span class=\"ref-norma\">art. 82.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"la Audiencia se constituirá con un solo magistrado o magistrada, mediante un turno de reparto\"</span>. Juicio verbal por cuantía: un solo magistrado por turno de reparto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8494","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurado. El juicio del Jurado se celebrará en el ámbito de la Audiencia Provincial u otros Tribunales y en la forma que establezca la ley. La composición y competencia del Jurado es la regulada:","o":["en la Ley de Enjuiciamiento Criminal, sin perjuicio de lo dispuesto en otras leyes.","en la Ley Orgánica del Tribunal del Jurado.","en el Código Penal.","en esta misma ley orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en la Ley Orgánica del Tribunal del Jurado</mark></span>El <span class=\"ref-norma\">art. 83 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La composición y competencia del Jurado es la regulada en la Ley Orgánica del Tribunal del Jurado\"</span>. La remisión es a la LO del Tribunal del Jurado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8499","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Adscripción funcional. La adscripción de los jueces, las juezas, los magistrados y las magistradas a las Secciones que integren los Tribunales de Instancia será:","o":["funcional.","orgánica.","temporal.","definitiva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">funcional</mark></span>El <span class=\"ref-norma\">art. 84.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Su adscripción a las referidas Secciones será funcional\"</span>. La adscripción es funcional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8501","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Extensión de jurisdicción. Se podrá establecer que algunas de las Secciones que integren los Tribunales de Instancia extiendan su jurisdicción a uno o varios partidos judiciales de la misma provincia, o de varias provincias limítrofes:","o":["dentro de la misma comunidad autónoma o de comunidades limítrofes.","dentro del ámbito de una misma Audiencia Provincial.","dentro del ámbito de un mismo Tribunal Superior de Justicia.","sin limitación territorial alguna."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dentro del ámbito de un mismo Tribunal Superior de Justicia</mark></span>El <span class=\"ref-norma\">art. 84.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"o de varias provincias limítrofes dentro del ámbito de un mismo Tribunal Superior de Justicia\"</span>. El límite es el ámbito de un mismo TSJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8601","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Procesos complejos. En el Tribunal de Instancia se podrá nombrar a dos de sus jueces, juezas, magistrados o magistradas, conforme a un turno anual preestablecido y público, para que, junto con aquel o aquella a quien le hubiere sido turnado el asunto inicialmente, se encarguen de la instrucción de un determinado proceso penal o conozcan en primera instancia de un procedimiento de cualquier orden jurisdiccional cuando, en atención al volumen, la especial complejidad o el número de intervinientes de un procedimiento:","o":["tal nombramiento favorezca el ejercicio de la función jurisdiccional.","lo solicite el Ministerio Fiscal o alguna de las partes.","lo acuerde la Sala de Gobierno del Tribunal Superior de Justicia, en los términos que establezca la ley orgánica.","el procedimiento supere los dos años de tramitación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tal nombramiento favorezca el ejercicio de la función jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 84.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando, en atención al volumen, la especial complejidad o el número de intervinientes de un procedimiento, tal nombramiento favorezca el ejercicio de la función jurisdiccional\"</span>. Se justifica por volumen, complejidad o número de intervinientes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8603","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Procesos complejos. Los jueces nombrados para un procedimiento complejo conocerán de dicho procedimiento hasta su completa terminación, sin perjuicio de que:","o":["queden exentos de reparto de nuevos asuntos, conforme al procedimiento que establezcan las leyes procesales.","puedan ser sustituidos cada seis meses.","se les puedan seguir repartiendo otros asuntos.","queden adscritos a la Audiencia Provincial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se les puedan seguir repartiendo otros asuntos</mark></span>El <span class=\"ref-norma\">art. 84.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Estos jueces, juezas, magistrados o magistradas conocerán de dicho procedimiento hasta su completa terminación, sin perjuicio de que se les puedan seguir repartiendo otros asuntos\"</span>. Conocen hasta la terminación y siguen recibiendo reparto de otros asuntos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8605","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección Civil. Las Secciones Civiles de los Tribunales de Instancia conocerán, en el orden civil, en primera instancia:","o":["de los juicios que no vengan atribuidos por esta ley a otros órganos judiciales.","de todos los juicios de cuantía inferior a seis mil euros.","de los juicios sobre derechos reales inmobiliarios exclusivamente, sin perjuicio de lo dispuesto en otras leyes.","de los juicios que determine la Sala de Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de los juicios que no vengan atribuidos por esta ley a otros órganos judiciales</mark></span>El <span class=\"ref-norma\">art. 85 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"1.º En primera instancia, de los juicios que no vengan atribuidos por esta ley a otros órganos judiciales\"</span>. Tienen competencia residual en primera instancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8608","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. Cuando se estime conveniente, en función de la carga de trabajo, se creará en el Tribunal de Instancia una Sección de Familia, Infancia y Capacidad, que extenderá su jurisdicción:","o":["a toda la provincia.","a todo el partido judicial.","a dos partidos judiciales.","a la capital de la provincia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a todo el partido judicial</mark></span>El <span class=\"ref-norma\">art. 86.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se creará en el Tribunal de Instancia una Sección de Familia, Infancia y Capacidad, que extenderá su jurisdicción a todo el partido judicial\"</span>. Jurisdicción en todo el partido judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8609","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. El Gobierno podrá establecer por real decreto, a propuesta del Consejo General del Poder Judicial y, en su caso, con informe favorable de la comunidad autónoma con competencias en materia de Justicia, Secciones de Familia, Infancia y Capacidad que extiendan su jurisdicción:","o":["a dos o más partidos dentro de la misma provincia.","a toda la comunidad autónoma.","a dos o más provincias limítrofes.","a toda la provincia en que se ubiquen, conforme al procedimiento que establezcan las leyes procesales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a dos o más partidos dentro de la misma provincia</mark></span>El <span class=\"ref-norma\">art. 86.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Secciones de Familia, Infancia y Capacidad que extiendan su jurisdicción a dos o más partidos dentro de la misma provincia\"</span>. Dos o más partidos dentro de la misma provincia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8644","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Instrucción. Las Secciones de Instrucción y las Secciones Únicas conocerán de la autorización del internamiento de extranjeros en los centros de internamiento, así como del control de la estancia de éstos en los mismos y en:","o":["las dependencias policiales de los puertos y aeropuertos.","las salas de inadmisión de fronteras.","los centros de acogida de refugiados.","los establecimientos penitenciarios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las salas de inadmisión de fronteras</mark></span>El <span class=\"ref-norma\">art. 88.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"así como del control de la estancia de éstos en los mismos y en las salas de inadmisión de fronteras\"</span>. También las salas de inadmisión de fronteras. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8645","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Instrucción. Los procedimientos de revisión de medidas por modificación de circunstancias podrán ser tramitados:","o":["por el juez o jueza inicialmente competente.","por el Presidente de la Sección de Instrucción.","por la Sección de Familia en todo caso.","por el Ministerio Fiscal con autorización judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por el juez o jueza inicialmente competente</mark></span>El <span class=\"ref-norma\">art. 88.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los procedimientos de revisión de medidas por modificación de circunstancias podrán ser tramitados por el juez o jueza inicialmente competente\"</span>. Por el juez inicialmente competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8647","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Agrupación de Secciones de Instrucción. Para acordar la agrupación de Secciones de Instrucción de varios partidos judiciales será necesario contar con la propuesta o informe tanto de la Sala de Gobierno del Tribunal Superior de Justicia correspondiente como de:","o":["la Fiscalía de la Audiencia Provincial.","los Colegios de Abogados de las poblaciones afectadas, sin perjuicio de lo dispuesto en otras leyes.","las Juntas de Jueces y Juezas de las poblaciones afectadas.","las Diputaciones Provinciales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las Juntas de Jueces y Juezas de las poblaciones afectadas</mark></span>El <span class=\"ref-norma\">art. 88.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Para acordar dicha agrupación será necesario contar con la propuesta o informe tanto de la Sala de Gobierno del Tribunal Superior de Justicia correspondiente como de las Juntas de Jueces y Juezas de las poblaciones afectadas\"</span>. Sala de Gobierno del TSJ y Juntas de Jueces. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8751","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Agrupación de Secciones de Instrucción. La agrupación de Secciones de Instrucción de varios partidos judiciales estará presidida por el Presidente o la Presidenta del Tribunal de Instancia:","o":["del partido judicial con mayor número de habitantes.","del partido judicial que designe el Consejo General del Poder Judicial.","de la capital de la provincia.","del partido judicial con mayor número de asuntos penales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del partido judicial con mayor número de habitantes</mark></span>El <span class=\"ref-norma\">art. 88.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"estará presidida por el Presidente o la Presidenta del Tribunal de Instancia del partido judicial con mayor número de habitantes\"</span>. Preside el del partido con mayor número de habitantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8752","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Agrupación de Secciones de Instrucción. Las normas para el reparto de asuntos concretos materia de la agrupación de Secciones de Instrucción se aprobarán posteriormente por:","o":["el Consejo General del Poder Judicial, en los términos que establezca la ley orgánica.","el Ministerio de Justicia.","la Junta de Jueces de la agrupación.","la Sala de Gobierno del Tribunal Superior de Justicia respectivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Sala de Gobierno del Tribunal Superior de Justicia respectivo</mark></span>El <span class=\"ref-norma\">art. 88.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"elaborará las normas para el reparto de asuntos concretos materia de la agrupación, que posteriormente se aprobarán por la Sala de Gobierno del Tribunal Superior de Justicia respectivo\"</span>. Las aprueba la Sala de Gobierno del TSJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8755","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer. Cuando se estime conveniente, en función de la carga de trabajo, se creará en el Tribunal de Instancia una Sección de Violencia sobre la Mujer, que extenderá su jurisdicción:","o":["a todo el partido judicial.","a toda la provincia.","a la capital y su comarca, conforme al procedimiento que establezcan las leyes procesales.","a la comunidad autónoma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a todo el partido judicial</mark></span>El <span class=\"ref-norma\">art. 89.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se creará en el Tribunal de Instancia una Sección de Violencia sobre la Mujer, que extenderá su jurisdicción a todo el partido judicial\"</span>. Todo el partido judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8756","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer. El Gobierno podrá establecer por real decreto, a propuesta del Consejo General del Poder Judicial y, en su caso, con informe de la comunidad autónoma con competencias en materia de Justicia, Secciones de Violencia sobre la Mujer que extiendan su jurisdicción:","o":["a toda la provincia.","a dos o más provincias limítrofes, sin perjuicio de lo dispuesto en otras leyes.","a toda la comunidad autónoma.","a dos o más partidos dentro de la misma provincia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a dos o más partidos dentro de la misma provincia</mark></span>El <span class=\"ref-norma\">art. 89.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Secciones de Violencia sobre la Mujer que extiendan su jurisdicción a dos o más partidos dentro de la misma provincia\"</span>. Dos o más partidos de la misma provincia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8771","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Dependencias judiciales. El Consejo General del Poder Judicial deberá estudiar la necesidad o carencia de dependencias que impidan la confrontación de la víctima y el agresor durante el proceso, así como impulsar su creación, en colaboración con:","o":["el Ministerio de Justicia y las comunidades autónomas competentes.","el Ministerio del Interior y los Ayuntamientos.","la Fiscalía General del Estado y los Colegios de Abogados, sin perjuicio de lo dispuesto en otras leyes.","el Defensor del Pueblo y las Delegaciones del Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Ministerio de Justicia y las comunidades autónomas competentes</mark></span>El <span class=\"ref-norma\">art. 89.10 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"impulsar, en su caso, la creación de las mismas, en colaboración con el Ministerio de Justicia y las comunidades autónomas competentes\"</span>. Ministerio de Justicia y comunidades autónomas competentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8773","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia contra la Infancia y la Adolescencia. Cuando se estime conveniente, en función de la carga de trabajo, se creará en el Tribunal de Instancia una Sección de Violencia contra la Infancia y la Adolescencia, que extenderá su jurisdicción:","o":["a toda la provincia.","a la capital y su comarca, sin perjuicio de lo dispuesto en otras leyes.","a todo el partido judicial.","a dos o más partidos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a todo el partido judicial</mark></span>El <span class=\"ref-norma\">art. 89 bis.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se creará en el Tribunal de Instancia una Sección de Violencia contra la Infancia y la Adolescencia, que extenderá su jurisdicción a todo el partido judicial\"</span>. Todo el partido judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8783","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Menores. Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, y con jurisdicción en toda ella, existirá una Sección de Menores. No obstante, cuando el volumen de trabajo lo aconseje, podrán establecerse Secciones de Menores cuya jurisdicción se extienda a un partido, a una agrupación de partidos o:","o":["a dos o más provincias de la misma comunidad autónoma.","a toda la comunidad autónoma en todo caso.","a dos o más comunidades autónomas.","a una provincia y a las limítrofes de otra comunidad, sin perjuicio de lo dispuesto en otras leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a dos o más provincias de la misma comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 91.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuya jurisdicción se extienda o bien a un partido determinado o agrupación de partidos, o bien a dos o más provincias de la misma comunidad autónoma\"</span>. Dos o más provincias de la misma comunidad autónoma. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8787","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Vigilancia Penitenciaria. Podrán establecerse Secciones de Vigilancia Penitenciaria en Tribunales de Instancia que tengan su sede en poblaciones distintas de la capital de provincia. El Gobierno establecerá la sede de estas Secciones, previa audiencia:","o":["de la comunidad autónoma afectada y del Consejo General del Poder Judicial.","del Ministerio del Interior y de la Fiscalía General del Estado.","del Tribunal Superior de Justicia y del Ayuntamiento afectado.","del Consejo General del Poder Judicial y de la Dirección General de Instituciones Penitenciarias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de la comunidad autónoma afectada y del Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 92.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Gobierno establecerá la sede de estas Secciones, previa audiencia de la comunidad autónoma afectada y del Consejo General del Poder Judicial\"</span>. Audiencia de la comunidad autónoma y del CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8789","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Vigilancia Penitenciaria. El juez, jueza, magistrado o magistrada destinado o destinada en una Sección de Vigilancia Penitenciaria podrá:","o":["ejercer, además, funciones en las Secciones civiles del Tribunal.","desempeñar la Presidencia del Tribunal de Instancia simultáneamente, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","compatibilizar las funciones propias de esta Sección con las de otras Secciones del orden jurisdiccional penal del mismo Tribunal de Instancia.","actuar como juez de guardia con carácter permanente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">compatibilizar las funciones propias de esta Sección con las de otras Secciones del orden jurisdiccional penal del mismo Tribunal de Instancia</mark></span>El <span class=\"ref-norma\">art. 92.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrá compatibilizar las funciones propias de esta Sección con las de otras Secciones del orden jurisdiccional penal del mismo Tribunal de Instancia\"</span>. Solo con otras Secciones del orden penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8791","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Contencioso-Administrativo. También podrán crearse excepcionalmente Secciones de lo Contencioso-Administrativo:","o":["que extiendan su jurisdicción a más de una provincia dentro de la misma comunidad autónoma.","que extiendan su jurisdicción a toda la comunidad autónoma, conforme al procedimiento que establezcan las leyes procesales.","con sede en poblaciones de más de cien mil habitantes.","con jurisdicción en dos comunidades autónomas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que extiendan su jurisdicción a más de una provincia dentro de la misma comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 93.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"También podrán crearse excepcionalmente Secciones de lo Contencioso-Administrativo que extiendan su jurisdicción a más de una provincia dentro de la misma comunidad autónoma\"</span>. Más de una provincia dentro de la misma comunidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8909","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de plazas. El Consejo General del Poder Judicial, con informe favorable del Ministerio de Justicia y, en su caso, de la comunidad autónoma, oída la Sala de Gobierno del Tribunal Superior de Justicia, podrá acordar la especialización de una o varias plazas judiciales de Tribunales de Instancia de la misma provincia y del mismo orden jurisdiccional, estén o no en el mismo partido judicial, asumiendo las personas destinadas en ellas el conocimiento de determinadas materias:","o":["por tiempo determinado.","con carácter indefinido.","durante dos años improrrogables.","mientras dure la carga de trabajo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por tiempo determinado</mark></span>El <span class=\"ref-norma\">art. 96.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"asumiendo por tiempo determinado las personas destinadas en ellas el conocimiento de determinadas materias o clases de asuntos\"</span>. Por tiempo determinado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8927","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Pérdida de la condición de Juez. La separación por pérdida de la nacionalidad española, sanción disciplinaria, condena por delito doloso e incapacidad se acordará:","o":["de oficio, sin audiencia del interesado.","previo informe del Tribunal Supremo.","previo expediente, con intervención del Ministerio Fiscal.","por acuerdo del Pleno de la Sala de Gobierno, salvo que la ley disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">previo expediente, con intervención del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 379.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La separación en los casos previstos en las letras b), c), d) y e) del apartado anterior se acordará previo expediente, con intervención del Ministerio Fiscal\"</span>. Requiere expediente con intervención del Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8933","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jubilación. Los Jueces y Magistrados sólo podrán ser jubilados:","o":["por edad y por incapacidad permanente para el ejercicio de sus funciones.","por edad y por sanción disciplinaria.","por incapacidad temporal prolongada y por edad, sin perjuicio de lo dispuesto en otras leyes.","por edad y por decisión del Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por edad y por incapacidad permanente para el ejercicio de sus funciones</mark></span>El <span class=\"ref-norma\">art. 385 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Jueces y Magistrados sólo podrán ser jubilados: 1.º Por edad. 2.º Por incapacidad permanente para el ejercicio de sus funciones\"</span>. Dos causas: edad e incapacidad permanente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9051","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidades. Serán incompatibles, cuando concurra entre ellos alguna de las relaciones de matrimonio, situación equivalente o parentesco hasta el segundo grado, los Presidentes y Magistrados de la Sala de lo Penal de la Audiencia Nacional y los de las Audiencias Provinciales, respecto de los miembros del Ministerio Fiscal de la correspondiente Fiscalía, salvo cuando:","o":["en la Audiencia Provincial hubiere más de tres secciones.","en la Audiencia hubiere más de dos secciones.","la Fiscalía cuente con más de diez fiscales.","el Fiscal no intervenga en el mismo procedimiento, en los términos que establezca la ley orgánica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en la Audiencia Provincial hubiere más de tres secciones</mark></span>El <span class=\"ref-norma\">art. 392.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"salvo cuando en la Audiencia Provincial hubiere más de tres secciones\"</span>. La salvedad es que la Audiencia Provincial tenga más de tres secciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9052","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidades. Serán incompatibles, cuando concurra entre ellos alguna de las relaciones de matrimonio o parentesco hasta el segundo grado, los Presidentes, Magistrados y Jueces respecto de:","o":["los Procuradores que actúen ante su órgano jurisdiccional.","los miembros de las Fuerzas y Cuerpos de Seguridad de su partido, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","los peritos designados en sus procedimientos.","los Secretarios y demás personal al servicio de la Administración de Justicia que dependan de ellos directamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los Secretarios y demás personal al servicio de la Administración de Justicia que dependan de ellos directamente</mark></span>El <span class=\"ref-norma\">art. 392.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"d) Los Presidentes, Magistrados y Jueces respecto de los Secretarios y demás personal al servicio de la Administración de Justicia que dependan de ellos directamente\"</span>. Personal al servicio de la Administración de Justicia que dependa directamente de ellos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9054","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Prohibiciones de desempeño del cargo. No podrán los jueces desempeñar su cargo en una Audiencia Provincial o Tribunal de Instancia que comprenda dentro de su circunscripción una población en la que, por poseer el mismo, su cónyuge o parientes de segundo grado de consanguinidad intereses económicos, tengan arraigo que pueda obstaculizarles el imparcial ejercicio de la función jurisdiccional. Se exceptúan:","o":["las poblaciones superiores a cincuenta mil habitantes.","las poblaciones superiores a cien mil habitantes en las que radique la sede del órgano jurisdiccional.","las capitales de provincia.","las poblaciones en que el interés económico sea inferior a un importe fijado, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las poblaciones superiores a cien mil habitantes en las que radique la sede del órgano jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 393.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Se exceptúan las poblaciones superiores a cien mil habitantes en las que radique la sede del órgano jurisdiccional\"</span>. Poblaciones de más de cien mil habitantes sede del órgano. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9070","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Asociación profesional. Las asociaciones profesionales de jueces y magistrados quedarán válidamente constituidas desde que se inscriban en el registro que será llevado al efecto por:","o":["el Ministerio de Justicia.","el Consejo General del Poder Judicial.","el Tribunal Supremo.","el Ministerio del Interior, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 401 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"quedarán válidamente constituidas desde que se inscriban en el registro que será llevado al efecto por el Consejo General del Poder Judicial\"</span>. El registro lo lleva el CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9082","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad penal. El juicio de responsabilidad penal contra Jueces y Magistrados podrá incoarse por providencia del Tribunal competente o en virtud de querella:","o":["del Consejo General del Poder Judicial exclusivamente.","del Ministerio Fiscal, o del perjudicado u ofendido, o mediante el ejercicio de la acción popular.","del Ministerio Fiscal exclusivamente.","del perjudicado u ofendido, previa autorización del Tribunal Supremo, salvo que la ley disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del Ministerio Fiscal, o del perjudicado u ofendido, o mediante el ejercicio de la acción popular</mark></span>El <span class=\"ref-norma\">art. 406 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrá incoarse por providencia del Tribunal competente o en virtud de querella del Ministerio Fiscal, o del perjudicado u ofendido, o mediante el ejercicio de la acción popular\"</span>. Providencia del Tribunal o querella del Fiscal, del perjudicado o por acción popular. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9085","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad penal. Cuando el Consejo General del Poder Judicial, el Gobierno u otro órgano o autoridad del Estado o de una Comunidad Autónoma considere que un Juez o Magistrado ha realizado, en el ejercicio de su cargo, un hecho que puede ser constitutivo de delito o falta, lo pondrá en conocimiento:","o":["del Tribunal Supremo para que incoe la causa.","de la Sala de Gobierno del Tribunal Superior de Justicia.","del Ministerio Fiscal por si procediere el ejercicio de la acción penal.","del Presidente del Tribunal en que el Juez preste servicio, en los términos que establezca la ley orgánica."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">del Ministerio Fiscal por si procediere el ejercicio de la acción penal</mark></span>El <span class=\"ref-norma\">art. 409 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"lo pondrá en conocimiento del Ministerio Fiscal por si procediere el ejercicio de la acción penal, sin perjuicio de lo dispuesto en el artículo 406\"</span>. Se comunica al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9104","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Dirección de la Policía Judicial. En las funciones de investigación penal, la Policía Judicial actuará:","o":["bajo la dirección del Ministerio del Interior.","bajo la dirección exclusiva del Ministerio Fiscal, en los términos que establezca la ley orgánica.","con autonomía funcional respecto de los jueces.","bajo la dirección de los juzgados y tribunales y del Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">bajo la dirección de los juzgados y tribunales y del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 550.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En las funciones de investigación penal, la Policía Judicial actuará bajo la dirección de los juzgados y tribunales y del Ministerio Fiscal\"</span>. Bajo la dirección de juzgados, tribunales y Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9106","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Independencia judicial. Según la LOPJ, están obligados a respetar la independencia de los Jueces y Magistrados:","o":["las Administraciones Públicas.","los poderes públicos exclusivamente.","todos.","los miembros del Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todos</mark></span>El <span class=\"ref-norma\">art. 13 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Todos están obligados a respetar la independencia de los Jueces y Magistrados.\"</span> Todos."},{"i":"8-ia-9122","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La Comunidad Autónoma. La Comunidad Autónoma será el ámbito territorial de:","o":["las Audiencias Provinciales, sin perjuicio de lo que establezcan los tratados internacionales.","los Tribunales Superiores de Justicia.","los Juzgados de lo Penal.","la Audiencia Nacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los Tribunales Superiores de Justicia</mark></span>El <span class=\"ref-norma\">art. 34 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Comunidad Autónoma será el ámbito territorial de los Tribunales Superiores de Justicia.\"</span> Los TSJ."},{"i":"8-ia-9133","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Composición del Tribunal Supremo. El Tribunal Supremo se compondrá de su Presidente, de los Presidentes de Sala y de:","o":["los Vocales del Consejo General del Poder Judicial, salvo que el órgano competente acuerde otra cosa de forma motivada.","los Fiscales de Sala.","los Letrados de la Administración de Justicia.","los Magistrados que determine la ley para cada una de las Salas y, en su caso, Secciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los Magistrados que determine la ley para cada una de las Salas y, en su caso, Secciones</mark></span>El <span class=\"ref-norma\">art. 54 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"los Magistrados que determine la ley para cada una de las Salas y, en su caso, Secciones en que las mismas puedan articularse.\"</span> Presidente, Presidentes de Sala y Magistrados."},{"i":"8-ia-9144","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Rehabilitación. Quienes hubieren perdido la condición de Juez o Magistrado por determinadas causas podrán solicitar su rehabilitación del:","o":["Consejo General del Poder Judicial.","Ministerio de Justicia, sin perjuicio de lo que establezcan los tratados internacionales.","Tribunal Supremo.","Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 380 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrán solicitar del Consejo General del Poder Judicial su rehabilitación\"</span> Se solicita al CGPJ."},{"i":"8-ia-9146","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Deber de reserva. Los Jueces y Magistrados no podrán revelar los hechos o noticias referentes a personas físicas o jurídicas de los que hayan tenido conocimiento:","o":["en el ámbito privado.","en el ejercicio de sus funciones.","durante los diez años posteriores a su jubilación.","en actuaciones secretas exclusivamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en el ejercicio de sus funciones</mark></span>El <span class=\"ref-norma\">art. 396 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"de los que hayan tenido conocimiento en el ejercicio de sus funciones.\"</span> Lo conocido en el ejercicio de sus funciones."},{"i":"8-ia-9147","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ámbito de las asociaciones. Las asociaciones profesionales de jueces y magistrados deberán tener ámbito nacional, sin perjuicio de la existencia de secciones cuyo ámbito coincida con:","o":["el de una provincia.","el de una Audiencia Provincial, salvo que el órgano competente acuerde otra cosa de forma motivada.","el de un Tribunal Superior de Justicia.","el de un Partido Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el de un Tribunal Superior de Justicia</mark></span>El <span class=\"ref-norma\">art. 401 (regla 3.ª) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"sin perjuicio de la existencia de secciones cuyo ámbito coincida con el de un Tribunal Superior de Justicia.\"</span> Ámbito nacional, con secciones por TSJ."},{"i":"8-ia-9155","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Comunicación de posibles delitos. Cuando otras Autoridades judiciales tuvieren conocimiento de la posible comisión de un delito por un Juez o Magistrado en el ejercicio de su cargo, lo comunicarán al Juez o Tribunal competente, oído:","o":["el Consejo General del Poder Judicial.","el propio Juez afectado.","el Ministerio Fiscal.","la Sala de Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 408 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"lo comunicarán al Juez o Tribunal competente, oído el Ministerio Fiscal, con remisión de los antecedentes necesarios.\"</span> Se oye al Ministerio Fiscal."}]},{"a":"Artículo 29 ✱","q":[{"i":"8-10","p":". Ley Orgánica 6/1985, del Poder Judicial. La planta de los juzgados y tribunales se establecerá por ley. Será revisada, al menos, cada ________, previo informe del Consejo General del Poder Judicial, para adaptarla a las nuevas necesidades.","o":["Dos años.","Tres años.","Cuatro años.","Cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco años.</mark></span><span class=\"ref-norma\">Art. 37.5 · Del Consejo General del Poder Judicial</span>. La LOPJ (art. 37.5) establece que la demarcación judicial (que incluye la planta de juzgados y tribunales) será revisada, al menos, cada cinco años, o antes si las circunstancias lo aconsejan."},{"i":"8-55","p":"Ley Orgánica 6/1985, del Poder Judicial. La planta de los juzgados y tribunales se establecerá por ley. Será revisada, previo informe del Consejo General del Poder Judicial, para adaptarla a las nuevas necesidades:","o":["Al menos, cada cuatro años.","Cada cuatro años.","Al menos, cada cinco años.","Cada cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al menos, cada cinco años.</mark></span><span class=\"ref-norma\">Art. 48.3 · Del Consejo General del Poder Judicial</span>. El artículo 48.3 de la LOPJ establece que la planta de los juzgados y tribunales será revisada por Ley, previo informe del Consejo General del Poder Judicial, para adaptarla a las nuevas necesidades, al menos, cada cinco años."},{"i":"8-100","p":"¿Con qué periodicidad será objeto de revisión la planta de Juzgados y Tribunales, conforme a la Ley Orgánica del Poder Judicial?","o":["Al menos cada diez años.","Al menos cada cinco años.","Cada vez que se aprueben los Presupuestos Generales del Estado.","Cada cuatro años, coincidiendo con la renovación del Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al menos cada cinco años.</mark></span><span class=\"ref-norma\">Art. 36.3 · Poder Judicial</span>. El artículo 36.3 de la LOPJ establece que la planta de Juzgados y Tribunales será revisada al menos cada cinco años."},{"i":"8-270","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Superior de Justicia. El Tribunal Superior de Justicia tomará el nombre de la Comunidad Autónoma y extenderá su jurisdicción:","o":["Al ámbito de la provincia en que tenga su sede.","Al ámbito de la Comunidad Autónoma y de las ciudades con Estatuto de Autonomía limítrofes.","Al ámbito territorial de ésta.","Al ámbito territorial de ésta, salvo en el orden contencioso-administrativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al ámbito territorial de ésta</mark></span>El <span class=\"ref-norma\">art. 71 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Superior de Justicia tomará el nombre de la Comunidad Autónoma y extenderá su jurisdicción al ámbito territorial de ésta.\"</span>"},{"i":"8-ia-8178","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Planta. La planta de los tribunales se establecerá por ley y será revisada con base en la evolución de las cargas de trabajo, población y otros parámetros que se consideren relevantes, al menos:","o":["cada tres años, previo informe del Consejo General del Poder Judicial, en los términos que establezca la ley orgánica.","cada cinco años, previo informe del Consejo General del Poder Judicial.","cada diez años, previo informe del Ministerio de Justicia.","cada cinco años, previo informe de las Comunidades Autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cada cinco años, previo informe del Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 29 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Será revisada con base en la evolución de las cargas de trabajo, población y otros parámetros que se consideren relevantes, al menos, cada cinco años, previo informe del Consejo General del Poder Judicial\"</span>. Revisión al menos quinquenal, previo informe del CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8179","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Planta. La revisión de la planta de los tribunales podrá ser instada:","o":["por las comunidades autónomas con competencia en materia de Justicia para adaptarla a las necesidades de su ámbito territorial.","por los Tribunales Superiores de Justicia para adaptarla a la carga de trabajo.","por el Consejo General del Poder Judicial, previo informe del Ministerio de Justicia, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","por los colegios profesionales de abogados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por las comunidades autónomas con competencia en materia de Justicia para adaptarla a las necesidades de su ámbito territorial</mark></span>El <span class=\"ref-norma\">art. 29.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrá ser instada por las comunidades autónomas con competencia en materia de Justicia para adaptarla a las necesidades de su ámbito territorial\"</span>. Pueden instarla las comunidades autónomas con competencias en Justicia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 44 EX ✱","q":[{"i":"8-15","p":". Ley Orgánica 6/1985, del Poder Judicial. El cargo de Juez de Vigilancia Penitenciaria:","o":["No será compatible con el desempeño de un órgano del orden jurisdiccional penal.","Será compatible con el desempeño de un órgano de cualquier orden jurisdiccional.","Será compatible con el desempeño de un órgano del orden jurisdiccional penal.","Será compatible con el desempeño de un cargo público."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Será compatible con el desempeño de un órgano del orden jurisdiccional penal.</mark></span><span class=\"ref-norma\">Art. 94.5 · Poder Judicial</span>. La LOPJ (art. 94.5) establece que el cargo de Juez de Vigilancia Penitenciaria será compatible con el desempeño de un órgano del orden jurisdiccional penal."},{"i":"8-ia-8194","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Preferencia del orden penal. El orden jurisdiccional penal es siempre preferente, y:","o":["los órganos del orden penal no pueden plantear conflictos de competencia a otros órdenes, sin perjuicio de lo dispuesto en otras leyes.","ningún Juez o Tribunal podrá plantear conflicto de competencia a los órganos de dicho orden jurisdiccional.","solo el Tribunal Supremo puede plantear conflicto a los órganos penales.","ningún órgano podrá plantear conflicto de competencia a la Audiencia Nacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ningún Juez o Tribunal podrá plantear conflicto de competencia a los órganos de dicho orden jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 44 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El orden jurisdiccional penal es siempre preferente. Ningún Juez o Tribunal podrá plantear conflicto de competencia a los órganos de dicho orden jurisdiccional\"</span>. No se puede plantear conflicto de competencia a los órganos penales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8777","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia contra la Infancia y la Adolescencia · medidas. Las Secciones de Violencia contra la Infancia y la Adolescencia serán igualmente competentes para la adopción de las medidas cautelares legalmente previstas que aseguren la protección de las víctimas menores de edad, sin perjuicio de:","o":["las facultades del Ministerio Fiscal.","las competencias de la Sección de Menores.","las competencias atribuidas al juez de guardia.","las atribuciones de las entidades públicas de protección de menores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las competencias atribuidas al juez de guardia</mark></span>El <span class=\"ref-norma\">art. 89 bis.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) La adopción de las medidas cautelares legalmente previstas que aseguren la protección de las víctimas menores de edad, sin perjuicio de las competencias atribuidas al juez de guardia\"</span>. Sin perjuicio de las competencias del juez de guardia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"General / Poder Judicial","q":[{"i":"8-16","p":". Ley Orgánica 6/1985, del Poder Judicial. De los Abogados, procuradores y graduados sociales. Corresponde la representación de las partes en todo tipo de procesos:","o":["Exclusivamente a los Procuradores, salvo cuando la ley autorice otra cosa.","Exclusivamente a los Procuradores, sin excepciones.","Exclusivamente a los Abogados y los Procuradores, salvo cuando la ley autorice otra cosa.","Exclusivamente a los Abogados, sin excepciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Exclusivamente a los Procuradores, salvo cuando la ley autorice otra cosa.</mark></span><span class=\"ref-norma\">Art. 543 · Poder Judicial</span>. El artículo 543 de la LOPJ atribuye a los Procuradores la representación de las partes en todo tipo de procesos, salvo cuando la ley autorice otra cosa. Los Abogados se encargan de la defensa (art. 542)."}]},{"a":"Artículo 92 EX R16","q":[{"i":"8-18","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 92.1. En el Tribunal de Instancia con sede en la capital de cada provincia, dentro del orden jurisdiccional penal, existirá una Sección de Vigilancia Penitenciaria, que tendrá las funciones jurisdiccionales previstas en la ley en materia:","o":["de ejecución de penas privativas de libertad y medidas de seguridad.","Emisión y ejecución de los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley.","Control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias, amparo de los derechos y beneficios de los internos en los establecimientos penitenciarios y demás que señale la ley.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 92.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"existirá una Sección de Vigilancia Penitenciaria, que tendrá las funciones jurisdiccionales previstas en la ley en materia de ejecución de penas privativas de libertad y medidas de seguridad, emisión y ejecución de los instrumentos de reconocimiento mutuo [...], control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias, amparo de los derechos y beneficios de los internos\"</span> (verificado con el texto del temario)."},{"i":"8-83","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 92.4. De los Tribunales de Instancia. Señale la CORRECTA.","o":["Las Secciones de Vigilancia Penitenciaria no podrán extender su jurisdicción a más de una provincia.","Podrá establecerse que la Sección de Vigilancia Penitenciaria extienda su jurisdicción a dos o más provincias de la misma comunidad autónoma.","En el Tribunal de Instancia con sede en la capital de cada provincia existirá una Sección de lo Penal cuya jurisdicción no se extenderá a toda la provincia.","Las Secciones de Vigilancia Penitenciaria no tienen funciones sobre el control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Podrá establecerse que la Sección de Vigilancia Penitenciaria extienda su jurisdicción a dos o más provincias de la misma comunidad autónoma</mark></span>Según el <span class=\"ref-norma\">art. 92.4 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Podrá establecerse que la Sección de Vigilancia Penitenciaria extienda su jurisdicción a dos o más provincias de la misma comunidad autónoma, o uno o más partidos dentro de la misma provincia\"</span> (verificado con el texto del temario)."},{"i":"8-155","p":"(LOPJ) El Tribunal Supremo está compuesto por Salas que se integran por:","o":["Un número de Magistrados fijado por la Ley de Demarcación y Planta Judicial.","Un mínimo de cinco Magistrados.","Un número de Magistrados determinado reglamentariamente.","Un mínimo de tres Magistrados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un número de Magistrados fijado por la Ley de Demarcación y Planta Judicial.</mark></span><span class=\"ref-norma\">Art. 55.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 55.1 de la LOPJ establece que el número de Magistrados que integran las Salas del Tribunal Supremo será el que se determine por la Ley de Demarcación y de Planta Judicial."},{"i":"8-ia-8786","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Vigilancia Penitenciaria. Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia, dentro del orden jurisdiccional penal, existirá una Sección de Vigilancia Penitenciaria, que tendrá las funciones jurisdiccionales previstas en la ley en materia de ejecución de penas privativas de libertad y medidas de seguridad, control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias y:","o":["dirección de la ejecución de las penas no privativas de libertad.","amparo de los derechos y beneficios de los internos en los establecimientos penitenciarios y demás que señale la ley.","autorización del internamiento de extranjeros en centros de internamiento.","resolución de los recursos contra los acuerdos de los directores de prisión, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">amparo de los derechos y beneficios de los internos en los establecimientos penitenciarios y demás que señale la ley</mark></span>El <span class=\"ref-norma\">art. 92.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias, amparo de los derechos y beneficios de los internos en los establecimientos penitenciarios y demás que señale la ley\"</span>. Incluye el amparo de los derechos y beneficios de los internos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8788","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Vigilancia Penitenciaria. El número de Tribunales de Instancia con Secciones de Vigilancia Penitenciaria, su ámbito territorial y número de magistrados y magistradas integrantes de cada una de ellas, se determinará en la Ley de Demarcación y Planta Judicial, atendiendo principalmente a:","o":["la población reclusa de cada provincia.","el número de condenados por delitos graves, sin perjuicio de lo dispuesto en otras leyes.","la carga de trabajo del año anterior.","los establecimientos penitenciarios existentes y a la clase de éstos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los establecimientos penitenciarios existentes y a la clase de éstos</mark></span>El <span class=\"ref-norma\">art. 92.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se determinará en la Ley de Demarcación y Planta Judicial, atendiendo principalmente a los establecimientos penitenciarios existentes y a la clase de éstos\"</span>. Atiende a los establecimientos penitenciarios existentes y su clase. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 85 EXOF EX","q":[{"i":"8-20","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 85. Las Secciones Civiles de los Tribunales de Instancia conocerán, en el orden civil:","o":["De los actos de jurisdicción voluntaria en los términos que prevean las leyes.","De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido.","De las cuestiones de competencia en materia civil entre los jueces y las juezas de paz del partido.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 85 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Estas Secciones conocerán, en el orden civil: [...] 2.º De los actos de jurisdicción voluntaria [...] 3.º De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido. 4.º De las cuestiones de competencia en materia civil entre los jueces y las juezas de paz del partido\"</span> (verificado con el texto del temario)."},{"i":"8-77","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 85. Las Secciones Civiles de los Tribunales de Instancia conocerán, en el orden civil, entre otras:","o":["De las cuestiones de competencia en materia civil entre los jueces y las juezas de paz del partido.","De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido.","De los actos de jurisdicción voluntaria en los términos que prevean las leyes.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 85 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Estas Secciones conocerán, en el orden civil: [...] 2.º De los actos de jurisdicción voluntaria [...] 3.º De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido. 4.º De las cuestiones de competencia en materia civil entre los jueces y las juezas de paz del partido\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8606","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección Civil. Las Secciones Civiles de los Tribunales de Instancia conocerán de los actos de jurisdicción voluntaria y de los recursos que establezca la ley contra las resoluciones de:","o":["los Letrados de la Administración de Justicia del partido.","las Secciones de Familia del partido.","los Registradores de la Propiedad del partido.","los jueces y las juezas de paz del partido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los jueces y las juezas de paz del partido</mark></span>El <span class=\"ref-norma\">art. 85 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"2.º De los actos de jurisdicción voluntaria en los términos que prevean las leyes. 3.º De los recursos que establezca la ley contra las resoluciones de los jueces y las juezas de paz del partido\"</span>. También las cuestiones de competencia civil entre jueces de paz del partido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8607","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección Civil. Las Secciones Civiles de los Tribunales de Instancia conocerán de las solicitudes de reconocimiento y ejecución de sentencias y demás resoluciones judiciales extranjeras y de la ejecución de laudos o resoluciones arbitrales extranjeros, a no ser que:","o":["el demandado resida fuera de España.","el Tribunal Superior de Justicia avoque el conocimiento.","con arreglo a lo acordado en los tratados y otras normas internacionales, corresponda su conocimiento a otra Sección o Tribunal.","el laudo haya sido dictado en un Estado no miembro de la Unión Europea, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con arreglo a lo acordado en los tratados y otras normas internacionales, corresponda su conocimiento a otra Sección o Tribunal</mark></span>El <span class=\"ref-norma\">art. 85 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a no ser que, con arreglo a lo acordado en los tratados y otras normas internacionales, corresponda su conocimiento a otra Sección o Tribunal\"</span>. La excepción son los tratados y normas internacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 383 EX ✱","q":[{"i":"8-21","p":"Ley Orgánica 1/1985 del Poder Judicial. La suspensión de los Jueces y Magistrados sólo tendrá lugar en los casos siguientes:","o":["Cuando se hubiere declarado haber lugar a proceder contra ellos por delitos cometidos en el ejercicio de sus funciones.","Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento.","Cuando se decretare en expediente disciplinario o de incapacidad, ya con carácter provisional, ya definitivo.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 383 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 383 de la LOPJ contempla como causas de suspensión provisional las tres opciones indicadas: la apertura de proceso penal por delito cometido en el ejercicio de las funciones (a), el auto de prisión, fianza o procesamiento por delito doloso no funcional (b), y la suspensión en un expediente disciplinario o de incapacidad (c)."},{"i":"8-306","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Suspensión de jueces y magistrados. La suspensión de los Jueces y Magistrados sólo tendrá lugar, entre otros casos:","o":["Cuando por cualquier delito imprudente se hubiere dictado contra ellos auto de procesamiento.","Cuando se hubiere incoado contra ellos un expediente informativo por el Consejo General del Poder Judicial, en los términos que determine la ley orgánica correspondiente.","Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento.","Cuando se hubiere dictado auto de prisión por cualquier delito, doloso o imprudente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento</mark></span>El <span class=\"ref-norma\">art. 383 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"º Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento.\"</span>"},{"i":"8-ia-8930","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Suspensión. La suspensión de los Jueces y Magistrados sólo tendrá lugar en los casos siguientes: cuando se hubiere declarado haber lugar a proceder contra ellos por delitos cometidos en el ejercicio de sus funciones; cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento; y:","o":["cuando sean imputados por cualquier delito imprudente.","cuando lo solicite el Ministerio Fiscal en cualquier causa, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","cuando se les imponga una sanción de traslado forzoso.","cuando se decretare en expediente disciplinario o de incapacidad, ya con carácter provisional, ya definitivo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuando se decretare en expediente disciplinario o de incapacidad, ya con carácter provisional, ya definitivo</mark></span>El <span class=\"ref-norma\">art. 383 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"3.º Cuando se decretare en expediente disciplinario o de incapacidad, ya con carácter provisional, ya definitivo\"</span>. Hay también un cuarto supuesto: sentencia firme con pena de suspensión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 390 EXOF","q":[{"i":"8-24","p":"L.O. 6/1985 del Poder Judicial. Los que ejerciendo cualquier empleo, cargo o profesión de los expresados en el artículo anterior fueren nombrados Jueces o Magistrados, deberán optar, ______________________________________ por uno u otro cargo, o cesar en el ejercicio de la actividad incompatible.","o":["En el plazo de ocho días.","En el plazo de diez días.","En el plazo de quince días.","En el plazo de veinte días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el plazo de ocho días.</mark></span><span class=\"ref-norma\">Art. 390.1 · Poder Judicial</span>. Según el artículo 390.1 de la LOPJ, la opción por un cargo compatible con la actividad judicial debe realizarse en el plazo de ocho días a partir del nombramiento, o se entenderá que renuncian al nombramiento judicial."},{"i":"8-ia-8942","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Opción. Los que ejerciendo cualquier empleo, cargo o profesión incompatible fueren nombrados Jueces o Magistrados, deberán optar por uno u otro cargo, o cesar en el ejercicio de la actividad incompatible, en el plazo de:","o":["diez días.","quince días.","un mes.","ocho días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ocho días</mark></span>El <span class=\"ref-norma\">art. 390 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"deberán optar, en el plazo de ocho días, por uno u otro cargo, o cesar en el ejercicio de la actividad incompatible\"</span>. Plazo de ocho días; si no optan, se entiende que renuncian al nombramiento judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 61 EXOF EX ✱","q":[{"i":"8-25","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas conocerá de las demandas de responsabilidad civil que se dirijan contra: Seleccione la incorrecta.","o":["Presidentes de Sala.","Presidente de una CC. AA.","Todos los Magistrados de una Sala de dicho Tribunal.","La mayor parte de los Magistrados de una Sala."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Presidente de una CC. AA.</mark></span><span class=\"ref-norma\">Art. 61.3 · De la Organización y Planta de Juzgados y Tribunales</span>. La Sala especial del artículo 61.3.3º de la LOPJ está prevista para conocer de las demandas de responsabilidad civil dirigidas contra el Presidente del Tribunal Supremo, los Presidentes de Sala o todos o la mayor parte de los Magistrados de una Sala del Tribunal Supremo. El Presidente de una C. A. no entra dentro de esta competencia (b)."},{"i":"8-58","p":"Ley Orgánica 6/1985, del Poder Judicial. Además de las competencias atribuidas a cada una de las Salas del Tribunal Supremo, éstas conocerán en particular en cada una de ella:","o":["De las recusaciones que se interpongan contra los Magistrados que las compongan.","De las cuestiones de competencia entre Juzgados o Tribunales del propio orden jurisdiccional que no tengan otro superior común.","De las cuestiones de competencia entre Juzgados o Tribunales que no tengan otro superior común.","Las opciones A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las opciones A y B son correctas</mark></span>A y B son literales; C omite «del propio orden jurisdiccional». Según el <span class=\"ref-norma\">art. 60.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Conocerá además cada una de las Salas del Tribunal Supremo de las recusaciones que se interpusieren contra los Magistrados que las compongan, y de las cuestiones de competencia entre Juzgados o Tribunales del propio orden jurisdiccional que no tengan otro superior común\"</span> (verificado con el texto del temario)."},{"i":"8-171","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá de la instrucción y enjuiciamiento de las causas contra los Presidentes de Sala o contra los Magistrados de una Sala, cuando sean juzgados todos o la mayor parte de los que la constituyen?","o":["Una Sección formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas.","Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas.","Una Sección, formada por el Presidente del Tribunal Supremo, el de la Sala de lo Contencioso-administrativo y cinco Magistrados de esta misma Sala, que serán los dos más antiguos y los tres más modernos.","Una Sala, formada por el Presidente del Tribunal Supremo, el de la Sala de lo Contencioso-administrativo y cinco Magistrados de esta misma Sala que serán los dos más antiguos y los tres más modernos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una d…</mark></span><span class=\"ref-norma\">Art. 61 · De la Organización y Planta de Juzgados y Tribunales</span>. En los casos especiales de enjuiciamiento de Presidentes de Sala o Magistrados del Tribunal Supremo, cuando se juzgue a la mayoría de los miembros de una Sala, conoce la Sala del art. 61 de la L.O.P.J., que está integrada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas. En este caso, el texto de la opción b) corresponde a la composición de la Sala especial del art. 61."},{"i":"8-236","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial De la Audiencia Nacional. Una Sala formada por el Presidente de la Audiencia Nacional, los Presidentes de las Salas y el Magistrado más antiguo y el más moderno de cada una, o aquel que, respectivamente, le sustituya, conocerá de los incidentes de recusación:","o":["Del Presidente.","De los Presidentes de Sala.","De más de dos Magistrados de una Sala.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 67.2 · De la Organización y Planta de Juzgados y Tribunales</span>. La Sala especial del Tribunal Supremo, y por remisión normativa la Sala de la Audiencia Nacional con idéntica composición, conoce de la recusación del Presidente, de los Presidentes de Sala o de más de dos Magistrados de una Sala (Art. 67.2 LOPJ)."},{"i":"8-ia-8317","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala especial del Tribunal Supremo. Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas conocerá, entre otros asuntos:","o":["de los recursos de revisión contra las sentencias dictadas en única instancia por la Sala de lo Contencioso-Administrativo de dicho Tribunal.","de los recursos de casación contra las sentencias de las Audiencias Provinciales.","de los conflictos de competencia entre Juzgados de distinto orden jurisdiccional.","de los recursos de apelación contra las resoluciones de la Sala de lo Penal de la Audiencia Nacional, sin perjuicio de lo dispuesto en otras leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de los recursos de revisión contra las sentencias dictadas en única instancia por la Sala de lo Contencioso-Administrativo de dicho Tribunal</mark></span>El <span class=\"ref-norma\">art. 61.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"1.º De los recursos de revisión contra las sentencias dictadas en única instancia por la Sala de lo Contencioso-Administrativo de dicho Tribunal\"</span>. La Sala especial del art. 61 conoce de la revisión contra las sentencias de única instancia de la Sala Tercera. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8318","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala especial del Tribunal Supremo. La Sala especial del Tribunal Supremo conocerá de los incidentes de recusación del Presidente del Tribunal Supremo, o de los Presidentes de Sala, o de:","o":["más de tres Magistrados de una Sala.","cualquier Magistrado de una Sala.","dos o más Magistrados de distintas Salas.","más de dos Magistrados de una Sala."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">más de dos Magistrados de una Sala</mark></span>El <span class=\"ref-norma\">art. 61.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"2.º De los incidentes de recusación del Presidente del Tribunal Supremo, o de los Presidentes de Sala, o de más de dos Magistrados de una Sala\"</span>. El número es «más de dos Magistrados». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8319","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala especial del Tribunal Supremo. La Sala especial del Tribunal Supremo conocerá del conocimiento de las pretensiones de declaración de error judicial cuando éste se impute:","o":["a un Magistrado de la Sala de lo Penal.","a la Audiencia Nacional o a un Tribunal Superior de Justicia.","a una Sala del Tribunal Supremo.","a un Juez de Instrucción o de lo Penal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a una Sala del Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 61.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"5.º Del conocimiento de las pretensiones de declaración de error judicial cuando éste se impute a una Sala del Tribunal Supremo\"</span>. El error judicial imputado a una Sala del TS lo conoce la Sala especial del art. 61. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8320","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala especial del Tribunal Supremo. La Sala especial del Tribunal Supremo conocerá de los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos, conforme a lo dispuesto en:","o":["la Ley Orgánica 1/2002, de 22 de marzo, reguladora del Derecho de Asociación.","la Ley Orgánica 6/2002, de 27 de junio, de Partidos Políticos.","la Ley Orgánica 5/1985, de 19 de junio, del Régimen Electoral General.","la Ley Orgánica 2/1979, del Tribunal Constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Ley Orgánica 6/2002, de 27 de junio, de Partidos Políticos</mark></span>El <span class=\"ref-norma\">art. 61.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"6.º De los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos, conforme a lo dispuesto en la Ley Orgánica 6/2002, de 27 de junio, de Partidos Políticos\"</span>. La norma aplicable es la Ley Orgánica 6/2002 de Partidos Políticos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8321","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala especial del Tribunal Supremo. Una Sección formada por el Presidente del Tribunal Supremo, el de la Sala de lo Contencioso-administrativo y cinco Magistrados de esta misma Sala, que serán los dos más antiguos y los tres más modernos, conocerá:","o":["del recurso de casación para la unificación de doctrina cuando la contradicción se produzca entre sentencias dictadas en única instancia por Secciones distintas de dicha Sala.","de los recursos de revisión contra las sentencias de la Audiencia Nacional, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","de la declaración de ilegalidad de los partidos políticos.","de los conflictos de competencia entre órdenes jurisdiccionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del recurso de casación para la unificación de doctrina cuando la contradicción se produzca entre sentencias dictadas en única instancia por Secciones distintas de dicha Sala</mark></span>El <span class=\"ref-norma\">art. 61.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conocerá del recurso de casación para la unificación de doctrina cuando la contradicción se produzca entre sentencias dictadas en única instancia por Secciones distintas de dicha Sala\"</span>. Conoce de la casación para unificación de doctrina entre Secciones distintas de la Sala Tercera. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8347","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo de la Audiencia Nacional. La Sala de lo Contencioso-Administrativo de la Audiencia Nacional conocerá en única instancia de los recursos contencioso-administrativos contra disposiciones y actos de:","o":["los Delegados del Gobierno y los Presidentes de las Comunidades Autónomas, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","las Comunidades Autónomas cuando afecten a varias de ellas.","los Ministros, Ministras, Secretarios y Secretarias de Estado que la ley no atribuya a la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia.","los Ministros, sin excepción, cuando afecten a más de una provincia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los Ministros, Ministras, Secretarios y Secretarias de Estado que la ley no atribuya a la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia</mark></span>El <span class=\"ref-norma\">art. 66 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En única instancia, de los recursos contencioso-administrativos contra disposiciones y actos de los Ministros, Ministras, Secretarios y Secretarias de Estado que la ley no atribuya a la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia\"</span>. Ministros y Secretarios de Estado, salvo lo atribuido al Tribunal Central de Instancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8351","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recusaciones. Una Sala formada por el Presidente de la Audiencia Nacional, los Presidentes de las Salas y el Magistrado más antiguo y el más moderno de cada una conocerá de los incidentes de recusación del Presidente, de los Presidentes de Sala o de:","o":["más de tres Magistrados de una Sala.","cualquier Magistrado de la Sala de lo Penal.","más de dos Magistrados de una Sala.","más de un Magistrado de cada Sala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">más de dos Magistrados de una Sala</mark></span>El <span class=\"ref-norma\">art. 69 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conocerá de los incidentes de recusación del Presidente, de los Presidentes de Sala o de más de dos Magistrados de una Sala\"</span>. Más de dos Magistrados de una Sala. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9081","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad penal. La responsabilidad penal de los Jueces y Magistrados por delitos o faltas cometidos en el ejercicio de las funciones de su cargo se exigirá:","o":["conforme a la Ley de Enjuiciamiento Criminal exclusivamente.","conforme a lo que acuerde el Consejo General del Poder Judicial.","conforme a lo dispuesto en esta ley.","conforme al Estatuto Orgánico del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">conforme a lo dispuesto en esta ley</mark></span>El <span class=\"ref-norma\">art. 405 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La responsabilidad penal de los Jueces y Magistrados por delitos o faltas cometidos en el ejercicio de las funciones de su cargo se exigirá conforme a lo dispuesto en esta ley\"</span>. Conforme a la LOPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9154","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad penal. La responsabilidad penal de los Jueces y Magistrados por delitos o faltas cometidos en el ejercicio de las funciones de su cargo se exigirá:","o":["conforme a lo dispuesto en el Código Penal exclusivamente.","conforme a lo dispuesto en esta ley.","ante el Consejo General del Poder Judicial.","conforme a las normas del Estatuto Orgánico del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">conforme a lo dispuesto en esta ley</mark></span>El <span class=\"ref-norma\">art. 405 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se exigirá conforme a lo dispuesto en esta ley.\"</span> Conforme a la propia LOPJ."}]},{"a":"Artículo 80 ✱","q":[{"i":"8-26","p":"Ley Orgánica 6/1985, del Poder Judicial. Las Audiencias Provinciales, que tendrán su sede:","o":["En la pedanía de la provincia, de la que tomarán su nombre.","En el municipio de la provincia, de la que tomarán su nombre.","En el partido judicial de la provincia, de la que tomarán su nombre.","En la capital de la provincia, de la que tomarán su nombre."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En la capital de la provincia, de la que tomarán su nombre.</mark></span><span class=\"ref-norma\">Art. 80.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 80.1 de la LOPJ establece que las Audiencias Provinciales tendrán su sede en la capital de la provincia, de la que tomarán su nombre, y extenderán su jurisdicción a toda ella."},{"i":"8-52","p":"Ley Orgánica 6/1985, del Poder Judicial. Audiencia Provinciales. ¿Quién podrá acordar que el conocimiento de determinadas clases de asuntos se atribuya en exclusiva a una sección de la Audiencia Provincial?","o":["El Consejo General del Poder Judicial.","La Sala de Gobierno.","El Tribunal Superior de Justicia.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial</mark></span>Lo acuerda el CGPJ, previo informe de la Sala de Gobierno (no la Sala de Gobierno por sí). Según el <span class=\"ref-norma\">art. 80.3 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"el Consejo General del Poder Judicial podrá acordar que el conocimiento de determinadas clases de asuntos se atribuya en exclusiva a una sección de la Audiencia Provincial, que extenderá siempre su competencia a todo su ámbito territorial [...]. Este acuerdo se publicará en el «Boletín Oficial del Estado»\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8478","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencias Provinciales. Las Audiencias Provinciales, que tendrán su sede en la capital de la provincia, de la que tomarán su nombre, extenderán su jurisdicción:","o":["a los partidos judiciales de la capital.","a toda ella.","a los municipios de más de cien mil habitantes.","a la capital y su área metropolitana."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a toda ella</mark></span>El <span class=\"ref-norma\">art. 80.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las Audiencias Provinciales, que tendrán su sede en la capital de la provincia, de la que tomarán su nombre, extenderán su jurisdicción a toda ella\"</span>. Jurisdicción en toda la provincia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8479","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencias Provinciales. Podrán crearse Secciones de la Audiencia Provincial fuera de la capital de la provincia, a las que quedarán adscritos:","o":["uno o varios partidos judiciales.","uno o varios municipios.","las comarcas naturales de la provincia.","los Tribunales de Instancia de la provincia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">uno o varios partidos judiciales</mark></span>El <span class=\"ref-norma\">art. 80.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Podrán crearse Secciones de la Audiencia Provincial fuera de la capital de la provincia, a las que quedarán adscritos uno o varios partidos judiciales\"</span>. Se adscriben uno o varios partidos judiciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8480","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencias Provinciales. El Consejo General del Poder Judicial podrá acordar, previo informe de la correspondiente Sala de Gobierno, que el conocimiento de determinadas clases de asuntos se atribuya en exclusiva a una sección de la Audiencia Provincial, que extenderá siempre su competencia a todo su ámbito territorial aun cuando existieren secciones desplazadas. Este acuerdo se publicará:","o":["en el «Boletín Oficial» de la provincia correspondiente.","en el tablón de anuncios de la Audiencia.","en el «Boletín Oficial» de la comunidad autónoma.","en el «Boletín Oficial del Estado»."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en el «Boletín Oficial del Estado»</mark></span>El <span class=\"ref-norma\">art. 80.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Este acuerdo se publicará en el \"Boletín Oficial del Estado\"\"</span>. Se publica en el BOE. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8495","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales de Instancia. Habrá un Tribunal de Instancia en cada partido judicial, con sede en su capital, de la que:","o":["tomará su nombre.","dependerá orgánicamente.","extenderá su jurisdicción.","recibirá sus medios materiales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tomará su nombre</mark></span>El <span class=\"ref-norma\">art. 84.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Habrá un Tribunal de Instancia en cada partido judicial, con sede en su capital, de la que tomará su nombre\"</span>. Toma su nombre de la capital del partido judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 61 quinquies","q":[{"i":"8-27","p":"Ley Orgánica 1/1985 del Poder Judicial. Del Tribunal Supremo. Del Gabinete Técnico. Los Letrados que fueren seleccionados serán nombrados por:","o":["Un año.","Dos años.","Tres años.","Cuatro años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un año.</mark></span><span class=\"ref-norma\">Art. 61 · De la Organización y Planta de Juzgados y Tribunales</span>. Según el artículo 61 quinquies de la LOPJ, los Letrados del Gabinete Técnico del Tribunal Supremo serán nombrados por un periodo de un año, prorrogable después por periodos sucesivos de tres años."},{"i":"8-84","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. Los Letrados que fueron seleccionados para formar parte del Gabinete Técnico del Tribunal Supremo serán nombrados por un año, pudiendo ser prorrogados por sucesivos períodos de:","o":["Un año.","Dos años.","Tres años.","Cuatro años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tres años.</mark></span>De acuerdo con la Disposición Adicional Novena.2 de la LOPJ, los Letrados del Gabinete Técnico del Tribunal Supremo serán nombrados por un año y podrán ser prorrogados por sucesivos períodos de tres años."},{"i":"8-ia-8330","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento en el Gabinete Técnico. Los Letrados del Gabinete Técnico que fueren seleccionados serán nombrados por un año y podrán ser prorrogados por sucesivos periodos de:","o":["dos años.","cinco años.","un año.","tres años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres años</mark></span>El <span class=\"ref-norma\">art. 61 quinquies de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Letrados que fueren seleccionados serán nombrados por un año. Una vez cumplido ese plazo, el Presidente del Tribunal Supremo, oídos el Presidente de Sala respectivo y el Director del Gabinete Técnico, propondrá, en su caso, la prórroga en la plaza, de conformidad con el procedimiento establecido para el nombramiento inicial. Los Letrados podrán ser prorrogados por sucesivos periodos de tres años\"</span>. Un año inicial y prórrogas de tres años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 544 ✱","q":[{"i":"8-28","p":"L.O. 1/1985 del Poder Judicial. La colegiación de los Abogados, Procuradores y Graduados Sociales:","o":["Será obligatoria para actuar ante los Juzgados y Tribunales en los términos previstos en esta Ley y por la legislación general sobre colegios profesionales, salvo que actúen fuera del ámbito de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral.","No será obligatoria para actuar ante los Juzgados y Tribunales en los términos previstos en esta Ley y por la legislación general sobre colegios profesionales, salvo que actúen al servicio de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral.","Será obligatoria para actuar ante los Juzgados y Tribunales en los términos previstos en esta Ley y por la legislación general sobre colegios profesionales, salvo que actúen al servicio de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Será obligatoria para actuar ante los Juzgados y Tribunales en los términos previstos en esta Ley y por la legislación general sobre colegi…</mark></span>La regla general es la colegiación obligatoria para el ejercicio ante Juzgados y Tribunales. La LOPJ y la legislación sobre Colegios Profesionales establecen como principal excepción aquellos que actúan al servicio de las Administraciones o entidades públicas con relación funcionarial o laboral. La opción (c) recoge la regla general y su excepción."},{"i":"8-142","p":"(LOPJ) La colegiación de los Abogados, Procuradores y Graduados Sociales es:","o":["Facultativa para el ejercicio ante los Juzgados y Tribunales.","Obligatoria para actuar ante los Juzgados y Tribunales, salvo que actúen al servicio de las Administraciones Públicas por dependencia funcionarial o laboral.","Obligatoria únicamente para Abogados y Procuradores, siendo facultativa para los Graduados Sociales.","Obligatoria, sin excepción alguna."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Obligatoria para actuar ante los Juzgados y Tribunales, salvo que actúen al servicio de las Administraciones Públicas por dependencia funci…</mark></span><span class=\"ref-norma\">Art. 545.4 · Poder Judicial</span>. El artículo 545.4 de la LOPJ establece la obligatoriedad de la colegiación con la excepción de que actúen al servicio de las Administraciones Públicas por dependencia funcionarial o laboral."},{"i":"8-184","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De los abogados, procuradores y graduados sociales. Señale la INCORRECTA.","o":["Los Abogados, Procuradores y Graduados Sociales, una vez iniciado su ejercicio profesional, prestarán juramento o promesa de acatamiento a la Constitución y al resto del ordenamiento jurídico.","Salvo que la ley disponga otra cosa, las partes podrán designar libremente a sus representantes y defensores entre los Procuradores y Abogados que reúnan los requisitos exigidos por las leyes.","La colegiación de los Abogados, Procuradores y Graduados Sociales será obligatoria para actuar ante los Juzgados y Tribunales en los términos previstos en esta Ley y por la legislación general sobre colegios profesionales, salvo que actúen al servicio de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral.","En los procedimientos laborales y de Seguridad Social la representación técnica podrá ser ostentada por un Graduado Social, al que serán de aplicación las obligaciones inherentes a su función."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Abogados, Procuradores y Graduados Sociales, una vez iniciado su ejercicio profesional, prestarán juramento o promesa de acatamiento a la Constitución y al resto del ordenamiento jurídico</mark></span>Es «antes de iniciar», no «una vez iniciado». Según el <span class=\"ref-norma\">art. 544 de la LOPJ</span>: <span class=\"ref-concepto\">\"Los Abogados, Procuradores y Graduados Sociales, antes de iniciar su ejercicio profesional, prestarán juramento o promesa de acatamiento a la Constitución y al resto del ordenamiento jurídico\"</span> (verificado con el texto del temario oficial)."},{"i":"8-ia-9096","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Juramento y colegiación. Los Abogados, Procuradores y Graduados Sociales, antes de iniciar su ejercicio profesional, prestarán juramento o promesa de acatamiento a la Constitución y al resto del ordenamiento jurídico. La colegiación de los mismos será obligatoria para actuar ante los Juzgados y Tribunales, salvo que:","o":["actúen en procedimientos de cuantía inferior a seis mil euros, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","actúen ante el orden jurisdiccional social.","sean ejercientes con menos de cinco años de antigüedad.","actúen al servicio de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">actúen al servicio de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral</mark></span>El <span class=\"ref-norma\">art. 544 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"salvo que actúen al servicio de las Administraciones públicas o entidades públicas por razón de dependencia funcionarial o laboral\"</span>. Excepción: servicio a las Administraciones públicas por dependencia funcionarial o laboral. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 84 EX ✱","q":[{"i":"8-29","p":"L.O. 6/1985 del Poder Judicial. De las Audiencias Provinciales. Señale la incorrecta.","o":["Podrán crearse Secciones de la Audiencia Provincial fuera de la capital de la provincia, a las que quedarán adscritos uno o varios partidos judiciales.","En todo caso, y previo informe de la correspondiente Sala de Gobierno, el Consejo General del Poder Judicial podrá acordar que el conocimiento de determinadas clases de asuntos se atribuya en exclusiva a una sección de la Audiencia Provincial (extensión de competencia a todo su ámbito territorial).","Cuando el escaso número de asuntos de que conozca una Audiencia Provincial lo aconseje, podrá consistir en Juez y dos Magistrados, incluido el Presidente. En este caso, la Audiencia Provincial se completará para el enjuiciamiento, fallo y cuando la naturaleza de la resolución a dictar lo exija, con el número de Magistrados que se precise del Tribunal Superior de Justicia.","La adscripción de los Magistrados a las distintas secciones tendrá carácter funcional cuando no estuvieren separados por orden jurisdiccional o por especialización. Si lo estuvieren, la adscripción será funcional exclusivamente dentro de las del mismo orden o especialidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando el escaso número de asuntos de que conozca una Audiencia Provincial lo aconseje, podrá consistir en Juez y dos Magistrados, incluido…</mark></span><span class=\"ref-norma\">Art. 81.2 · De la Organización y Planta de Juzgados y Tribunales</span>. La opción (c) es incorrecta. Según el artículo 81.2 de la LOPJ, si la composición de la Audiencia Provincial es mínima (Presidente y dos Magistrados), se completará para el enjuiciamiento y fallo con Magistrados que se precisen de la misma Audiencia Provincial, no del Tribunal Superior de Justicia."},{"i":"8-177","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Cómo se puede establecer, como órganos distintos, en aquellos partidos en que fuere conveniente, los Juzgados de Primera Instancia y los Juzgados de Instrucción?","o":["Por ley orgánica.","Reglamentariamente.","Por Ley de planta y demarcación.","Por orden ministerial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por Ley de planta y demarcación.</mark></span>- La LOPJ indica que en aquellos partidos en que fuere conveniente, los Juzgados de Primera Instancia y los Juzgados de Instrucción podrán establecerse como órganos distintos por Ley de planta y demarcación. &amp;lt;hr&amp;gt;"},{"i":"8-301","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales de Instancia. Las Secciones del Tribunal de Instancia contarán con una Presidencia de Sección cuando concurran, entre otras, las siguientes circunstancias:","o":["Que en el Tribunal de Instancia hubiere tres o más Secciones.","Que en el Tribunal de Instancia hubiere dos o más Secciones.","Que en la Sección de que se trate existan cinco o más plazas judiciales.","Que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a veinte."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que en el Tribunal de Instancia hubiere dos o más Secciones</mark></span>El <span class=\"ref-norma\">art. 84.3 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Cada Tribunal de Instancia contará con una Presidencia. Las Secciones del Tribunal de Instancia contarán con una Presidencia de Sección cuando concurran las siguientes circunstancias: a) Que en el Tribunal de Instancia hubiere dos o más Secciones.\"</span>"},{"i":"8-ia-8496","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de los Tribunales de Instancia. Los Tribunales de Instancia estarán integrados por una Sección Única, de Civil y de Instrucción. En los supuestos determinados por la Ley de Demarcación y de Planta Judicial, el Tribunal de Instancia se integrará:","o":["por una Sección de Familia y otra de lo Penal.","por una Sección Civil y otra de lo Mercantil.","por tres Secciones: Civil, Instrucción y Familia, en los términos que establezca la ley orgánica.","por una Sección Civil y otra Sección de Instrucción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por una Sección Civil y otra Sección de Instrucción</mark></span>El <span class=\"ref-norma\">art. 84.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En los supuestos determinados por la Ley 38/1988, de 28 de diciembre, de Demarcación y de Planta Judicial, el Tribunal de Instancia se integrará por una Sección Civil y otra Sección de Instrucción\"</span>. En esos supuestos se divide en Sección Civil y Sección de Instrucción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8498","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Presidencia de los Tribunales de Instancia. Las Secciones del Tribunal de Instancia contarán con una Presidencia de Sección cuando concurran, entre otras, las siguientes circunstancias: que en el Tribunal de Instancia hubiere dos o más Secciones y que en la Sección de que se trate existan:","o":["cinco o más plazas judiciales, y que el número total de plazas del Tribunal sea igual o superior a diez.","ocho o más plazas judiciales, y que el número total de plazas del Tribunal sea igual o superior a doce.","diez o más plazas judiciales, y que el número total de plazas del Tribunal sea igual o superior a quince.","seis o más plazas judiciales, y que el número total de plazas del Tribunal sea igual o superior a ocho."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">ocho o más plazas judiciales, y que el número total de plazas del Tribunal sea igual o superior a doce</mark></span>El <span class=\"ref-norma\">art. 84.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Que en el Tribunal de Instancia hubiere dos o más Secciones. b) Que en la Sección de que se trate existan ocho o más plazas judiciales. c) Que el número total de plazas judiciales del Tribunal de Instancia sea igual o superior a doce\"</span>. Ocho o más plazas en la Sección y doce o más en el Tribunal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8500","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Adscripción funcional. Los jueces destinados en una Sección del Tribunal de Instancia podrán conocer de los asuntos de nuevo ingreso de otras Secciones, siempre que se trate de asuntos del mismo orden jurisdiccional. Esta asignación se realizará mediante acuerdo del Consejo General del Poder Judicial, a propuesta de la Presidencia del Tribunal y:","o":["oído el Ministerio Fiscal y la Sala de Gobierno.","previo informe de la comunidad autónoma.","previa autorización del Tribunal Superior de Justicia, sin perjuicio de lo dispuesto en otras leyes.","oída la Junta de Jueces y Juezas del orden jurisdiccional al que se refiera."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">oída la Junta de Jueces y Juezas del orden jurisdiccional al que se refiera</mark></span>El <span class=\"ref-norma\">art. 84.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Esta asignación se realizará mediante acuerdo del Consejo General del Poder Judicial, a propuesta de la Presidencia del Tribunal y oída la Junta de Jueces y Juezas del orden jurisdiccional al que se refiera\"</span>. Se oye a la Junta de Jueces del orden jurisdiccional correspondiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 36 R9","q":[{"i":"8-30","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 36. La creación de las Secciones de las Audiencias y Tribunales y de plazas judiciales, siempre que no suponga alteración de la demarcación judicial, corresponderá a:","o":["El Ministerio de Justicia.","El Gobierno.","El Consejo General del Poder Judicial.","Las Comunidades Autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Gobierno</mark></span>Según el <span class=\"ref-norma\">art. 36 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"La creación de las Secciones de las Audiencias y Tribunales y de plazas judiciales, siempre que no suponga alteración de la demarcación judicial, corresponderá al Gobierno, oídos preceptivamente la comunidad autónoma afectada y el Consejo General del Poder Judicial\"</span> (verificado con el texto del temario)."},{"i":"8-157","p":"(LOPJ) La superior inspección y vigilancia sobre todos los Juzgados y Tribunales corresponde a:","o":["El Ministerio de Justicia, a través del Letrado de la Administración de Justicia.","El Consejo General del Poder Judicial.","El Tribunal Supremo, a través de la Sala de Gobierno.","La Dirección General de Relaciones con la Administración de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial.</mark></span><span class=\"ref-norma\">Art. 163 · Del Consejo General del Poder Judicial</span>. El artículo 163 de la LOPJ atribuye la superior inspección y vigilancia sobre todos los Juzgados y Tribunales al Consejo General del Poder Judicial."},{"i":"8-ia-8186","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Creación de Secciones y plazas. La creación de las Secciones de las Audiencias y Tribunales y de plazas judiciales, siempre que no suponga alteración de la demarcación judicial, corresponderá:","o":["al Consejo General del Poder Judicial, oída la comunidad autónoma afectada, salvo que la ley disponga otra cosa.","al Gobierno, oídos preceptivamente la comunidad autónoma afectada y el Consejo General del Poder Judicial.","al Ministerio de Justicia, previo informe del Tribunal Supremo.","a las Cortes Generales, mediante ley orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Gobierno, oídos preceptivamente la comunidad autónoma afectada y el Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 36 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"corresponderá al Gobierno, oídos preceptivamente la comunidad autónoma afectada y el Consejo General del Poder Judicial\"</span>. Compete al Gobierno oyendo preceptivamente a la comunidad autónoma y al CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 101 ✱ R17","q":[{"i":"8-31","p":"L.O. 1/1985 del Poder Judicial. Los Jueces de Paz y sus sustitutos serán elegidos por:","o":["El Pleno del Ayuntamiento.","La Sala de Gobierno de la Audiencia Provincial.","La Sala de Gobierno del Tribunal Superior de Justicia.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Pleno del Ayuntamiento.</mark></span><span class=\"ref-norma\">Art. 101.2 · Poder Judicial</span>. El artículo 101.2 de la LOPJ establece que los Jueces de Paz y sus sustitutos serán elegidos por el Pleno del Ayuntamiento con el voto favorable de la mayoría absoluta de sus miembros."},{"i":"8-32","p":"L.O. 1/1985 del Poder Judicial. Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de:","o":["Dos años.","Tres años.","Cuatro años.","Cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuatro años.</mark></span><span class=\"ref-norma\">Art. 101.1 · De la Organización y Planta de Juzgados y Tribunales</span>. Según el artículo 101.1 de la LOPJ, los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente."},{"i":"8-67","p":"Ley Orgánica 6/1985 del Poder Judicial. Los Jueces de Paz y sus sustitutos serán elegidos por:","o":["La Sala de Gobierno del Tribunal Superior de Justicia.","La Sala de Gobierno de la Audiencia Provincial.","El Juez de Primera Instancia e Instrucción.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas</mark></span>Según el <span class=\"ref-norma\">art. 101 de la LOPJ</span>: <span class=\"ref-concepto\">\"Los Jueces de Paz y sus sustitutos serán elegidos por el Pleno del Ayuntamiento, con el voto favorable de la mayoría absoluta de sus miembros\"</span> (verificado con el texto del temario oficial)."},{"i":"8-87","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De los Juzgados de Paz. Los Jueces de Paz y sus sustitutos serán nombrados para un período de:","o":["Un año.","Dos años.","Tres años.","Cuatro años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuatro años.</mark></span><span class=\"ref-norma\">Art. 101.1 · De la Organización y Planta de Juzgados y Tribunales</span>. Según el artículo 101.1 de la LOPJ, los Jueces de Paz y sus sustitutos serán nombrados para un período de cuatro años."},{"i":"8-105","p":"¿Cuál es la duración del periodo de nombramiento de los Jueces de Paz y sus sustitutos?","o":["Dos años.","Tres años.","Cuatro años.","Cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuatro años.</mark></span><span class=\"ref-norma\">Art. 101.1 · Poder Judicial</span>. El artículo 101.1 de la LOPJ establece un periodo de nombramiento de cuatro años."},{"i":"8-106","p":"La elección de Jueces de Paz y sus sustitutos por el Pleno del Ayuntamiento requiere:","o":["Mayoría simple de los miembros.","Mayoría de dos tercios de los miembros.","Voto favorable de la mayoría absoluta de sus miembros.","Unanimidad de los miembros presentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Voto favorable de la mayoría absoluta de sus miembros.</mark></span><span class=\"ref-norma\">Art. 101.2 · Poder Judicial</span>. El artículo 101.2 de la LOPJ exige el voto favorable de la mayoría absoluta del Pleno del Ayuntamiento."},{"i":"8-107","p":"Los Jueces de Paz prestarán juramento o promesa:","o":["Ante la Sala de Gobierno del Tribunal Superior de Justicia.","Ante el Presidente del Tribunal Superior de Justicia.","Ante el Juez de Primera Instancia e Instrucción.","Ante el Pleno del Ayuntamiento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ante el Juez de Primera Instancia e Instrucción.</mark></span><span class=\"ref-norma\">Art. 101.5 · Poder Judicial</span>. El artículo 101.5 de la LOPJ establece que el juramento se presta ante el Juez de Primera Instancia e Instrucción."},{"i":"8-117","p":"¿Quién nombra a los Jueces de Paz y sus sustitutos?","o":["El Pleno del Ayuntamiento.","El Juez de Primera Instancia e Instrucción.","La Sala de Gobierno del Tribunal Superior de Justicia correspondiente.","El Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de Gobierno del Tribunal Superior de Justicia correspondiente.</mark></span><span class=\"ref-norma\">Art. 101.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 101.1 de la LOPJ indica que son nombrados por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente, a propuesta del Ayuntamiento."},{"i":"8-127","p":"Ley Orgánica 6/1985 del Poder Judicial. Los Jueces de Paz prestarán juramento ante:","o":["El Pleno del Ayuntamiento.","El Juez de Primera Instancia e Instrucción.","El Consejo General del Poder Judicial.","Las Salas de Gobierno del Tribunal Superior de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Juez de Primera Instancia e Instrucción.</mark></span><span class=\"ref-norma\">Art. 102.2 · Poder Judicial</span>. Los Jueces de Paz prestarán juramento ante el Juez de Primera Instancia e Instrucción y tomarán posesión ante quien se hallara ejerciendo la jurisdicción (art. 102.2 LOPJ)."},{"i":"8-153","p":"(LOPJ) ¿Quién puede acordar que los Juzgados de Paz sean servidos por un Juez de Paz nombrado directamente, sin propuesta del Ayuntamiento?","o":["El Tribunal Superior de Justicia, a propuesta del Juez de Primera Instancia e Instrucción.","El Consejo General del Poder Judicial.","El Presidente del Tribunal Superior de Justicia.","La Sala de Gobierno del Tribunal Superior de Justicia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de Gobierno del Tribunal Superior de Justicia.</mark></span><span class=\"ref-norma\">Art. 101.4 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 101.4 de la LOPJ indica que si el Ayuntamiento no presenta la propuesta en el plazo de tres meses, la Sala de Gobierno del Tribunal Superior de Justicia designará directamente al Juez de Paz."},{"i":"8-224","p":"Ley Orgánica 6/1985 del Poder Judicial. Los Jueces de Paz y sus sustitutos serán elegidos por _________ con el voto favorable de la _________ de la de sus miembros, entre las personas que, reuniendo las condiciones legales, así lo soliciten.","o":["La Sala de Gobierno del Tribunal Superior de Justicia / mayoría absoluta.","El Pleno del Ayuntamiento / mayoría absoluta.","La Sala de Gobierno del Tribunal Superior de Justicia / mayoría simple.","El Pleno del Ayuntamiento / mayoría simple."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Pleno del Ayuntamiento / mayoría absoluta.</mark></span><span class=\"ref-norma\">Art. 101.2 · Poder Judicial</span>. El nombramiento de Jueces de Paz y sustitutos es a propuesta del Pleno del Ayuntamiento con el voto favorable de la mayoría absoluta de sus miembros (Art. 101.2 LOPJ)."},{"i":"8-228","p":"Ley Orgánica 6/1985 del Poder Judicial. De los Jueces y las Juezas de Paz. Si en el plazo de _________ a contar desde que se produjera la vacante en un Juzgado de Paz, el Ayuntamiento correspondiente no efectuase la propuesta prevenida en los apartados anteriores, la Sala de Gobierno del Tribunal Superior de Justicia procederá a designar al Juez de Paz.","o":["Tres meses.","Cinco meses.","Seis meses.","Dos meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres meses.</mark></span><span class=\"ref-norma\">Art. 101.2 · De la Organización y Planta de Juzgados y Tribunales</span>. El plazo que tiene el Ayuntamiento para proponer al Juez de Paz es de tres meses desde que se produce la vacante (Art. 101.2 LOPJ)."},{"i":"8-231","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de __________ por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente.","o":["Seis años.","Dos años.","Un año.","Cuatro años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuatro años.</mark></span><span class=\"ref-norma\">Art. 101.1 · De la Organización y Planta de Juzgados y Tribunales</span>. Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente (Art. 101.1 LOPJ)."},{"i":"8-ia-8916","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento de los Jueces de Paz. Los Jueces de Paz y sus sustitutos serán nombrados para un periodo de cuatro años por la Sala de Gobierno del Tribunal Superior de Justicia correspondiente. El nombramiento recaerá:","o":["en las personas propuestas por el Consejo General del Poder Judicial.","en las personas elegidas por el respectivo Ayuntamiento.","en las personas designadas por el Juez de Primera Instancia e Instrucción.","en las personas que superen una oposición libre."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en las personas elegidas por el respectivo Ayuntamiento</mark></span>El <span class=\"ref-norma\">art. 101.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El nombramiento recaerá en las personas elegidas por el respectivo Ayuntamiento\"</span>. Nombra la Sala de Gobierno, entre los elegidos por el Ayuntamiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8917","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento de los Jueces de Paz. Los Jueces de Paz y sus sustitutos serán elegidos por el Pleno del Ayuntamiento, con el voto favorable de la mayoría absoluta de sus miembros, entre las personas que, reuniendo las condiciones legales, así lo soliciten. Si no hubiere solicitante:","o":["el pleno elegirá libremente.","lo designará la Sala de Gobierno.","lo designará el Alcalde.","quedará vacante hasta la siguiente convocatoria."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el pleno elegirá libremente</mark></span>El <span class=\"ref-norma\">art. 101.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Si no hubiere solicitante, el pleno elegirá libremente\"</span>. El pleno elige libremente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8918","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento de los Jueces de Paz. Aprobado el acuerdo del Pleno del Ayuntamiento sobre el Juez de Paz, será remitido:","o":["directamente a la Sala de Gobierno del Tribunal Superior de Justicia, sin perjuicio de lo dispuesto en otras leyes.","al Consejo General del Poder Judicial.","al Presidente de la Audiencia Provincial.","al Juez de Primera Instancia e Instrucción, quien lo elevará a la Sala de Gobierno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al Juez de Primera Instancia e Instrucción, quien lo elevará a la Sala de Gobierno</mark></span>El <span class=\"ref-norma\">art. 101.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Aprobado el acuerdo correspondiente, será remitido al Juez de Primera Instancia e Instrucción, quien lo elevará a la Sala de Gobierno\"</span>. Lo remite al Juez de Primera Instancia e Instrucción, que lo eleva a la Sala de Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8919","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento de los Jueces de Paz. Si en el plazo de tres meses, a contar desde que se produjera la vacante en un Juzgado de Paz, el Ayuntamiento correspondiente no efectuase la propuesta:","o":["el Consejo General del Poder Judicial designará al Juez de Paz, en los términos que establezca la ley orgánica.","se amortizará la plaza del Juzgado de Paz.","la Sala de Gobierno del Tribunal Superior de Justicia procederá a designar al Juez de Paz.","el Ayuntamiento podrá designar a su sustituto sin plazo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Sala de Gobierno del Tribunal Superior de Justicia procederá a designar al Juez de Paz</mark></span>El <span class=\"ref-norma\">art. 101.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Si en el plazo de tres meses, a contar desde que se produjera la vacante en un Juzgado de Paz, el Ayuntamiento correspondiente no efectuase la propuesta prevenida en los apartados anteriores, la Sala de Gobierno del Tribunal Superior de Justicia procederá a designar al Juez de Paz\"</span>. A los tres meses designa la Sala de Gobierno del TSJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8920","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento de los Jueces de Paz. La Sala de Gobierno del Tribunal Superior de Justicia designará al Juez de Paz también cuando la persona propuesta por el Ayuntamiento no reuniera, a juicio de la misma Sala de Gobierno y:","o":["oído el Consejo General del Poder Judicial, los requisitos reglamentarios.","oído el Ministerio Fiscal, las condiciones exigidas por esta ley.","oído el Juez de Primera Instancia, la aptitud necesaria.","oído el Ayuntamiento, los requisitos de residencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">oído el Ministerio Fiscal, las condiciones exigidas por esta ley</mark></span>El <span class=\"ref-norma\">art. 101.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Se actuará de igual modo cuando la persona propuesta por el Ayuntamiento no reuniera, a juicio de la misma Sala de Gobierno y oído el Ministerio Fiscal, las condiciones exigidas por esta ley\"</span>. Se oye al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8921","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Toma de posesión de los Jueces de Paz. Los Jueces de Paz prestarán juramento ante el Juez de Primera Instancia e Instrucción y tomarán posesión:","o":["ante quien se hallara ejerciendo la jurisdicción.","ante el Pleno del Ayuntamiento.","ante la Sala de Gobierno del Tribunal Superior de Justicia.","ante el Secretario del Juzgado de Paz."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ante quien se hallara ejerciendo la jurisdicción</mark></span>El <span class=\"ref-norma\">art. 101.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Jueces de Paz prestarán juramento ante el Juez de Primera Instancia e Instrucción y tomarán posesión ante quien se hallara ejerciendo la jurisdicción\"</span>. Juramento ante el Juez de Primera Instancia e Instrucción; posesión ante quien ejerza la jurisdicción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 82 bis EX","q":[{"i":"8-37","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De los Tribunales Superiores de Justicia. En el caso de que el número de asuntos lo aconseje, podrán crearse una o más Secciones e incluso Sala de lo Penal con su propia circunscripción territorial en aquellas capitales que ya sean sedes de otras Salas del Tribunal Superior:","o":["A los solos efectos de conocer los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales.","Con todas las competencias.","Conocer los recursos de apelación e instrucción de los casos encomendados al TSJ.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A los solos efectos de conocer los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provincia…</mark></span><span class=\"ref-norma\">Art. 77.3 · Poder Judicial</span>. El artículo 77.3 de la LOPJ limita la competencia de estas secciones/Salas creadas en otras capitales de provincia a conocer de los recursos de apelación mencionados en el párrafo c) de dicho apartado."},{"i":"8-235","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial De los Tribunales Superiores de Justicia. Las Salas de lo Contencioso Administrativo de los Tribunales Superiores de Justicia conocerán, entre otros, en única instancia, de los recursos que se deduzcan en relación con: señale la INCORRECTA.","o":["Las resoluciones dictadas en alzada por el Tribunal Económico-Administrativo Central en materia de tributos solicitados.","Los actos y disposiciones de las Juntas Electorales Provinciales y de Comunidades Autónomas, así como los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre proclamación de electos y elección y proclamación de Presidentes de Corporaciones locales en los términos de la legislación electoral.","La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica reguladora del Derecho de Reunión.","Los convenios entre Administraciones públicas cuyas competencias se ejerzan en el ámbito territorial de la correspondiente Comunidad Autónoma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las resoluciones dictadas en alzada por el Tribunal Económico-Administrativo Central en materia de tributos solicitados.</mark></span><span class=\"ref-norma\">Art. 11.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El conocimiento en única instancia de los recursos contencioso-administrativos contra las resoluciones dictadas en alzada por el Tribunal Económico-Administrativo Central (TEA Central) corresponde a la Sala de lo Contencioso-Administrativo de la Audiencia Nacional (Art. 11.1.b de la Ley de la Jurisdicción Contencioso-Administrativa), no a los TSJ."},{"i":"8-300","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencias Provinciales. Los acuerdos de reparto de asuntos de las Audiencias Provinciales serán objeto de publicación en el «Boletín Oficial del Estado» y producirán efectos:","o":["Desde el día siguiente al de su publicación, salvo que se establezca otro momento posterior.","A los veinte días de su publicación, salvo que, por razones de urgencia, se establezca otro momento anterior, salvo que el órgano competente acuerde otra cosa de forma motivada.","Desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior.","Desde el inicio del semestre siguiente a aquel en que se adopten, sin excepción alguna."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior</mark></span>El <span class=\"ref-norma\">art. 82 bis.4 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los acuerdos a que se refiere el presente artículo serán objeto de publicación en el \"Boletín Oficial del Estado\" y producirán efectos desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior.\"</span>"},{"i":"8-ia-8456","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. Como Sala de lo Penal, corresponde al Tribunal Superior de Justicia el conocimiento de los recursos de apelación:","o":["contra las resoluciones dictadas por las Secciones de Instrucción de los Tribunales de Instancia, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","contra las sentencias de la Audiencia Nacional en primera instancia.","contra los autos de las Secciones de Menores de los Tribunales de Instancia.","contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes</mark></span>El <span class=\"ref-norma\">art. 73.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes\"</span>. Apelación contra las resoluciones de primera instancia de las Audiencias Provinciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8459","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. En el caso de que el número de asuntos lo aconseje, podrán crearse Secciones e incluso Sala de lo Penal con su propia circunscripción territorial en aquellas capitales que ya sean sedes de otras Salas del Tribunal Superior, a los solos efectos de conocer:","o":["los recursos de apelación contra las resoluciones de las Audiencias Provinciales en primera instancia y aquellas otras apelaciones atribuidas por las leyes al Tribunal Superior de Justicia.","las causas penales contra aforados autonómicos.","los recursos de casación en materia penal de la comunidad autónoma, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes.","las cuestiones de competencia entre órganos penales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los recursos de apelación contra las resoluciones de las Audiencias Provinciales en primera instancia y aquellas otras apelaciones atribuidas por las leyes al Tribunal Superior de Justicia</mark></span>El <span class=\"ref-norma\">art. 73.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a los solos efectos de conocer los recursos de apelación a los que se refiere la letra c) del apartado 3 de este artículo y aquellas otras apelaciones atribuidas por las leyes al Tribunal Superior de Justicia\"</span>. Solo a efectos de las apelaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8493","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de las Audiencias Provinciales. Los acuerdos del Consejo General del Poder Judicial de especialización de secciones de las Audiencias Provinciales serán objeto de publicación en el «Boletín Oficial del Estado» y producirán efectos:","o":["desde el día siguiente a su publicación, sin excepciones, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","desde el inicio del año judicial siguiente.","desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior.","a los tres meses de su publicación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior</mark></span>El <span class=\"ref-norma\">art. 82 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"producirán efectos desde el inicio del año siguiente a aquel en que se adopten, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior\"</span>. Efectos desde el inicio del año siguiente, salvo urgencia razonada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8911","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de plazas. Los acuerdos del Consejo General del Poder Judicial sobre especialización se publicarán en el «Boletín Oficial del Estado» y producirán efectos:","o":["desde el día siguiente al de su publicación, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes.","desde el inicio del año judicial siguiente.","desde el inicio del año siguiente a aquel en que se adopte, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior.","desde los tres meses de su publicación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">desde el inicio del año siguiente a aquel en que se adopte, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior</mark></span>El <span class=\"ref-norma\">art. 96.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"producirán efectos desde el inicio del año siguiente a aquel en que se adopte, salvo que, por razones de urgencia, razonadamente se establezca otro momento anterior\"</span>. Desde el inicio del año siguiente, salvo urgencia razonada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 73 EXOF ✱","q":[{"i":"8-38","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De los Tribunales Superiores de Justicia. Como Sala de lo Penal, corresponde a esta Sala, entre otras: Señale la incorrecta.","o":["La instrucción y el fallo de las causas penales contra Magistrados del Ministerio Fiscal por delitos cometidos en el ejercicio de su cargo en la comunidad autónoma, siempre que esta atribución no corresponda al Tribunal Supremo.","La instrucción y el fallo de las causas penales contra miembros del Ministerio Fiscal por delitos cometidos en el ejercicio de su cargo en la comunidad autónoma, siempre que esta atribución no corresponda al Tribunal Supremo.","La instrucción y el fallo de las causas penales contra funcionarios por delitos cometidos en el ejercicio de su cargo en la comunidad autónoma, aunque esta atribución no corresponda al Tribunal Supremo.","La instrucción y el fallo de las causas penales contra Magistrados por delitos cometidos en el ejercicio de su cargo en la comunidad autónoma, siempre que esta atribución no corresponda al Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La instrucción y el fallo de las causas penales contra funcionarios por delitos cometidos en el ejercicio de su cargo en la comunidad autón…</mark></span><span class=\"ref-norma\">Art. 73.3.b) · Poder Judicial</span>. El artículo 73.3.b) de la LOPJ otorga competencia a la Sala de lo Penal del TSJ para conocer de la instrucción y el fallo de las causas penales contra Jueces, Magistrados y miembros del Ministerio Fiscal de la Comunidad Autónoma. No tiene competencia sobre &quot;funcionarios&quot; en general, sino sobre altos cargos y autoridades autonómicas (art. 73.3.c)."},{"i":"8-53","p":"Ley Orgánica 6/1985, del Poder Judicial. Para la instrucción contra un Magistrado del Tribunal Superior de Justicia, se designará de entre los miembros de la Sala, un instructor que no formará parte de la misma para enjuiciarlas. ¿Con qué criterio?","o":["Conforme a un turno preestablecido.","Conforme al turno de antigüedad.","Conforme a un turno rotatorio.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Conforme a un turno preestablecido.</mark></span><span class=\"ref-norma\">Art. 307 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. La designación del instructor de un Magistrado del TSJ se realiza de entre los miembros de la Sala, y se hará conforme a un turno preestablecido, tal como se prevé para la instrucción de causas contra jueces y magistrados (Art. 307 LOPJ, aplicable por analogía)."},{"i":"8-239","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial ¿Quién conocerá de las funciones de apoyo y control del arbitraje que se establezcan en la ley, así como de las peticiones de exequátur de laudos o resoluciones arbitrales extranjeros, a no ser que, con arreglo a lo acordado en los tratados o las normas de la Unión Europea, corresponda su conocimiento a otro Juzgado o Tribunal?","o":["A la Sala de lo Civil y Penal del Tribunal Superior de Justicia.","A la Sala de lo Civil del Tribunal Superior de Justicia.","A la Sala de lo Social de la Audiencia Nacional.","Al Juzgado Central de lo Contencioso Administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A la Sala de lo Civil y Penal del Tribunal Superior de Justicia.</mark></span><span class=\"ref-norma\">Art. 85.5 · De la Organización y Planta de Juzgados y Tribunales</span>. Las funciones de apoyo y control del arbitraje que se establezcan en la Ley de Arbitraje corresponden a la Sala de lo Civil y Penal del Tribunal Superior de Justicia de la Comunidad Autónoma donde se haya dictado el laudo (Art. 85.5 LOPJ). Aunque el exequátur general de laudos extranjeros se ha trasladado a la Sala de lo Civil del Tribunal Supremo, la formulación de la pregunta, que incluye ambas competencias y las opciones dadas, apunta al órgano que tradicionalmente y por las funciones de apoyo ejerce esta jurisdicción en el ámbito autonómico. Fuentes"},{"i":"8-272","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. Como Sala de lo Penal, corresponde a la Sala de lo Civil y Penal del Tribunal Superior de Justicia, entre otras funciones:","o":["El conocimiento de las causas penales que los Estatutos de Autonomía reservan al conocimiento de los Tribunales Superiores de Justicia.","El conocimiento de los recursos de casación contra las sentencias dictadas por las Audiencias Provinciales, en los términos que determine la ley orgánica correspondiente.","La instrucción y el fallo de las causas penales contra miembros del Gobierno de la Nación.","La decisión de las cuestiones de competencia entre órganos de distintas Comunidades Autónomas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El conocimiento de las causas penales que los Estatutos de Autonomía reservan al conocimiento de los Tribunales Superiores de Justicia</mark></span>El <span class=\"ref-norma\">art. 73.3 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"3. Como Sala de lo Penal, corresponde a esta Sala: a) El conocimiento de las causas penales que los Estatutos de Autonomía reservan al conocimiento de los Tribunales Superiores de Justicia.\"</span>"},{"i":"8-273","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. Como Sala de lo Penal, corresponde a la Sala de lo Civil y Penal del Tribunal Superior de Justicia el conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por:","o":["Las Secciones de Instrucción de los Tribunales de Instancia, así como el de todos los de queja.","La Audiencia Nacional, así como el de todos aquellos previstos por las leyes.","Los Juzgados de Paz, así como el de los recursos de casación que prevea la ley.","Las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes</mark></span>El <span class=\"ref-norma\">art. 73.3.c) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"c) El conocimiento de los recursos de apelación contra las resoluciones dictadas en primera instancia por las Audiencias Provinciales, así como el de todos aquellos previstos por las leyes.\"</span>"},{"i":"8-274","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. En el caso de que el número de asuntos lo aconseje, podrán crearse una o más Secciones e incluso Sala de lo Penal con su propia circunscripción territorial:","o":["En cualquier capital de provincia de la Comunidad Autónoma, para conocer de todos los asuntos penales.","En aquellas capitales que no sean sedes de otras Salas del Tribunal Superior, para conocer los recursos de casación, salvo que el órgano competente acuerde otra cosa de forma motivada.","En aquellas capitales que ya sean sedes de otras Salas del Tribunal Superior, a los solos efectos de conocer los recursos de apelación.","En las ciudades con Estatuto de Autonomía, a los solos efectos de instruir las causas contra aforados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En aquellas capitales que ya sean sedes de otras Salas del Tribunal Superior, a los solos efectos de conocer los recursos de apelación</mark></span>El <span class=\"ref-norma\">art. 73.6 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"6. En el caso de que el número de asuntos lo aconseje, podrán crearse una o más Secciones e incluso Sala de lo Penal con su propia circunscripción territorial en aquellas capitales que ya sean sedes de otras Salas del Tribunal Superior, a los solos efectos de conocer los recursos de apelación\"</span>"},{"i":"8-ia-8451","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. La Sala de lo Civil y Penal del Tribunal Superior de Justicia conocerá, como Sala de lo Civil, del recurso de casación que establezca la ley contra resoluciones de órganos jurisdiccionales del orden civil con sede en la comunidad autónoma, siempre que el recurso se funde en infracción de normas del derecho civil, foral o especial, propio de la comunidad, y:","o":["cuando el correspondiente Estatuto de Autonomía haya previsto esta atribución.","cuando lo autorice el Tribunal Supremo.","cuando la cuantía del asunto exceda de seiscientos mil euros.","cuando el recurso haya sido admitido por la Sala Primera del Tribunal Supremo, en los términos que establezca la ley orgánica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuando el correspondiente Estatuto de Autonomía haya previsto esta atribución</mark></span>El <span class=\"ref-norma\">art. 73.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que el recurso se funde en infracción de normas del derecho civil, foral o especial, propio de la comunidad, y cuando el correspondiente Estatuto de Autonomía haya previsto esta atribución\"</span>. Requiere que el Estatuto de Autonomía haya previsto la atribución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8454","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. Como Sala de lo Civil, el Tribunal Superior de Justicia conoce igualmente de las demandas de responsabilidad civil dirigidas contra el Presidente y miembros del Consejo de Gobierno de la comunidad autónoma y contra los miembros de la Asamblea legislativa, cuando tal atribución:","o":["no esté prevista en las leyes procesales.","no corresponda, según los Estatutos de Autonomía, al Tribunal Supremo.","no corresponda a la Audiencia Nacional.","no haya sido asumida por el Parlamento autonómico, en los términos que establezca la ley orgánica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no corresponda, según los Estatutos de Autonomía, al Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 73.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando tal atribución no corresponda, según los Estatutos de Autonomía, al Tribunal Supremo\"</span>. Si el Estatuto la atribuye al Tribunal Supremo, no corresponde al TSJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8455","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. Como Sala de lo Penal, corresponde al Tribunal Superior de Justicia la instrucción y el fallo de las causas penales contra jueces, magistrados y miembros del Ministerio Fiscal por delitos o faltas cometidos en el ejercicio de su cargo en la comunidad autónoma, siempre que:","o":["esta atribución no corresponda al Tribunal Supremo.","esta atribución no corresponda a la Audiencia Nacional.","el delito esté castigado con pena grave.","lo solicite el Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">esta atribución no corresponda al Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 73.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que esta atribución no corresponda al Tribunal Supremo\"</span>. Subsidiaria respecto del Tribunal Supremo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 74 EX ✱","q":[{"i":"8-39","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. ¿A quién corresponde autorizar, mediante auto, el requerimiento de información por parte de la Agencia Española de Protección de Datos y otras autoridades administrativas independientes de ámbito estatal a los operadores que presten servicios de comunicaciones electrónicas disponibles al público y de los prestadores de servicios de la sociedad de la información, cuando ello sea necesario de acuerdo con la legislación específica?","o":["A la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia.","A la Sala de lo Contencioso-administrativo del Tribunal Supremo.","A la Sala de lo Contencioso-administrativo de la Audiencia Nacional.","A la Sala de lo Contencioso-Administrativo del Tribunal Superior de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia</mark></span>Si lo pide una autoridad AUTONÓMICA de protección de datos, corresponde a la Sala de lo Contencioso-Administrativo del TSJ (art. 74.5). Según el <span class=\"ref-norma\">art. 95.e de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Corresponde a la Sección de lo Contencioso-Administrativo autorizar, mediante auto, el requerimiento de información por parte de la Agencia Española de Protección de Datos y otras autoridades administrativas independientes de ámbito estatal\"</span> (verificado con el texto del temario)."},{"i":"8-49","p":"Ley Orgánica 6/1985, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. ¿A quién corresponde autorizar, mediante auto, el requerimiento de información por parte de autoridades autonómicas de protección de datos a los operadores que presten servicios de comunicaciones electrónicas disponibles al público y de los prestadores de servicios de la sociedad de la información, cuando ello sea necesario de acuerdo con la legislación específica?","o":["A la Sala de lo Contencioso-administrativo del Tribunal Supremo.","A la Sala de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","A la Sala de lo Contencioso-administrativo de la Audiencia Nacional.","Al Tribunal Constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A la Sala de lo Contencioso-administrativo de los Tribunales Superiores de Justicia</mark></span>Si la autoridad es la AEPD u otra de ámbito estatal: Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia (art. 95.e). Según el <span class=\"ref-norma\">art. 74.5 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Corresponde a las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia autorizar, mediante auto, el requerimiento de información por parte de autoridades autonómicas de protección de datos\"</span> (verificado con el texto del temario)."},{"i":"8-129","p":"Ley Orgánica 6/1985 del Poder Judicial. La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica reguladora del Derecho de Reunión corresponderá a:","o":["Las Salas de lo Contencioso-Administrativo de la Audiencia Provincial.","Las Salas de lo Contencioso-Administrativo de la Audiencia Nacional.","Las Salas de lo Contencioso-Administrativo del Tribunal Supremo.","Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia.</mark></span><span class=\"ref-norma\">Art. 74.2 · Poder Judicial</span>. Corresponde a las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocer de la prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica reguladora del Derecho de Reunión (art. 74.2 LOPJ)."},{"i":"8-132","p":"Ley Orgánica 6/1985 del Poder Judicial. De las disposiciones generales emanadas de las Comunidades Autónomas y de las Entidades locales conocerá:","o":["Los Juzgados de lo Contencioso-Administrativo.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-Administrativo del Tribunal Superior de Justicia.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-Administrativo del Tribunal Superior de Justicia</mark></span>Ya no son los Juzgados de lo Contencioso: lo conoce la Sala del TSJ. Según el <span class=\"ref-norma\">art. 74.1.b de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los recursos que se deduzcan en relación con: [...] b) Las disposiciones generales emanadas de las comunidades autónomas y de las Entidades locales\"</span> (verificado con el texto del temario)."},{"i":"8-197","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá de los recursos contencioso-administrativos que se deduzcan en relación con los actos y disposiciones de la Administración Periférica del Estado y de la Administración de las Comunidades Autónomas, en materias de personal, propiedades especiales y expropiación forzosa, a excepción de lo dispuesto en esta ley?","o":["La Sala de lo Contencioso-Administrativo del Tribunal Supremo.","La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.","La Sección de lo Contencioso-administrativo del Tribunal de Instancia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo de los Tribunales Superiores de Justicia.</mark></span><span class=\"ref-norma\">Art. 74.4 · Poder Judicial</span>. El artículo 74.4 de la LOPJ atribuye a las Salas de lo Contencioso-administrativo de los Tribunales Superiores de Justicia el conocimiento de los recursos contra los actos y disposiciones de la Administración Periférica del Estado y de la Administración de las Comunidades Autónomas, cuyo conocimiento no esté expresamente atribuido a otros órganos."},{"i":"8-275","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los recursos que se deduzcan en relación con:","o":["Los actos y disposiciones de la Junta Electoral Central en materia de proclamación de electos.","Los actos y disposiciones de las Juntas Electorales Provinciales y de Comunidades Autónomas, así como los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre proclamación de electos.","Los acuerdos de las Juntas Electorales de Zona sobre elección de Alcaldes en municipios de menos de mil habitantes, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","Los actos de las Cortes Generales y de las Asambleas Legislativas en materia de personal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los actos y disposiciones de las Juntas Electorales Provinciales y de Comunidades Autónomas, así como los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre proclamación de electos</mark></span>El <span class=\"ref-norma\">art. 74.1.f) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"f) Los actos y disposiciones de las Juntas Electorales Provinciales y de Comunidades Autónomas, así como los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre proclamación de electos y elección y proclamación de Presidentes y Presidentas de Corporaciones locales en los términos de la legislación electoral.\"</span>"},{"i":"8-276","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los recursos que se deduzcan en relación con:","o":["La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, reguladora del derecho de reunión.","La prohibición de manifestaciones convocadas en lugares de tránsito público, previstas en la Ley Orgánica 4/2015.","La disolución de reuniones previstas en la Ley Orgánica 9/1983, por orden de la autoridad gubernativa.","Los convenios entre Administraciones públicas cuyas competencias se ejerzan en el ámbito de la comunidad autónoma, en los términos que determine la ley orgánica correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, reguladora del derecho de reunión</mark></span>El <span class=\"ref-norma\">art. 74.1.h) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"h) La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, de 15 de julio, reguladora del derecho de reunión.\"</span>"},{"i":"8-277","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán de los actos y resoluciones dictados por órganos de la Administración General del Estado cuya competencia se extienda a todo el territorio nacional y cuyo nivel orgánico sea:","o":["Superior al de Director General, en materias de personal, propiedades especiales y sanciones.","Inferior a Subsecretario, en materias de personal, contratación y expropiación forzosa.","Igual al de Ministro o Secretario de Estado, en materias de personal y propiedades especiales, salvo que el órgano competente acuerde otra cosa de forma motivada.","Inferior a Ministro, Ministra, Secretario o Secretaria de Estado, en materias de personal, propiedades especiales y expropiación forzosa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Inferior a Ministro, Ministra, Secretario o Secretaria de Estado, en materias de personal, propiedades especiales y expropiación forzosa</mark></span>El <span class=\"ref-norma\">art. 74.1.i) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"i) Los actos y resoluciones dictados por órganos de la Administración General del Estado cuya competencia se extienda a todo el territorio nacional y cuyo nivel orgánico sea inferior a Ministro, Ministra, Secretario o Secretaria de Estado, en materias de personal, propiedades especiales y expropiación forzosa\"</span>"},{"i":"8-ia-8464","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los actos y resoluciones dictados por los Tribunales Económico-Administrativos Regionales y Locales:","o":["que resuelvan reclamaciones de cuantía superior a seiscientos mil euros.","que sean recurridos en alzada ante el Tribunal Económico-Administrativo Central.","en materia de tributos del Estado exclusivamente.","que pongan fin a la vía económico-administrativa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">que pongan fin a la vía económico-administrativa</mark></span>El <span class=\"ref-norma\">art. 74.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los actos y resoluciones dictados por los Tribunales Económico-Administrativos Regionales y Locales que pongan fin a la vía económico-administrativa\"</span>. Los que ponen fin a la vía económico-administrativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8466","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los actos y disposiciones de las Juntas Electorales Provinciales y de Comunidades Autónomas, así como de los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre:","o":["proclamación de candidaturas y designación de interventores, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","proclamación de electos y elección y proclamación de Presidentes y Presidentas de Corporaciones locales en los términos de la legislación electoral.","escrutinio general y proclamación de resultados autonómicos.","convocatoria de elecciones locales y autonómicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">proclamación de electos y elección y proclamación de Presidentes y Presidentas de Corporaciones locales en los términos de la legislación electoral</mark></span>El <span class=\"ref-norma\">art. 74.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"así como los recursos contencioso-electorales contra acuerdos de las Juntas Electorales sobre proclamación de electos y elección y proclamación de Presidentes y Presidentas de Corporaciones locales en los términos de la legislación electoral\"</span>. Proclamación de electos y elección y proclamación de Presidentes de Corporaciones locales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8467","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los convenios entre Administraciones públicas:","o":["cuyas competencias se ejerzan en el ámbito territorial de la correspondiente comunidad autónoma.","suscritos por la Administración General del Estado con las Entidades locales, salvo que la ley disponga otra cosa.","que afecten a más de una comunidad autónoma.","cuya cuantía no exceda de tres millones de euros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuyas competencias se ejerzan en el ámbito territorial de la correspondiente comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 74.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los convenios entre Administraciones públicas cuyas competencias se ejerzan en el ámbito territorial de la correspondiente comunidad autónoma\"</span>. El criterio es el ámbito territorial de la comunidad autónoma. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8468","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los recursos relativos a la prohibición o la propuesta de modificación de reuniones previstas en:","o":["la Ley Orgánica 1/1992, de Protección de la Seguridad Ciudadana, conforme al procedimiento que establezcan las leyes procesales.","la Ley Orgánica 4/2015, de Protección de la Seguridad Ciudadana.","la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad.","la Ley Orgánica 9/1983, de 15 de julio, reguladora del derecho de reunión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Ley Orgánica 9/1983, de 15 de julio, reguladora del derecho de reunión</mark></span>El <span class=\"ref-norma\">art. 74.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La prohibición o la propuesta de modificación de reuniones previstas en la Ley Orgánica 9/1983, de 15 de julio, reguladora del derecho de reunión\"</span>. Es la LO 9/1983 reguladora del derecho de reunión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8469","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en segunda instancia:","o":["de las apelaciones promovidas contra las sentencias de la Audiencia Nacional.","de las apelaciones contra los actos de las Entidades locales.","de las apelaciones promovidas contra sentencias y autos dictados en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia y de los correspondientes recursos de queja.","de los recursos de casación contra las sentencias de las Audiencias Provinciales, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de las apelaciones promovidas contra sentencias y autos dictados en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia y de los correspondientes recursos de queja</mark></span>El <span class=\"ref-norma\">art. 74.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Conocerán, en segunda instancia, de las apelaciones promovidas contra sentencias y autos dictados en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia y de los correspondientes recursos de queja\"</span>. Apelaciones y recursos de queja respecto de las Secciones de lo Contencioso-Administrativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8470","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. A las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia les corresponde, con arreglo a lo establecido en esta ley, el conocimiento de los recursos de revisión contra las sentencias:","o":["dictadas en única instancia por la Audiencia Nacional, conforme al procedimiento que establezcan las leyes procesales.","firmes dictadas en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia.","dictadas en apelación por las Audiencias Provinciales.","firmes dictadas por el Tribunal Supremo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">firmes dictadas en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia</mark></span>El <span class=\"ref-norma\">art. 74.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"el conocimiento de los recursos de revisión contra las sentencias firmes dictadas en las Secciones de lo Contencioso-Administrativo de los Tribunales de Instancia\"</span>. Revisión contra sentencias firmes de las Secciones de lo Contencioso-Administrativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8471","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Corresponde a las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia autorizar, mediante auto, el requerimiento de información por parte de autoridades autonómicas de protección de datos a los operadores que presten servicios de comunicaciones electrónicas disponibles al público y de los prestadores de servicios de la sociedad de la información, cuando:","o":["ello sea necesario de acuerdo con la legislación específica.","lo solicite el Ministerio Fiscal.","exista una investigación penal en curso.","el interesado lo haya denunciado previamente, sin perjuicio de lo dispuesto en otras leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ello sea necesario de acuerdo con la legislación específica</mark></span>El <span class=\"ref-norma\">art. 74.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando ello sea necesario de acuerdo con la legislación específica\"</span>. Se autoriza mediante auto cuando sea necesario conforme a la legislación específica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8905","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. Corresponde a la Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia autorizar, mediante auto, el requerimiento de información por parte de la Agencia Española de Protección de Datos y otras autoridades administrativas independientes de ámbito estatal a los operadores que presten servicios de comunicaciones electrónicas, cuando:","o":["ello sea necesario de acuerdo con la legislación específica.","lo solicite el Ministerio Fiscal.","exista riesgo para la seguridad nacional.","el operador se niegue a facilitar los datos, salvo que la ley disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ello sea necesario de acuerdo con la legislación específica</mark></span>El <span class=\"ref-norma\">art. 95.e de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando ello sea necesario de acuerdo con la legislación específica\"</span>. Cuando sea necesario según la legislación específica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 379 EX ✱","q":[{"i":"8-40","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la inamovilidad de Jueces y Magistrados. La condición de Jueces o Magistrados se perderá por las siguientes causas:","o":["Por la condena a pena privativa de libertad por razón de delito de imprudencia.","Por renuncia a la Carrera Judicial.","Por la condena a pena de multa por razón de delito doloso.","Por traslado forzoso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por renuncia a la Carrera Judicial</mark></span>Se corrigen las opciones C y D, que también eran causas reales. Según el <span class=\"ref-norma\">art. 379.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"La condición de Jueces o Magistrados se perderá por las siguientes causas: a) Por renuncia a la Carrera Judicial. b) Por pérdida de la nacionalidad española. c) En virtud de sanción disciplinaria de separación [...] d) Por la condena a pena privativa de libertad por razón de delito doloso [...] f) Por jubilación\"</span> (verificado con el texto del temario)."},{"i":"8-112","p":"La condición de Juez o Magistrado se perderá por:","o":["Pérdida de la nacionalidad española.","Condena a pena privativa de libertad por razón de delito doloso.","Renuncia a la Carrera Judicial.","Todas las anteriores son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las anteriores son correctas</mark></span>Según el <span class=\"ref-norma\">art. 379 de la LOPJ</span>: <span class=\"ref-concepto\">\"b) Por pérdida de la nacionalidad española. c) En virtud de sanción disciplinaria de separación de la Carrera Judicial. d) Por la condena a pena privativa de libertad por razón de delito doloso\"</span> (verificado con el texto del temario oficial)."},{"i":"8-193","p":"Ley Orgánica 6/1985 del Poder Judicial. De los Abogados, Procuradores y Graduados Sociales. Señale la INCORRECTA.","o":["Corresponde en exclusiva la denominación y función de procurador al licenciado en Derecho que ejerza profesionalmente la dirección y defensa de las partes en toda clase de procesos, el asesoramiento y consejo jurídico.","Las correcciones disciplinarias por su actuación ante los juzgados y tribunales se regirán por lo establecido en esta ley y en las leyes procesales.","Los abogados deberán guardar secreto de todos los hechos o noticias de que conozcan por razón de cualesquiera de las modalidades de su actuación profesional, no pudiendo ser obligados a declarar sobre los mismos.","Salvo que la ley disponga otra cosa, las partes podrán designar libremente a sus representantes y defensores entre los Procuradores y Abogados que reúnan los requisitos exigidos por las leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Corresponde en exclusiva la denominación y función de procurador al licenciado en Derecho que ejerza profesionalmente la dirección y defens…</mark></span>- La función del Procurador es la representación de las partes ante los Juzgados y Tribunales. La dirección y defensa de las partes, así como el asesoramiento y consejo jurídico, son funciones exclusivas del Abogado. &amp;lt;hr&amp;gt;"},{"i":"8-305","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Pérdida de la condición de juez. La condición de Jueces o Magistrados se perderá, entre otras causas:","o":["Por traslado forzoso a otra plaza o por sanción disciplinaria de suspensión de funciones, sin perjuicio de lo que establezcan los tratados internacionales.","Por cumplir sesenta y cinco años de edad o por incapacidad temporal prolongada.","Por condena a pena privativa de libertad por razón de delito imprudente.","Por pérdida de la nacionalidad española o en virtud de sanción disciplinaria de separación de la Carrera Judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por pérdida de la nacionalidad española o en virtud de sanción disciplinaria de separación de la Carrera Judicial</mark></span>El <span class=\"ref-norma\">art. 379.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Por pérdida de la nacionalidad española. c) En virtud de sanción disciplinaria de separación de la Carrera Judicial.\"</span>"},{"i":"8-ia-8926","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Pérdida de la condición de Juez. La condición de Jueces o Magistrados se perderá, entre otras causas, por la condena a pena privativa de libertad por razón de delito doloso. En los casos en que la pena no fuera superior a seis meses, el Consejo General del Poder Judicial, de forma motivada y atendiendo a la entidad del delito cometido:","o":["deberá mantener la condición de Juez sin sanción alguna, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","suspenderá al Juez durante el tiempo de la pena.","trasladará al Juez a un destino distinto.","podrá sustituir la pérdida de la condición de Magistrado o Juez por la sanción prevista en el artículo 420.1, d)."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">podrá sustituir la pérdida de la condición de Magistrado o Juez por la sanción prevista en el artículo 420.1, d)</mark></span>El <span class=\"ref-norma\">art. 379.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En los casos en que la pena no fuera superior a seis meses, el Consejo General del Poder Judicial, de forma motivada y atendiendo a la entidad del delito cometido, podrá sustituir la pérdida de la condición de Magistrado o Juez por la sanción prevista en el artículo 420.1, d)\"</span>. Posible sustitución cuando la pena no supere seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 octies","q":[{"i":"8-41","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la extensión y límites de la jurisdicción. Los Tribunales españoles se declararán incompetentes:","o":["Cuando el supuesto litigioso presente vinculación con España y los Tribunales de los distintos Estados conectados con el supuesto hayan declinado su competencia.","Si su competencia no estuviera fundada en las disposiciones de las leyes españolas, de conformidad con lo previsto en las leyes procesales.","Cuando se trate del reconocimiento y la ejecución de resoluciones judiciales, decisiones arbitrales y acuerdos de mediación dictados por los Tribunales extranjeros.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Si su competencia no estuviera fundada en las disposiciones de las leyes españolas, de conformidad con lo previsto en las leyes procesales.</mark></span><span class=\"ref-norma\">Art. 9.6 · De la Extensión y Límites de la Jurisdicción</span>. El artículo 9.6 de la LOPJ establece que los Tribunales españoles se declararán incompetentes &quot;Si su competencia no estuviera fundada en las disposiciones de las leyes españolas&quot;. En los supuestos de las opciones (a) y (c), la misma ley establece que los Tribunales españoles no podrán abstenerse o declinar su competencia."},{"i":"8-ia-8068","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Apreciación de la competencia. No serán competentes los Tribunales españoles:","o":["cuando el demandado resida habitualmente en el extranjero.","en aquellos casos en que los fueros de competencia previstos en las leyes españolas no contemplen dicha competencia.","cuando haya litispendencia internacional con un Tribunal de la Unión Europea, sin perjuicio de lo dispuesto en otras leyes.","en las pretensiones relativas a bienes que se hallen fuera de España."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en aquellos casos en que los fueros de competencia previstos en las leyes españolas no contemplen dicha competencia</mark></span>El <span class=\"ref-norma\">art. 22 octies.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"No serán competentes los Tribunales españoles en aquellos casos en que los fueros de competencia previstos en las leyes españolas no contemplen dicha competencia\"</span>. La incompetencia deriva de la ausencia de fuero en las leyes españolas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8069","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Apreciación de la competencia. Los Tribunales españoles apreciarán, de oficio o a instancia de parte, su competencia de conformidad con las normas vigentes y las circunstancias concurrentes:","o":["en el momento de presentación de la demanda, y el proceso se sustanciará hasta su conclusión aunque dichas normas o circunstancias hayan sido modificadas con posterioridad, salvo que expresamente se determine lo contrario.","en el momento de la contestación a la demanda, y el proceso se sustanciará con las normas vigentes al dictar sentencia, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","en el momento en que se dicte sentencia, aplicando las normas que se hubieran modificado.","en el momento de la admisión a trámite, salvo que las partes acuerden otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en el momento de presentación de la demanda, y el proceso se sustanciará hasta su conclusión aunque dichas normas o circunstancias hayan sido modificadas con posterioridad, salvo que expresamente se determine lo contrario</mark></span>El <span class=\"ref-norma\">art. 22 octies.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"las circunstancias concurrentes en el momento de presentación de la demanda, y el proceso se sustanciará hasta su conclusión aunque dichas normas o circunstancias hayan sido modificadas con posterioridad, salvo que expresamente se determine lo contrario\"</span>. Rige el momento de presentación de la demanda (perpetuatio iurisdictionis). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8070","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Declinatoria. Los Tribunales españoles no podrán abstenerse o declinar su competencia cuando el supuesto litigioso presente vinculación con España y:","o":["las partes se hayan sometido a un Tribunal extranjero.","el demandado haya impugnado la competencia en tiempo y forma.","exista un acuerdo de elección de foro a favor de un Tribunal extranjero, sin perjuicio de lo dispuesto en otras leyes.","los Tribunales de los distintos Estados conectados con el supuesto hayan declinado su competencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los Tribunales de los distintos Estados conectados con el supuesto hayan declinado su competencia</mark></span>El <span class=\"ref-norma\">art. 22 octies.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Tribunales españoles no podrán abstenerse o declinar su competencia cuando el supuesto litigioso presente vinculación con España y los Tribunales de los distintos Estados conectados con el supuesto hayan declinado su competencia\"</span>. Se evita la denegación de justicia cuando todos los demás Estados conectados han declinado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8346","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá de los recursos contra las resoluciones dictadas por la Sección de Vigilancia Penitenciaria del Tribunal Central de Instancia:","o":["de conformidad con lo previsto en el Código Penal, en los términos que establezca la ley orgánica.","cuando la pena impuesta exceda de cinco años.","siempre que lo solicite el Ministerio Fiscal.","de conformidad con lo previsto en la disposición adicional quinta."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de conformidad con lo previsto en la disposición adicional quinta</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De los recursos contra las resoluciones dictadas por la Sección de Vigilancia Penitenciaria del Tribunal Central de Instancia de conformidad con lo previsto en la disposición adicional quinta\"</span>. Conforme a la disposición adicional quinta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 6 R3","q":[{"i":"8-47","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. Los jueces y tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios:","o":["A la Constitución.","A la Ley.","Al principio de jerarquía normativa.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 6 · Poder Judicial</span>. El artículo 6 de la LOPJ establece que los Jueces y Tribunales no aplicarán los Reglamentos o cualquier otra disposición contraria a la Constitución, a la Ley o al principio de jerarquía normativa."},{"i":"8-139","p":"(LOPJ) Según el artículo 6 de la LOPJ:","o":["Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios a la Ley, a la Constitución o al principio de jerarquía normativa.","Los Jueces y Tribunales no aplicarán los reglamentos contrarios a la ley o a la Constitución.","Los Jueces y Tribunales inaplicarán los reglamentos o cualquier otra disposición contrarios a la ley o al principio de jerarquía normativa.","Los Jueces y Tribunales aplicarán la norma de rango superior en caso de conflicto con los reglamentos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios a la Ley, a la Constitución o al principio de …</mark></span><span class=\"ref-norma\">Art. 6 · Poder Judicial</span>. El artículo 6 de la LOPJ establece que &quot;Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios a la Constitución, a la ley o al principio de jerarquía normativa.&quot;"},{"i":"8-ia-8013","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Control de los reglamentos. Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios:","o":["a la Constitución, a la ley o al principio de jerarquía normativa.","a la Constitución o a las leyes orgánicas exclusivamente.","a la ley o a la jurisprudencia del Tribunal Supremo.","a la Constitución y a los tratados internacionales ratificados, en los términos que establezca la ley orgánica."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Constitución, a la ley o al principio de jerarquía normativa</mark></span>El <span class=\"ref-norma\">art. 6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Jueces y Tribunales no aplicarán los reglamentos o cualquier otra disposición contrarios a la Constitución, a la ley o al principio de jerarquía normativa\"</span>. Se enumeran tres referentes: Constitución, ley y principio de jerarquía normativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8018","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Atribución de jurisdicción. Los jueces y juezas, así como los Tribunales ejercerán su jurisdicción exclusivamente en aquellos casos en que les venga atribuida:","o":["por esta ley orgánica.","por la Constitución o por esta ley.","por esta ley o por los tratados internacionales.","por esta u otra ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por esta u otra ley</mark></span>El <span class=\"ref-norma\">art. 9.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"ejercerán su jurisdicción exclusivamente en aquellos casos en que les venga atribuida por esta u otra ley\"</span>. La atribución puede venir de esta u otra ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 18 ✱","q":[{"i":"8-54","p":"Ley Orgánica 6/1985, del Poder Judicial. Del Poder Judicial y del ejercicio de la potestad jurisdiccional. Señale la opción correcta en esta materia:","o":["Las resoluciones judiciales no podrán dejarse sin efecto.","Sólo por causa de utilidad pública o interés social, declarada por el Gobierno, podrán expropiarse los derechos reconocidos frente a la Administración Pública en una sentencia firme, antes de su ejecución.","Todos podrán ejercer la acción popular, en los casos y formas establecidos en la ley.","Todos podrán participar en la Administración de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sólo por causa de utilidad pública o interés social, declarada por el Gobierno, podrán expropiarse los derechos reconocidos frente a la Adm…</mark></span><span class=\"ref-norma\">Art. 17.2 · Poder Judicial</span>. (Pregunta repetida). El artículo 17.2 de la LOPJ establece que: &quot;Sólo por causa de utilidad pública o interés social, declarada por el Gobierno, podrán expropiarse los derechos reconocidos frente a la Administración Pública en una sentencia firme, antes de su ejecución.&quot;"},{"i":"8-141","p":"(LOPJ) Es obligación de los poderes públicos garantizar la defensa y la asistencia de Abogado, en los términos establecidos en:","o":["La Ley de Enjuiciamiento Criminal y la Ley de Enjuiciamiento Civil.","La Constitución y en las Leyes.","La Constitución y en los Tratados Internacionales.","La Ley de Asistencia Jurídica Gratuita."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Constitución y en las Leyes.</mark></span><span class=\"ref-norma\">Art. 546.1 · Poder Judicial</span>. El artículo 546.1 de la LOPJ establece que la garantía de la defensa y asistencia de abogado debe ser en los términos establecidos en la Constitución y en las leyes."},{"i":"8-243","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ejecución de resoluciones. Lo dispuesto en el artículo sobre el cumplimiento de las resoluciones judiciales se entiende sin perjuicio del derecho de gracia, cuyo ejercicio, de acuerdo con la Constitución y las leyes, corresponde:","o":["Al Presidente del Gobierno.","Al Rey.","Al Consejo de Ministros, a propuesta del Ministro de Justicia.","Al Tribunal Supremo, previo informe del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Rey</mark></span>El <span class=\"ref-norma\">art. 18.3 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"3. Lo dispuesto en este artículo se entiende sin perjuicio del derecho de gracia, cuyo ejercicio, de acuerdo con la Constitución y las leyes, corresponde al Rey.\"</span>"},{"i":"8-ia-8044","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ejecución de resoluciones. Las resoluciones judiciales solo podrán dejarse sin efecto:","o":["por acuerdo del órgano judicial que las dictó, de oficio o a instancia de parte.","en virtud de los recursos previstos en las leyes.","por el Consejo General del Poder Judicial, en los casos de error.","por el Tribunal Constitucional mediante recurso de amparo exclusivamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en virtud de los recursos previstos en las leyes</mark></span>El <span class=\"ref-norma\">art. 18.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las resoluciones judiciales solo podrán dejarse sin efecto en virtud de los recursos previstos en las leyes\"</span>. Solo mediante los recursos previstos legalmente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8045","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ejecución de resoluciones. Solo por causa de utilidad pública o interés social, declarada por el Gobierno, podrán expropiarse los derechos reconocidos frente a la Administración Pública en una sentencia firme, antes de su ejecución. En este caso:","o":["el Juez o Tribunal a quien corresponda la ejecución será el único competente para señalar por vía incidental la correspondiente indemnización.","el Gobierno fijará la indemnización que proceda, sin posibilidad de recurso.","el Consejo de Ministros señalará la indemnización previo informe del Consejo de Estado, conforme al procedimiento que establezcan las leyes procesales.","el Tribunal Supremo fijará la indemnización en única instancia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Juez o Tribunal a quien corresponda la ejecución será el único competente para señalar por vía incidental la correspondiente indemnización</mark></span>El <span class=\"ref-norma\">art. 18.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En este caso, el Juez o Tribunal a quien corresponda la ejecución será el único competente para señalar por vía incidental la correspondiente indemnización\"</span>. La indemnización la fija el órgano judicial de la ejecución, por vía incidental. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 65 EXOF ✱","q":[{"i":"8-56","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 65.5.º. La Sala de lo Penal de la Audiencia Nacional conocerá de los recursos establecidos en la ley contra las sentencias y otras resoluciones de las siguientes Secciones del Tribunal Central de Instancia:","o":["Sección de lo Penal.","Sección de Instrucción.","Sección de Menores.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 65.5.º de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"La Sala de lo Penal de la Audiencia Nacional conocerá: [...] 5.º De los recursos establecidos en la ley contra las sentencias y otras resoluciones de la Sección de lo Penal, de la Sección de Instrucción [...] y de la Sección de Menores, del Tribunal Central de Instancia\"</span> (verificado con el texto del temario)."},{"i":"8-63","p":"Ley Orgánica 6/1985, del Poder Judicial. De la extensión y límites de la jurisdicción y de la planta y organización de los juzgados y tribunales. De la composición y atribuciones de los órganos jurisdiccionales. La Sala de lo Penal de la Audiencia Nacional conocerá. Señale la opción incorrecta.","o":["De los recursos establecidos en la ley contra las sentencias y otras resoluciones de la Sección de lo Penal del Tribunal Central de Instancia.","De los recursos establecidos en la ley contra las sentencias y otras resoluciones de la Sección de Instrucción del Tribunal Central de Instancia.","De los recursos establecidos en la ley contra las sentencias y otras resoluciones de una Sección de Violencia de Género del Tribunal Central de Instancia.","De los recursos establecidos en la ley contra las sentencias y otras resoluciones de la Sección de Menores del Tribunal Central de Instancia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De los recursos establecidos en la ley contra las sentencias y otras resoluciones de una Sección de Violencia de Género del Tribunal Central de Instancia</mark></span>No existe una Sección de Violencia de Género en el Tribunal Central de Instancia. Según el <span class=\"ref-norma\">art. 65.5.º de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"De los recursos establecidos en la ley contra las sentencias y otras resoluciones de la Sección de lo Penal, de la Sección de Instrucción [...] y de la Sección de Menores, del Tribunal Central de Instancia\"</span> (verificado con el texto del temario)."},{"i":"8-150","p":"(LOPJ) Es competente la Audiencia Nacional para el enjuiciamiento de los delitos de falsificación de moneda y fabricación de tarjetas de crédito y débito falsas y cheques de viajero falsos o cualquier otro instrumento de pago distinto del efectivo, siempre que sean cometidos por:","o":["Más de 3 personas.","Grupos criminales o más de 5 personas.","Organizaciones o grupos criminales.","Bandas armadas y grupos criminales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Organizaciones o grupos criminales.</mark></span><span class=\"ref-norma\">Art. 65.1.b) · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 65.1.b) de la LOPJ establece la competencia &quot;siempre que sean cometidos por organizaciones o grupos criminales.&quot;"},{"i":"8-180","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Señale la incorrecta sobre la Sala de lo Penal de la Audiencia Nacional.","o":["Conocerá de los procedimientos de extradición pasiva.","Conocerá de las causas por los delitos cometidos fuera del territorio nacional, cuando conforme a las leyes o a los tratados corresponda su enjuiciamiento a los Tribunales españoles.","Conocerá de las causas por delitos de homicidio cometidos en territorio nacional.","Conocerá de los recursos que establezca la ley contra las sentencias y demás resoluciones de la Sección de Menores del Tribunal Central de Instancia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Conocerá de las causas por delitos de homicidio cometidos en territorio nacional</mark></span>La Sala de lo Penal no conoce de homicidios cometidos en territorio nacional. Según el <span class=\"ref-norma\">art. 65 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"La Sala de lo Penal de la Audiencia Nacional conocerá: [...] 4.º [...] la resolución de los procedimientos judiciales de extradición pasiva [...] 5.º De los recursos [...] de la Sección de Menores, del Tribunal Central de Instancia\"</span> (verificado con el texto del temario)."},{"i":"8-267","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá del enjuiciamiento, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, de las causas por los siguientes delitos, entre otros:","o":["Homicidios dolosos cometidos por funcionarios públicos en el ejercicio de su cargo.","Defraudaciones y maquinaciones para alterar el precio de las cosas que produzcan grave repercusión en la economía nacional.","Delitos contra la propiedad intelectual cometidos en el territorio de una sola Audiencia, salvo que el órgano competente acuerde otra cosa de forma motivada.","Delitos de lesiones graves cometidos fuera del territorio nacional por extranjeros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Defraudaciones y maquinaciones para alterar el precio de las cosas que produzcan grave repercusión en la economía nacional</mark></span>El <span class=\"ref-norma\">art. 65.1.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"c) Defraudaciones y maquinaciones para alterar el precio de las cosas que produzcan o puedan producir grave repercusión en la seguridad del tráfico mercantil, en la economía nacional o perjuicio patrimonial en una generalidad de personas en el territorio de más de una Audiencia.\"</span>"},{"i":"8-268","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá del enjuiciamiento de los delitos:","o":["Contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno.","Contra los miembros de las Cortes Generales y del Gobierno en el ejercicio de sus cargos, conforme al procedimiento que reglamentariamente se establezca.","Contra el titular de la Corona y su Consorte, con exclusión del Sucesor o Sucesora.","Contra altos organismos de la Nación y la forma de Estado, con exclusión de la Corona."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno</mark></span>El <span class=\"ref-norma\">art. 65.1.º.a) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Delitos contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno.\"</span>"},{"i":"8-269","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá de los recursos respecto a los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley, y de la resolución de los procedimientos judiciales de extradición pasiva:","o":["Siempre que la detención hubiera tenido lugar en la provincia de Madrid.","Únicamente cuando el afectado resida en territorio nacional al tiempo de la detención.","Salvo que la detención se hubiese producido en el territorio de otra Audiencia Provincial, sin perjuicio de lo que establezcan los tratados internacionales.","Sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento</mark></span>El <span class=\"ref-norma\">art. 65.4.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"4.º De los recursos respecto a los instrumentos de reconocimiento mutuo de resoluciones penales en la Unión Europea que les atribuya la ley, y la resolución de los procedimientos judiciales de extradición pasiva, sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento.\"</span>"},{"i":"8-ia-8339","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá del enjuiciamiento de las causas por delitos contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y:","o":["seguridad exterior del Estado.","integridad territorial.","forma de Gobierno.","orden constitucional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">forma de Gobierno</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Delitos contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno\"</span>. Se trata de los delitos contra la Corona, altos organismos de la Nación y forma de Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8340","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá del enjuiciamiento de los delitos de falsificación de moneda y fabricación de tarjetas de crédito y débito falsas y cheques de viajero falsos, siempre que sean cometidos:","o":["por funcionarios públicos o sus colaboradores.","por organizaciones o grupos criminales.","en el territorio de más de una Audiencia.","por extranjeros en territorio español."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por organizaciones o grupos criminales</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que sean cometidos por organizaciones o grupos criminales\"</span>. Se exige que se cometan por organizaciones o grupos criminales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8341","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá de los delitos de tráfico de drogas o estupefacientes, fraudes alimentarios y de sustancias farmacéuticas o medicinales, siempre que sean cometidos por bandas o grupos organizados y:","o":["produzcan efectos en lugares pertenecientes a distintas Audiencias.","afecten a más de una Comunidad Autónoma.","se cometan fuera del territorio nacional.","afecten a la salud pública de más de cien personas, salvo que la ley disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">produzcan efectos en lugares pertenecientes a distintas Audiencias</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que sean cometidos por bandas o grupos organizados y produzcan efectos en lugares pertenecientes a distintas Audiencias\"</span>. Se exige que produzcan efectos en lugares de distintas Audiencias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8343","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo penal de la Audiencia Nacional extenderá su competencia al conocimiento:","o":["de los delitos de menor gravedad cometidos en el mismo hecho.","de las faltas conexas con los delitos de su competencia.","de los delitos conexos con todos los anteriormente reseñados.","de los delitos cometidos por los mismos autores en un plazo de cinco años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de los delitos conexos con todos los anteriormente reseñados</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En todo caso, la Sala de lo penal de la Audiencia Nacional extenderá su competencia al conocimiento de los delitos conexos con todos los anteriormente reseñados\"</span>. Se extiende a los delitos conexos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8344","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá de los procedimientos judiciales de extradición pasiva:","o":["únicamente cuando la detención haya tenido lugar en Madrid.","sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento.","cuando el afectado resida en España y se encuentre detenido, conforme al procedimiento que establezcan las leyes procesales.","cuando el Estado requirente sea miembro de la Unión Europea."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"y la resolución de los procedimientos judiciales de extradición pasiva, sea cual fuere el lugar de residencia o en que hubiese tenido lugar la detención del afectado por el procedimiento\"</span>. Sin importar el lugar de residencia o detención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8345","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá de las cuestiones de cesión de jurisdicción en materia penal:","o":["derivadas del cumplimiento de tratados internacionales en los que España sea parte.","derivadas de resoluciones de tribunales de la Unión Europea.","planteadas entre los Tribunales de Instancia y el Tribunal Central de Instancia, sin perjuicio de lo dispuesto en otras leyes.","derivadas de conflictos entre órganos jurisdiccionales penales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">derivadas del cumplimiento de tratados internacionales en los que España sea parte</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De las cuestiones de cesión de jurisdicción en materia penal derivadas del cumplimiento de tratados internacionales en los que España sea parte\"</span>. Se trata de las derivadas del cumplimiento de tratados internacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 90 EX","q":[{"i":"8-57","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 90.4. ¿A quién corresponde la ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción?","o":["A las Audiencias Provinciales.","A las Secciones de lo Penal de los Tribunales de Instancia.","A los Tribunales Superiores de Justicia.","Al Tribunal Supremo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A las Secciones de lo Penal de los Tribunales de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 90.4 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Corresponde asimismo a las Secciones de lo Penal la ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción, Secciones de Violencia sobre la Mujer y Secciones de Violencia contra la Infancia y la Adolescencia\"</span> (verificado con el texto del temario)."},{"i":"8-68","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 90.4. Corresponde asimismo a las Secciones de lo Penal de los Tribunales de Instancia:","o":["La ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción, Secciones de Violencia sobre la Mujer y Secciones de Violencia contra la Infancia y la Adolescencia.","El reconocimiento y ejecución de las resoluciones que impongan sanciones pecuniarias transmitidas por las autoridades competentes de otros Estados miembros de la Unión Europea, cuando las mismas deban cumplirse en territorio español.","Los procedimientos de decomiso autónomo por los delitos para cuyo conocimiento sean competentes.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Las tres opciones figuran en el art. 90.4. Según el <span class=\"ref-norma\">art. 90.4 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Corresponde asimismo a las Secciones de lo Penal la ejecución de las sentencias dictadas en causas por delito grave o menos grave [...]; el reconocimiento y ejecución de las resoluciones que impongan sanciones pecuniarias transmitidas por las autoridades competentes de otros Estados miembros de la Unión Europea [...], y los procedimientos de decomiso autónomo\"</span> (verificado con el texto del temario)."},{"i":"8-71","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 90.4. Corresponde asimismo a las Secciones de lo Penal de los Tribunales de Instancia:","o":["La ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción, Secciones de Violencia sobre la Mujer y Secciones de Violencia contra la Infancia y la Adolescencia.","El reconocimiento y ejecución de las resoluciones que impongan sanciones pecuniarias transmitidas por las autoridades competentes de otros Estados miembros de la Unión Europea, cuando las mismas deban cumplirse en territorio español.","Los procedimientos de decomiso autónomo por los delitos para cuyo conocimiento sean competentes.","Todas son correctas. Nota: Esta pregunta es idéntica a la Pregunta 3."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas. Nota: Esta pregunta es idéntica a la Pregunta 3</mark></span>Las tres opciones figuran en el art. 90.4. Según el <span class=\"ref-norma\">art. 90.4 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Corresponde asimismo a las Secciones de lo Penal la ejecución de las sentencias dictadas en causas por delito grave o menos grave [...]; el reconocimiento y ejecución de las resoluciones que impongan sanciones pecuniarias transmitidas por las autoridades competentes de otros Estados miembros de la Unión Europea [...], y los procedimientos de decomiso autónomo\"</span> (verificado con el texto del temario)."},{"i":"8-73","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 90.4. ¿A qué órgano corresponderá la ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción?","o":["Secciones de lo Penal de los Tribunales de Instancia.","Audiencia Provincial.","Secciones de lo Social de los Tribunales de Instancia.","Secciones Civiles de los Tribunales de Instancia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Secciones de lo Penal de los Tribunales de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 90.4 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Corresponde asimismo a las Secciones de lo Penal la ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8779","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Penal. Con carácter general, en el Tribunal de Instancia, con sede en la capital de cada provincia y con jurisdicción en toda ella, existirá:","o":["una Sección de lo Penal.","una Sala de lo Penal.","una Sección de lo Penal por cada partido judicial.","una Audiencia Penal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una Sección de lo Penal</mark></span>El <span class=\"ref-norma\">art. 90.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Con carácter general, en el Tribunal de Instancia, con sede en la capital de cada provincia y con jurisdicción en toda ella, existirá una Sección de lo Penal\"</span>. Una Sección de lo Penal por provincia, con sede en la capital. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8780","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Penal. También podrán establecerse Secciones de lo Penal en Tribunales de Instancia que tengan su sede en poblaciones distintas de la capital de provincia:","o":["con jurisdicción en toda la provincia.","con competencia exclusiva sobre delitos leves.","siempre que la población supere los cien mil habitantes, en los términos que establezca la ley orgánica.","delimitándose en cada caso el ámbito territorial de su jurisdicción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">delimitándose en cada caso el ámbito territorial de su jurisdicción</mark></span>El <span class=\"ref-norma\">art. 90.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"También podrán establecerse Secciones de lo Penal en Tribunales de Instancia que tengan su sede en poblaciones distintas de la capital de provincia, delimitándose en cada caso el ámbito territorial de su jurisdicción\"</span>. Se delimita el ámbito territorial de cada una. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8781","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Penal. Para facilitar el conocimiento de los asuntos instruidos por las Secciones de Violencia sobre la Mujer y de Violencia contra la Infancia y la Adolescencia, y atendiendo al número de asuntos existentes, en la Sección de lo Penal:","o":["podrán especializarse una o varias plazas judiciales, salvo que la ley disponga otra cosa.","deberá crearse una Sección específica.","deberán especializarse una o varias plazas judiciales.","se atribuirán a la Audiencia Provincial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">deberán especializarse una o varias plazas judiciales</mark></span>El <span class=\"ref-norma\">art. 90.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"deberán especializarse una o varias plazas judiciales de la Sección de lo Penal\"</span>. Deberán especializarse plazas judiciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8782","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Penal. Corresponde a las Secciones de lo Penal la ejecución de las sentencias dictadas en causas por delito grave o menos grave por las Secciones de Instrucción y por las Secciones de Violencia, y el reconocimiento y ejecución de las resoluciones que impongan sanciones pecuniarias transmitidas por las autoridades competentes de:","o":["cualquier Estado con el que España tenga convenio, aunque no sea de la Unión Europea, conforme al procedimiento que establezcan las leyes procesales.","otros Estados miembros de la Unión Europea, cuando las mismas deban cumplirse en territorio español.","las Comunidades Autónomas en las que se hayan impuesto.","organismos internacionales con sede en España."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">otros Estados miembros de la Unión Europea, cuando las mismas deban cumplirse en territorio español</mark></span>El <span class=\"ref-norma\">art. 90.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"el reconocimiento y ejecución de las resoluciones que impongan sanciones pecuniarias transmitidas por las autoridades competentes de otros Estados miembros de la Unión Europea, cuando las mismas deban cumplirse en territorio español\"</span>. Otros Estados miembros de la Unión Europea. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9 EXOF EX ✱ R4","q":[{"i":"8-59","p":"Ley Orgánica 6/1985, del Poder Judicial. Del Poder Judicial y del ejercicio de la potestad jurisdiccional. Señale la opción correcta en esta materia:","o":["Los Tribunales y Juzgados del orden social conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional.","Los del orden jurisdiccional penal tendrán atribuido el conocimiento de las causas y juicios criminales que correspondan a la jurisdicción militar.","Los del orden contencioso-administrativo conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones sociales sujetas al derecho administrativo, con las disposiciones generales de rango de ley y con las normas reglamentarias.","En el orden civil, corresponderá a la jurisdicción militar la prevención de los juicios de testamentaría y de abintestato de los miembros de las Fuerzas Armadas que, en situación de conflicto armado, fallecieren en campaña o navegación, limitándose a la práctica de la asistencia imprescindible para disponer el sepelio del difunto y la formación del inventario y aseguramiento provisorio de sus bienes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En el orden civil, corresponderá a la jurisdicción militar la prevención de los juicios de testamentaría y de abintestato de los miembros de las Fuerzas Armadas que, en situación de conflicto armado, fallecieren en campaña o navegación, limitándose a la práctica de la asistencia imprescindible para disponer el sepelio del difunto y la formación del inventario y aseguramiento provisorio de sus bienes</mark></span>Según el <span class=\"ref-norma\">art. 9.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"En este orden civil, corresponderá a la Jurisdicción Militar la prevención de los juicios de testamentaría y de abintestato de los miembros de las Fuerzas Armadas que, en situación de conflicto armado, fallecieren en campaña o navegación\"</span> (verificado con el texto del temario)."},{"i":"8-168","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. ¿Quién conocerá de los recursos contra la inactividad de la Administración y contra sus actuaciones materiales que constituyan vía de hecho?","o":["Los Tribunales y Juzgados del orden social.","Los Tribunales y Juzgados del orden civil.","Los Tribunales y Juzgados del orden penal.","Los Tribunales y Juzgados del orden contencioso-administrativo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los Tribunales y Juzgados del orden contencioso-administrativo.</mark></span><span class=\"ref-norma\">Art. 9 · Poder Judicial</span>. Los recursos contra la inactividad de la Administración y la vía de hecho (actuaciones materiales) son competencia de los Tribunales y Juzgados del orden contencioso-administrativo (art. 9 de la L.O.P.J., que delimita la jurisdicción)."},{"i":"8-189","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quiénes conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional?","o":["Los Tribunales y Juzgados del orden social.","Los Tribunales y Juzgados del orden civil.","Los Tribunales y Juzgados del orden penal.","Los Tribunales y Juzgados del orden contencioso-administrativo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Tribunales y Juzgados del orden civil.</mark></span>- La LOPJ establece que la jurisdicción ordinaria, que tiene carácter de residual o común en materia de competencias, es la civil. Los Tribunales y Juzgados del orden civil conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional. &amp;lt;hr&amp;gt;"},{"i":"8-209","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quiénes conocerán de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al derecho administrativo, con las disposiciones generales de rango inferior a la ley y con los reales decretos legislativos en los términos previstos en la Constitución, de conformidad con lo que establezca la Ley de esa jurisdicción?","o":["Los jueces y juezas, así como los Tribunales del orden civil.","Los jueces y juezas, así como los Tribunales del orden penal.","Los jueces y juezas, así como los Tribunales del orden contencioso-administrativo.","Los jueces y juezas, así como los Tribunales del orden social."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los jueces y juezas, así como los Tribunales del orden contencioso-administrativo.</mark></span><span class=\"ref-norma\">Art. 9.4 · Poder Judicial</span>. El artículo 9.4 de la LOPJ atribuye a los del orden contencioso-administrativo el conocimiento de las pretensiones que se deduzcan en relación con la actuación de las Administraciones públicas sujeta al Derecho Administrativo."},{"i":"8-222","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los _________ conocerán de las pretensiones que se promuevan dentro de la rama social del Derecho, tanto en conflictos individuales como colectivos, así como las reclamaciones en materia de Seguridad Social o contra el Estado cuando le atribuya responsabilidad la legislación laboral.","o":["Los del orden jurisdiccional social.","Los Tribunales y Juzgados del orden civil.","Los Tribunales y Juzgados del orden penal.","Los Tribunales y Juzgados del orden contencioso administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los del orden jurisdiccional social</mark></span>Según el <span class=\"ref-norma\">art. 9 de la LOPJ</span>: <span class=\"ref-concepto\">\"Los del orden jurisdiccional social conocerán de las pretensiones que se promuevan dentro de la rama social del derecho, tanto en conflictos individuales como colectivos, así como las reclamaciones en materia de Seguridad Social o contra el Estado cuando le atribuya responsabilidad la legislación laboral\"</span> (verificado con el texto del temario oficial)."},{"i":"8-237","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial Del Poder Judicial. De los abogados, procuradores y graduados sociales. La representación técnica podrá ser ostentada por un graduado social en los procedimientos:","o":["Laborales y de Seguridad Social.","Civiles.","Penales.","Administrativos y civiles."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Laborales y de Seguridad Social.</mark></span><span class=\"ref-norma\">Art. 544 · Poder Judicial</span>. La representación y defensa técnica de las partes por un Graduado Social es propia del orden jurisdiccional social, que conoce de las pretensiones en materia laboral y de Seguridad Social (Art. 544 LOPJ y Ley Reguladora de la Jurisdicción Social)."},{"i":"8-ia-8019","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Orden jurisdiccional civil. Los jueces y juezas, así como los Tribunales del orden civil conocerán, además de las materias que les son propias, de:","o":["todas aquellas que no estén atribuidas a la jurisdicción penal o militar.","las que expresamente les atribuyan las leyes civiles y mercantiles.","todas aquellas que no estén atribuidas a otro orden jurisdiccional.","las reclamaciones de responsabilidad patrimonial entre particulares."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todas aquellas que no estén atribuidas a otro orden jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 9.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional\"</span>. El orden civil tiene carácter residual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8020","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Orden jurisdiccional civil. En el orden civil, corresponderá a la Jurisdicción Militar la prevención de los juicios de testamentaría y de abintestato de los miembros de las Fuerzas Armadas que, en situación de conflicto armado, fallecieren en campaña o navegación, limitándose a:","o":["la formación del inventario y la adjudicación provisional de los bienes a los herederos.","la práctica de la asistencia imprescindible para disponer el sepelio del difunto y la formación del inventario y aseguramiento provisorio de sus bienes.","la declaración de herederos y la partición de los bienes del difunto.","la práctica de la asistencia imprescindible para el sepelio y la administración de los bienes durante el conflicto, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la práctica de la asistencia imprescindible para disponer el sepelio del difunto y la formación del inventario y aseguramiento provisorio de sus bienes</mark></span>El <span class=\"ref-norma\">art. 9.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"limitándose a la práctica de la asistencia imprescindible para disponer el sepelio del difunto y la formación del inventario y aseguramiento provisorio de sus bienes\"</span>. La jurisdicción militar solo previene: sepelio, inventario y aseguramiento provisorio, dando cuenta a la autoridad judicial civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8023","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Orden jurisdiccional contencioso-administrativo. Quedan excluidos del conocimiento del orden contencioso-administrativo los recursos directos o indirectos que se interpongan contra las Normas Forales fiscales de las Juntas Generales de los Territorios Históricos de Álava, Guipúzcoa y Vizcaya, que corresponderán, en exclusiva:","o":["al Tribunal Supremo, en los términos establecidos por la disposición adicional quinta de esta ley, en los términos que establezca la ley orgánica.","al Tribunal Superior de Justicia del País Vasco, en única instancia.","al Tribunal Constitucional, en los términos establecidos por la disposición adicional quinta de su Ley Orgánica.","a la Audiencia Nacional, en los términos establecidos por su ley de planta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Tribunal Constitucional, en los términos establecidos por la disposición adicional quinta de su Ley Orgánica</mark></span>El <span class=\"ref-norma\">art. 9.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"que corresponderán, en exclusiva, al Tribunal Constitucional, en los términos establecidos por la disposición adicional quinta de su Ley Orgánica\"</span>. Son competencia exclusiva del Tribunal Constitucional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8024","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad patrimonial. Si en la producción del daño por el que se reclama responsabilidad patrimonial de las Administraciones públicas hubieran concurrido sujetos privados:","o":["el demandante deducirá su pretensión frente a ellos ante el orden jurisdiccional civil.","el demandante deducirá también frente a ellos su pretensión ante este orden jurisdiccional.","el juez civil se inhibirá en favor del contencioso-administrativo una vez firme la sentencia.","la Administración repetirá contra ellos en vía administrativa exclusivamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el demandante deducirá también frente a ellos su pretensión ante este orden jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 9.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Si a la producción del daño hubieran concurrido sujetos privados, el demandante deducirá también frente a ellos su pretensión ante este orden jurisdiccional\"</span>. La pretensión frente a los sujetos privados concurrentes también se deduce ante el orden contencioso-administrativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8025","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad patrimonial. El orden contencioso-administrativo conocerá igualmente de las reclamaciones de responsabilidad cuando el interesado accione directamente:","o":["contra la aseguradora de la Administración, junto a la Administración respectiva.","contra la aseguradora de la Administración, con independencia de que se demande a la Administración.","contra el personal al servicio de la Administración, de forma exclusiva.","contra la entidad privada responsable, sin demandar a la Administración."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">contra la aseguradora de la Administración, junto a la Administración respectiva</mark></span>El <span class=\"ref-norma\">art. 9.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Igualmente conocerán de las reclamaciones de responsabilidad cuando el interesado accione directamente contra la aseguradora de la Administración, junto a la Administración respectiva\"</span>. La acción directa contra la aseguradora se ejerce junto con la Administración respectiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8026","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Orden jurisdiccional social. Los del orden jurisdiccional social conocerán de las pretensiones que se promuevan dentro de la rama social del derecho, tanto en conflictos individuales como colectivos, así como de las reclamaciones en materia de Seguridad Social o:","o":["contra las Comunidades Autónomas cuando les atribuya responsabilidad la legislación laboral.","contra la Administración cuando le atribuya responsabilidad la legislación administrativa.","contra el Fondo de Garantía Salarial en todo caso.","contra el Estado cuando le atribuya responsabilidad la legislación laboral."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">contra el Estado cuando le atribuya responsabilidad la legislación laboral</mark></span>El <span class=\"ref-norma\">art. 9.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"así como las reclamaciones en materia de Seguridad Social o contra el Estado cuando le atribuya responsabilidad la legislación laboral\"</span>. La reclamación contra el Estado es social cuando la responsabilidad deriva de la legislación laboral. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 57 ✱","q":[{"i":"8-60","p":"Ley Orgánica 6/1985, del Poder Judicial. La Sala de lo Penal del Tribunal Supremo conocerá. Señale la opción incorrecta.","o":["De la instrucción y enjuiciamiento de las causas contra Magistrados de la Audiencia Nacional.","De la instrucción y enjuiciamiento de las causas contra Magistrados de la Audiencia Provincial.","De los procedimientos de decomiso autónomo por los delitos para cuyo conocimiento sean competentes.","De los demás asuntos que le atribuya esta Ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De la instrucción y enjuiciamiento de las causas contra Magistrados de la Audiencia Provincial</mark></span>Las causas contra Magistrados de una Audiencia Provincial no son de la Sala de lo Penal del Tribunal Supremo. Según el <span class=\"ref-norma\">art. 57 de la LOPJ</span>: <span class=\"ref-concepto\">\"3.º De la instrucción y enjuiciamiento de las causas contra Magistrados de la Audiencia Nacional, de un Tribunal Superior de Justicia o de los Fiscales europeos delegados\"</span> (verificado con el texto del temario oficial)."},{"i":"8-81","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. La Sala de lo Social del Tribunal Supremo conocerá de:","o":["Los recursos de casación.","Los recursos de revisión.","Otros recursos extraordinarios que establezca la ley en materias propias de este orden jurisdiccional.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas.</mark></span><span class=\"ref-norma\">Art. 56.1 · De la Organización y Planta de Juzgados y Tribunales</span>. La Sala de lo Social del Tribunal Supremo conoce del recurso de casación, del recurso de revisión, y de otros recursos extraordinarios en materias propias de dicho orden jurisdiccional, según establece la LOPJ y la Ley Reguladora de la Jurisdicción Social (artículo 56.1 LOPJ)."},{"i":"8-88","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. La Sala de lo Penal del Tribunal Supremo conocerá:","o":["De los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la ley.","De los recursos de casación, reposición y otros extraordinarios en materia penal que establezca la ley.","De los recursos de reposición, apelación y otros extraordinarios en materia penal que establezca la ley.","De los recursos de queja, apelación y otros extraordinarios en materia penal que establezca la ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la ley.</mark></span><span class=\"ref-norma\">Art. 57.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 57.1.1º de la LOPJ establece que la Sala de lo Penal del Tribunal Supremo conocerá de los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la Ley. (Nota: Las opciones b, c y d son idénticas o incorrectas)."},{"i":"8-92","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. La Sala de lo Penal del Tribunal Supremo conocerá:","o":["De los recursos de casación, reposición y otros extraordinarios en materia penal que establezca la ley.","De los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la ley.","De los recursos de reposición, apelación y otros extraordinarios en materia penal que establezca la ley.","De los recursos de apelación y otros extraordinarios en materia penal que establezca la ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la ley.</mark></span><span class=\"ref-norma\">Art. 57.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 57.1.1º de la LOPJ establece que la Sala de lo Penal del Tribunal Supremo conocerá de los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la Ley. (Nota: Pregunta repetida en esencia con respecto a la 7, solo cambian las opciones)."},{"i":"8-93","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. La Sala de lo Penal del Tribunal Supremo conocerá:","o":["De los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la ley.","De los recursos de casación, reposición y otros extraordinarios en materia penal que establezca la ley.","De los recursos de reposición, apelación y otros extraordinarios en materia penal que establezca la ley.","De la instrucción y enjuiciamiento de las causas contra el Presidente del Gobierno, Presidentes del Congreso y del Senado, Presidente del Tribunal Supremo y del Consejo General del Poder Judicial, Presidente del Tribunal Constitucional, miembros del Gobierno, Diputados y Senadores, Vocales del Consejo General del Poder Judicial, Magistrados del Tribunal Constitucional y del Tribunal de Cuentas, y del Fiscal General del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la ley.</mark></span><span class=\"ref-norma\">Art. 57.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 57.1.1º de la LOPJ establece que la Sala de lo Penal del Tribunal Supremo conocerá de los recursos de casación, revisión y otros extraordinarios en materia penal que establezca la Ley. La opción d) es la materia del artículo 57.1.2º."},{"i":"8-163","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá de la instrucción y enjuiciamiento de las causas contra los Fiscales Europeos delegados?","o":["La Sala de lo Penal de la Audiencia Nacional.","La Sala de lo Civil y de lo Penal del Tribunal Superior de Justicia.","La Sala de lo Penal del Tribunal Supremo.","El Tribunal Constitucional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Penal del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 57.1 · De la Organización y Planta de Juzgados y Tribunales</span>. La Sala de lo Penal del Tribunal Supremo es competente para la instrucción y enjuiciamiento de las causas contra los Fiscales Europeos Delegados, dada la alta relevancia de su cargo (art. 57.1.13ª de la L.O.P.J.)."},{"i":"8-205","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá de la instrucción y enjuiciamiento de las causas contra el Presidente del Tribunal Supremo?","o":["La Sala de lo Penal de la Audiencia Nacional.","La Sala de lo Civil y de lo Penal del Tribunal Superior de Justicia.","La Sala de lo Penal del Tribunal Supremo.","El Tribunal Constitucional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Penal del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 57.1.a) · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 57.1.a) de la LOPJ atribuye a la Sala de lo Penal del Tribunal Supremo el conocimiento de la instrucción y enjuiciamiento de las causas contra el Presidente y los demás Magistrados de este Tribunal."},{"i":"8-ia-8310","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal del Tribunal Supremo. En las causas a que se refieren los números segundo y tercero del párrafo primero del artículo sobre la Sala de lo Penal del Tribunal Supremo, se designará de entre los miembros de la Sala, conforme a un turno preestablecido:","o":["un instructor, que formará parte de la Sala para enjuiciarlas.","un Fiscal instructor, que no formará parte de la Sala.","un Letrado de la Administración de Justicia, que dirigirá las diligencias.","un instructor, que no formará parte de la misma para enjuiciarlas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un instructor, que no formará parte de la misma para enjuiciarlas</mark></span>El <span class=\"ref-norma\">art. 57 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se designará de entre los miembros de la Sala, conforme a un turno preestablecido, un instructor, que no formará parte de la misma para enjuiciarlas\"</span>. El instructor se designa por turno y no formará parte de la Sala enjuiciadora. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8311","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal del Tribunal Supremo. En las causas por delitos atribuidos a la Fiscalía Europea contra determinadas personas aforadas, se designará de entre los miembros de la Sala, conforme a un turno preestablecido:","o":["un Fiscal europeo delegado, que ejercerá la acción penal, sin perjuicio de lo dispuesto en otras leyes.","un Magistrado instructor, que formará parte de la Sala.","un Juez de garantías, que no formará parte de la misma para enjuiciarlas.","un Juez de instrucción de la Audiencia Nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un Juez de garantías, que no formará parte de la misma para enjuiciarlas</mark></span>El <span class=\"ref-norma\">art. 57.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se designará de entre los miembros de la Sala, conforme a un turno preestablecido, un Juez de garantías, que no formará parte de la misma para enjuiciarlas\"</span>. En los delitos de la Fiscalía Europea se designa un Juez de garantías. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8316","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias comunes de las Salas. En las recusaciones que se interpusieren contra los Magistrados de una Sala del Tribunal Supremo, los Magistrados recusados:","o":["formarán parte de la Sala, pero no votarán.","no formarán parte de la Sala.","serán sustituidos por el Presidente de la Sala.","se abstendrán de manera automática de intervenir."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no formarán parte de la Sala</mark></span>El <span class=\"ref-norma\">art. 60.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"A estos efectos, los Magistrados recusados no formarán parte de la Sala\"</span>. No forman parte de la Sala a estos efectos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8457","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil y Penal del TSJ. Para la instrucción de las causas penales contra jueces, magistrados y fiscales aforados ante el Tribunal Superior de Justicia, se designará de entre los miembros de la Sala, conforme a un turno preestablecido:","o":["un instructor que formará parte de la Sala enjuiciadora, sin perjuicio de lo dispuesto en otras leyes.","un Fiscal que dirigirá la investigación.","un instructor que no formará parte de la misma para enjuiciarlas.","un Juez de Instrucción de la capital de la comunidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un instructor que no formará parte de la misma para enjuiciarlas</mark></span>El <span class=\"ref-norma\">art. 73.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se designará de entre los miembros de la Sala, conforme a un turno preestablecido, un instructor que no formará parte de la misma para enjuiciarlas\"</span>. El instructor no forma parte de la Sala que enjuicia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9136","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Magistrados recusados. En las recusaciones contra Magistrados de la Audiencia Nacional, los Magistrados recusados:","o":["no formarán parte de la Sala.","formarán parte de la Sala sin voto.","presidirán la Sala.","serán sustituidos por el Presidente de la Audiencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no formarán parte de la Sala</mark></span>El <span class=\"ref-norma\">art. 68.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"los Magistrados recusados no formarán parte de la Sala.\"</span> No forman parte de la Sala."}]},{"a":"Artículo 64 bis ✱","q":[{"i":"8-65","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los Magistrados de la Sala de apelaciones podrán ser adscritos a otra Sala de diferente orden. Para la adscripción se valorarán:","o":["La antigüedad en el escalafón.","La especialidad o experiencia de los magistrados afectados.","A ser posible, sus preferencias.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Los tres criterios figuran en el artículo. Según el <span class=\"ref-norma\">art. 64 bis.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Para la adscripción se valorarán la antigüedad en el escalafón y la especialidad o experiencia de los magistrados afectados y, a ser posible, sus preferencias\"</span> (verificado con el texto del temario)."},{"i":"8-75","p":"Ley Orgánica 6/1985 del Poder Judicial. De la Audiencia Nacional. Señale la incorrecta.","o":["La Sala de Apelación de la Audiencia Nacional conocerá de los recursos que les sean dados por esta ley contra las resoluciones de las Salas de lo Civil y de lo Penal.","La Audiencia Nacional se compondrá de un Presidente, los Presidentes de Sala y los Magistrados que determine la ley para cada una de sus Salas y Secciones.","Cuando la sensible y continuada diferencia en el volumen de trabajo lo aconseje, los magistrados de esta Sala, con el acuerdo favorable de la Sala de Gobierno, previa propuesta del Presidente del Tribunal, podrán ser adscritos por el Consejo General del Poder Judicial, total o parcialmente, y sin que ello signifique incremento retributivo alguno, a otra Sala de diferente orden.","Para la adscripción se valorarán la antigüedad en el escalafón y la especialidad o experiencia de los magistrados afectados y, a ser posible, sus preferencias."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de Apelación de la Audiencia Nacional conocerá de los recursos que les sean dados por esta ley contra las resoluciones de las Salas de lo Civil y de lo Penal</mark></span>La Audiencia Nacional no tiene Sala de lo Civil: la apelación es contra las resoluciones de la Sala de lo Penal. Según el <span class=\"ref-norma\">art. 64 bis de la LOPJ</span>: <span class=\"ref-concepto\">\"La Sala de Apelación de la Audiencia Nacional conocerá de los recursos de esta clase que establezca la ley contra las resoluciones de la Sala de lo Penal\"</span> (verificado con el texto del temario oficial)."},{"i":"8-ia-8336","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de Apelación. La Sala de Apelación de la Audiencia Nacional conocerá de los recursos de esta clase que establezca la ley contra las resoluciones:","o":["de las Salas de lo Penal y de lo Contencioso-Administrativo.","de la Sala de lo Penal.","de la Sala de lo Social.","de la Sala de lo Penal y del Tribunal Central de Instancia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de la Sala de lo Penal</mark></span>El <span class=\"ref-norma\">art. 64 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conocerá de los recursos de esta clase que establezca la ley contra las resoluciones de la Sala de lo Penal\"</span>. Solo contra las resoluciones de la Sala de lo Penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8337","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de Apelación. Cuando la sensible y continuada diferencia en el volumen de trabajo lo aconseje, los magistrados de la Sala de Apelación, con el acuerdo favorable de la Sala de Gobierno, previa propuesta del Presidente del Tribunal, podrán ser adscritos:","o":["por el Consejo General del Poder Judicial, total o parcialmente, y sin que ello signifique incremento retributivo alguno, a otra Sala de diferente orden.","por el Presidente de la Audiencia Nacional, con incremento retributivo, a otra Sala.","por la Sala de Gobierno, parcialmente y con carácter permanente, a la Sala de lo Penal, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","por el Ministerio de Justicia, previo informe del Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por el Consejo General del Poder Judicial, total o parcialmente, y sin que ello signifique incremento retributivo alguno, a otra Sala de diferente orden</mark></span>El <span class=\"ref-norma\">art. 64 bis.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrán ser adscritos por el Consejo General del Poder Judicial, total o parcialmente, y sin que ello signifique incremento retributivo alguno, a otra Sala de diferente orden\"</span>. Los adscribe el CGPJ, sin incremento retributivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8338","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de Apelación. Para la adscripción de magistrados de la Sala de Apelación a otra Sala se valorarán:","o":["la antigüedad en la Carrera Judicial y la edad de los magistrados afectados, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","la carga de trabajo de la Sala de destino y los méritos de los magistrados.","la aptitud y el rendimiento demostrado en los últimos cinco años.","la antigüedad en el escalafón y la especialidad o experiencia de los magistrados afectados y, a ser posible, sus preferencias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la antigüedad en el escalafón y la especialidad o experiencia de los magistrados afectados y, a ser posible, sus preferencias</mark></span>El <span class=\"ref-norma\">art. 64 bis.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Para la adscripción se valorarán la antigüedad en el escalafón y la especialidad o experiencia de los magistrados afectados y, a ser posible, sus preferencias\"</span>. Se valoran antigüedad en el escalafón, especialidad o experiencia y, si es posible, preferencias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 89 EX R15","q":[{"i":"8-66","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 89.11. El Consejo General del Poder Judicial encomendará _________________________ la evaluación de los datos provenientes de las Secciones de Violencia sobre la Mujer, así como de aquellos asuntos relacionados con esta materia en órganos judiciales no específicos.","o":["Al Observatorio contra la Violencia Doméstica y de Género.","Al Observatorio Nacional contra la Violencia de Género.","A la Comisión Sectorial contra la Violencia Doméstica y de Género.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Observatorio contra la Violencia Doméstica y de Género</mark></span>Según el <span class=\"ref-norma\">art. 89.11 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"El Consejo General del Poder Judicial encomendará al Observatorio contra la Violencia Doméstica y de Género la evaluación de los datos provenientes de las Secciones de Violencia sobre la Mujer, así como de aquellos asuntos relacionados con esta materia en órganos judiciales no específicos\"</span> (verificado con el texto del temario)."},{"i":"8-128","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Anualmente se elaborará un informe sobre los datos relativos a violencia de género y violencia sexual, que será publicado y remitido a:","o":["Comisión de seguimiento y evaluación de los acuerdos del Informe del Senado.","La Comisión de seguimiento y evaluación de los acuerdos del Pacto de Estado contra la Violencia de Género del Congreso de los Diputados.","Comisión especial de seguimiento y evaluación de los acuerdos del Informe de las Cortes Generales.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Comisión de seguimiento y evaluación de los acuerdos del Pacto de Estado contra la Violencia de Género del Congreso de los Diputados.</mark></span><span class=\"ref-norma\">Art. 61 ter · Poder Judicial</span>. El informe se remitirá a la Comisión de seguimiento y evaluación de los acuerdos del Pacto de Estado en materia de Violencia de Género del Congreso de los Diputados, así como a la Comisión de seguimiento y evaluación de las estrategias acordadas por el Senado dentro del Pacto de Estado contra la Violencia de Género (art. 61 ter.11 LOPJ). La opción (b) es parcialmente correcta y la más representativa."},{"i":"8-302","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer. Las Secciones de Violencia sobre la Mujer tendrán de forma exclusiva y excluyente competencia en el orden civil cuando concurran:","o":["Alguno de los requisitos que establece la ley, de forma alternativa.","Simultáneamente los requisitos que establece la ley.","Los requisitos que fije cada Sala de Gobierno para su territorio.","Simultáneamente los requisitos que establezca el Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Simultáneamente los requisitos que establece la ley</mark></span>El <span class=\"ref-norma\">art. 89.7 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las Secciones de Violencia sobre la Mujer tendrán de forma exclusiva y excluyente competencia en el orden civil cuando concurran simultáneamente los siguientes requisitos:\"</span>"},{"i":"8-ia-8610","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. El Consejo General del Poder Judicial, previo informe de las Salas de Gobierno, podrá acordar que, en aquellos Tribunales de Instancia donde no hubiere una Sección de Familia, Infancia y Capacidad y sea conveniente por razón de la carga de trabajo, el conocimiento de los asuntos de familia corresponda:","o":["a la Sección de lo Mercantil de la capital, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","a la Sección de Violencia sobre la Mujer.","a la Audiencia Provincial de la provincia.","a uno de los jueces de la Sección Civil, o Civil y de Instrucción que constituya una Sección Única."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a uno de los jueces de la Sección Civil, o Civil y de Instrucción que constituya una Sección Única</mark></span>El <span class=\"ref-norma\">art. 86.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"el conocimiento de los asuntos referidos en este artículo corresponda a uno de los jueces, juezas, magistrados o magistradas de la Sección Civil, o Civil y de Instrucción que constituya una Sección Única\"</span>. Corresponde a uno de los jueces de la Sección Civil o Única. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8618","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. Entre las materias de la jurisdicción exclusiva y excluyente de las Secciones de Familia, Infancia y Capacidad figuran los expedientes de jurisdicción voluntaria en materia de personas y familia, con excepción de los regulados en:","o":["los capítulos I y II del título II de la Ley de Jurisdicción Voluntaria, en los términos que establezca la ley orgánica.","los capítulos VI y VII del título I de la Ley de Enjuiciamiento Civil.","los capítulos IX y X del título II del Código Civil.","los capítulos IX y X del título I de la Ley 15/2015, de 2 de julio, de la Jurisdicción Voluntaria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los capítulos IX y X del título I de la Ley 15/2015, de 2 de julio, de la Jurisdicción Voluntaria</mark></span>El <span class=\"ref-norma\">art. 86.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"j) Los expedientes de jurisdicción voluntaria en materia de personas y familia, con excepción de los regulados en los capítulos IX y X del título I de la Ley 15/2015, de 2 de julio, de la Jurisdicción Voluntaria\"</span>. La excepción son los capítulos IX y X. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8754","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer. El Consejo General del Poder Judicial, previo informe de las Salas de Gobierno, podrá acordar que, en aquellos Tribunales de Instancia donde no hubiere una Sección de Violencia sobre la Mujer y sea conveniente por razón de la carga de trabajo, el conocimiento de estos asuntos corresponda:","o":["a la Sección de Familia, Infancia y Capacidad del Tribunal, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","a uno de los jueces de la Sección de Instrucción, o de Civil y de Instrucción que constituya una Sección Única.","a la Audiencia Provincial de la provincia.","a la Sección de lo Penal de la capital."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a uno de los jueces de la Sección de Instrucción, o de Civil y de Instrucción que constituya una Sección Única</mark></span>El <span class=\"ref-norma\">art. 89.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"el conocimiento de los asuntos referidos en este artículo corresponda a uno de los jueces o juezas de la Sección de Instrucción, o de Civil y de Instrucción que constituya una Sección Única\"</span>. A un juez de la Sección de Instrucción o de la Sección Única. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8757","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer. En los partidos judiciales en que exista un Tribunal de Instancia con Sección Única integrada por una sola plaza judicial, el juez o jueza que la ocupe será quien asuma el conocimiento de los asuntos de violencia sobre la mujer, cuando:","o":["lo acuerde el Consejo General del Poder Judicial en cada caso, en los términos que establezca la ley orgánica.","la víctima lo solicite expresamente.","ninguna Sección de Violencia sobre la Mujer extienda su jurisdicción a ese partido judicial.","el Ministerio Fiscal lo interese."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ninguna Sección de Violencia sobre la Mujer extienda su jurisdicción a ese partido judicial</mark></span>El <span class=\"ref-norma\">art. 89.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando ninguna Sección de Violencia sobre la Mujer extienda su jurisdicción a ese partido judicial\"</span>. Solo si ninguna Sección de Violencia sobre la Mujer extiende su jurisdicción a ese partido. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8758","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · penal. Las Secciones de Violencia sobre la Mujer conocerán, en el orden penal, de la instrucción de los procesos por delitos de homicidio, aborto, lesiones, lesiones al feto, contra la libertad, contra la integridad moral, contra la libertad e indemnidad sexual, contra la intimidad y el derecho a la propia imagen, contra el honor o cualquier otro delito cometido con violencia o intimidación, siempre que se hubiesen cometido contra quien sea o haya sido su esposa o mujer que esté o haya estado ligada al autor:","o":["por análoga relación de afectividad, siempre que haya existido convivencia.","por análoga relación de afectividad, aun sin convivencia.","por relación de parentesco hasta el segundo grado.","por relación laboral o de dependencia económica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por análoga relación de afectividad, aun sin convivencia</mark></span>El <span class=\"ref-norma\">art. 89.5.a de LOPJ</span> dispone: <span class=\"ref-concepto\">\"contra quien sea o haya sido su esposa o mujer que esté o haya estado ligada al autor por análoga relación de afectividad, aun sin convivencia\"</span>. La relación de afectividad no exige convivencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8759","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · penal. Las Secciones de Violencia sobre la Mujer conocen también de los delitos cometidos sobre los descendientes, propios o de la esposa o conviviente, o sobre los menores o personas con discapacidad que con él convivan o que se hallen sujetos a la potestad, tutela, curatela, acogimiento o guarda de hecho de la esposa o conviviente, cuando:","o":["también se haya producido un acto de violencia de género.","el agresor haya sido condenado previamente por violencia de género.","la esposa o conviviente haya denunciado los hechos.","el menor sea de nacionalidad española."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">también se haya producido un acto de violencia de género</mark></span>El <span class=\"ref-norma\">art. 89.5.a de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando también se haya producido un acto de violencia de género\"</span>. Exige que también se haya producido un acto de violencia de género. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8761","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · penal. Las Secciones de Violencia sobre la Mujer conocerán de la adopción de las correspondientes órdenes de protección a las víctimas, sin perjuicio de:","o":["las competencias del Ministerio Fiscal.","las competencias de las Secciones de Instrucción de la capital.","las competencias atribuidas al juez o jueza de guardia.","las facultades de las Fuerzas y Cuerpos de Seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las competencias atribuidas al juez o jueza de guardia</mark></span>El <span class=\"ref-norma\">art. 89.5.c de LOPJ</span> dispone: <span class=\"ref-concepto\">\"c) De la adopción de las correspondientes órdenes de protección a las víctimas, sin perjuicio de las competencias atribuidas al juez o jueza de guardia\"</span>. Sin perjuicio de las competencias del juez de guardia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8762","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · penal. Las Secciones de Violencia sobre la Mujer conocerán de la instrucción de los procesos por el delito de quebrantamiento previsto y penado en el artículo 468 del Código Penal cuando la persona ofendida por el delito cuya condena, medida cautelar o medida de seguridad se haya quebrantado sea o haya sido su esposa, o mujer ligada al autor por análoga relación de afectividad aun sin convivencia, así como:","o":["los ascendientes de la esposa o conviviente, con independencia de la convivencia, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes.","los descendientes, propios o de la esposa o conviviente, o los menores o personas con discapacidad con medidas de apoyo que con él convivan o que se hallen sujetos a la potestad, tutela, curatela, acogimiento o guarda de hecho de la esposa o conviviente.","los hermanos y demás parientes hasta el cuarto grado.","cualquier persona que haya sido testigo de los hechos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los descendientes, propios o de la esposa o conviviente, o los menores o personas con discapacidad con medidas de apoyo que con él convivan o que se hallen sujetos a la potestad, tutela, curatela, acogimiento o guarda de hecho de la esposa o conviviente</mark></span>El <span class=\"ref-norma\">art. 89.5.g de LOPJ</span> dispone: <span class=\"ref-concepto\">\"así como los descendientes, propios o de la esposa o conviviente, o los menores o personas con discapacidad con medidas de apoyo que con él convivan o que se hallen sujetos a la potestad, tutela, curatela, acogimiento o guarda de hecho de la esposa o conviviente\"</span>. Incluye descendientes y menores o personas con discapacidad convivientes o a cargo de la esposa o conviviente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8763","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · penal. Las Secciones de Violencia sobre la Mujer conocerán de la instrucción de los procesos por los delitos contra la libertad sexual previstos en el título VIII del libro II del Código Penal, por los delitos de mutilación genital femenina, matrimonio forzado, acoso con connotación sexual y la trata con fines de explotación sexual cuando:","o":["la persona ofendida por el delito sea mujer.","la persona ofendida sea menor de edad.","el autor sea pareja o expareja de la víctima.","el hecho se haya cometido en el ámbito doméstico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la persona ofendida por el delito sea mujer</mark></span>El <span class=\"ref-norma\">art. 89.5.h de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando la persona ofendida por el delito sea mujer\"</span>. Basta que la ofendida sea mujer. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8764","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · civil. Las Secciones de Violencia sobre la Mujer podrán conocer en el orden civil, en todo caso de conformidad con los procedimientos y recursos previstos en la Ley de Enjuiciamiento Civil, de los asuntos relativos al matrimonio y a su régimen económico matrimonial y los que tengan por objeto:","o":["la liquidación de herencias y legados de la mujer víctima.","la adopción de medidas de apoyo a personas con discapacidad, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","la instrucción de delitos contra las relaciones familiares.","la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho</mark></span>El <span class=\"ref-norma\">art. 89.6.a de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Los relativos al matrimonio y a su régimen económico matrimonial y los que tengan por objeto la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho\"</span>. Se trata de los asuntos de matrimonio y medidas de trascendencia familiar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8765","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · civil. Las Secciones de Violencia sobre la Mujer podrán conocer en el orden civil de los procedimientos de liquidación del régimen económico matrimonial instados:","o":["por la mujer víctima de violencia de género, exclusivamente, conforme al procedimiento que establezcan las leyes procesales.","por el Ministerio Fiscal en nombre de la víctima.","por los herederos de la mujer víctima de violencia de género, así como los que se insten frente a estos herederos.","por los acreedores del matrimonio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por los herederos de la mujer víctima de violencia de género, así como los que se insten frente a estos herederos</mark></span>El <span class=\"ref-norma\">art. 89.6.h de LOPJ</span> dispone: <span class=\"ref-concepto\">\"h) Los que versen sobre los procedimientos de liquidación del régimen económico matrimonial instados por los herederos de la mujer víctima de violencia de género, así como los que se insten frente a estos herederos\"</span>. Los instados por los herederos de la víctima o frente a ellos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8767","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia civil exclusiva y excluyente. Las Secciones de Violencia sobre la Mujer tendrán de forma exclusiva y excluyente competencia en el orden civil cuando concurran simultáneamente determinados requisitos, entre ellos:","o":["que alguna de las partes del proceso civil sea víctima de actos de violencia de género o de violencia sexual.","que ambas partes del proceso civil hayan sido víctimas de actos de violencia, sin perjuicio de lo dispuesto en otras leyes.","que el proceso civil haya sido promovido por el Ministerio Fiscal.","que la víctima haya solicitado la competencia de la Sección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que alguna de las partes del proceso civil sea víctima de actos de violencia de género o de violencia sexual</mark></span>El <span class=\"ref-norma\">art. 89.7 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"b) Que alguna de las partes del proceso civil sea víctima de actos de violencia de género, en los términos a que hace referencia el apartado 5. a), o de actos de violencia sexual\"</span>. Basta que alguna de las partes sea víctima. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8768","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia civil exclusiva y excluyente. Entre los requisitos para que las Secciones de Violencia sobre la Mujer tengan competencia civil exclusiva y excluyente figura que se hayan iniciado ante la Sección de Violencia sobre la Mujer de un Tribunal de Instancia actuaciones penales por delito o delito leve a consecuencia de un acto de violencia de género o sexual, o:","o":["se haya dictado sentencia condenatoria firme.","se haya interpuesto denuncia ante las Fuerzas y Cuerpos de Seguridad, en los términos que establezca la ley orgánica.","se haya acordado la prisión provisional del investigado.","se haya adoptado una orden de protección a una víctima de violencia de género."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se haya adoptado una orden de protección a una víctima de violencia de género</mark></span>El <span class=\"ref-norma\">art. 89.7 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"o se haya adoptado una orden de protección a una víctima de violencia de género\"</span>. Alternativa: orden de protección adoptada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8769","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inadmisión. Cuando el juez o la jueza apreciara que los actos puestos en su conocimiento, de forma notoria, no constituyen expresión de violencia de género o de violencia sexual:","o":["deberá archivar las actuaciones sin más trámite.","deberá dar traslado al Ministerio Fiscal para que decida, salvo que la ley disponga otra cosa.","podrá inadmitir la pretensión, remitiéndola al órgano judicial competente.","continuará conociendo del asunto hasta su terminación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrá inadmitir la pretensión, remitiéndola al órgano judicial competente</mark></span>El <span class=\"ref-norma\">art. 89.8 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Cuando el juez o la jueza apreciara que los actos puestos en su conocimiento, de forma notoria, no constituyen expresión de violencia de género o de violencia sexual, podrá inadmitir la pretensión, remitiéndola al órgano judicial competente\"</span>. Puede inadmitir y remitir al órgano competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8772","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Observatorio. El Consejo General del Poder Judicial encomendará al Observatorio contra la Violencia Doméstica y de Género la evaluación de los datos provenientes de las Secciones de Violencia sobre la Mujer. Anualmente se elaborará un informe sobre los datos relativos a violencia de género y violencia sexual, que será publicado y remitido a:","o":["la Delegación del Gobierno contra la Violencia de Género exclusivamente, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","las Comunidades Autónomas y el Defensor del Pueblo.","el Ministerio de Igualdad y la Fiscalía General del Estado.","la Comisión de seguimiento y evaluación de los acuerdos del Pacto de Estado en materia de Violencia de Género del Congreso de los Diputados y a la del Senado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Comisión de seguimiento y evaluación de los acuerdos del Pacto de Estado en materia de Violencia de Género del Congreso de los Diputados y a la del Senado</mark></span>El <span class=\"ref-norma\">art. 89.11 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"será publicado y remitido a la Comisión de seguimiento y evaluación de los acuerdos del Pacto de Estado en materia de Violencia de Género del Congreso de los Diputados, así como a la Comisión de seguimiento y evaluación de las estrategias acordadas por el Senado dentro del Pacto de Estado contra la Violencia de Género\"</span>. Se remite a las comisiones de seguimiento del Congreso y del Senado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 541 EX ✱","q":[{"i":"8-72","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del Ministerio Fiscal y la fiscalía europea. Sin perjuicio de las funciones encomendadas a otros órganos, el Ministerio Fiscal tiene por misión:","o":["Promover la acción de la Justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados.","Velar por la independencia de los tribunales y procurar ante éstos la satisfacción del interés social.","Investigar y ejercer la acción penal, ante el órgano de enjuiciamiento competente en primera instancia.","a) y b) son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a) y b) son correctas</mark></span>Investigar y ejercer la acción penal es de la Fiscalía Europea. Según el <span class=\"ref-norma\">art. 541 de la LOPJ</span>: <span class=\"ref-concepto\">\"Sin perjuicio de las funciones encomendadas a otros órganos, el Ministerio Fiscal tiene por misión promover la acción de la Justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de los tribunales y procurar ante éstos la satisfacción del interés social\"</span> (verificado con el texto del temario oficial)."},{"i":"8-131","p":"Ley Orgánica 6/1985 del Poder Judicial. ¿Quién tiene por misión, entre otras, promover la acción de la Justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados?","o":["El Ministerio de Justicia.","El Gobierno.","El Consejo General del Poder Judicial.","El Ministerio Fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 3 · Poder Judicial</span>. Corresponde al Ministerio Fiscal promover la acción de la Justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la Ley, de oficio o a petición de los interesados (art. 3 LOPJ, en remisión al art. 124 CE y al Estatuto Orgánico del Ministerio Fiscal)."},{"i":"8-140","p":"(LOPJ) El Ministerio Fiscal, según la LOPJ, velará por la independencia de los Tribunales y procurará ante éstos la satisfacción del:","o":["Interés público.","Interés social.","Interés general.","Interés de la Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Interés social.</mark></span><span class=\"ref-norma\">Art. 3.2 · Poder Judicial</span>. El artículo 3.2 de la LOPJ, al definir las funciones del Ministerio Fiscal, establece que procurará ante los Tribunales la satisfacción del interés social."},{"i":"8-ia-9087","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ministerio Fiscal. Sin perjuicio de las funciones encomendadas a otros órganos, el Ministerio Fiscal tiene por misión promover la acción de la Justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados, así como velar por la independencia de los tribunales y:","o":["procurar ante éstos la satisfacción del interés social.","procurar la ejecución de sus resoluciones, en los términos que establezca la ley orgánica.","promover la formación de los jueces.","procurar la representación de las partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">procurar ante éstos la satisfacción del interés social</mark></span>El <span class=\"ref-norma\">art. 541.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"así como velar por la independencia de los tribunales y procurar ante éstos la satisfacción del interés social\"</span>. Vela por la independencia de los tribunales y procura la satisfacción del interés social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9088","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ministerio Fiscal. El Ministerio Fiscal se regirá:","o":["por lo que disponga la Ley de Enjuiciamiento Criminal.","por las instrucciones del Ministro de Justicia.","por el Reglamento del Consejo General del Poder Judicial.","por lo que disponga su Estatuto Orgánico."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por lo que disponga su Estatuto Orgánico</mark></span>El <span class=\"ref-norma\">art. 541.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Ministerio Fiscal se regirá por lo que disponga su Estatuto Orgánico\"</span>. Se rige por su Estatuto Orgánico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 95 EX","q":[{"i":"8-76","p":"Ley Orgánica 6/1985, del Poder Judicial. ¿Qué Tribunal tramitará los expedientes de ejecución de las órdenes europeas de detención y entrega?","o":["La Sección de Instrucción del Tribunal Central de Instancia.","La Sala de lo Penal de la Audiencia Nacional.","La Sección de lo Penal del Tribunal Central de Instancia.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sección de Instrucción del Tribunal Central de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 95.a de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Sección de Instrucción, que instruirá las causas cuyo enjuiciamiento corresponda a la Sala de lo Penal de la Audiencia Nacional [...] y tramitará los expedientes de ejecución de las órdenes europeas de detención y entrega, los procedimientos de extradición pasiva\"</span> (verificado con el texto del temario)."},{"i":"8-94","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 95.d. La competencia de la Sección de Vigilancia Penitenciaria del Tribunal Central de Instancia, cuando el penado cumpla también otras condenas que no hubiesen sido impuestas por la Audiencia Nacional, será:","o":["Preferente y excluyente.","Preferente pero no excluyente.","Ordinaria y excluyente.","Excluyente pero no preferente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Preferente y excluyente</mark></span>Según el <span class=\"ref-norma\">art. 95.d de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"En todo caso, la competencia de esta Sección será preferente y excluyente cuando el penado cumpla también otras condenas que no hubiesen sido impuestas por la Audiencia Nacional\"</span> (verificado con el texto del temario)."},{"i":"8-185","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿A quién le corresponde tramitar los procedimientos de extradición pasiva?","o":["A la Sección de Instrucción del Tribunal Central de Instancia.","A las Audiencias Provinciales.","A la Sección de lo Penal del Tribunal Central de Instancia.","Al Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A la Sección de Instrucción del Tribunal Central de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 95.a de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Sección de Instrucción, que instruirá las causas [...] y tramitará los expedientes de ejecución de las órdenes europeas de detención y entrega, los procedimientos de extradición pasiva\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8484","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias penales de las Audiencias Provinciales. Las Audiencias Provinciales conocerán en el orden penal de las causas por delito, a excepción de:","o":["los delitos castigados con pena inferior a cinco años de prisión.","los delitos cometidos por menores de edad.","los delitos conexos con otros de la competencia de la Audiencia Nacional, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","los que la ley atribuye al conocimiento de las Secciones de lo Penal de los Tribunales de Instancia o de otros Tribunales previstos en esta ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los que la ley atribuye al conocimiento de las Secciones de lo Penal de los Tribunales de Instancia o de otros Tribunales previstos en esta ley</mark></span>El <span class=\"ref-norma\">art. 82.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De las causas por delito, a excepción de los que la ley atribuye al conocimiento de las Secciones de lo Penal de los Tribunales de Instancia o de otros Tribunales previstos en esta ley\"</span>. Se exceptúan los atribuidos a las Secciones de lo Penal de los Tribunales de Instancia u otros tribunales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8795","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia, que contará con las siguientes Secciones, entre otras:","o":["Sección de Instrucción, que instruirá las causas cuyo enjuiciamiento corresponda a la Sala de lo Penal de la Audiencia Nacional o, en su caso, a la Sección de lo Penal del propio Tribunal Central de Instancia.","Sección Civil, que conocerá de los juicios de mayor cuantía.","Sección de Familia, que conocerá de las crisis matrimoniales internacionales, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","Sección de lo Mercantil, que conocerá de los concursos de ámbito nacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sección de Instrucción, que instruirá las causas cuyo enjuiciamiento corresponda a la Sala de lo Penal de la Audiencia Nacional o, en su caso, a la Sección de lo Penal del propio Tribunal Central de Instancia</mark></span>El <span class=\"ref-norma\">art. 95 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Sección de Instrucción, que instruirá las causas cuyo enjuiciamiento corresponda a la Sala de lo Penal de la Audiencia Nacional o, en su caso, a la Sección de lo Penal del propio Tribunal Central de Instancia\"</span>. La Sección de Instrucción instruye las causas de la Sala de lo Penal de la AN o de su propia Sección de lo Penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8902","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. La Sección de lo Penal del Tribunal Central de Instancia conocerá, en los casos en que así lo establezcan las leyes procesales, de las causas por los delitos que la ley atribuye a la Sala de lo Penal de la Audiencia Nacional y de los demás asuntos que señalen las leyes. Corresponde asimismo a esta Sección:","o":["el conocimiento de los recursos de apelación contra las resoluciones de la Sección de Instrucción, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","la instrucción de las causas contra aforados.","el control de la ejecución de las penas privativas de libertad.","la ejecución de las sentencias dictadas en causas por delito grave o menos grave por la Sección de Instrucción del propio Tribunal Central de Instancia, y los procedimientos de decomiso autónomo por los delitos para cuyo conocimiento sean competentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la ejecución de las sentencias dictadas en causas por delito grave o menos grave por la Sección de Instrucción del propio Tribunal Central de Instancia, y los procedimientos de decomiso autónomo por los delitos para cuyo conocimiento sean competentes</mark></span>El <span class=\"ref-norma\">art. 95.b de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Corresponde asimismo a la Sección de lo Penal la ejecución de las sentencias dictadas en causas por delito grave o menos grave por la Sección de Instrucción del propio Tribunal Central de Instancia, y los procedimientos de decomiso autónomo por los delitos para cuyo conocimiento sean competentes\"</span>. Ejecución de sentencias de la Sección de Instrucción y decomiso autónomo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8903","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. La Sección de Vigilancia Penitenciaria del Tribunal Central de Instancia tendrá las funciones jurisdiccionales previstas en la Ley Orgánica General Penitenciaria en relación con los delitos competencia de la Audiencia Nacional. En todo caso, la competencia de esta Sección será preferente y excluyente cuando el penado:","o":["esté sujeto a una medida de seguridad privativa de libertad, sin perjuicio de lo dispuesto en otras leyes.","haya sido condenado por delitos de terrorismo.","cumpla también otras condenas que no hubiesen sido impuestas por la Audiencia Nacional.","se encuentre en un establecimiento penitenciario de Madrid."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cumpla también otras condenas que no hubiesen sido impuestas por la Audiencia Nacional</mark></span>El <span class=\"ref-norma\">art. 95.d de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En todo caso, la competencia de esta Sección será preferente y excluyente cuando el penado cumpla también otras condenas que no hubiesen sido impuestas por la Audiencia Nacional\"</span>. Preferente y excluyente cuando cumpla también condenas no impuestas por la Audiencia Nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8904","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. La Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia conocerá, en primera o única instancia, de los recursos contra disposiciones y actos emanados de autoridades, organismos, órganos y entidades públicas:","o":["con competencia en más de una comunidad autónoma.","con competencia en todo el territorio nacional, en los términos que la ley establezca.","de la Administración General del Estado con rango de Subsecretario, en los términos que establezca la ley orgánica.","de ámbito autonómico que afecten a más de una provincia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">con competencia en todo el territorio nacional, en los términos que la ley establezca</mark></span>El <span class=\"ref-norma\">art. 95.e de LOPJ</span> dispone: <span class=\"ref-concepto\">\"de los recursos contencioso-administrativos contra disposiciones y actos emanados de autoridades, organismos, órganos y entidades públicas con competencia en todo el territorio nacional, en los términos que la ley establezca\"</span>. Entidades públicas con competencia en todo el territorio nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 66 ✱","q":[{"i":"8-78","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición y atribuciones de los órganos jurisdiccionales. La solicitud de autorización para la declaración prevista en la disposición adicional quinta de la Ley Orgánica de Protección de Datos Personales y Garantía de los Derechos Digitales, cuando tal solicitud sea formulada por la Agencia Española de Protección de Datos, corresponderá a:","o":["A la Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","A la Sala de lo Contencioso-Administrativo del Tribunal Superior de Justicia.","La Sala de lo Contencioso-Administrativo de la Audiencia Provincial.","La Sala de lo Contencioso-Administrativo del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A la Sala de lo Contencioso-Administrativo de la Audiencia Nacional.</mark></span><span class=\"ref-norma\">Art. 66.4 · De la Organización y Planta de Juzgados y Tribunales</span>. La disposición adicional quinta de la Ley Orgánica 3/2018 (LOPDGDD) remite la competencia para autorizar la declaración o a un órgano concreto en la LOPJ. El artículo 66.4 de la LOPJ atribuye a la Sala de lo Contencioso-Administrativo de la Audiencia Nacional la competencia para el conocimiento de la solicitud de autorización judicial de la Agencia Española de Protección de Datos."},{"i":"8-135","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 65.1.1.º.a. ¿Quién conocerá del enjuiciamiento, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, de los delitos contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno?","o":["La sala de lo Penal del Tribunal Supremo.","La Sala de lo Penal de la Audiencia Nacional.","La Sala de lo Penal del Tribunal Superior de Justicia.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Sala de lo Penal de la Audiencia Nacional</mark></span>No es el Tribunal Supremo. Según el <span class=\"ref-norma\">art. 65.1.1.º.a de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"La Sala de lo Penal de la Audiencia Nacional conocerá: 1.º Del enjuiciamiento, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, de las causas por los siguientes delitos: a) Delitos contra el titular de la Corona, su Consorte, su Sucesor o Sucesora, altos organismos de la Nación y forma de Gobierno\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8348","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo de la Audiencia Nacional. La Sala de lo Contencioso-Administrativo de la Audiencia Nacional conocerá en única instancia de los recursos contencioso-administrativos contra los actos dictados por:","o":["el Consejo de Seguridad Nacional.","la Comisión de Vigilancia de Actividades de Financiación del Terrorismo.","la Agencia Española de Protección de Datos, sin perjuicio de lo dispuesto en otras leyes.","el Comité de Seguridad Aérea."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Comisión de Vigilancia de Actividades de Financiación del Terrorismo</mark></span>El <span class=\"ref-norma\">art. 66 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"contra los actos dictados por la Comisión de Vigilancia de Actividades de Financiación del Terrorismo\"</span>. Los actos de la Comisión de Vigilancia de Actividades de Financiación del Terrorismo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 82 EX ✱","q":[{"i":"8-80","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De las Audiencias Provinciales. Las Audiencias Provinciales conocerán en el orden penal:","o":["De los recursos que establece la ley contra las resoluciones dictadas por las Secciones de Instrucción y de lo Penal de los Tribunales de Instancia de la provincia.","De los recursos que establezca la ley contra las resoluciones en materia penal dictadas por las Secciones de Violencia sobre la Mujer de la provincia.","De los recursos contra las resoluciones de las Secciones de Menores de los Tribunales de Instancia con sede en la provincia y de las cuestiones de competencia entre los mismos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 82.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Las Audiencias Provinciales conocerán en el orden penal: [...] 2.º De los recursos [...] contra las resoluciones dictadas por las Secciones de Instrucción y de lo Penal de los Tribunales de Instancia de la provincia. 3.º [...] Secciones de Violencia sobre la Mujer [...] 4.º [...] Secciones de Menores\"</span> (verificado con el texto del temario)."},{"i":"8-104","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 82.2.1.º. ¿Quién conoce de los recursos de apelación que establezca la ley contra las resoluciones dictadas en primera instancia por las Secciones Civiles de los Tribunales de Instancia de la provincia?","o":["La Sala de lo Civil y Penal del Tribunal Superior de Justicia.","El Tribunal Superior de Justicia.","La Audiencia Provincial.","La Sala de Apelación del Tribunal Superior de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Audiencia Provincial</mark></span>Según el <span class=\"ref-norma\">art. 82.2.1.º de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"De los recursos que establezca la ley contra las resoluciones dictadas en primera instancia por las Secciones Civiles de los Tribunales de Instancia de la provincia\"</span> (verificado con el texto del temario)."},{"i":"8-233","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial De la inamovilidad de los jueces y magistrados. La suspensión de los Jueces y Magistrados sólo tendrá lugar en los casos siguientes: señale la INCORRECTA.","o":["Cuando se hubiere declarado haber lugar a proceder contra ellos por delitos cometidos en el ejercicio de sus funciones.","Cuando por cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento.","Cuando se decretare en expediente disciplinario o de incapacidad, ya con carácter provisional, ya definitivo.","Por sentencia firme condenatoria en que se imponga como pena principal o accesoria la de suspensión, aunque procediere la separación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por sentencia firme condenatoria en que se imponga como pena principal o accesoria la de suspensión, aunque procediere la separación.</mark></span><span class=\"ref-norma\">Art. 384.2 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. La suspensión tiene lugar por sentencia firme condenatoria en que se imponga la pena de suspensión de empleo o cargo público (Art. 384.2.1ª LOPJ). Si un delito diera lugar a la pena de separación, el Juez o Magistrado perdería la condición, que es una consecuencia distinta y superior a la suspensión (Art. 379 LOPJ), haciendo que la cláusula &quot;aunque procediere la separación&quot; sea incorrecta."},{"i":"8-299","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencias Provinciales. Las Audiencias Provinciales conocerán en el orden penal:","o":["Exclusivamente de las causas por delitos graves, quedando los recursos reservados a los Tribunales Superiores de Justicia.","De los recursos de casación contra las sentencias de las Secciones de Instrucción y de las cuestiones de competencia entre Comunidades, en los términos que determine la ley orgánica correspondiente.","Solo de las causas que la ley atribuya a la Sección de lo Penal, sin conocer de recursos.","De las causas por delitos que la ley determine, de los recursos que establezca la ley contra resoluciones de los Tribunales de Instancia y de las cuestiones de competencia, entre otras funciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De las causas por delitos que la ley determine, de los recursos que establezca la ley contra resoluciones de los Tribunales de Instancia y de las cuestiones de competencia, entre otras funciones</mark></span>El <span class=\"ref-norma\">art. 82.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las Audiencias Provinciales conocerán en el orden penal:\"</span>"},{"i":"8-ia-8486","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias penales de las Audiencias Provinciales. A fin de facilitar el conocimiento de los recursos contra las resoluciones penales dictadas por las Secciones de Violencia sobre la Mujer y de Violencia contra la Infancia y la Adolescencia, y atendiendo al número de asuntos existentes, en las Audiencias Provinciales:","o":["podrán especializarse una o varias de sus Secciones.","deberán especializarse una o varias de sus Secciones.","se creará una Sala específica en cada capital.","se atribuirán los recursos a la Sala de lo Penal del Tribunal Superior de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">deberán especializarse una o varias de sus Secciones</mark></span>El <span class=\"ref-norma\">art. 82.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"A fin de facilitar el conocimiento de estos recursos, y atendiendo al número de asuntos existentes, deberán especializarse una o varias de sus Secciones\"</span>. En lo penal «deberán» especializarse; en lo civil «podrán». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8487","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias penales de las Audiencias Provinciales. Las Audiencias Provinciales conocerán también de los recursos contra las resoluciones de las Secciones de Menores de los Tribunales de Instancia con sede en la provincia y:","o":["de las cuestiones de competencia entre los mismos.","de las cuestiones de competencia entre las Secciones de Instrucción.","de los recursos contra las resoluciones de Vigilancia Penitenciaria en todo caso.","de las recusaciones de los jueces de menores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de las cuestiones de competencia entre los mismos</mark></span>El <span class=\"ref-norma\">art. 82.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las Audiencias Provinciales conocerán también de los recursos contra las resoluciones de las Secciones de Menores de los Tribunales de Instancia con sede en la provincia y de las cuestiones de competencia entre los mismos\"</span>. Recursos contra las Secciones de Menores y cuestiones de competencia entre ellas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8488","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias penales de las Audiencias Provinciales. Las Audiencias Provinciales conocerán de los recursos que establezca la ley contra las resoluciones de las Secciones de Vigilancia Penitenciaria de los Tribunales de Instancia, cuando:","o":["la pena impuesta sea superior a cinco años.","el penado haya sido condenado por delito grave.","el Tribunal Superior de Justicia no sea competente, en los términos que establezca la ley orgánica.","la competencia no corresponda a la Sala de lo Penal de la Audiencia Nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la competencia no corresponda a la Sala de lo Penal de la Audiencia Nacional</mark></span>El <span class=\"ref-norma\">art. 82.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De los recursos que establezca la ley contra las resoluciones de las Secciones de Vigilancia Penitenciaria de los Tribunales de Instancia, cuando la competencia no corresponda a la Sala de lo Penal de la Audiencia Nacional\"</span>. Salvo que corresponda a la Sala de lo Penal de la Audiencia Nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8490","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales de Marca de la Unión Europea. La Sección o Secciones de la Audiencia Provincial de Alicante especializadas en materia mercantil conocerán, en segunda instancia y de forma exclusiva, de los recursos relativos a la marca de la Unión Europea y a los dibujos y modelos comunitarios. En el ejercicio de esta competencia:","o":["extenderán su jurisdicción a la Comunidad Valenciana y se denominarán Tribunales de Propiedad Industrial, conforme al procedimiento que establezcan las leyes procesales.","extenderán su jurisdicción a todo el territorio nacional, y a estos solos efectos se denominarán Tribunales de Marca de la Unión Europea.","actuarán como Sala de la Audiencia Nacional.","extenderán su jurisdicción a las provincias de la costa mediterránea."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">extenderán su jurisdicción a todo el territorio nacional, y a estos solos efectos se denominarán Tribunales de Marca de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 82.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En el ejercicio de esta competencia extenderán su jurisdicción a todo el territorio nacional, y a estos solos efectos se denominarán Tribunales de Marca de la Unión Europea\"</span>. Jurisdicción nacional y denominación de Tribunales de Marca de la Unión Europea. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8491","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Otras competencias de las Audiencias Provinciales. Corresponde igualmente a las Audiencias Provinciales el conocimiento de las cuestiones de competencia en materia civil y penal que se susciten entre los jueces, las juezas, los magistrados y las magistradas:","o":["de un mismo o distinto Tribunal de Instancia de la provincia.","de distintas provincias de la comunidad autónoma.","de la Audiencia Provincial y de la Audiencia Nacional, sin perjuicio de lo dispuesto en otras leyes.","de las Secciones de lo Social de la provincia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de un mismo o distinto Tribunal de Instancia de la provincia</mark></span>El <span class=\"ref-norma\">art. 82.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De las cuestiones de competencia en materia civil y penal que se susciten entre los jueces, las juezas, los magistrados y las magistradas de un mismo o distinto Tribunal de Instancia de la provincia\"</span>. Entre jueces de un mismo o distinto Tribunal de Instancia de la provincia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 407 ✱","q":[{"i":"8-82","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la responsabilidad penal. Cuando el Tribunal Supremo, por razón de los pleitos o causas de que conozca o por cualquier otro medio, tuviere noticia de algún acto de Jueces o Magistrados realizado en el ejercicio de su cargo y que pueda calificarse de delito o falta, lo comunicará:","o":["Al Tribunal competente.","Al Ministerio Fiscal.","Al Consejo General del Poder Judicial.","Al Ministerio de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Tribunal competente</mark></span>Se comunica al Tribunal competente, previa audiencia del Ministerio Fiscal (que no es el destinatario). Según el <span class=\"ref-norma\">art. 407 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"lo comunicará, oyendo previamente al Ministerio Fiscal, al Tribunal competente, a los efectos de incoación de la causa\"</span> (verificado con el texto del temario)."},{"i":"8-119","p":"Cuando el Tribunal Supremo, por razón de los pleitos o causas de que conozca o por cualquier otro medio, tuviere noticia de algún acto de Jueces o Magistrados realizado en el ejercicio de su cargo y que pueda calificarse de delito o falta, lo comunicará, a los efectos de incoación de la causa, a:","o":["Al Tribunal competente.","Al Ministerio Fiscal.","A y B son correctas.","Ninguna es correcta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Tribunal competente</mark></span>El Ministerio Fiscal solo es oído; el destinatario es el Tribunal competente. Según el <span class=\"ref-norma\">art. 407 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"lo comunicará, oyendo previamente al Ministerio Fiscal, al Tribunal competente, a los efectos de incoación de la causa\"</span> (verificado con el texto del temario)."},{"i":"8-ia-9083","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad penal. Cuando el Tribunal Supremo, por razón de los pleitos o causas de que conozca o por cualquier otro medio, tuviere noticia de algún acto de Jueces o Magistrados realizado en el ejercicio de su cargo y que pueda calificarse de delito o falta, lo comunicará:","o":["oyendo previamente al Ministerio Fiscal, al Tribunal competente, a los efectos de incoación de la causa.","al Consejo General del Poder Judicial, que decidirá la apertura de la causa, conforme al procedimiento que establezcan las leyes procesales.","al Ministerio Fiscal, sin trámite previo.","a la Sala de Gobierno del Tribunal Superior de Justicia correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">oyendo previamente al Ministerio Fiscal, al Tribunal competente, a los efectos de incoación de la causa</mark></span>El <span class=\"ref-norma\">art. 407 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"lo comunicará, oyendo previamente al Ministerio Fiscal, al Tribunal competente, a los efectos de incoación de la causa\"</span>. Lo comunica al Tribunal competente, oyendo antes al Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 12","q":[{"i":"8-85","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. En el ejercicio de la potestad jurisdiccional, los Jueces y Magistrados son _____________________ respecto a todos los órganos judiciales y de gobierno del Poder Judicial.","o":["Autosuficientes.","Dependientes.","Independientes.","Soberanos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Independientes.</mark></span><span class=\"ref-norma\">Art. 12.1 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 12.1 de la LOPJ establece que en el ejercicio de la potestad jurisdiccional, los Jueces y Magistrados son independientes respecto a todos los órganos judiciales y de gobierno del Poder Judicial."},{"i":"8-ia-8034","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Independencia judicial. En el ejercicio de la potestad jurisdiccional, los Jueces y Magistrados son independientes:","o":["respecto al Poder Ejecutivo y al Poder Legislativo exclusivamente.","respecto a los órganos de gobierno del Poder Judicial, pero no respecto a los tribunales superiores.","respecto a todos los poderes del Estado, salvo el Tribunal Constitucional.","respecto a todos los órganos judiciales y de gobierno del Poder Judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">respecto a todos los órganos judiciales y de gobierno del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 12.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"los Jueces y Magistrados son independientes respecto a todos los órganos judiciales y de gobierno del Poder Judicial\"</span>. La independencia lo es respecto a todos los órganos judiciales y de gobierno del Poder Judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8035","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Independencia judicial. No podrán los Jueces y Tribunales corregir la aplicación o interpretación del ordenamiento jurídico hecha por sus inferiores en el orden jerárquico judicial sino:","o":["cuando lo autorice el Consejo General del Poder Judicial.","cuando actúen en el ejercicio de sus funciones gubernativas.","cuando administren justicia en virtud de los recursos que las leyes establezcan.","cuando exista una sentencia contradictoria del Tribunal Supremo, salvo que la ley disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuando administren justicia en virtud de los recursos que las leyes establezcan</mark></span>El <span class=\"ref-norma\">art. 12.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"sino cuando administren justicia en virtud de los recursos que las leyes establezcan\"</span>. Solo por la vía de los recursos legales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8036","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Independencia judicial. Los Jueces y Tribunales, órganos de gobierno de los mismos o el Consejo General del Poder Judicial no podrán dictar instrucciones, de carácter general o particular, dirigidas a sus inferiores, sobre:","o":["la organización interna de las oficinas judiciales y el reparto de asuntos.","la aplicación o interpretación del ordenamiento jurídico que lleven a cabo en el ejercicio de su función jurisdiccional.","la aplicación de las normas de procedimiento exclusivamente.","la interpretación de los reglamentos del Consejo General del Poder Judicial, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la aplicación o interpretación del ordenamiento jurídico que lleven a cabo en el ejercicio de su función jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 12.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"dictar instrucciones, de carácter general o particular, dirigidas a sus inferiores, sobre la aplicación o interpretación del ordenamiento jurídico que lleven a cabo en el ejercicio de su función jurisdiccional\"</span>. La prohibición alcanza a instrucciones generales o particulares sobre la aplicación o interpretación del ordenamiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 14","q":[{"i":"8-86","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder Judicial y del ejercicio de la potestad jurisdiccional. ¿Quién promoverá las acciones pertinentes en defensa de la independencia judicial?","o":["El Ministerio Fiscal.","El Gobierno.","El Ministerio de Justicia.","El Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal.</mark></span><span class=\"ref-norma\">Art. 14.2 · Poder Judicial</span>. El artículo 14.2 de la LOPJ indica que el Ministerio Fiscal, por sí o a petición de aquéllos, promoverá las acciones pertinentes en defensa de la independencia judicial."},{"i":"8-ia-8037","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Perturbación de la independencia. Los Jueces y Magistrados que se consideren inquietados o perturbados en su independencia lo pondrán en conocimiento:","o":["del Consejo General del Poder Judicial, dando cuenta de los hechos al Juez o Tribunal competente para seguir el procedimiento adecuado.","del Ministerio Fiscal, que dará cuenta de los hechos al Consejo General del Poder Judicial, sin perjuicio de lo dispuesto en otras leyes.","del Presidente del Tribunal Supremo, que promoverá las acciones pertinentes.","de la Sala de Gobierno del Tribunal Superior de Justicia correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del Consejo General del Poder Judicial, dando cuenta de los hechos al Juez o Tribunal competente para seguir el procedimiento adecuado</mark></span>El <span class=\"ref-norma\">art. 14 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"lo pondrán en conocimiento del Consejo General del Poder Judicial, dando cuenta de los hechos al Juez o Tribunal competente para seguir el procedimiento adecuado\"</span>. Se comunica al CGPJ y se da cuenta al Juez o Tribunal competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8038","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Perturbación de la independencia. El Ministerio Fiscal, por sí o a petición de los Jueces y Magistrados inquietados en su independencia:","o":["investigará los hechos y dará cuenta al Consejo General del Poder Judicial.","solicitará la intervención del Tribunal Constitucional.","adoptará las medidas cautelares indispensables para restaurar el orden jurídico.","promoverá las acciones pertinentes en defensa de la independencia judicial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">promoverá las acciones pertinentes en defensa de la independencia judicial</mark></span>El <span class=\"ref-norma\">art. 14.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Ministerio Fiscal, por sí o a petición de aquéllos, promoverá las acciones pertinentes en defensa de la independencia judicial\"</span>. Promueve las acciones pertinentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 81 EXOF","q":[{"i":"8-89","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la composición del Poder Judicial. Las Audiencias Provinciales se compondrán de:","o":["Un Presidente y dos o más magistrados.","Un Presidente, un Vicepresidente y dos o más magistrados.","Un Presidente y dos o más Vicepresidentes.","Un Presidente y un magistrado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un Presidente y dos o más magistrados.</mark></span><span class=\"ref-norma\">Art. 81.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 81.1 de la LOPJ establece que las Audiencias Provinciales se compondrán de un Presidente y dos o más magistrados. (Nota: Pregunta idéntica a la 8)."},{"i":"8-143","p":"(LOPJ) En relación con la composición de las Audiencias Provinciales, señale la respuesta CORRECTA:","o":["Se compondrán de un Presidente y cuatro o más Magistrados.","El Presidente de la Audiencia Provincial tendrá la consideración de Presidente de Sala.","Cuando el escaso número de asuntos lo aconseje, su plantilla podrá constar de uno o dos Magistrados, incluido el Presidente.","Se compondrán de un Presidente y dos o más Magistrados, pudiendo estar integradas por dos o más Secciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Se compondrán de un Presidente y dos o más Magistrados, pudiendo estar integradas por dos o más Secciones.</mark></span><span class=\"ref-norma\">Art. 81.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 81.1 de la LOPJ establece que las Audiencias Provinciales se compondrán de un Presidente y dos o más Magistrados, y que podrán estar integradas por dos o más Secciones."},{"i":"8-ia-8481","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Composición de las Audiencias Provinciales. Las Audiencias Provinciales se compondrán de un Presidente y dos o más magistrados. También podrán estar integradas por dos o más Secciones de la misma composición, en cuyo caso el Presidente de la Audiencia presidirá:","o":["la Sección de lo Penal exclusivamente.","todas las Secciones de forma rotatoria.","una de las Secciones que determinará al principio de su mandato.","la Sección que determine la Sala de Gobierno cada año, sin perjuicio de lo dispuesto en otras leyes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una de las Secciones que determinará al principio de su mandato</mark></span>El <span class=\"ref-norma\">art. 81.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"en cuyo caso el Presidente de la Audiencia presidirá una de las Secciones que determinará al principio de su mandato\"</span>. Preside una de las Secciones, que elige al principio de su mandato. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8483","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Composición de las Audiencias Provinciales. Cuando así lo aconseje la mejor Administración de Justicia, las Secciones de la Audiencia podrán estar formadas por:","o":["cuatro o más magistrados.","tres o más magistrados.","cinco o más magistrados.","un máximo de cuatro magistrados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuatro o más magistrados</mark></span>El <span class=\"ref-norma\">art. 81.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"las Secciones de la Audiencia podrán estar formadas por cuatro o más magistrados\"</span>. Cuatro o más magistrados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 389 ✱","q":[{"i":"8-95","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De las incompatibilidades y prohibiciones. El cargo de Juez o Magistrado es incompatible, entre otras: Señale la INCORRECTA.","o":["Con el ejercicio de cualquier jurisdicción incluida la del Poder Judicial.","Con cualquier cargo de elección popular o designación política del Estado, Comunidades Autónomas, Provincias y demás entidades locales y organismos dependientes de cualquiera de ellos.","Con los empleos o cargos dotados o retribuidos por la Administración del Estado, las Cortes Generales, la Casa Real, Comunidades Autónomas, Provincias, Municipios y cualesquiera entidades, organismos o empresas dependientes de unos u otras.","Con los empleos de todas clases en los Tribunales y Juzgados de cualquier orden jurisdiccional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con el ejercicio de cualquier jurisdicción incluida la del Poder Judicial.</mark></span><span class=\"ref-norma\">Art. 389.1 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 389.1º de la LOPJ establece que el cargo de Juez o Magistrado es incompatible con el ejercicio de cualquier otra jurisdicción ajena a la del Poder Judicial. Por tanto, la opción a) es incorrecta porque sí es compatible con la jurisdicción del Poder Judicial, ya que es la que ejercen."},{"i":"8-286","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidades. El cargo de Juez o Magistrado es incompatible:","o":["Con el ejercicio de la docencia en materias jurídicas, entre otros supuestos.","Con la participación en actividades de producción literaria, científica o técnica, entre otros supuestos.","Con el ejercicio de cualquier otra jurisdicción ajena a la del Poder Judicial, entre otros supuestos.","Con la administración del patrimonio personal o familiar, entre otros supuestos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Con el ejercicio de cualquier otra jurisdicción ajena a la del Poder Judicial, entre otros supuestos</mark></span>El <span class=\"ref-norma\">art. 389 (encabezamiento) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"El cargo de Juez o Magistrado es incompatible: 1.º Con el ejercicio de cualquier otra jurisdicción ajena a la del Poder Judicial.\"</span>"},{"i":"8-287","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidades. El cargo de Juez o Magistrado es incompatible:","o":["Con el asesoramiento jurídico retribuido, pero no con el gratuito.","Con todo tipo de asesoramiento jurídico, sea o no retribuido.","Con el asesoramiento jurídico en materias ajenas a su jurisdicción.","Con todo tipo de asesoramiento jurídico, salvo que lo autorice el Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Con todo tipo de asesoramiento jurídico, sea o no retribuido</mark></span>El <span class=\"ref-norma\">art. 389.7.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"7.º Con todo tipo de asesoramiento jurídico, sea o no retribuido.\"</span>"},{"i":"8-288","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidades. El cargo de Juez o Magistrado es incompatible:","o":["Con el ejercicio de toda actividad mercantil, por sí o por otro.","Con el ejercicio de la actividad mercantil por sí, pero no por otro.","Con el ejercicio de la actividad mercantil habitual, no con la ocasional.","Con la titularidad de acciones de sociedades mercantiles, por sí o por otro."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con el ejercicio de toda actividad mercantil, por sí o por otro</mark></span>El <span class=\"ref-norma\">art. 389.8.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"8.º Con el ejercicio de toda actividad mercantil, por sí o por otro.\"</span>"},{"i":"8-ia-8940","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidades. El cargo de Juez o Magistrado es incompatible con todo empleo, cargo o profesión retribuida, salvo:","o":["la docencia y la participación en consejos de administración sin intervención directa, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","la docencia o investigación jurídica, así como la producción y creación literaria, artística, científica y técnica, y las publicaciones derivadas de aquélla.","la docencia y el arbitraje en procesos mercantiles.","la docencia universitaria y la dirección de revistas jurídicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la docencia o investigación jurídica, así como la producción y creación literaria, artística, científica y técnica, y las publicaciones derivadas de aquélla</mark></span>El <span class=\"ref-norma\">art. 389 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"5.º Con todo empleo, cargo o profesión retribuida, salvo la docencia o investigación jurídica, así como la producción y creación literaria, artística, científica y técnica, y las publicaciones derivadas de aquélla\"</span>. Las excepciones son la docencia o investigación jurídica y la creación literaria, artística, científica y técnica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8941","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidades. El cargo de Juez o Magistrado es incompatible con el ejercicio de la Abogacía y de la Procuraduría, con todo tipo de asesoramiento jurídico, sea o no retribuido, y con:","o":["el ejercicio de toda actividad mercantil, por sí o por otro.","el ejercicio de la docencia universitaria.","la participación en actividades deportivas no profesionales, salvo que la ley disponga otra cosa.","la pertenencia a asociaciones profesionales de jueces."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el ejercicio de toda actividad mercantil, por sí o por otro</mark></span>El <span class=\"ref-norma\">art. 389 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"8.º Con el ejercicio de toda actividad mercantil, por sí o por otro\"</span>. Incompatible con toda actividad mercantil por sí o por otro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 548","q":[{"i":"8-96","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la policía judicial. Se establecerán unidades de Policía Judicial que dependerán funcionalmente de __________________________ en el desempeño de todas las actuaciones que aquéllas les encomienden.","o":["Las autoridades judiciales.","La Unidad Orgánica de Policía Judicial donde esté encuadrada.","El Ministerio Fiscal.","a) y c) son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a) y c) son correctas</mark></span>Según el <span class=\"ref-norma\">art. 548 de la LOPJ</span>: <span class=\"ref-concepto\">\"Se establecerán unidades de Policía Judicial que dependerán funcionalmente de las autoridades judiciales y del Ministerio Fiscal en el desempeño de todas las actuaciones que aquéllas les encomienden\"</span> (verificado con el texto del temario oficial)."},{"i":"8-201","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Se establecerán unidades de Policía Judicial que dependerán funcionalmente de _________ en el desempeño de todas las actuaciones que aquéllas les encomienden.","o":["Las autoridades judiciales.","El Ministerio de Justicia.","A y B son correctas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las autoridades judiciales.</mark></span><span class=\"ref-norma\">Art. 548.1 · De la Oficina Judicial y el Personal al Servicio de la Administración de Justicia</span>. El artículo 548.1 de la LOPJ establece que las unidades de Policía Judicial dependerán funcionalmente de las autoridades judiciales y del Ministerio Fiscal. La opción (a) es correcta al mencionar a las autoridades judiciales, siendo la (b) incorrecta."},{"i":"8-ia-9101","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Unidades de Policía Judicial. Por ley se fijará la organización de las unidades de Policía Judicial y:","o":["el régimen retributivo y las plantillas de sus miembros.","los medios materiales y las sedes de las unidades.","los medios de selección y régimen jurídico de sus miembros.","las relaciones con las autoridades judiciales en cada partido."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los medios de selección y régimen jurídico de sus miembros</mark></span>El <span class=\"ref-norma\">art. 548.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Por ley se fijará la organización de estas unidades y los medios de selección y régimen jurídico de sus miembros\"</span>. También por ley los medios de selección y régimen jurídico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9156","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Funciones de la Policía Judicial. Corresponde específicamente a las unidades de Policía Judicial la averiguación acerca de los responsables y circunstancias de los hechos delictivos y la detención de los primeros, dando cuenta seguidamente:","o":["al Consejo General del Poder Judicial.","al Ministerio del Interior.","a la Sala de Gobierno.","a la autoridad judicial y fiscal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a la autoridad judicial y fiscal</mark></span>El <span class=\"ref-norma\">art. 549.1.a) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"dando cuenta seguidamente a la autoridad judicial y fiscal\"</span> Autoridad judicial y fiscal."},{"i":"8-ia-9157","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Coerción. Corresponde a las unidades de Policía Judicial la realización material de las actuaciones que exijan el ejercicio de la coerción y ordenare:","o":["la autoridad judicial o fiscal.","el Ministro del Interior.","el Director General de la Policía.","el Delegado del Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la autoridad judicial o fiscal</mark></span>El <span class=\"ref-norma\">art. 549.1.c) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"las actuaciones que exijan el ejercicio de la coerción y ordenare la autoridad judicial o fiscal.\"</span> Lo ordena la autoridad judicial o fiscal."}]},{"a":"Artículo 546 ✱ R21","q":[{"i":"8-97","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De los abogados, procuradores y graduados sociales. Las correcciones disciplinarias por su actuación ante los juzgados y tribunales se regirán por:","o":["Sus Colegios conforme a sus Estatutos.","Sus Consejos conforme a sus Estatutos.","Lo establecido en esta ley y en las leyes procesales.","Sus Comisiones disciplinarias conforme a sus Estatutos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Lo establecido en esta ley y en las leyes procesales.</mark></span><span class=\"ref-norma\">Art. 546.3 · Poder Judicial</span>. El artículo 546.3 de la LOPJ dispone que las correcciones disciplinarias por la actuación de Abogados, Procuradores y Graduados Sociales ante los Juzgados y Tribunales se regirán por lo establecido en esta ley y en las leyes procesales."},{"i":"8-292","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Abogados, Procuradores y Graduados Sociales. Los Abogados, Procuradores y Graduados Sociales están sujetos en el ejercicio de su profesión a responsabilidad:","o":["Civil y disciplinaria, pero no penal.","Civil y penal, quedando la disciplinaria reservada a los Colegios.","Penal y disciplinaria, según proceda.","Civil, penal y disciplinaria, según proceda."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Civil, penal y disciplinaria, según proceda</mark></span>El <span class=\"ref-norma\">art. 546.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2. Los Abogados, Procuradores y Graduados Sociales están sujetos en el ejercicio de su profesión a responsabilidad civil, penal y disciplinaria, según proceda.\"</span>"},{"i":"8-ia-9098","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Garantía de la defensa. Es obligación de los poderes públicos garantizar la defensa y la asistencia de Abogado o la representación técnica de Graduado Social:","o":["en todos los procedimientos, sin excepción.","en los términos establecidos en la Constitución y en las leyes.","a quienes lo soliciten por escrito al Colegio, sin perjuicio de lo dispuesto en otras leyes.","únicamente en los procesos penales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los términos establecidos en la Constitución y en las leyes</mark></span>El <span class=\"ref-norma\">art. 546.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Es obligación de los poderes públicos garantizar la defensa y la asistencia de Abogado o la representación técnica de Graduado Social en los términos establecidos en la Constitución y en las leyes\"</span>. Conforme a la Constitución y las leyes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9099","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad disciplinaria. La responsabilidad disciplinaria de los Abogados, Procuradores y Graduados Sociales por su conducta profesional compete declararla a:","o":["los correspondientes Colegios y Consejos conforme a sus estatutos, que deberán respetar las garantías de la defensa de todo el procedimiento sancionador.","los Juzgados y Tribunales ante los que actúen, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","el Consejo General del Poder Judicial.","el Ministerio de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los correspondientes Colegios y Consejos conforme a sus estatutos, que deberán respetar las garantías de la defensa de todo el procedimiento sancionador</mark></span>El <span class=\"ref-norma\">art. 546.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La responsabilidad disciplinaria por su conducta profesional compete declararla a los correspondientes Colegios y Consejos conforme a sus estatutos, que deberán respetar en todo caso las garantías de la defensa de todo el procedimiento sancionador\"</span>. Compete a los Colegios y Consejos; las correcciones ante los tribunales se rigen por la LOPJ y las leyes procesales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5 bis","q":[{"i":"8-98","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. Se podrá interponer ______________________ ante el Tribunal Supremo contra una resolución judicial firme, con arreglo a las normas procesales de cada orden jurisdiccional, cuando el Tribunal Europeo de Derechos Humanos haya declarado que dicha resolución ha sido dictada en violación de alguno de los derechos reconocidos en el Convenio Europeo para la Protección de los Derechos Humanos y Libertades Fundamentales y sus Protocolos, siempre que la violación, por su naturaleza y gravedad, entrañe efectos que persistan y no puedan cesar de ningún otro modo que no sea mediante esta revisión.","o":["Recurso de reforma.","Recurso de súplica.","Recurso de revisión.","Recurso de apelación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Recurso de revisión.</mark></span><span class=\"ref-norma\">Art. 5 bis · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 5 bis de la LOPJ establece la posibilidad de interponer un recurso de revisión ante el Tribunal Supremo en este supuesto específico de violación de derechos del Convenio Europeo de Derechos Humanos por una resolución judicial firme."},{"i":"8-ia-8012","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recurso de revisión por resolución del TEDH. Se podrá interponer recurso de revisión ante el Tribunal Supremo contra una resolución judicial firme cuando el Tribunal Europeo de Derechos Humanos haya declarado que dicha resolución ha sido dictada en violación de alguno de los derechos reconocidos en el Convenio, siempre que la violación, por su naturaleza y gravedad:","o":["entrañe efectos que persistan y no puedan ser reparados mediante indemnización.","entrañe efectos que persistan y no puedan cesar de ningún otro modo que no sea mediante esta revisión.","haya causado un perjuicio irreparable al recurrente y se interponga en el plazo de un año, sin perjuicio de lo dispuesto en otras leyes.","afecte a derechos fundamentales y no haya sido objeto de recurso de amparo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">entrañe efectos que persistan y no puedan cesar de ningún otro modo que no sea mediante esta revisión</mark></span>El <span class=\"ref-norma\">art. 5 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que la violación, por su naturaleza y gravedad, entrañe efectos que persistan y no puedan cesar de ningún otro modo que no sea mediante esta revisión\"</span>. El requisito es que los efectos persistan y no puedan cesar de otro modo que mediante la revisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4","q":[{"i":"8-99","p":"La jurisdicción se extiende a:","o":["Todas las personas, a todas las materias y a todo el territorio español, en la forma establecida en la Constitución y en las Leyes.","Todas las personas, a todas las materias, pero limitada al territorio nacional.","Solo a las personas físicas, a todas las materias y a todo el territorio español.","Todas las personas, pero limitada a las materias no atribuidas a otro orden jurisdiccional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Todas las personas, a todas las materias y a todo el territorio español, en la forma establecida en la Constitución y en las Leyes.</mark></span><span class=\"ref-norma\">Art. 4 · Poder Judicial</span>. El artículo 4 de la LOPJ establece la extensión de la jurisdicción."}]},{"a":"Artículo 56","q":[{"i":"8-102","p":"La Audiencia Nacional se compone de las siguientes Salas, señale la que NO es correcta:","o":["Sala de Apelación.","Sala de lo Penal.","Sala de lo Civil.","Sala de lo Contencioso-Administrativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sala de lo Civil.</mark></span><span class=\"ref-norma\">Art. 64 · De la Organización y Planta de Juzgados y Tribunales</span>. Las Salas de la Audiencia Nacional son: Apelación, Penal, Contencioso-Administrativo y Social (Art. 64 LOPJ). No existe la Sala de lo Civil."},{"i":"8-111","p":"(LOPJ) ¿Ante qué Sala se exigirá la responsabilidad civil de los Magistrados de las Audiencias Provinciales, de los Tribunales Superiores de Justicia y de la Audiencia Nacional?","o":["Sala de lo Civil del Tribunal Supremo.","Sala de lo Civil y Penal del Tribunal Superior de Justicia.","Sala de lo Penal del Tribunal Supremo.","Sala de Gobierno del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sala de lo Civil del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 411 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 411 de la LOPJ establece que la responsabilidad civil de Jueces y Magistrados (excepto los del TS) se exigirá ante la Sala de lo Civil del Tribunal Supremo."},{"i":"8-115","p":"¿Cuál de las siguientes es una competencia de la Sala de Gobierno del Tribunal Supremo?","o":["Resolver los recursos de apelación contra las sentencias dictadas por la Audiencia Nacional.","Resolver los recursos de alzada interpuestos contra los acuerdos de las Salas de Gobierno de los Tribunales Superiores de Justicia.","Conocer de las pretensiones de declaración de error judicial cuando este se impute a una Sala del Tribunal Supremo.","Conocer de los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Resolver los recursos de alzada interpuestos contra los acuerdos de las Salas de Gobierno de los Tribunales Superiores de Justicia.</mark></span><span class=\"ref-norma\">Art. 149.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 149.1.10º de la LOPJ atribuye a la Sala de Gobierno del TS la competencia de resolver los recursos de alzada contra los acuerdos de las Salas de Gobierno de los TT.SS.JJ."},{"i":"8-122","p":"Ley Orgánica 6/1985 del Poder Judicial. ¿Quién conocerá de las demandas de responsabilidad civil por hechos realizados en el ejercicio de su cargo, dirigidas contra los Consejeros del Tribunal de Cuentas?","o":["La Sala de lo Penal del Tribunal Supremo.","La Sala de lo Penal de la Audiencia Nacional.","La Sala de lo Civil y de lo Penal del Tribunal Superior de Justicia.","La Sala de lo Civil del Tribunal Supremo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de lo Civil del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 56.4 · De la Organización y Planta de Juzgados y Tribunales</span>. Corresponde a la Sala Primera, de lo Civil, del Tribunal Supremo, el conocimiento de las demandas de responsabilidad civil, por hechos realizados en el ejercicio de su cargo, dirigidas contra, entre otros, los Consejeros del Tribunal de Cuentas (art. 56.4 LOPJ)."},{"i":"8-198","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá del enjuiciamiento por falsificación de moneda y fabricación de tarjetas de crédito y débito falsas y cheques de viajero falsos o cualquier otro instrumento de pago distinto del efectivo, siempre que sean cometidos por organizaciones o grupos criminales?","o":["La Sala de lo Penal de la Audiencia Nacional, en todo caso.","El Tribunal Constitucional.","La Sala de lo Civil y Penal de los Tribunales Superiores de Justicia.","La Sala de lo Penal de la Audiencia Nacional, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de lo Penal de la Audiencia Nacional, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia</mark></span>Según el <span class=\"ref-norma\">art. 65.1.1.º.b de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"La Sala de lo Penal de la Audiencia Nacional conocerá: 1.º Del enjuiciamiento, salvo que corresponda en primera instancia a la Sección de lo Penal del Tribunal Central de Instancia, de las causas por los siguientes delitos: [...] b) Falsificación de moneda y fabricación de tarjetas de crédito y débito falsas y cheques de viajero falsos [...] siempre que sean cometidos por organizaciones o grupos criminales\"</span> (verificado con el texto del temario)."},{"i":"8-207","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién ejercerá la Jefatura del Ministerio Fiscal?","o":["El Ministro Fiscal.","El Fiscal General del Estado.","El Fiscal de Sala.","El Ministerio de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Fiscal General del Estado.</mark></span><span class=\"ref-norma\">Art. 124 · Poder Judicial</span>. El artículo 124 de la Constitución Española y el Estatuto Orgánico del Ministerio Fiscal establecen que el Fiscal General del Estado ostenta la Jefatura del Ministerio Fiscal."},{"i":"8-216","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. En todos los casos en que, según la ley, proceda recurso de casación, será suficiente para fundamentarlo la infracción de precepto constitucional. En este supuesto, la competencia para decidir el recurso corresponderá siempre _________ cualquiera que sean la materia, el derecho aplicable y el orden jurisdiccional.","o":["Al Tribunal Supremo.","Al Tribunal Superior de Justicia.","A la Audiencia Nacional.","Al Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 56 · De la Organización y Planta de Juzgados y Tribunales</span>. La competencia para conocer de los recursos de casación en los distintos órdenes jurisdiccionales recae en el Tribunal Supremo, como máximo órgano de la jurisdicción ordinaria (Art. 56 LOPJ y siguientes)."},{"i":"8-232","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial ¿Quién conocerá de las demandas de responsabilidad civil por hechos realizados en el ejercicio de su cargo, dirigidas contra el Presidente de la Audiencia Nacional?","o":["A la Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","La Sala de lo Civil y de lo Penal del Tribunal Superior de Justicia.","La Sala de lo Civil del Tribunal Supremo.","El Tribunal Constitucional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Civil del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 56.1 · De la Organización y Planta de Juzgados y Tribunales</span>. El conocimiento de las demandas de responsabilidad civil, por hechos realizados en el ejercicio de sus respectivos cargos, dirigidas contra el Presidente de la Audiencia Nacional, corresponde a la Sala de lo Civil del Tribunal Supremo (Art. 56.1.1ª LOPJ)."},{"i":"8-ia-8306","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil del Tribunal Supremo. La Sala de lo Civil del Tribunal Supremo conocerá de los recursos de casación, revisión y otros extraordinarios en materia civil que establezca la ley y de las demandas de responsabilidad civil por hechos realizados en el ejercicio de su cargo, dirigidas contra el Presidente del Gobierno, Presidentes del Congreso y del Senado y, entre otros:","o":["los Alcaldes de capitales de provincia y los Presidentes de Diputación.","los Magistrados de las Audiencias Provinciales y los Jueces de Instrucción, en los términos que establezca la ley orgánica.","los Delegados del Gobierno y los Subdelegados en las provincias.","el Fiscal General del Estado, el Defensor del Pueblo y el Presidente y Consejeros del Tribunal de Cuentas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Fiscal General del Estado, el Defensor del Pueblo y el Presidente y Consejeros del Tribunal de Cuentas</mark></span>El <span class=\"ref-norma\">art. 56 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Fiscal General del Estado, Fiscales de Sala del Tribunal Supremo, Presidente y Consejeros del Tribunal de Cuentas, Presidente y Consejeros del Consejo de Estado, Defensor del Pueblo\"</span>. La lista incluye al Fiscal General del Estado, Tribunal de Cuentas, Consejo de Estado y Defensor del Pueblo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8307","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Civil del Tribunal Supremo. La Sala de lo Civil del Tribunal Supremo conocerá de las demandas de responsabilidad civil dirigidas contra Magistrados de la Audiencia Nacional o de los Tribunales Superiores de Justicia:","o":["por cualquier hecho, aunque no esté relacionado con el ejercicio de su cargo.","por hechos delictivos declarados por sentencia firme.","por hechos realizados en el ejercicio de sus cargos.","por hechos cometidos fuera del ejercicio de sus cargos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por hechos realizados en el ejercicio de sus cargos</mark></span>El <span class=\"ref-norma\">art. 56 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De las demandas de responsabilidad civil dirigidas contra Magistrados de la Audiencia Nacional o de los Tribunales Superiores de Justicia por hechos realizados en el ejercicio de sus cargos\"</span>. Solo por hechos realizados en el ejercicio de sus cargos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8308","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal del Tribunal Supremo. La Sala de lo Penal del Tribunal Supremo conocerá de la instrucción y enjuiciamiento de las causas contra el Presidente del Gobierno, Presidentes del Congreso y del Senado, miembros del Gobierno, Diputados y Senadores y, entre otros:","o":["los Presidentes de las Audiencias Provinciales y los Jueces Decanos.","el Presidente de la Audiencia Nacional y de cualquiera de sus Salas y de los Tribunales Superiores de Justicia, y el Fiscal General del Estado.","los Alcaldes y Concejales de los municipios de más de cien mil habitantes, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","los Delegados del Gobierno en las Comunidades Autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Presidente de la Audiencia Nacional y de cualquiera de sus Salas y de los Tribunales Superiores de Justicia, y el Fiscal General del Estado</mark></span>El <span class=\"ref-norma\">art. 57 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Presidente de la Audiencia Nacional y de cualquiera de sus Salas y de los Tribunales Superiores de Justicia, Fiscal General del Estado\"</span>. Incluye presidentes de la AN y sus Salas y de los TSJ, y al Fiscal General del Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 83 EX R14","q":[{"i":"8-103","p":"En relación con las Audiencias Provinciales:","o":["Tendrán su sede en la capital de la provincia y su jurisdicción se extiende a toda ella.","No podrán crearse Secciones de la Audiencia Provincial fuera de la capital.","Podrán crearse Secciones fuera de la capital, a las que quedarán adscritos uno o varios partidos judiciales.","Las respuestas (a) y (c) son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las respuestas (a) y (c) son correctas</mark></span>Según el <span class=\"ref-norma\">art. 80 de la LOPJ</span>: <span class=\"ref-concepto\">\"Las Audiencias Provinciales, que tendrán su sede en la capital de la provincia, de la que tomarán su nombre, extenderán su jurisdicción a toda ella\"</span> (verificado con el texto del temario oficial)."}]},{"a":"Artículo 25 EXOF ✱","q":[{"i":"8-108","p":"En el orden social, los Juzgados y Tribunales españoles NO serán competentes cuando:","o":["Se trate de conflictos colectivos, si se han planteado por sindicatos con implantación en España.","El demandado tenga su domicilio en territorio español.","Los servicios se hayan prestado en el extranjero y el contrato se haya celebrado fuera de España.","El trabajador y el empresario tengan nacionalidad española, cualquiera que sea el lugar de prestación de servicios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los servicios se hayan prestado en el extranjero y el contrato se haya celebrado fuera de España</mark></span>Según el <span class=\"ref-norma\">art. 25 de la LOPJ</span>: <span class=\"ref-concepto\">\"En materia de derechos y obligaciones derivados de contrato de trabajo, cuando los servicios se hayan prestado en España o el contrato se haya celebrado en territorio español\"</span> (verificado con el texto del temario oficial)."},{"i":"8-256","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia en el orden social. En el orden social, los jueces y juezas, así como los Tribunales españoles serán competentes:","o":["Únicamente en materia de Seguridad Social frente a entidades españolas.","En las materias que enumera el propio artículo, como los derechos y obligaciones derivados de contrato de trabajo.","En todo caso, con preferencia de cualquier otro, para cualquier pretensión de carácter laboral, conforme al procedimiento que reglamentariamente se establezca.","Solo cuando el contrato de trabajo se haya celebrado en territorio español."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En las materias que enumera el propio artículo, como los derechos y obligaciones derivados de contrato de trabajo</mark></span>El <span class=\"ref-norma\">art. 25 (encabezamiento) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"En el orden social, los jueces y juezas, así como los Tribunales españoles serán competentes:\"</span>"},{"i":"8-257","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia en el orden social. En el orden social, los Tribunales españoles serán competentes en materia de control de legalidad de los convenios colectivos de trabajo celebrados en España y de:","o":["Pretensiones derivadas de conflictos colectivos de trabajo promovidos en territorio español.","Pretensiones derivadas de conflictos individuales de trabajo promovidos en territorio español.","Pretensiones de Seguridad Social frente a entidades españolas.","Conflictos colectivos de trabajo promovidos en cualquier Estado de la Unión Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Pretensiones derivadas de conflictos colectivos de trabajo promovidos en territorio español</mark></span>El <span class=\"ref-norma\">art. 25.2.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2.º En materia de control de legalidad de los convenios colectivos de trabajo celebrados en España y de pretensiones derivadas de conflictos colectivos de trabajo promovidos en territorio español.\"</span>"},{"i":"8-258","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia en el orden social. En el orden social, los Tribunales españoles serán competentes en materia de pretensiones de Seguridad Social frente a:","o":["Entidades extranjeras con sede en la Unión Europea, aunque no tengan representación en España, sin perjuicio de lo que establezcan los tratados internacionales.","Cualquier entidad gestora, con independencia de su domicilio o de su representación en España.","Entidades españolas, con exclusión de las que tengan solo una agencia o delegación en España.","Entidades españolas o que tengan domicilio, agencia, delegación o cualquier otra representación en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Entidades españolas o que tengan domicilio, agencia, delegación o cualquier otra representación en España</mark></span>El <span class=\"ref-norma\">art. 25.3.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"3.º En materia de pretensiones de Seguridad Social frente a entidades españolas o que tengan domicilio, agencia, delegación o cualquier otra representación en España.\"</span>"},{"i":"8-ia-8062","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Foros subsidiarios. En defecto de los criterios anteriores, los Tribunales españoles serán competentes en materia de declaración de ausencia o fallecimiento, cuando el desaparecido:","o":["hubiera tenido su último domicilio en territorio español y tuviera nacionalidad española, en los términos que establezca la ley orgánica.","haya tenido su residencia habitual en España los dos últimos años.","tuviera bienes inmuebles en territorio español.","hubiera tenido su último domicilio en territorio español o tuviera nacionalidad española."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">hubiera tenido su último domicilio en territorio español o tuviera nacionalidad española</mark></span>El <span class=\"ref-norma\">art. 22 quáter.a de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En materia de declaración de ausencia o fallecimiento, cuando el desaparecido hubiera tenido su último domicilio en territorio español o tuviera nacionalidad española\"</span>. Basta último domicilio en España o nacionalidad española (criterios alternativos). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8159","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción universal · terrorismo. En materia de terrorismo, la jurisdicción española será también competente cuando el delito haya sido cometido contra una institución u organismo de la Unión Europea que:","o":["tenga su sede en España.","tenga delegación o representación en España.","financie parcialmente España.","cuente con personal español."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tenga su sede en España</mark></span>El <span class=\"ref-norma\">art. 23.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"6.º el delito haya sido cometido contra una institución u organismo de la Unión Europea que tenga su sede en España\"</span>. El criterio es la sede en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8173","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden social. En el orden social, los jueces y juezas, así como los Tribunales españoles serán competentes en materia de derechos y obligaciones derivados de contrato de trabajo, entre otros supuestos, cuando:","o":["el trabajador tenga nacionalidad española y los servicios se presten en España.","el empresario tenga nacionalidad española y el contrato se celebre en el extranjero, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","el trabajador y el empresario tengan nacionalidad española, cualquiera que sea el lugar de prestación de los servicios o de celebración del contrato.","el contrato se haya celebrado en España y el trabajador sea extranjero."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el trabajador y el empresario tengan nacionalidad española, cualquiera que sea el lugar de prestación de los servicios o de celebración del contrato</mark></span>El <span class=\"ref-norma\">art. 25 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando el trabajador o la trabajadora y el empresario o la empresaria tengan nacionalidad española, cualquiera que sea el lugar de prestación de los servicios o de celebración del contrato\"</span>. Basta que ambos tengan nacionalidad española, sin importar el lugar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8174","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden social. En el caso de contrato de embarque, los Tribunales españoles serán competentes en el orden social, además de por los criterios generales, si:","o":["el buque enarbola pabellón español.","el contrato fue precedido de oferta recibida en España por trabajador español.","el trabajador tiene su residencia en España, conforme al procedimiento que establezcan las leyes procesales.","el contrato se firmó ante un cónsul español."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el contrato fue precedido de oferta recibida en España por trabajador español</mark></span>El <span class=\"ref-norma\">art. 25 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"y, además, en el caso de contrato de embarque, si el contrato fue precedido de oferta recibida en España por trabajador español\"</span>. La oferta debe haberse recibido en España por un trabajador español. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8175","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden social. En el orden social, los Tribunales españoles serán competentes en materia de control de legalidad de los convenios colectivos de trabajo celebrados en España y de pretensiones derivadas de conflictos colectivos de trabajo:","o":["promovidos en territorio español.","promovidos por sindicatos de implantación nacional.","que afecten a trabajadores de nacionalidad española.","que afecten a empresas con domicilio en España."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">promovidos en territorio español</mark></span>El <span class=\"ref-norma\">art. 25 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"de pretensiones derivadas de conflictos colectivos de trabajo promovidos en territorio español\"</span>. El criterio es que el conflicto colectivo se promueva en territorio español. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9109","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia general. En materias no contempladas expresamente y si no mediare sumisión a los Tribunales españoles, estos resultarán competentes cuando el demandado:","o":["sea de nacionalidad española, salvo que el órgano competente acuerde otra cosa de forma motivada.","tenga bienes en España.","haya contratado en España.","tenga su domicilio en España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tenga su domicilio en España</mark></span>El <span class=\"ref-norma\">art. 22 ter.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando el demandado tenga su domicilio en España\"</span> Domicilio del demandado en España."}]},{"a":"Artículo 547 ✱","q":[{"i":"8-109","p":"La función de la Policía Judicial comprende, entre otras:","o":["La dirección de la instrucción de las causas penales.","El auxilio a los Juzgados y Tribunales y al Ministerio Fiscal en la averiguación de los delitos.","La decisión sobre la procedencia de medidas cautelares penales.","La ratificación de las resoluciones de la autoridad judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El auxilio a los Juzgados y Tribunales y al Ministerio Fiscal en la averiguación de los delitos.</mark></span><span class=\"ref-norma\">Art. 547 · De la Oficina Judicial y el Personal al Servicio de la Administración de Justicia</span>. El artículo 547 de la LOPJ define la función de la Policía Judicial como el auxilio en la averiguación de delitos y en el descubrimiento y aseguramiento de delincuentes."},{"i":"8-176","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. De la Policía Judicial. Señale la INCORRECTA.","o":["Por ley se fijará la organización de las unidades de Policía Judicial.","La función de la Policía Judicial comprende el auxilio a los órganos jurisdiccionales y al Ministerio Fiscal en la averiguación de los delincuentes y en el descubrimiento y aseguramiento de los delitos.","Se establecerán unidades de Policía Judicial que dependerán funcionalmente de las autoridades judiciales y del Ministerio Fiscal en el desempeño de todas las actuaciones que aquéllas les encomienden.","Por ley se fijarán los medios de selección y régimen jurídico de los miembros de las unidades de Policía Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La función de la Policía Judicial comprende el auxilio a los órganos jurisdiccionales y al Ministerio Fiscal en la averiguación de los delincuentes y en el descubrimiento y aseguramiento de los delitos</mark></span>La opción B invierte «delitos» y «delincuentes». Según el <span class=\"ref-norma\">art. 547 de la LOPJ</span>: <span class=\"ref-concepto\">\"La función de la Policía Judicial comprende el auxilio a los juzgados y tribunales y al Ministerio Fiscal en la averiguación de los delitos y en el descubrimiento y aseguramiento de los delincuentes\"</span> (verificado con el texto del temario oficial)."}]},{"a":"Artículo 3 ✱","q":[{"i":"8-110","p":"¿Qué principio NO se menciona en el artículo 1 de la LOPJ como característico de los Jueces y Magistrados?","o":["Independencia.","Inamovilidad.","Responsabilidad.","Unidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Unidad.</mark></span><span class=\"ref-norma\">Art. 1 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 1 de la LOPJ indica que los Jueces y Magistrados son independientes, inamovibles, responsables y sometidos únicamente a la Constitución y a la Ley. La unidad es un principio de la jurisdicción (Art. 3)."},{"i":"8-169","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿En qué basan su funcionamiento los órganos de la jurisdicción militar?","o":["En el principio de unidad jurisdiccional.","En el principio de autonomía.","En el principio de eficacia castrense.","En el principio de proporcionalidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En el principio de unidad jurisdiccional.</mark></span><span class=\"ref-norma\">Art. 117.5 · Poder Judicial</span>. La jurisdicción militar, si bien con peculiaridades, forma parte del Poder Judicial del Estado y basa su organización y funcionamiento en el principio de unidad jurisdiccional (art. 117.5 de la Constitución Española y art. 3.2 de la L.O.P.J.)."},{"i":"8-181","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La jurisdicción se extiende a todas las personas, a todas las materias y a todo el territorio español, en la forma establecida:","o":["En la Constitución y en las Leyes.","Por el Gobierno.","Por el Consejo General del Estado.","En los Tratados Internacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En la Constitución y en las Leyes.</mark></span><span class=\"ref-norma\">Art. 3 · Poder Judicial</span>. - El artículo 3 de la LOPJ establece que la jurisdicción se extiende en la forma establecida en la Constitución y en las Leyes. &amp;lt;hr&amp;gt;"},{"i":"8-217","p":"Ley Orgánica 6/1985 del Poder Judicial. Las correcciones disciplinarias por su actuación ante los Juzgados y Tribunales se regirán por lo establecido:","o":["En la Ley Orgánica del Poder Judicial.","En las leyes penales.","Por los Colegios y Consejos conforme a sus estatutos.","A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En la Ley Orgánica del Poder Judicial.</mark></span>La potestad de imponer correcciones disciplinarias (policía de estrados) a Abogados y Procuradores por hechos cometidos ante ellos está regulada en los Arts. 552 a 556 de la Ley Orgánica del Poder Judicial."},{"i":"8-218","p":"Ley Orgánica 6/1985 del Poder Judicial. De la inamovilidad de Jueces y Magistrados. El Juez o Magistrado que hubiere sido rehabilitado será destinado con arreglo a lo dispuesto:","o":["En la Ley Orgánica del Poder Judicial.","En la Constitución.","En el Reglamento del Poder Judicial.","En lo que se determine por orden ministerial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En la Ley Orgánica del Poder Judicial.</mark></span><span class=\"ref-norma\">Art. 382 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El Art. 382 LOPJ establece que el Juez o Magistrado rehabilitado será destinado con arreglo a lo dispuesto en la Ley Orgánica del Poder Judicial misma."},{"i":"8-223","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿En qué basan su organización los órganos de la jurisdicción militar?","o":["En el principio de proporcionalidad.","En el principio de unidad jurisdiccional.","En el principio de autonomía.","En el principio de eficacia castrense."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el principio de unidad jurisdiccional.</mark></span><span class=\"ref-norma\">Art. 3 · Poder Judicial</span>. El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales, y la Jurisdicción Militar está integrada en el Poder Judicial del Estado, sujeta a este principio (Art. 3 LOPJ y Art. 117.5 CE)."},{"i":"8-ia-8004","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Unidad de la jurisdicción. La jurisdicción es única y se ejerce por los jueces, las juezas y los Tribunales previstos en esta ley orgánica, sin perjuicio de:","o":["las competencias que los Estatutos de Autonomía atribuyan a los Tribunales Superiores de Justicia.","las potestades jurisdiccionales reconocidas por la Constitución a otros órganos.","las funciones de los órganos de gobierno del Poder Judicial.","los poderes de los árbitros designados por las partes en los términos de la ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las potestades jurisdiccionales reconocidas por la Constitución a otros órganos</mark></span>El <span class=\"ref-norma\">art. 3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"sin perjuicio de las potestades jurisdiccionales reconocidas por la Constitución a otros órganos\"</span>. La salvedad es a favor de las potestades jurisdiccionales que la Constitución reconoce a otros órganos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8005","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Unidad de la jurisdicción. Los órganos de la jurisdicción militar, integrante del Poder Judicial del Estado, basan su organización y funcionamiento en el principio de unidad jurisdiccional y administran Justicia:","o":["en el ámbito estrictamente castrense y, en su caso, en las materias que establezca la declaración del estado de sitio.","en el ámbito castrense y, en su caso, en las materias que establezca la declaración del estado de excepción, en los términos que establezca la ley orgánica.","en el ámbito estrictamente militar y en todos los delitos cometidos por militares.","en el ámbito castrense y en las materias que determine el Consejo de Ministros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en el ámbito estrictamente castrense y, en su caso, en las materias que establezca la declaración del estado de sitio</mark></span>El <span class=\"ref-norma\">art. 3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"administran Justicia en el ámbito estrictamente castrense y, en su caso, en las materias que establezca la declaración del estado de sitio\"</span>. La ley habla del estado de sitio, no del de excepción, y del ámbito «estrictamente castrense». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8006","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Extensión de la jurisdicción. La jurisdicción se extiende a todas las personas, a todas las materias y a todo el territorio español, en la forma establecida:","o":["en la Constitución y en los tratados internacionales.","en las leyes orgánicas y en los Estatutos de Autonomía.","en esta ley orgánica y en las leyes procesales.","en la Constitución y en las leyes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en la Constitución y en las leyes</mark></span>El <span class=\"ref-norma\">art. 4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La jurisdicción se extiende a todas las personas, a todas las materias y a todo el territorio español, en la forma establecida en la Constitución y en las leyes\"</span>. La fórmula legal es «la Constitución y las leyes». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8021","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Orden jurisdiccional penal. Los del orden jurisdiccional penal tendrán atribuido el conocimiento de las causas y juicios criminales, con excepción de:","o":["los que correspondan a la jurisdicción militar.","los que correspondan a los Jueces de Paz.","los delitos leves y las faltas de menor entidad.","los que correspondan al Tribunal del Jurado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los que correspondan a la jurisdicción militar</mark></span>El <span class=\"ref-norma\">art. 9.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"tendrán atribuido el conocimiento de las causas y juicios criminales, con excepción de los que correspondan a la jurisdicción militar\"</span>. La única excepción legal es la jurisdicción militar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8154","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden penal. Conocerá la jurisdicción española de los hechos cometidos por españoles o extranjeros fuera del territorio nacional cuando sean susceptibles de tipificarse, según la ley penal española, como alguno de los siguientes delitos:","o":["de genocidio y lesa humanidad, sin condición alguna.","de traición y contra la paz o la independencia del Estado.","de blanqueo de capitales y de corrupción en las transacciones económicas.","de falsificación de moneda extranjera."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de traición y contra la paz o la independencia del Estado</mark></span>El <span class=\"ref-norma\">art. 23.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) De traición y contra la paz o la independencia del Estado\"</span>. Genocidio y lesa humanidad están en el apartado 4, con condiciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9126","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Conflictos de jurisdicción. El planteamiento, tramitación y decisión de los conflictos de jurisdicción se ajustará a:","o":["lo que decida el Tribunal Supremo en cada caso.","lo dispuesto en la ley.","el reglamento del Consejo General del Poder Judicial.","las normas de la Ley Orgánica del Tribunal Constitucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">lo dispuesto en la ley</mark></span>El <span class=\"ref-norma\">art. 41 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se ajustará a lo dispuesto en la ley.\"</span> A lo dispuesto en la ley."}]},{"a":"Artículo 398 ✱ R19","q":[{"i":"8-113","p":"(LOPJ) Un Juez o Magistrado, si debe declarar en un procedimiento por razón de su cargo, ¿ante qué autoridad inferior podrá hacerlo si la declaración es en el lugar donde presta servicios?","o":["Ante el Juez de Instrucción de la causa.","Ante el Juez de Paz.","Ante el Magistrado que esté de turno.","Ante ninguna autoridad inferior, sino ante el Juez o Tribunal que conozca la causa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ante ninguna autoridad inferior, sino ante el Juez o Tribunal que conozca la causa.</mark></span><span class=\"ref-norma\">Art. 398 · Poder Judicial</span>. El artículo 398 de la LOPJ prohíbe que la declaración de un Juez o Magistrado se practique ante una autoridad inferior."},{"i":"8-149","p":"(LOPJ) De toda detención de Jueces o Magistrados se dará cuenta, por el medio más rápido, al Presidente de:","o":["La Sala de Gobierno del Tribunal Supremo.","La Audiencia Nacional.","La Sala de Gobierno del Tribunal Superior de Justicia.","El Tribunal o la Audiencia de quien dependa el Juez o Magistrado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Tribunal o la Audiencia de quien dependa el Juez o Magistrado.</mark></span><span class=\"ref-norma\">Art. 398.2 · Poder Judicial</span>. El artículo 398.2 de la LOPJ establece que se dará cuenta al Presidente del Tribunal o de la Audiencia de quien dependa el Juez o Magistrado."},{"i":"8-ia-9062","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inmunidad judicial. Los Jueces y Magistrados en servicio activo sólo podrán ser detenidos por orden de Juez competente o en caso de flagrante delito. En este último caso se tomarán las medidas de aseguramiento indispensables y se entregará inmediatamente el detenido:","o":["al Presidente del Tribunal Superior de Justicia.","al Juez de Instrucción más próximo.","al Fiscal de guardia del partido.","a la Sala de Gobierno del Tribunal de que dependa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Juez de Instrucción más próximo</mark></span>El <span class=\"ref-norma\">art. 398.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se tomarán las medidas de aseguramiento indispensables y se entregará inmediatamente el detenido al Juez de Instrucción más próximo\"</span>. Se entrega al Juez de Instrucción más próximo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9063","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inmunidad judicial. De toda detención de un Juez o Magistrado se dará cuenta, por el medio más rápido, al:","o":["Presidente del Tribunal o de la Audiencia de quien dependa el Juez o Magistrado.","Presidente del Consejo General del Poder Judicial, en los términos que establezca la ley orgánica.","Fiscal General del Estado.","Presidente del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Presidente del Tribunal o de la Audiencia de quien dependa el Juez o Magistrado</mark></span>El <span class=\"ref-norma\">art. 398.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De toda detención se dará cuenta, por el medio mas rápido, al Presidente del Tribunal o de la Audiencia de quien dependa el Juez o Magistrado\"</span>. Al Presidente del Tribunal o Audiencia de que dependa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 47","q":[{"i":"8-114","p":"En un conflicto de competencia entre órganos de distintos órdenes jurisdiccionales (Sala de Conflictos de Competencia del TS), ¿cuál es el plazo máximo para que el Ministerio Fiscal emita su informe?","o":["Cinco días.","Diez días.","Quince días.","Veinte días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Diez días.</mark></span><span class=\"ref-norma\">Art. 47.2 · Poder Judicial</span>. El artículo 47.2 de la LOPJ establece que la Sala, oído el Ministerio Fiscal por plazo no superior a diez días, dictará auto en los diez siguientes."},{"i":"8-ia-8196","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Resolución del conflicto. La Sala de Conflictos, oído el Ministerio Fiscal por plazo no superior a diez días, dictará auto en los diez siguientes, y contra él:","o":["cabe recurso de reposición ante la misma Sala.","cabe recurso de casación ante el Pleno del Tribunal Supremo, conforme al procedimiento que establezcan las leyes procesales.","cabe recurso de revisión en el plazo de cinco días.","no cabe recurso alguno; el auto resolverá definitivamente el conflicto de competencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no cabe recurso alguno; el auto resolverá definitivamente el conflicto de competencia</mark></span>El <span class=\"ref-norma\">art. 47 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"dictará auto en los diez siguientes, sin que contra él quepa recurso alguno. El auto que se dicte resolverá definitivamente el conflicto de competencia\"</span>. No cabe recurso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 1 ✱","q":[{"i":"8-123","p":"Ley Orgánica 6/1985 del Poder Judicial. ¿De quién emana la Justicia?","o":["Del Rey.","Del pueblo.","De los Jueces y Magistrados.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del pueblo.</mark></span><span class=\"ref-norma\">Art. 1.1 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. La Justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados (art. 1.1 LOPJ y art. 117.1 CE)."},{"i":"8-ia-8001","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Principios del Poder Judicial. La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del Poder Judicial, que son:","o":["independientes, inamovibles, responsables y sometidos únicamente a la Constitución y al imperio de la ley.","independientes, inamovibles, responsables y sometidos a la Constitución, a la ley y a las instrucciones del Consejo General del Poder Judicial.","independientes, inviolables, irresponsables y sometidos únicamente a la Constitución.","imparciales, inamovibles, responsables y sometidos únicamente a la ley y a la jurisprudencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">independientes, inamovibles, responsables y sometidos únicamente a la Constitución y al imperio de la ley</mark></span>El <span class=\"ref-norma\">art. 1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"independientes, inamovibles, responsables y sometidos únicamente a la Constitución y al imperio de la ley\"</span>. La ley habla de sometimiento «únicamente a la Constitución y al imperio de la ley»; no hay sometimiento a instrucciones ni inviolabilidad o irresponsabilidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8485","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias penales de las Audiencias Provinciales. Para el conocimiento de los recursos contra resoluciones de las Secciones de Instrucción de los Tribunales de Instancia en juicios por delitos leves la Audiencia Provincial se constituirá:","o":["con tres magistrados, mediante un turno de reparto.","con un solo magistrado, designado por el Presidente.","con un solo magistrado o magistrada, mediante un turno de reparto.","con el Presidente de la Audiencia, que resolverá en todo caso, sin perjuicio de lo dispuesto en otras leyes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con un solo magistrado o magistrada, mediante un turno de reparto</mark></span>El <span class=\"ref-norma\">art. 82.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"la Audiencia se constituirá con un solo magistrado o magistrada, mediante un turno de reparto\"</span>. Un solo magistrado por turno de reparto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 393 ✱","q":[{"i":"8-124","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. No podrían los Jueces y Magistrados desempeñar su cargo en una Audiencia o Juzgado en que hayan ejercido la Abogacía o el cargo de Procurador en:","o":["El año anterior a su nombramiento.","Los dos años anteriores a su nombramiento.","Los tres años anteriores a su nombramiento.","Ninguna es correcta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los dos años anteriores a su nombramiento.</mark></span><span class=\"ref-norma\">Art. 393.1 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. Los Jueces y Magistrados no podrán desempeñar su cargo... en una Audiencia o en la plaza concreta de la Sección del Tribunal de Instancia donde hayan ejercido la Abogacía o el cargo de Procurador o Procuradora en los dos años anteriores a su nombramiento (art. 393.1.3º LOPJ)."},{"i":"8-192","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. No podrán los Jueces y Magistrados desempeñar su cargo en una Audiencia o Juzgado en que hayan ejercido la abogacía o el cargo de procurador en los:","o":["Dos años anteriores a su nombramiento.","Cinco años anteriores a su nombramiento.","Unos años anteriores a su nombramiento.","Cuatro años anteriores a su nombramiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos años anteriores a su nombramiento</mark></span>Son dos años (como en la pregunta 8-124). Según el <span class=\"ref-norma\">art. 393.3 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"No podrán los jueces, juezas, magistrados y magistradas desempeñar su cargo: [...] 3. En una Audiencia o en la plaza concreta de la Sección del Tribunal de Instancia donde hayan ejercido la abogacía o el cargo de procurador o procuradora en los dos años anteriores a su nombramiento\"</span> (verificado con el texto del temario)."},{"i":"8-208","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. No podrán los Jueces y Magistrados desempeñar su cargo en las Salas de Tribunales y Juzgados donde ejerzan habitualmente, como Abogado o Procurador, su cónyuge o un pariente dentro del segundo grado de consanguinidad o afinidad. Esta incompatibilidad no será aplicable en las poblaciones donde las Secciones Civiles y de Instrucción de los Tribunales de Instancia que constituyan Secciones Únicas cuenten con:","o":["Diez o más plazas judiciales o donde existan Salas con tres o más Secciones.","Diez o más plazas judiciales o donde existan Salas con dos o más Secciones.","Cinco o más plazas judiciales o donde existan Salas con tres o más Secciones.","Cinco o más plazas judiciales o donde existan Salas con dos o más Secciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Diez o más plazas judiciales o donde existan Salas con tres o más Secciones.</mark></span><span class=\"ref-norma\">Art. 393.1 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 393.1.2ª de la LOPJ establece que la incompatibilidad no será aplicable si las Secciones Únicas cuentan con diez o más plazas judiciales o donde existan Salas con tres o más Secciones."},{"i":"8-ia-9053","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Prohibiciones de desempeño del cargo. No podrán los jueces, juezas, magistrados y magistradas desempeñar su cargo en los Tribunales donde ejerzan habitualmente, como abogado, abogada, procurador o procuradora, su cónyuge o un pariente dentro del segundo grado de consanguinidad o afinidad. Esta incompatibilidad no será aplicable:","o":["en las poblaciones de más de cien mil habitantes.","cuando el cónyuge ejerza en otro orden jurisdiccional.","en las poblaciones donde las Secciones Civiles y de Instrucción que constituyan Secciones Únicas cuenten con diez o más plazas judiciales o donde existan Salas con tres o más Secciones.","cuando el pariente no intervenga en el procedimiento concreto, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en las poblaciones donde las Secciones Civiles y de Instrucción que constituyan Secciones Únicas cuenten con diez o más plazas judiciales o donde existan Salas con tres o más Secciones</mark></span>El <span class=\"ref-norma\">art. 393.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Esta incompatibilidad no será aplicable en las poblaciones donde las Secciones Civiles y de Instrucción de los Tribunales de Instancia que constituyan Secciones Únicas cuenten con diez o más plazas judiciales o donde existan Salas con tres o más Secciones\"</span>. Diez o más plazas en las Secciones Únicas, o Salas con tres o más Secciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9055","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Prohibiciones de desempeño del cargo. No podrán los jueces desempeñar su cargo en una Audiencia o en la plaza concreta de la Sección del Tribunal de Instancia donde hayan ejercido la abogacía o el cargo de procurador o procuradora:","o":["en los dos años anteriores a su nombramiento.","en los cinco años anteriores a su nombramiento.","en el año anterior a su nombramiento.","durante más de diez años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en los dos años anteriores a su nombramiento</mark></span>El <span class=\"ref-norma\">art. 393.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"donde hayan ejercido la abogacía o el cargo de procurador o procuradora en los dos años anteriores a su nombramiento\"</span>. Dos años anteriores al nombramiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 61 bis EX ✱","q":[{"i":"8-126","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Al servicio del Tribunal Supremo existirá un Gabinete Técnico, que asistirá a la Presidencia. Este estará integrado por un Director y por miembros de la Carrera Judicial y otros juristas que ostentarán la denominación de:","o":["Letrados del Gabinete Técnico.","Juristas del Gabinete Técnico.","Miembros del Gabinete Técnico.","Magistrados del Gabinete Técnico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Letrados del Gabinete Técnico.</mark></span><span class=\"ref-norma\">Art. 61 bis · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. Los juristas al servicio del Gabinete Técnico del Tribunal Supremo ostentarán la denominación de Letrados del Gabinete Técnico (art. 61 bis.3 LOPJ)."},{"i":"8-147","p":"(LOPJ) El Gabinete Técnico del Tribunal Supremo:","o":["Está bajo la superior dirección del Presidente del Tribunal Supremo y lo dirige el Secretario de Gobierno.","Su composición y plantilla se determina por Real Decreto a propuesta del Pleno del CGPJ.","Su composición y plantilla las determina el Ministerio de Justicia, oída la Sala de Gobierno del Tribunal Supremo y previo informe del Consejo General del Poder Judicial.","Está compuesto por personal funcionario de los Cuerpos al servicio de la Administración de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Su composición y plantilla las determina el Ministerio de Justicia, oída la Sala de Gobierno del Tribunal Supremo y previo informe del Consejo General del Poder Judicial</mark></span>Según el <span class=\"ref-norma\">art. 61 bis de la LOPJ</span>: <span class=\"ref-concepto\">\"El Ministerio de Justicia, oída la Sala de Gobierno del Tribunal Supremo y previo informe del Consejo General del Poder Judicial e informe favorable del Ministerio de Hacienda y Administraciones Públicas, determinará la composición y plantilla del Gabinete Técnico\"</span> (verificado con el texto del temario oficial)."},{"i":"8-170","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Supremo. ¿Quién asistirá a la Presidencia y a sus diferentes Salas en los procesos de admisión de los asuntos de que conozcan y mediante la elaboración de estudios e informes que se le soliciten?","o":["Un Gabinete Técnico.","Una Sala formada por el Presidente del Tribunal Supremo, los Presidentes de Sala y el Magistrado más antiguo y el más moderno de cada una de ellas.","Una Sección, formada por el Presidente del Tribunal Supremo, el de la Sala de lo Contencioso-administrativo y cinco Magistrados de esta misma Sala, que serán los dos más antiguos y los tres más modernos.","Un Consejo Especial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un Gabinete Técnico.</mark></span><span class=\"ref-norma\">Art. 586 · De la Organización y Planta de Juzgados y Tribunales</span>. Esta pregunta es idéntica a la 13/20 y 14/20. El órgano encargado de asistir a la Presidencia y a las Salas del Tribunal Supremo en los procesos de admisión y mediante la elaboración de estudios e informes es el Gabinete Técnico (art. 586 de la L.O.P.J.)."},{"i":"8-ia-8322","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Gabinete Técnico. Al servicio del Tribunal Supremo existirá un Gabinete Técnico, que asistirá a la Presidencia y a sus diferentes Salas en los procesos de admisión de los asuntos de que conozcan y mediante:","o":["la redacción de las sentencias de casación.","la formación de los jueces y magistrados.","la dirección de las unidades de apoyo del Tribunal, sin perjuicio de lo dispuesto en otras leyes.","la elaboración de estudios e informes que se le soliciten."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la elaboración de estudios e informes que se le soliciten</mark></span>El <span class=\"ref-norma\">art. 61 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"que asistirá a la Presidencia y a sus diferentes Salas en los procesos de admisión de los asuntos de que conozcan y mediante la elaboración de estudios e informes que se le soliciten\"</span>. Asiste en la admisión de asuntos y elabora estudios e informes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8323","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Gabinete Técnico. El Gabinete Técnico del Tribunal Supremo estará integrado por un Director y por:","o":["Letrados de la Administración de Justicia y funcionarios del Cuerpo de Gestión Procesal, en los términos que establezca la ley orgánica.","Magistrados del Tribunal Supremo designados por el Pleno.","miembros de la Carrera judicial y otros juristas que ostentarán la denominación de Letrados del Gabinete Técnico.","Fiscales de Sala y miembros de la Carrera judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">miembros de la Carrera judicial y otros juristas que ostentarán la denominación de Letrados del Gabinete Técnico</mark></span>El <span class=\"ref-norma\">art. 61 bis.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Gabinete Técnico estará integrado por un Director y por miembros de la Carrera judicial y otros juristas que ostentarán la denominación de Letrados del Gabinete Técnico\"</span>. Director, miembros de la Carrera judicial y otros juristas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8324","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Gabinete Técnico. En el Gabinete Técnico del Tribunal Supremo existirán tantas áreas como órdenes jurisdiccionales. Dentro de cada área podrá existir una sección de Admisión y otra sección de:","o":["Documentación y Jurisprudencia.","Estudios e Informes.","Coordinación y Apoyo.","Asuntos Generales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Estudios e Informes</mark></span>El <span class=\"ref-norma\">art. 61 bis.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Dentro de cada área podrá existir una sección de Admisión y otra sección de Estudios e Informes\"</span>. Las secciones son Admisión y Estudios e Informes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8325","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Gabinete Técnico. En cada una de las áreas del Gabinete Técnico habrá uno o varios Letrados que asuman funciones de coordinación, designados por el Presidente del Tribunal Supremo y que deberán tener una antigüedad mínima de:","o":["diez años en el ejercicio de su respectiva profesión.","cinco años en el ejercicio de su respectiva profesión.","quince años en la Carrera Judicial.","veinte años de servicios en la Administración de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez años en el ejercicio de su respectiva profesión</mark></span>El <span class=\"ref-norma\">art. 61 bis.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"y deberán tener una antigüedad mínima de diez años en el ejercicio de su respectiva profesión\"</span>. La antigüedad mínima es de diez años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8326","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Gabinete Técnico. Excepcionalmente, por razones coyunturales y debidamente justificadas, a propuesta del Consejo General del Poder Judicial y oída la Sala de Gobierno del Tribunal Supremo, podrá el Ministerio de Justicia adscribir temporalmente, con el límite máximo de:","o":["dos años, un número adicional de Letrados al Gabinete Técnico.","seis meses, un número adicional de miembros al Gabinete Técnico.","tres años, un número adicional de miembros al servicio del Tribunal, salvo que la ley disponga otra cosa.","un año, un número adicional de miembros al servicio del Gabinete Técnico."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un año, un número adicional de miembros al servicio del Gabinete Técnico</mark></span>El <span class=\"ref-norma\">art. 61 bis.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrá el Ministerio de Justicia adscribir temporalmente, con el límite máximo de un año, un número adicional de miembros al servicio del Gabinete Técnico\"</span>. El límite máximo es de un año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9077","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Retribuciones. Son retribuciones básicas de los jueces y magistrados el sueldo y la antigüedad, y son retribuciones complementarias:","o":["el complemento de destino, el de productividad y el de residencia.","el complemento específico y el de dedicación exclusiva.","el complemento de destino, el complemento específico y el complemento de carrera profesional.","el complemento de destino y la gratificación por servicios extraordinarios, en los términos que establezca la ley orgánica."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el complemento de destino, el complemento específico y el complemento de carrera profesional</mark></span>El <span class=\"ref-norma\">art. 403.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Son retribuciones complementarias el complemento de destino, el complemento específico y el complemento de carrera profesional\"</span>. Destino, específico y carrera profesional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 381","q":[{"i":"8-137","p":"Ley Orgánica 1/1985, de 1 de julio, del Poder Judicial. De la inamovilidad de los Jueces y Magistrados. Quienes hubieren perdido la condición de Juez o Magistrado, podrán solicitar del Consejo General del Poder Judicial su rehabilitación. Si la rehabilitación se denegare, no podrá iniciarse nuevo procedimiento para obtenerla en los _____________ plazo que se computará a partir de la resolución denegatoria inicial del Consejo General del Poder Judicial.","o":["Tres años siguientes.","Cuatro años siguientes.","Dos años siguientes.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres años siguientes</mark></span>Son tres años, no dos. Según el <span class=\"ref-norma\">art. 381.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"Si la rehabilitación se denegare, no podrá iniciarse nuevo procedimiento para obtenerla en los tres años siguientes\"</span> (verificado con el texto del temario)."},{"i":"8-304","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia, que contará, entre otras, con las siguientes Secciones:","o":["Instrucción, Familia, Vigilancia Penitenciaria y de lo Social.","Instrucción, Menores, Violencia sobre la Mujer y de lo Mercantil, conforme al procedimiento que reglamentariamente se establezca.","Instrucción, Apelación, Vigilancia Penitenciaria y de lo Civil.","Instrucción, Menores, Vigilancia Penitenciaria y de lo Contencioso-Administrativo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Instrucción, Menores, Vigilancia Penitenciaria y de lo Contencioso-Administrativo</mark></span>El <span class=\"ref-norma\">art. 95 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"En la Villa de Madrid y con jurisdicción en todo el territorio nacional existirá un Tribunal Central de Instancia, que contará con las siguientes Secciones: a) Sección de Instrucción\"</span>"},{"i":"8-ia-8929","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Rehabilitación. Si la rehabilitación de un Juez o Magistrado se denegare, no podrá iniciarse nuevo procedimiento para obtenerla en los tres años siguientes, plazo que se computará:","o":["a partir de la resolución denegatoria inicial del Consejo General del Poder Judicial.","a partir de la notificación al interesado.","a partir de la firmeza de la resolución denegatoria, sin perjuicio de lo dispuesto en otras leyes.","a partir de la presentación de la solicitud."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a partir de la resolución denegatoria inicial del Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 381.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"no podrá iniciarse nuevo procedimiento para obtenerla en los tres años siguientes, plazo que se computará a partir de la resolución denegatoria inicial del Consejo General del Poder Judicial\"</span>. Tres años desde la resolución denegatoria inicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 96","q":[{"i":"8-146","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 96.1. Cuando en una circunscripción exista más de una plaza judicial de la misma Sección de un Tribunal de Instancia, ¿quién puede acordar que una o varias de las personas destinadas en ellas asuman con carácter exclusivo el conocimiento de determinadas clases de asuntos?","o":["El Gobierno, previo informe del Ministerio de Justicia.","La Sala de Gobierno del Tribunal Superior de Justicia, sin informe de nadie.","El Consejo General del Poder Judicial, previo informe de las Salas de Gobierno y de las Administraciones con competencias en materia de Justicia.","La Junta de Jueces y Juezas por mayoría."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial, previo informe de las Salas de Gobierno y de las Administraciones con competencias en materia de Justicia</mark></span>Según el <span class=\"ref-norma\">art. 96.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"El Consejo General del Poder Judicial podrá acordar, previo informe de las Salas de Gobierno y de las Administraciones con competencias en materia de Justicia, que en aquellas circunscripciones donde exista más de una plaza judicial de la misma Sección, una o varias de las personas destinadas en ellas asuman con carácter exclusivo el conocimiento de determinadas clases de asuntos\"</span> (verificado con el texto del temario)."},{"i":"8-161","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. Señale la INCORRECTA.","o":["La justicia emana del pueblo.","El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados en las leyes y en los tratados internacionales.","La justicia se administra por el Gobierno.","Los órganos de la jurisdicción militar, integrante del Poder Judicial del Estado, basan su organización y funcionamiento en el principio de unidad jurisdiccional y administran Justicia en el ámbito estrictamente castrense."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La justicia se administra por el Gobierno.</mark></span><span class=\"ref-norma\">Art. 117 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. La afirmación incorrecta es que &quot;La justicia se administra por el Gobierno&quot;. La justicia se administra en nombre del Rey por Jueces y Magistrados integrantes del Poder Judicial, y la potestad jurisdiccional corresponde exclusivamente a los Juzgados y Tribunales (art. 117 de la Constitución Española y art. 2 de la L.O.P.J.)."},{"i":"8-188","p":"Ley Orgánica 6/1985, del Poder Judicial, art. 96.2. ¿Quién podrá acordar que en aquellas provincias en que existan más de cinco plazas judiciales en las Secciones de lo Mercantil de los Tribunales de Instancia uno o varios de los jueces destinados en ellas asuman con carácter exclusivo el conocimiento de determinadas clases de asuntos?","o":["El Consejo General del Poder Judicial.","El Ministro de Justicia.","El Fiscal General del Estado.","El Consejo de Ministros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial</mark></span>Según el <span class=\"ref-norma\">art. 96.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"El Consejo General del Poder Judicial, oída la Sala de Gobierno del Tribunal Superior de Justicia y con informe favorable de las Administraciones con competencias en materia de Justicia en cada territorio, podrá acordar que en aquellas provincias en que existan más de cinco plazas judiciales en las Secciones de lo Mercantil de los Tribunales de Instancia existentes, uno o varios de los jueces [...] asuman con carácter exclusivo el conocimiento de determinadas clases de asuntos\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8463","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del TSJ. Las Salas de lo Contencioso-Administrativo de los Tribunales Superiores de Justicia conocerán, en única instancia, de los actos y disposiciones de los órganos de gobierno de las Asambleas legislativas de las comunidades autónomas y de las instituciones autonómicas análogas al Tribunal de Cuentas y al Defensor del Pueblo:","o":["en materia de personal, administración y gestión patrimonial.","en materia de contratación y responsabilidad patrimonial, conforme al procedimiento que establezcan las leyes procesales.","en materia de personal exclusivamente.","en materia de presupuestos y gasto público."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en materia de personal, administración y gestión patrimonial</mark></span>El <span class=\"ref-norma\">art. 74.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los actos y disposiciones de los órganos de gobierno de las Asambleas legislativas de las comunidades autónomas y de las instituciones autonómicas análogas al Tribunal de Cuentas y al Defensor del Pueblo, en materia de personal, administración y gestión patrimonial\"</span>. Personal, administración y gestión patrimonial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8907","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de plazas. El Consejo General del Poder Judicial podrá acordar, previo informe de las Salas de Gobierno y de las Administraciones con competencias en materia de Justicia, que en aquellas circunscripciones donde exista más de una plaza judicial de la misma Sección, una o varias de las personas destinadas en ellas asuman con carácter exclusivo:","o":["la presidencia de la Sección durante dos años.","la dirección de los servicios comunes procesales, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes.","el conocimiento de determinadas clases de asuntos o de las ejecuciones propias del orden jurisdiccional de que se trate.","la instrucción de los asuntos de mayor gravedad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el conocimiento de determinadas clases de asuntos o de las ejecuciones propias del orden jurisdiccional de que se trate</mark></span>El <span class=\"ref-norma\">art. 96.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"una o varias de las personas destinadas en ellas asuman con carácter exclusivo el conocimiento de determinadas clases de asuntos o de las ejecuciones propias del orden jurisdiccional de que se trate\"</span>. Asuntos o ejecuciones de determinada clase con carácter exclusivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8908","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de plazas. El Consejo General del Poder Judicial, oída la Sala de Gobierno del Tribunal Superior de Justicia y con informe favorable de las Administraciones competentes, podrá acordar que en aquellas provincias en que existan más de cinco plazas judiciales en las Secciones de lo Mercantil, uno o varios de los jueces destinados en ellos asuman con carácter exclusivo:","o":["la jurisdicción exclusiva en materia concursal de toda la comunidad, en los términos que establezca la ley orgánica.","el conocimiento de determinadas clases de asuntos de entre los que sean competencia de estas Secciones.","las funciones de Presidente de la Sección.","la ejecución de las sentencias de los demás jueces."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el conocimiento de determinadas clases de asuntos de entre los que sean competencia de estas Secciones</mark></span>El <span class=\"ref-norma\">art. 96.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"que en aquellas provincias en que existan más de cinco plazas judiciales en las Secciones de lo Mercantil de los Tribunales de Instancia existentes, uno o varios de los jueces, juezas, magistrados o magistradas destinados en ellos asuman con carácter exclusivo el conocimiento de determinadas clases de asuntos de entre los que sean competencia de estas Secciones\"</span>. Más de cinco plazas mercantiles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8910","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de plazas. No podrán ser objeto de especialización por la vía del acuerdo del Consejo General del Poder Judicial sobre plazas de un mismo orden jurisdiccional:","o":["las plazas judiciales de las Secciones de lo Penal, salvo que la ley disponga otra cosa.","las plazas judiciales de las Secciones Civiles.","las plazas judiciales de las Secciones de Familia.","las plazas judiciales de las Secciones de Instrucción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las plazas judiciales de las Secciones de Instrucción</mark></span>El <span class=\"ref-norma\">art. 96.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Tampoco podrán ser objeto de especialización por esta vía las plazas judiciales de las Secciones de Instrucción\"</span>. Las Secciones de Instrucción quedan excluidas de esta vía de especialización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 386 EX ✱","q":[{"i":"8-148","p":"(LOPJ) ¿Cuál de las siguientes afirmaciones sobre la jubilación por edad de Jueces y Magistrados es CORRECTA según la LOPJ?","o":["Es forzosa a los setenta años de edad, pudiendo solicitar la prolongación hasta los setenta y dos.","Es forzosa a los sesenta y cinco años de edad, pudiendo prorrogar hasta los setenta y dos.","Es forzosa a los sesenta y cinco años de edad.","Es forzosa a los setenta años de edad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Es forzosa a los setenta años de edad, pudiendo solicitar la prolongación hasta los setenta y dos</mark></span>Según el <span class=\"ref-norma\">art. 386 de la LOPJ</span>: <span class=\"ref-concepto\">\"La jubilación por edad de los Jueces y Magistrados es forzosa y se decretará con la antelación suficiente para que el cese en la función se produzca efectivamente al cumplir la edad de setenta años. No obstante, podrán solicitar con dos meses de antelación a dicho momento la prolongación de la permanencia en el servicio activo hasta que cumplan como máximo setenta y dos años de edad\"</span> (verificado con el texto del temario oficial)."},{"i":"8-285","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jubilación. Los jueces y magistrados también podrán jubilarse a partir de los sesenta y cinco años siempre que así lo hubieren manifestado al Consejo General del Poder Judicial con:","o":["Tres meses de antelación, sin perjuicio de lo que establezcan los tratados internacionales.","Un año de antelación.","Un mes de antelación.","Seis meses de antelación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Seis meses de antelación</mark></span>El <span class=\"ref-norma\">art. 386.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2. También podrán jubilarse a partir de los sesenta y cinco años siempre que así lo hubieren manifestado al Consejo y General del Poder Judicial con seis meses de antelación\"</span>"},{"i":"8-ia-8934","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jubilación por edad. Los Jueces y Magistrados podrán solicitar la prolongación de la permanencia en el servicio activo hasta que cumplan como máximo setenta y dos años de edad, con una antelación de:","o":["seis meses al momento de cumplir los setenta años.","un año al momento de cumplir los setenta años.","tres meses al momento de cumplir los setenta y un años.","dos meses al momento de cumplir los setenta años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos meses al momento de cumplir los setenta años</mark></span>El <span class=\"ref-norma\">art. 386.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrán solicitar con dos meses de antelación a dicho momento la prolongación de la permanencia en el servicio activo hasta que cumplan como máximo setenta y dos años de edad\"</span>. Dos meses de antelación; el límite es setenta y dos años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8936","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jubilación por edad. Los Jueces y Magistrados podrán jubilarse a partir de los sesenta y cinco años siempre que así lo hubieren manifestado al Consejo General del Poder Judicial con:","o":["tres meses de antelación, conforme al procedimiento que establezcan las leyes procesales.","seis meses de antelación.","un año de antelación.","dos meses de antelación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seis meses de antelación</mark></span>El <span class=\"ref-norma\">art. 386.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"También podrán jubilarse a partir de los sesenta y cinco años siempre que así lo hubieren manifestado al Consejo y General del Poder Judicial con seis meses de antelación\"</span>. Seis meses de antelación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 61 quáter ✱","q":[{"i":"8-154","p":"(LOPJ) El nombramiento del Presidente de un Tribunal Superior de Justicia corresponde a:","o":["El Rey, a propuesta del Consejo de Ministros y a informe del CGPJ.","El Rey, a propuesta del Pleno del Tribunal Constitucional.","El Rey, a propuesta del Consejo General del Poder Judicial.","El Presidente del Gobierno, a propuesta del Ministro de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Rey, a propuesta del Consejo General del Poder Judicial.</mark></span><span class=\"ref-norma\">Art. 166 · Del Consejo General del Poder Judicial</span>. El artículo 166 de la LOPJ establece que el Presidente del Tribunal Superior de Justicia será nombrado por el Rey, a propuesta del Consejo General del Poder Judicial."},{"i":"8-230","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial Señale la INCORRECTA sobre el Gabinete Técnico del Tribunal Supremo.","o":["Los Letrados que hayan de prestar servicio en el Gabinete Técnico serán seleccionados mediante concurso de méritos, estableciéndose en el anuncio de la convocatoria los criterios de selección.","El Director del Gabinete Técnico y los Letrados serán declarados en situación administrativa de excedencia en la Carrera o Cuerpo de procedencia.","Los Letrados podrán ser cesados por el Presidente del Tribunal Supremo por incumplimiento grave de los deberes de su función.","El Pleno del Consejo General del Poder Judicial nombrará el Director del Gabinete Técnico, a propuesta vinculante del Presidente del Tribunal Supremo, debiendo acreditar los requisitos legalmente exigidos para poder acceder a la categoría de Magistrado del Tribunal Supremo, teniendo dicha consideración, a efectos representativos, mientras desempeñe el cargo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Director del Gabinete Técnico y los Letrados serán declarados en situación administrativa de excedencia en la Carrera o Cuerpo de procedencia</mark></span>La opción B dice «excedencia»: es la falsa. El Pleno del CGPJ SÍ nombra al Director (art. 61 quáter.1). Según el <span class=\"ref-norma\">art. 61 quinquies.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"El Director del Gabinete Técnico y los Letrados serán declarados en situación administrativa de servicios especiales en la Carrera o Cuerpo de procedencia\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8328","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento en el Gabinete Técnico. El Pleno del Consejo General del Poder Judicial nombrará al Director del Gabinete Técnico:","o":["a propuesta no vinculante del Presidente del Tribunal Supremo.","a propuesta vinculante del Presidente del Tribunal Supremo.","a propuesta de la Sala de Gobierno del Tribunal Supremo.","a propuesta de la Comisión Permanente del Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a propuesta vinculante del Presidente del Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 61 quáter.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"nombrará al Director del Gabinete Técnico, a propuesta vinculante del Presidente del Tribunal Supremo\"</span>. La propuesta del Presidente del TS es vinculante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8329","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento en el Gabinete Técnico. Los Letrados que hayan de prestar servicio en el Gabinete Técnico serán seleccionados:","o":["mediante concurso de méritos, estableciéndose en el anuncio de la convocatoria los criterios de selección.","mediante oposición libre convocada por el Ministerio de Justicia.","por designación directa del Presidente del Tribunal Supremo.","mediante concurso-oposición entre miembros de la Carrera Judicial, sin perjuicio de lo dispuesto en otras leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">mediante concurso de méritos, estableciéndose en el anuncio de la convocatoria los criterios de selección</mark></span>El <span class=\"ref-norma\">art. 61 quáter.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Letrados que hayan de prestar servicio en el Gabinete Técnico serán seleccionados mediante concurso de méritos, estableciéndose en el anuncio de la convocatoria los criterios de selección\"</span>. Concurso de méritos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 395 ✱","q":[{"i":"8-156","p":"(LOPJ) Indique cuál de las siguientes no es causa de abstención o recusación de Jueces y Magistrados, conforme a la LOPJ:","o":["Amistad íntima o enemistad manifiesta con cualquiera de las partes.","Haber ocupado cargo público o administrativo que haya podido permitir tener un conocimiento del objeto litigioso.","Haber tenido participación en la instrucción de la causa penal.","Tener o haber tenido pleito pendiente con alguna de las partes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tener o haber tenido pleito pendiente con alguna de las partes.</mark></span><span class=\"ref-norma\">Art. 219.12 · De los Jueces y Magistrados: Carrera, Estatuto y Régimen Disciplinario</span>. El artículo 219.12ª de la LOPJ solo contempla como causa el &quot;Tener pleito pendiente&quot; (actualmente pendiente), no la circunstancia de &quot;haber tenido&quot; uno en el pasado, que sí está incluida en la redacción de la opción (d)."},{"i":"8-ia-8906","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. La Sección de lo Contencioso-Administrativo del Tribunal Central de Instancia conocerá igualmente del procedimiento de ilegalización previsto en la Ley Orgánica de:","o":["Libertad Religiosa.","Derecho de Asociación.","Protección de Datos Personales.","Partidos Políticos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Partidos Políticos</mark></span>El <span class=\"ref-norma\">art. 95.e de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Igualmente conocerá la Sección de lo Contencioso-Administrativo del procedimiento previsto en el artículo 12 bis de la Ley Orgánica 6/2002, de 27 de junio, de Partidos Políticos\"</span>. Se trata de la Ley Orgánica de Partidos Políticos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9058","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Prohibiciones. No podrán los Jueces o Magistrados pertenecer a partidos políticos o sindicatos o tener empleo al servicio de los mismos, y les estará prohibido dirigir a los poderes, autoridades y funcionarios públicos o Corporaciones oficiales felicitaciones o censuras por sus actos, ni concurrir, en su calidad de miembros del Poder Judicial, a cualesquiera actos o reuniones públicos que no tengan carácter judicial, excepto aquéllas:","o":["que tengan por objeto cumplimentar al Presidente del Gobierno o a las Cortes Generales, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","que tengan por objeto cumplimentar al Rey o para las que hubieran sido convocados o autorizados a asistir por el Consejo General del Poder Judicial.","organizadas por las asociaciones judiciales.","a las que asistan por invitación personal de una autoridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">que tengan por objeto cumplimentar al Rey o para las que hubieran sido convocados o autorizados a asistir por el Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 395 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"excepto aquéllas que tengan por objeto cumplimentar al Rey o para las que hubieran sido convocados o autorizados a asistir por el Consejo General del Poder Judicial\"</span>. Cumplimentar al Rey o convocatoria o autorización del CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9059","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Prohibiciones. A los Jueces y Magistrados les estará prohibido tomar en las elecciones legislativas o locales:","o":["más parte que la de emitir su voto personal.","cualquier parte, incluido el voto.","parte como interventores o apoderados, sin perjuicio de lo dispuesto en otras leyes.","parte salvo como miembros de mesa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">más parte que la de emitir su voto personal</mark></span>El <span class=\"ref-norma\">art. 395.2.º de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Tomar en las elecciones legislativas o locales más parte que la de emitir su voto personal\"</span>. Solo pueden emitir su voto personal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9148","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Fines de las asociaciones. Las asociaciones profesionales de jueces y magistrados no podrán llevar a cabo actividades políticas ni tener vinculaciones con:","o":["partidos políticos o sindicatos.","colegios profesionales.","asociaciones de fiscales.","organizaciones internacionales de jueces."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">partidos políticos o sindicatos</mark></span>El <span class=\"ref-norma\">art. 401 (regla 2.ª) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"No podrán llevar a cabo actividades políticas ni tener vinculaciones con partidos políticos o sindicatos.\"</span> Partidos políticos o sindicatos."}]},{"a":"Artículo 19 ✱","q":[{"i":"8-158","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los ciudadanos de nacionalidad española podrán ejercer la acción __________ en los casos y formas establecidos en la ley.","o":["Penal.","Civil.","Popular.","Especial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Popular.</mark></span>La acción popular es el derecho que tienen los ciudadanos a ejercer la acción penal o procesal en defensa del interés público, tal como lo establece la L.O.P.J. en ciertos casos."},{"i":"8-244","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Participación en la Administración de Justicia. Los ciudadanos de nacionalidad española podrán ejercer la acción popular:","o":["En los casos y formas establecidos en la ley.","En todos los procesos penales, sin necesidad de que lo prevea una ley expresa.","En los casos y formas que establezca el Consejo General del Poder Judicial mediante acuerdo.","Únicamente en los procesos penales por delitos contra la Corona y forma de Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En los casos y formas establecidos en la ley</mark></span>El <span class=\"ref-norma\">art. 19.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. Los ciudadanos de nacionalidad española podrán ejercer la acción popular, en los casos y formas establecidos en la ley.\"</span>"},{"i":"8-246","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Participación en la Administración de Justicia. Tiene el carácter de Tribunal consuetudinario y tradicional:","o":["El Consejo de Hombres Buenos de la Vega Valenciana.","El Tribunal de las Aguas de Murcia.","El Tribunal de las Aguas de la Vega Valenciana.","El Tribunal de Aguas de la Huerta de Orihuela, junto con el Consejo de Hombres Buenos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Tribunal de las Aguas de la Vega Valenciana</mark></span>El <span class=\"ref-norma\">art. 19.3 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"3. Tiene el carácter de Tribunal consuetudinario y tradicional el Tribunal de las Aguas de la Vega Valenciana.\"</span>"},{"i":"8-247","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Participación en la Administración de Justicia. Se reconoce el carácter de Tribunal consuetudinario y tradicional al denominado:","o":["Tribunal de las Aguas de Murcia.","Consejo de Hombres Buenos de Murcia.","Consejo de Hombres Buenos de Valencia.","Tribunal de las Aguas de la Huerta de Murcia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Consejo de Hombres Buenos de Murcia</mark></span>El <span class=\"ref-norma\">art. 19.4 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"4. Se reconoce el carácter de Tribunal consuetudinario y tradicional al denominado Consejo de Hombres Buenos de Murcia.\"</span>"},{"i":"8-ia-8046","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Participación en la Administración de Justicia. Los ciudadanos de nacionalidad española podrán ejercer la acción popular:","o":["en cualquier proceso penal sin limitación alguna.","ante los órganos de la jurisdicción penal y contencioso-administrativa.","siempre que cuenten con la autorización del Ministerio Fiscal.","en los casos y formas establecidos en la ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en los casos y formas establecidos en la ley</mark></span>El <span class=\"ref-norma\">art. 19.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los ciudadanos de nacionalidad española podrán ejercer la acción popular, en los casos y formas establecidos en la ley\"</span>. La acción popular se ejerce en los casos y formas de la ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8047","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Participación en la Administración de Justicia. Los ciudadanos podrán participar en la Administración de Justicia mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la Ley determine; en los Tribunales consuetudinarios y tradicionales y:","o":["en los demás casos previstos en la Constitución.","en los procesos civiles que determine el Consejo General del Poder Judicial.","en los demás casos previstos en esta Ley.","en los juzgados de paz de los municipios sin Tribunal de Instancia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en los demás casos previstos en esta Ley</mark></span>El <span class=\"ref-norma\">art. 19.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"mediante la institución del Jurado, en la forma y con respecto a aquellos procesos penales que la Ley determine; en los Tribunales consuetudinarios y tradicionales y en los demás casos previstos en esta Ley\"</span>. Jurado, tribunales consuetudinarios y demás casos de esta Ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8048","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales consuetudinarios y tradicionales. Tiene el carácter de Tribunal consuetudinario y tradicional:","o":["el Tribunal de las Aguas de la Huerta de Murcia.","el Tribunal de las Aguas de la Vega Valenciana.","el Consejo de Hombres Buenos de Valencia.","el Juzgado Privativo de Aguas de la Vega de Granada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Tribunal de las Aguas de la Vega Valenciana</mark></span>El <span class=\"ref-norma\">art. 19.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Tiene el carácter de Tribunal consuetudinario y tradicional el Tribunal de las Aguas de la Vega Valenciana\"</span>. Murcia tiene el Consejo de Hombres Buenos; Orihuela, el Juzgado Privativo de Aguas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8049","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales consuetudinarios y tradicionales. Se reconoce el carácter de Tribunal consuetudinario y tradicional al denominado:","o":["Consejo de Hombres Buenos de Murcia.","Consejo de Hombres Buenos de Valencia.","Tribunal de las Aguas de Murcia.","Juzgado de Hombres Buenos de Orihuela."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Consejo de Hombres Buenos de Murcia</mark></span>El <span class=\"ref-norma\">art. 19.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Se reconoce el carácter de Tribunal consuetudinario y tradicional al denominado Consejo de Hombres Buenos de Murcia\"</span>. Es el Consejo de Hombres Buenos de Murcia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 58","q":[{"i":"8-159","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La Sala de lo Contencioso-Administrativo del Tribunal Supremo conocerá en primera instancia de los recursos contencioso-administrativos contra actos y disposiciones de los órganos competentes de: Señale la INCORRECTA.","o":["El Congreso de los Diputados.","El Tribunal de Cuentas.","El Defensor del Pueblo.","El Banco de España."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Banco de España</mark></span>Según el <span class=\"ref-norma\">art. 58 de la LOPJ</span>: <span class=\"ref-concepto\">\"Primero. En única instancia, de los recursos contencioso-administrativos contra actos y disposiciones del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y del Consejo General del Poder Judicial y contra los actos y disposiciones de los órganos competentes del Congreso de los Diputados y del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo\"</span> (verificado con el texto del temario oficial)."},{"i":"8-196","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá en única instancia, de los recursos contencioso-administrativos contra actos y disposiciones de los órganos competentes del Congreso de los Diputados?","o":["La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Superior de Justicia.","La Sala de lo Contencioso-administrativo del Tribunal Supremo.","La Sección de lo Contencioso-administrativo del Tribunal de Instancia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 58.1.a) · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 58.1.a) de la LOPJ, en relación con la Ley Reguladora de la Jurisdicción Contencioso-Administrativa (LJCA), atribuye a la Sala Tercera del Tribunal Supremo el conocimiento en única instancia de los recursos contra actos de los órganos competentes del Congreso y del Senado."},{"i":"8-199","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La Sala de lo Contencioso-Administrativo del Tribunal Supremo conocerá de la solicitud de autorización para la declaración prevista en la disposición adicional quinta de la Ley Orgánica de Protección de Datos Personales y Garantía de los Derechos Digitales, cuando tal solicitud sea formulada por:","o":["El Gobierno.","El Consejo General del Poder Judicial.","El Defensor del Pueblo.","El órgano superior de la Administración General del Estado que tenga la competencia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo General del Poder Judicial</mark></span>Si la pide la AEPD: Sala de lo Contencioso-Administrativo de la Audiencia Nacional (art. 66.f); si la autoridad autonómica: Sala del TSJ (art. 74.1.k). Según el <span class=\"ref-norma\">art. 58.Tercero de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"De la solicitud de autorización para la declaración prevista en la disposición adicional quinta de la Ley Orgánica 3/2018 [...] cuando tal solicitud sea formulada por el Consejo General del Poder Judicial\"</span> (verificado con el texto del temario)."},{"i":"8-214","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá en única instancia, de los recursos contencioso-administrativos contra actos y disposiciones del Consejo General del Poder Judicial?","o":["La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Superior de Justicia.","La Sala de lo Contencioso-administrativo del Tribunal Supremo.","El Tribunal Constitucional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 58.1.a) · Del Consejo General del Poder Judicial</span>. El artículo 58.1.a) de la LOPJ atribuye a la Sala de lo Contencioso-administrativo del Tribunal Supremo el conocimiento en única instancia de los recursos contra actos y disposiciones del Consejo General del Poder Judicial (CGPJ)."},{"i":"8-226","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá en única instancia, de los recursos contencioso-administrativos contra actos y disposiciones de las Comisiones Delegadas del Gobierno?","o":["La Sala de lo Contencioso-administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-administrativo del Tribunal Superior de Justicia.","La Sala de lo Contencioso-administrativo del Tribunal Supremo.","El Juzgado Central de lo Contencioso administrativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-administrativo del Tribunal Supremo.</mark></span><span class=\"ref-norma\">Art. 58 · De la Organización y Planta de Juzgados y Tribunales</span>. La Sala de lo Contencioso-administrativo del Tribunal Supremo es competente para conocer en única instancia de los recursos contra actos y disposiciones de las Comisiones Delegadas del Gobierno (Art. 58 LOPJ)."},{"i":"8-ia-8312","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del Tribunal Supremo. La Sala de lo Contencioso-administrativo del Tribunal Supremo conocerá en única instancia de los recursos contencioso-administrativos contra actos y disposiciones del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y:","o":["del Consejo de Estado y de los Ministros en el ejercicio de la potestad reglamentaria, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","del Consejo General del Poder Judicial y de los órganos competentes del Congreso de los Diputados y del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo.","del Consejo General del Poder Judicial y de los Secretarios de Estado.","de los Consejos de Gobierno de las Comunidades Autónomas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del Consejo General del Poder Judicial y de los órganos competentes del Congreso de los Diputados y del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo</mark></span>El <span class=\"ref-norma\">art. 58 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y del Consejo General del Poder Judicial y contra los actos y disposiciones de los órganos competentes del Congreso de los Diputados y del Senado, del Tribunal Constitucional, del Tribunal de Cuentas y del Defensor del Pueblo\"</span>. La lista incluye al CGPJ y a los órganos de Congreso, Senado, TC, Tribunal de Cuentas y Defensor del Pueblo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8313","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Contencioso-Administrativo del Tribunal Supremo. Corresponde a la Sala de lo Contencioso-administrativo del Tribunal Supremo conocer de la solicitud de autorización para la declaración prevista en la disposición adicional quinta de la Ley Orgánica de Protección de Datos Personales y garantía de los derechos digitales, cuando tal solicitud sea formulada por:","o":["el Consejo General del Poder Judicial.","la Agencia Española de Protección de Datos.","el Ministerio Fiscal.","el Defensor del Pueblo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 58 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando tal solicitud sea formulada por el Consejo General del Poder Judicial\"</span>. Si la solicita la Agencia Española de Protección de Datos, es la Sala de lo Contencioso-Administrativo de la Audiencia Nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 38 EX ✱","q":[{"i":"8-160","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá de la solicitud del Gobierno para la convalidación o revocación de los acuerdos de asunción o intervención de la gestión directa del servicio o los de intervención o explotación de redes?","o":["El Juzgado Central de lo Contencioso-administrativo.","La Sala de lo Contencioso-Administrativo de la Audiencia Nacional.","La Sala de lo Contencioso-Administrativo del Tribunal Supremo.","La Sala de lo Contencioso-Administrativo de la Audiencia Provincial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sala de lo Contencioso-Administrativo del Tribunal Supremo.</mark></span>La Sala de lo Contencioso-Administrativo del Tribunal Supremo es competente para conocer de las cuestiones relativas a la intervención y explotación de redes o asunción de gestión directa de servicios, a instancia del Gobierno, según la L.O.P.J."},{"i":"8-234","p":"- Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial De las Audiencias Provinciales. Las Audiencias Provinciales se compondrán de un Presidente y:","o":["Dos o más magistrados.","Tres o más magistrados.","Cuatro o más magistrados.","Diez o más magistrados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos o más magistrados.</mark></span><span class=\"ref-norma\">Art. 81.1 · De la Organización y Planta de Juzgados y Tribunales</span>. Las Audiencias Provinciales se compondrán de un Presidente y dos o más Magistrados (Art. 81.1 LOPJ)."},{"i":"8-ia-8188","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Conflictos de jurisdicción con la Administración. Los conflictos de jurisdicción entre los Juzgados o Tribunales y la Administración serán resueltos por un órgano colegiado constituido por el Presidente del Tribunal Supremo, que lo presidirá, y por cinco vocales, de los que:","o":["tres serán Magistrados de la Sala de lo Contencioso-Administrativo del Tribunal Supremo y los otros dos serán Consejeros Permanentes de Estado, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","dos serán Magistrados de la Sala de lo Penal y tres serán miembros del Consejo General del Poder Judicial.","cuatro serán Consejeros Permanentes de Estado y uno será Magistrado del Tribunal Constitucional.","dos serán Magistrados de la Sala de lo Contencioso-Administrativo del Tribunal Supremo, designados por el Pleno del Consejo General del Poder Judicial, y los otros tres serán Consejeros Permanentes de Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos serán Magistrados de la Sala de lo Contencioso-Administrativo del Tribunal Supremo, designados por el Pleno del Consejo General del Poder Judicial, y los otros tres serán Consejeros Permanentes de Estado</mark></span>El <span class=\"ref-norma\">art. 38 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"de los que dos serán Magistrados de la Sala de lo Contencioso-Administrativo del Tribunal Supremo, designados por el Pleno del Consejo General del Poder Judicial, y los otros tres serán Consejeros Permanentes de Estado\"</span>. Composición: 2 magistrados de la Sala Tercera y 3 Consejeros Permanentes de Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8189","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Conflictos de jurisdicción con la Administración. En el órgano colegiado que resuelve los conflictos de jurisdicción entre los Juzgados o Tribunales y la Administración, actuará como Secretario:","o":["el Letrado Mayor del Consejo de Estado.","el Secretario General del Consejo General del Poder Judicial.","el de Gobierno del Tribunal Supremo.","el Magistrado más moderno de la Sala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el de Gobierno del Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 38 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"actuando como Secretario el de Gobierno del Tribunal Supremo\"</span>. Actúa el Secretario de Gobierno del Tribunal Supremo; el Presidente tiene voto de calidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8492","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Especialización de las Audiencias Provinciales. El acuerdo de especialización de secciones de la Audiencia Provincial en materia mercantil deberá adoptarse necesariamente cuando el número de plazas de magistrados y magistradas de las Secciones de lo Mercantil existentes en la provincia fuera superior a:","o":["tres, en los términos que establezca la ley orgánica.","ocho.","diez.","cinco."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cinco</mark></span>El <span class=\"ref-norma\">art. 82 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El acuerdo de especialización deberá adoptarse necesariamente cuando el número de plazas de magistrados y magistradas de las Secciones de lo Mercantil existentes en la provincia fuera superior a cinco\"</span>. Más de cinco plazas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 2 R1","q":[{"i":"8-164","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. El ejercicio de la potestad jurisdiccional corresponde exclusivamente:","o":["Al Gobierno.","Al Rey.","A los Juzgados y Tribunales.","A las Fuerzas y Cuerpos de Seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los Juzgados y Tribunales.</mark></span><span class=\"ref-norma\">Art. 117 · Poder Judicial</span>. El ejercicio de la potestad jurisdiccional (juzgar y hacer ejecutar lo juzgado) corresponde exclusivamente a los Juzgados y Tribunales (art. 117 de la Constitución Española y art. 2 de la L.O.P.J.)."},{"i":"8-ia-8003","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ejercicio de la potestad jurisdiccional. Los jueces, las juezas y los Tribunales no ejercerán más funciones que las de juzgar y hacer ejecutar lo juzgado y:","o":["las que expresamente les atribuya el Consejo General del Poder Judicial en garantía del interés público.","las demás que les sean atribuidas por cualquier norma con rango de ley o reglamento.","las demás que expresamente les sean atribuidas por ley en garantía de cualquier derecho.","las de gobierno interno de sus respectivos órganos en los términos del reglamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las demás que expresamente les sean atribuidas por ley en garantía de cualquier derecho</mark></span>El <span class=\"ref-norma\">art. 2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"y las demás que expresamente les sean atribuidas por ley en garantía de cualquier derecho\"</span>. Las funciones adicionales han de estar «expresamente» atribuidas «por ley» y en garantía de cualquier derecho. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 11","q":[{"i":"8-167","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los Juzgados y Tribunales, de conformidad con el principio de ___________ deberán resolver siempre sobre las pretensiones que se les formulen, y solo podrán desestimarlas por motivos formales cuando el defecto fuese insubsanable o no se subsanare por el procedimiento establecido en las leyes.","o":["Tutela efectiva.","Responsabilidad.","Legalidad.","Atribución."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tutela efectiva.</mark></span><span class=\"ref-norma\">Art. 24 · Poder Judicial</span>. El principio que obliga a Jueces y Tribunales a resolver sobre las pretensiones, limitando la desestimación por motivos formales a casos insubsanables, es el de la Tutela Judicial Efectiva (art. 24 de la Constitución Española y art. 11 de la L.O.P.J.)."},{"i":"8-190","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Señale la incorrecta sobre la obligación de resolver de los Jueces y Tribunales.","o":["Los Jueces y Tribunales deben resolver en todo caso los asuntos de que conozcan.","Los Jueces y Tribunales se atendrán al sistema de fuentes establecido.","Los Jueces y Tribunales, de conformidad con el principio de efectividad, deberán resolver siempre sobre las pretensiones que se les formulen.","Los Jueces y Tribunales sólo podrán desestimar por motivos formales cuando el defecto fuese insubsanable o no se subsanase por el procedimiento establecido en las leyes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los Jueces y Tribunales, de conformidad con el principio de efectividad, deberán resolver siempre sobre las pretensiones que se les formulen</mark></span>El principio es el de tutela efectiva, no el «de efectividad». Según el <span class=\"ref-norma\">art. 11 de la LOPJ</span>: <span class=\"ref-concepto\">\"Los jueces y juezas, así como los Tribunales, de conformidad con el principio de tutela efectiva consagrado en el artículo 24 de la Constitución, deberán resolver siempre sobre las pretensiones que se les formulen, y solo podrán desestimarlas por motivos formales cuando el defecto fuese insubsanable o no se subsanare por el procedimiento establecido en las leyes\"</span> (verificado con el texto del temario oficial)."},{"i":"8-ia-8031","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Buena fe procesal. En todo tipo de procedimiento se respetarán las reglas de la buena fe. No surtirán efecto las pruebas:","o":["obtenidas sin autorización judicial previa en la fase de instrucción.","obtenidas por la policía judicial sin conocimiento del Ministerio Fiscal.","obtenidas, directa o indirectamente, violentando los derechos o libertades fundamentales.","obtenidas directamente violentando los derechos fundamentales, pero sí las derivadas de ellas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">obtenidas, directa o indirectamente, violentando los derechos o libertades fundamentales</mark></span>El <span class=\"ref-norma\">art. 11.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"No surtirán efecto las pruebas obtenidas, directa o indirectamente, violentando los derechos o libertades fundamentales\"</span>. La prueba ilícita lo es tanto directa como indirectamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8032","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Abuso de derecho. Los jueces y juezas, así como los Tribunales rechazarán fundadamente las peticiones, incidentes y excepciones que se formulen con:","o":["abuso de derecho o mala fe procesal declarada.","manifiesto abuso de derecho o entrañen fraude de ley o procesal.","evidente fraude de ley o falta de legitimación.","manifiesto abuso de derecho, sin necesidad de motivación, sin perjuicio de lo dispuesto en otras leyes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">manifiesto abuso de derecho o entrañen fraude de ley o procesal</mark></span>El <span class=\"ref-norma\">art. 11.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"rechazarán fundadamente las peticiones, incidentes y excepciones que se formulen con manifiesto abuso de derecho o entrañen fraude de ley o procesal\"</span>. El rechazo ha de ser fundado y por manifiesto abuso de derecho o fraude de ley o procesal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8033","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Obligación de resolver. Los jueces y juezas, así como los Tribunales, de conformidad con el principio de tutela efectiva consagrado en el artículo 24 de la Constitución, deberán resolver siempre sobre las pretensiones que se les formulen, y solo podrán desestimarlas por motivos formales cuando:","o":["el defecto fuese insubsanable o no se subsanare por el procedimiento establecido en las leyes.","el defecto fuese insubsanable, sin posibilidad de concesión de plazo, en los términos que establezca la ley orgánica.","el defecto no se subsanare en el plazo de cinco días.","el defecto afecte a la competencia del órgano judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el defecto fuese insubsanable o no se subsanare por el procedimiento establecido en las leyes</mark></span>El <span class=\"ref-norma\">art. 11.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"solo podrán desestimarlas por motivos formales cuando el defecto fuese insubsanable o no se subsanare por el procedimiento establecido en las leyes\"</span>. Solo si el defecto es insubsanable o no se subsana por el procedimiento legal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 bis R2","q":[{"i":"8-173","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Del poder judicial y del ejercicio de la potestad jurisdiccional. Los Jueces y Tribunales aplicarán el Derecho de la Unión Europea de conformidad con la jurisprudencia:","o":["Del Tribunal de Justicia de la Unión Europea.","De la Fiscalía de la Unión Europea.","Del Tribunal Europeo de los Derechos Humanos.","De la Corte Penal Internacional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Del Tribunal de Justicia de la Unión Europea.</mark></span><span class=\"ref-norma\">Art. 4 bis · Poder Judicial</span>. Los Jueces y Tribunales aplicarán el Derecho de la Unión Europea de conformidad con la jurisprudencia del Tribunal de Justicia de la Unión Europea (TJUE), que es el intérprete supremo del Derecho de la UE (art. 4 bis de la L.O.P.J.)."},{"i":"8-ia-8007","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Derecho de la Unión Europea. Cuando los Tribunales decidan plantear una cuestión prejudicial europea lo harán de conformidad con la jurisprudencia del Tribunal de Justicia de la Unión Europea y, en todo caso:","o":["mediante providencia, previa audiencia del Ministerio Fiscal.","mediante sentencia, previa audiencia de las partes y del Ministerio Fiscal.","mediante auto, previa audiencia de las partes.","mediante auto, una vez firme la resolución del proceso principal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">mediante auto, previa audiencia de las partes</mark></span>El <span class=\"ref-norma\">art. 4 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"y, en todo caso, mediante auto, previa audiencia de las partes\"</span>. Se plantea mediante auto y previa audiencia de las partes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 ✱","q":[{"i":"8-174","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Los Juzgados y Tribunales protegerán los derechos e intereses legítimos, tanto individuales como colectivos, sin que en ningún caso pueda producirse indefensión. Para la defensa de estos últimos se reconocerá la legitimación de las ___________ que resulten afectados o que estén legalmente habilitados para su defensa y promoción. Señale la correcta.","o":["Corporaciones, asociaciones, organizaciones sindicales y grupos.","Instituciones públicas o privadas.","Ayuntamientos y Comunidades Autónomas.","Colegios profesionales únicamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Corporaciones, asociaciones, organizaciones sindicales y grupos</mark></span>La pregunta pedía la «incorrecta» pero la opción marcada es la literal: se corrige el enunciado. Según el <span class=\"ref-norma\">art. 7 de la LOPJ</span>: <span class=\"ref-concepto\">\"Para la defensa de estos últimos se reconocerá la legitimación de las corporaciones, asociaciones, organizaciones sindicales y grupos que resulten afectados o que estén legalmente habilitados para su defensa y promoción\"</span> (verificado con el texto del temario oficial)."},{"i":"8-241","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Derechos fundamentales. En especial, los derechos enunciados en el artículo 53.2 de la Constitución se reconocerán, en todo caso, de conformidad con su contenido constitucionalmente declarado, sin que las resoluciones judiciales puedan:","o":["Interpretarlo conforme a la jurisprudencia del Tribunal Supremo ni modificarlo mediante recurso de casación.","Aplicarlo de forma directa ni suspender su ejercicio mediante medidas cautelares provisionales.","Ampliar su alcance más allá de lo previsto por el legislador orgánico en cada caso concreto.","Restringir, menoscabar o inaplicar dicho contenido."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Restringir, menoscabar o inaplicar dicho contenido</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2. En especial, los derechos enunciados en el artículo 53.2 de la Constitución se reconocerán, en todo caso, de conformidad con su contenido constitucionalmente declarado, sin que las resoluciones judiciales puedan restringir, menoscabar o inaplicar dicho contenido.\"</span>"},{"i":"8-ia-8014","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Derechos y libertades. Los derechos y libertades reconocidos en el Capítulo Segundo del Título I de la Constitución vinculan, en su integridad, a todos los Jueces y Tribunales y están garantizados:","o":["bajo la protección del Tribunal Constitucional en exclusiva.","bajo la garantía del Ministerio Fiscal y del Defensor del Pueblo.","en los términos que determinen las leyes de desarrollo.","bajo la tutela efectiva de los mismos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">bajo la tutela efectiva de los mismos</mark></span>El <span class=\"ref-norma\">art. 7.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"vinculan, en su integridad, a todos los Jueces y Tribunales y están garantizados bajo la tutela efectiva de los mismos\"</span>. La garantía es la tutela efectiva de los Jueces y Tribunales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8015","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Derechos y libertades. En especial, los derechos enunciados en el artículo 53.2 de la Constitución se reconocerán, en todo caso, de conformidad con su contenido constitucionalmente declarado, sin que las resoluciones judiciales puedan:","o":["limitar, suspender o modular dicho contenido.","interpretar, desarrollar o completar dicho contenido.","restringir, menoscabar o inaplicar dicho contenido.","restringir o menoscabar dicho contenido salvo autorización del Tribunal Constitucional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">restringir, menoscabar o inaplicar dicho contenido</mark></span>El <span class=\"ref-norma\">art. 7.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"sin que las resoluciones judiciales puedan restringir, menoscabar o inaplicar dicho contenido\"</span>. Los tres verbos legales son restringir, menoscabar o inaplicar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8016","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Derechos e intereses legítimos. Para la defensa de los derechos e intereses legítimos colectivos se reconocerá la legitimación de las corporaciones, asociaciones, organizaciones sindicales y grupos que:","o":["resulten afectados y estén inscritos en el registro correspondiente.","resulten afectados o que estén legalmente habilitados para su defensa y promoción.","estén legalmente habilitados por el Ministerio Fiscal para su defensa.","resulten afectados, previa autorización del juez o tribunal competente, salvo que la ley disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">resulten afectados o que estén legalmente habilitados para su defensa y promoción</mark></span>El <span class=\"ref-norma\">art. 7.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se reconocerá la legitimación de las corporaciones, asociaciones, organizaciones sindicales y grupos que resulten afectados o que estén legalmente habilitados para su defensa y promoción\"</span>. El requisito es alternativo: afectados «o» legalmente habilitados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 384","q":[{"i":"8-183","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. En caso de suspensión de Jueces y Magistrados cuando por la comisión de cualquier otro delito doloso se hubiere dictado contra ellos auto de prisión, de libertad bajo fianza o de procesamiento, el Juez o Tribunal que conociera de la causa lo comunicará:","o":["Al Consejo General del Poder Judicial.","Al Consejo de Estado.","Al Ministro de Justicia.","Al Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Consejo General del Poder Judicial</mark></span>Según el <span class=\"ref-norma\">art. 384.1 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"En los supuestos de los dos primeros apartados del artículo anterior, el Juez o Tribunal que conociera de la causa lo comunicará al Consejo General del Poder Judicial, quien hará efectiva la suspensión, previa audiencia del Ministerio Fiscal\"</span> (verificado con el texto del temario)."},{"i":"8-219","p":"Ley Orgánica 6/1985 del Poder Judicial. En caso de suspensión de Jueces y Magistrados en caso de sentencia firme condenatoria en que se imponga como pena principal o accesoria la de suspensión, cuando no procediere la separación, el Tribunal remitirá testimonio de la sentencia:","o":["Al Consejo General del Poder Judicial.","Al Consejo de Estado.","Al Ministerio de Justicia.","Al Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Consejo General del Poder Judicial</mark></span>Según el <span class=\"ref-norma\">art. 384.2 de la LOPJ</span> (texto del temario 2026, tras la reforma que crea los Tribunales de Instancia): <span class=\"ref-concepto\">\"En el caso del apartado 4, el Tribunal remitirá testimonio de la sentencia al Consejo General del Poder Judicial\"</span> (verificado con el texto del temario)."},{"i":"8-ia-8931","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Suspensión. En los supuestos de los dos primeros apartados del artículo sobre suspensión, el Juez o Tribunal que conociera de la causa lo comunicará al Consejo General del Poder Judicial, quien hará efectiva la suspensión:","o":["previo informe de la Sala de Gobierno.","previa audiencia del interesado y de su Presidente.","previa audiencia del Ministerio Fiscal.","previo dictamen del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">previa audiencia del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 384.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"lo comunicará al Consejo General del Poder Judicial, quien hará efectiva la suspensión, previa audiencia del Ministerio Fiscal\"</span>. Previa audiencia del Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8932","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Suspensión. La suspensión de un Juez o Magistrado por declararse haber lugar a proceder o por auto de prisión, fianza o procesamiento durará:","o":["hasta que se levante la medida cautelar.","hasta que recaiga en la causa sentencia absolutoria o auto de sobreseimiento.","por un plazo máximo de dos años.","hasta que el Consejo General del Poder Judicial acuerde su cese, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">hasta que recaiga en la causa sentencia absolutoria o auto de sobreseimiento</mark></span>El <span class=\"ref-norma\">art. 384.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La suspensión durará, en los casos de los apartados 1 y 2 del artículo anterior, hasta que recaiga en la causa sentencia absolutoria o auto de sobreseimiento\"</span>. Hasta sentencia absolutoria o auto de sobreseimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9100","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Policía Judicial. La función de la Policía Judicial comprende el auxilio a los juzgados y tribunales y al Ministerio Fiscal en la averiguación de los delitos y en el descubrimiento y aseguramiento de los delincuentes. Esta función competerá, cuando fueren requeridos para prestarla, a:","o":["los miembros de la Guardia Civil y del Cuerpo Nacional de Policía exclusivamente, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","las unidades de Policía Judicial en exclusiva.","los miembros de las Fuerzas y Cuerpos de Seguridad del Estado únicamente.","todos los miembros de las Fuerzas y Cuerpos de Seguridad, tanto si dependen del Gobierno central como de las comunidades autónomas o de los entes locales, dentro del ámbito de sus respectivas competencias."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">todos los miembros de las Fuerzas y Cuerpos de Seguridad, tanto si dependen del Gobierno central como de las comunidades autónomas o de los entes locales, dentro del ámbito de sus respectivas competencias</mark></span>El <span class=\"ref-norma\">art. 547 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Esta función competerá, cuando fueren requeridos para prestarla, a todos los miembros de las Fuerzas y Cuerpos de Seguridad, tanto si dependen del Gobierno central como de las comunidades autónomas o de los entes locales, dentro del ámbito de sus respectivas competencias\"</span>. Compete a todos los miembros de las FCS, estatales, autonómicos y locales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 391 ✱","q":[{"i":"8-194","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. No podrán pertenecer a una misma Sala de Justicia o Audiencia Provincial Magistrados que estuvieren unidos por vínculo matrimonial o situación de hecho equivalente, o tuvieren parentesco entre sí dentro del ___________ salvo que, por previsión legal existieren varias secciones, en cuyo caso podrán integrarse en secciones diversas, pero no formar Sala juntos.","o":["Quinto grado de consanguinidad o afinidad.","Segundo grado de consanguinidad o afinidad.","Cuarto grado de consanguinidad o afinidad.","Tercer grado de consanguinidad o afinidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Segundo grado de consanguinidad o afinidad.</mark></span>- La LOPJ establece la prohibición de formar parte de una misma Sala o Audiencia Provincial a Magistrados unidos por vínculo matrimonial o parentesco dentro del segundo grado de consanguinidad o afinidad. TEST 13"},{"i":"8-ia-8943","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Prohibiciones por parentesco. No podrán pertenecer a una misma Sala de Justicia o Audiencia Provincial Magistrados que estuvieren unidos por vínculo matrimonial o situación de hecho equivalente, o tuvieren parentesco entre sí dentro del:","o":["tercer grado de consanguinidad o afinidad, conforme al procedimiento que establezcan las leyes procesales.","primer grado de consanguinidad.","segundo grado de consanguinidad o afinidad.","cuarto grado de consanguinidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">segundo grado de consanguinidad o afinidad</mark></span>El <span class=\"ref-norma\">art. 391 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"o tuvieren parentesco entre sí dentro del segundo grado de consanguinidad o afinidad\"</span>. Segundo grado de consanguinidad o afinidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8944","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Prohibiciones por parentesco. Cuando existan varias secciones, Magistrados con vínculo matrimonial o parentesco hasta el segundo grado podrán integrarse en secciones diversas, pero:","o":["no presidir la misma Sección.","no formar Sala juntos.","no actuar como ponentes en el mismo recurso.","no integrar la misma Junta de Jueces."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no formar Sala juntos</mark></span>El <span class=\"ref-norma\">art. 391 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"en cuyo caso podrán integrarse en secciones diversas, pero no formar Sala juntos\"</span>. No pueden formar Sala juntos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 542","q":[{"i":"8-195","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿A quién le corresponde la dirección y defensa de las partes en toda clase de procesos?","o":["A los Procuradores.","Al Ministerio Fiscal.","A los Abogados.","A los Graduados Sociales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los Abogados</mark></span>Según el <span class=\"ref-norma\">art. 542 de la LOPJ</span>: <span class=\"ref-concepto\">\"Corresponde en exclusiva la denominación y función de abogado al licenciado en Derecho que ejerza profesionalmente la dirección y defensa de las partes en toda clase de procesos\"</span> (verificado con el texto del temario oficial)."},{"i":"8-220","p":"Ley Orgánica 6/1985 del Poder Judicial. En su actuación ante los juzgados y tribunales, ¿a qué principio se sujetarán los abogados?","o":["Al principio de buena fe.","Al principio de independencia.","Al principio de legalidad.","Al principio de igualdad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al principio de buena fe.</mark></span><span class=\"ref-norma\">Art. 542.2 · Poder Judicial</span>. Los Abogados, en su actuación ante los tribunales, deben sujetarse al principio de buena fe procesal, un requisito fundamental para el ejercicio correcto de la defensa y la lealtad procesal (Art. 542.2 LOPJ, en remisión a las leyes procesales, ej. Art. 247 LEC)."},{"i":"8-ia-9090","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Abogados. Corresponde en exclusiva la denominación y función de abogado al licenciado en Derecho que ejerza profesionalmente:","o":["la representación de las partes en toda clase de procesos.","la dirección y defensa de las partes en toda clase de procesos, o el asesoramiento y consejo jurídico.","el asesoramiento jurídico exclusivamente en procesos penales.","la defensa de las partes únicamente ante los Tribunales de Instancia, sin perjuicio de lo dispuesto en otras leyes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la dirección y defensa de las partes en toda clase de procesos, o el asesoramiento y consejo jurídico</mark></span>El <span class=\"ref-norma\">art. 542.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Corresponde en exclusiva la denominación y función de abogado al licenciado en Derecho que ejerza profesionalmente la dirección y defensa de las partes en toda clase de procesos, o el asesoramiento y consejo jurídico\"</span>. Dirección y defensa de las partes y asesoramiento y consejo jurídico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9091","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Abogados. En su actuación ante los juzgados y tribunales, los abogados son libres e independientes, se sujetarán al principio de buena fe, gozarán de los derechos inherentes a la dignidad de su función y:","o":["serán amparados por aquéllos en su libertad de expresión y defensa.","serán amparados por el Colegio de Abogados en su libertad de expresión.","estarán sometidos a las instrucciones de la parte.","gozarán de inmunidad por lo que manifiesten en juicio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">serán amparados por aquéllos en su libertad de expresión y defensa</mark></span>El <span class=\"ref-norma\">art. 542.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"gozarán de los derechos inherentes a la dignidad de su función y serán amparados por aquéllos en su libertad de expresión y defensa\"</span>. Los ampara el juzgado o tribunal en su libertad de expresión y defensa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9092","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Abogados. Los abogados deberán guardar secreto de todos los hechos o noticias de que conozcan por razón de cualquiera de las modalidades de su actuación profesional, no pudiendo ser:","o":["obligados a declarar salvo en causas penales.","exonerados de responsabilidad disciplinaria.","sancionados por el Colegio en ningún caso.","obligados a declarar sobre los mismos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">obligados a declarar sobre los mismos</mark></span>El <span class=\"ref-norma\">art. 542.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"no pudiendo ser obligados a declarar sobre los mismos\"</span>. No pueden ser obligados a declarar sobre ellos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 42 EX ✱","q":[{"i":"8-200","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién resolverá los conflictos de competencia entre órganos judiciales de distinto orden jurisdiccional?","o":["La Sala de Conflictos de Competencia.","La Sala Especial de Conflictos.","La Sala Especial de Conflictos de Jurisdicción.","La Sala de Gobierno del Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala de Conflictos de Competencia.</mark></span><span class=\"ref-norma\">Art. 38 · De la Organización y Planta de Juzgados y Tribunales</span>. El artículo 38 de la LOPJ establece la Sala especial de conflictos de competencia del Tribunal Supremo para resolver los conflictos positivos y negativos de competencia entre órganos judiciales de distinto orden jurisdiccional."},{"i":"8-ia-8191","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Renovación de los órganos decisorios. Los componentes de los órganos colegiados decisorios de los conflictos de jurisdicción se renovarán:","o":["anualmente.","cada dos años.","cada cinco años.","cada vez que se produzca una vacante."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">anualmente</mark></span>El <span class=\"ref-norma\">art. 40 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Anualmente se renovarán los componentes de los órganos colegiados decisorios previstos en los dos artículos anteriores\"</span>. Renovación anual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8192","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Conflictos de competencia entre órdenes. Los conflictos de competencia que puedan producirse entre Juzgados o Tribunales de distinto orden jurisdiccional, integrados en el Poder Judicial, se resolverán por una Sala especial del Tribunal Supremo, presidida por el Presidente y compuesta por:","o":["cuatro Magistrados, dos por cada orden jurisdiccional en conflicto, designados por el Pleno del Consejo General del Poder Judicial.","tres Magistrados de la Sala Primera designados por el Presidente.","dos Magistrados de la Sala de lo Contencioso-Administrativo.","dos Magistrados, uno por cada orden jurisdiccional en conflicto, que serán designados anualmente por la Sala de Gobierno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos Magistrados, uno por cada orden jurisdiccional en conflicto, que serán designados anualmente por la Sala de Gobierno</mark></span>El <span class=\"ref-norma\">art. 42 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se resolverán por una Sala especial del Tribunal Supremo, presidida por el Presidente y compuesta por dos Magistrados, uno por cada orden jurisdiccional en conflicto, que serán designados anualmente por la Sala de Gobierno\"</span>. Dos magistrados, uno por orden en conflicto, designados anualmente por la Sala de Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9124","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Relación de necesidades. El Consejo General del Poder Judicial remitirá al Ministerio de Justicia o al órgano competente de la comunidad autónoma una relación circunstanciada de las necesidades que estime existentes:","o":["anualmente.","semestralmente.","cada dos años.","cuando se lo soliciten."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">anualmente</mark></span>El <span class=\"ref-norma\">art. 37.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"remitirá anualmente al Ministerio de Justicia o al órgano competente de la comunidad autónoma con competencias en materia de justicia una relación circunstanciada de las necesidades que estime existentes.\"</span> Anualmente."}]},{"a":"Artículo 541 bis EX","q":[{"i":"8-203","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿Quién conocerá de la instrucción en primera instancia y vía de recurso contra los autores y demás partícipes en los delitos que perjudiquen los intereses financieros de la Unión Europea en los que, con arreglo al Reglamento (UE) 2017/1939 del Consejo, de 12 de octubre de 2017, ejerza de forma efectiva su competencia?","o":["La Fiscalía Europea.","Europol.","La OLAF.","El Tribunal de Justicia de la Unión Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Fiscalía Europea.</mark></span><span class=\"ref-norma\">Art. 541 bis · Poder Judicial</span>. El artículo 541 bis de la LOPJ (introducido por la LO 9/2021) establece que la Fiscalía Europea será responsable de investigar y ejercer la acción penal ante el órgano de enjuiciamiento competente en primera instancia y vía de recurso en estos delitos."},{"i":"8-ia-8309","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal del Tribunal Supremo. La Sala de lo Penal del Tribunal Supremo conocerá de la instrucción y enjuiciamiento de las causas contra los Magistrados de la Audiencia Nacional, de un Tribunal Superior de Justicia o:","o":["de los Fiscales europeos delegados.","de los Jueces de Instrucción y de Paz.","de los Magistrados de las Audiencias Provinciales.","de los Letrados de la Administración de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de los Fiscales europeos delegados</mark></span>El <span class=\"ref-norma\">art. 57 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De la instrucción y enjuiciamiento de las causas contra Magistrados de la Audiencia Nacional, de un Tribunal Superior de Justicia o de los Fiscales europeos delegados\"</span>. También los Fiscales europeos delegados; los Magistrados de Audiencias Provinciales corresponden al TSJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8901","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Central de Instancia. En la Sección de Instrucción del Tribunal Central de Instancia, los jueces y juezas de garantías conocerán de las peticiones de la Fiscalía Europea relativas a la adopción de medidas cautelares personales, la autorización de los actos que supongan limitación de los derechos fundamentales cuya adopción esté reservada a la autoridad judicial y demás supuestos que expresamente determine la ley. Igualmente, conocerán de las impugnaciones que establezca la ley contra:","o":["los decretos de los Fiscales europeos delegados.","las resoluciones del Fiscal General del Estado.","los autos de la Sala de lo Penal de la Audiencia Nacional.","las órdenes europeas de detención y entrega."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los decretos de los Fiscales europeos delegados</mark></span>El <span class=\"ref-norma\">art. 95 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Igualmente, conocerán de las impugnaciones que establezca la ley contra los decretos de los Fiscales europeos delegados\"</span>. Impugnaciones contra los decretos de los Fiscales europeos delegados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9089","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Fiscalía Europea. La Fiscalía Europea será responsable de investigar y ejercer la acción penal ante el órgano de enjuiciamiento competente en primera instancia y vía de recurso contra los autores y demás partícipes en los delitos que perjudiquen:","o":["los intereses financieros de los Estados miembros, con independencia del Reglamento, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","la seguridad jurídica de la Unión Europea y de sus ciudadanos.","los intereses financieros de la Unión Europea en los que, con arreglo al Reglamento (UE) 2017/1939 del Consejo, ejerza de forma efectiva su competencia.","los intereses de la Unión Europea en materia de terrorismo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los intereses financieros de la Unión Europea en los que, con arreglo al Reglamento (UE) 2017/1939 del Consejo, ejerza de forma efectiva su competencia</mark></span>El <span class=\"ref-norma\">art. 541 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"contra los autores y demás partícipes en los delitos que perjudiquen los intereses financieros de la Unión Europea en los que, con arreglo al Reglamento (UE) 2017/1939 del Consejo, de 12 de octubre de 2017, ejerza de forma efectiva su competencia\"</span>. Delitos contra los intereses financieros de la Unión, con arreglo al Reglamento (UE) 2017/1939. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 24 R7","q":[{"i":"8-206","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. ¿De quién es obligación garantizar la defensa y la asistencia de Abogado o la representación técnica de Graduado Social en los términos establecidos en la Constitución y en las leyes?","o":["De los Juzgados y Tribunales.","De los poderes públicos.","De las Fuerzas y Cuerpos de Seguridad Competentes.","Del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De los poderes públicos.</mark></span><span class=\"ref-norma\">Art. 24 · Poder Judicial</span>. El derecho fundamental a la defensa y asistencia letrada (Art. 24 CE) debe ser garantizado por los Poderes Públicos, que son los responsables de establecer el sistema de justicia gratuita."}]},{"a":"Artículo 545 EX","q":[{"i":"8-215","p":"Ley Orgánica 6/1985 del Poder Judicial. Se designarán _________ con arreglo a lo que en las leyes se establezca, a quien lo solicite o se niegue a nombrarlos, siendo _________ su intervención. La defensa o representación de oficio tendrá carácter gratuito para quien acredite insuficiencia de recursos para litigar en los términos que establezca la ley.","o":["De oficio / preceptiva.","A instancia de parte / recomendable.","De oficio / recomendable.","A instancia de parte / preceptiva."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De oficio / preceptiva</mark></span>Según el <span class=\"ref-norma\">art. 545 de la LOPJ</span>: <span class=\"ref-concepto\">\"Se designarán de oficio, con arreglo a lo que en las leyes se establezca, a quien lo solicite o se niegue a nombrarlos, siendo preceptiva su intervención. La defensa o representación de oficio tendrá carácter gratuito para quien acredite insuficiencia de recursos para litigar en los términos que establezca la ley\"</span> (verificado con el texto del temario oficial)."},{"i":"8-ia-9097","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Graduados Sociales. En los procedimientos laborales y de Seguridad Social la representación técnica podrá ser ostentada por:","o":["un Procurador, que actuará sin Abogado.","un representante sindical sin titulación.","un Graduado Social, al que serán de aplicación las obligaciones inherentes a su función.","un Letrado de la Administración de Justicia, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un Graduado Social, al que serán de aplicación las obligaciones inherentes a su función</mark></span>El <span class=\"ref-norma\">art. 545.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En los procedimientos laborales y de Seguridad Social la representación técnica podrá ser ostentada por un Graduado Social, al que serán de aplicación las obligaciones inherentes a su función\"</span>. Puede ostentarla un Graduado Social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 397 ✱","q":[{"i":"8-221","p":"Ley Orgánica 6/1985 del Poder Judicial. La competencia para la denegación de compatibilidades de Jueces y Magistrados, ¿a quién corresponde?","o":["Al Ministerio de Justicia.","Al Consejo General del Poder Judicial.","Al Presidente del Tribunal o Audiencia respectiva.","Al Consejo de Ministros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al Consejo General del Poder Judicial.</mark></span><span class=\"ref-norma\">Art. 397 · Del Consejo General del Poder Judicial</span>. La competencia para la autorización, reconocimiento o denegación de compatibilidades de Jueces y Magistrados corresponde al Consejo General del Poder Judicial (Art. 397 LOPJ)."},{"i":"8-ia-9061","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Compatibilidades. La competencia para la autorización, reconocimiento o denegación de compatibilidades de Jueces y Magistrados corresponde al Consejo General del Poder Judicial:","o":["previo informe de la Sala de Gobierno del Tribunal Superior de Justicia.","previo informe del Ministerio Fiscal.","previo informe del Presidente del Tribunal o Audiencia respectiva.","previa audiencia de la Asociación Judicial correspondiente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">previo informe del Presidente del Tribunal o Audiencia respectiva</mark></span>El <span class=\"ref-norma\">art. 397 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"corresponde al Consejo General del Poder Judicial, previo informe del Presidente del Tribunal o Audiencia respectiva\"</span>. Previo informe del Presidente del Tribunal o Audiencia respectiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 21 EXOF","q":[{"i":"8-248","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Extensión y límites de la jurisdicción. Los Tribunales civiles españoles conocerán de las pretensiones que se susciten en territorio español con arreglo a lo establecido en:","o":["Los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas.","Las leyes españolas y, supletoriamente, en los tratados y convenios internacionales en los que España sea parte, sin perjuicio de lo que establezcan los tratados internacionales.","Los tratados internacionales ratificados por España y en los reglamentos de la Unión Europea únicamente.","Las normas de la Unión Europea y en las leyes orgánicas, con exclusión de los convenios internacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas</mark></span>El <span class=\"ref-norma\">art. 21.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. Los Tribunales civiles españoles conocerán de las pretensiones que se susciten en territorio español con arreglo a lo establecido en los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas.\"</span>"},{"i":"8-ia-8052","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jurisdicción en el orden civil. Los Tribunales civiles españoles conocerán de las pretensiones que se susciten en territorio español con arreglo a lo establecido:","o":["en los tratados internacionales y en las leyes orgánicas españolas exclusivamente, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","en los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas.","en las normas de la Unión Europea y en los Convenios del Consejo de Europa.","en la Constitución, los tratados y los reglamentos europeos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas</mark></span>El <span class=\"ref-norma\">art. 21.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conocerán de las pretensiones que se susciten en territorio español con arreglo a lo establecido en los tratados y convenios internacionales en los que España sea parte, en las normas de la Unión Europea y en las leyes españolas\"</span>. Tratados, normas de la Unión Europea y leyes españolas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 quáter ✱","q":[{"i":"8-251","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia en defecto de otros criterios. En defecto de los criterios anteriores, los Tribunales españoles serán competentes en materia de relaciones personales y patrimoniales entre cónyuges, nulidad matrimonial, separación y divorcio, siempre que ningún otro Tribunal extranjero tenga competencia, entre otros supuestos:","o":["Cuando ambos cónyuges posean residencia habitual en España al tiempo de la interposición de la demanda.","Cuando uno solo de los cónyuges haya nacido en España, aunque ambos residan en el extranjero.","Cuando el matrimonio se hubiera celebrado ante autoridad española, aunque ninguno resida en España, salvo que el órgano competente acuerde otra cosa de forma motivada.","Cuando el demandante lleve al menos tres meses de residencia habitual en España."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuando ambos cónyuges posean residencia habitual en España al tiempo de la interposición de la demanda</mark></span>El <span class=\"ref-norma\">art. 22 quáter.c) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"c) En materia de relaciones personales y patrimoniales entre cónyuges, nulidad matrimonial, separación y divorcio y sus modificaciones, siempre que ningún otro Tribunal extranjero tenga competencia, cuando ambos cónyuges posean residencia habitual en España al tiempo de la interposición de la demanda\"</span>"},{"i":"8-ia-8054","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencia exclusiva de los Tribunales españoles. Con carácter exclusivo, los Tribunales españoles serán competentes en todo caso y con preferencia de cualquier otro, en materia de derechos reales y arrendamientos de bienes inmuebles que se hallen en España. No obstante, en contratos de arrendamiento celebrados para un uso particular durante un plazo máximo de seis meses consecutivos, serán igualmente competentes los españoles si:","o":["el demandado estuviera domiciliado en España, siempre que el arrendatario sea una persona física o jurídica, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","el arrendador estuviera domiciliado en España, con independencia del domicilio del arrendatario.","el inmueble se encuentre en España y el arrendatario sea una persona física de nacionalidad española.","el demandado estuviera domiciliado en España, siempre que el arrendatario sea una persona física y que éste y el propietario estén domiciliados en el mismo Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el demandado estuviera domiciliado en España, siempre que el arrendatario sea una persona física y que éste y el propietario estén domiciliados en el mismo Estado</mark></span>El <span class=\"ref-norma\">art. 22.a de LOPJ</span> dispone: <span class=\"ref-concepto\">\"serán igualmente competentes los órganos jurisdiccionales españoles si el demandado estuviera domiciliado en España, siempre que el arrendatario sea una persona física y que éste y el propietario estén domiciliados en el mismo Estado\"</span>. Exige domicilio del demandado en España, arrendatario persona física y domicilio de ambos en el mismo Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8063","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Foros subsidiarios. En materia de filiación y de relaciones paterno-filiales, protección de menores y de responsabilidad parental, serán competentes los Tribunales españoles cuando el hijo o menor tenga su residencia habitual en España al tiempo de la interposición de la demanda o el demandante sea español o resida habitualmente en España o, en todo caso:","o":["al menos desde un año antes de la presentación de la demanda.","al menos desde tres meses antes de la presentación de la demanda, salvo que la ley disponga otra cosa.","al menos desde seis meses antes de la presentación de la demanda.","desde el nacimiento del menor."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al menos desde seis meses antes de la presentación de la demanda</mark></span>El <span class=\"ref-norma\">art. 22 quáter.d de LOPJ</span> dispone: <span class=\"ref-concepto\">\"o resida habitualmente en España o, en todo caso, al menos desde seis meses antes de la presentación de la demanda\"</span>. El plazo legal es de seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 26 ✱","q":[{"i":"8-259","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales. Los Tribunales a los que se atribuye el ejercicio de la potestad jurisdiccional son los siguientes:","o":["Jueces y juezas de paz, Juzgados de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Audiencia Nacional, Tribunal Supremo y Tribunal Constitucional.","Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo, sin Jueces de paz, en los términos que determine la ley orgánica correspondiente.","Jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo.","Jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Audiencias Territoriales, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo</mark></span>Según el <span class=\"ref-norma\">art. 26 de la LOPJ</span>: <span class=\"ref-concepto\">\"Los Tribunales a los que se atribuye el ejercicio de la potestad jurisdiccional son los siguientes: a) Jueces y juezas de paz. b) Tribunales de Instancia. c) Audiencias Provinciales. d) Tribunales Superiores de Justicia. e) Tribunal Central de Instancia. f) Audiencia Nacional. g) Tribunal Supremo\"</span> (verificado con el texto del temario oficial)."},{"i":"8-ia-8176","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales. Los Tribunales a los que se atribuye el ejercicio de la potestad jurisdiccional son los siguientes: Jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia y:","o":["Audiencia Nacional, Tribunal Supremo y Tribunal Constitucional.","Tribunal Central de Instancia, Audiencia Territorial y Tribunal Supremo.","Audiencia Nacional, Tribunal de Cuentas y Tribunal Supremo.","Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 26 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"d) Tribunales Superiores de Justicia. e) Tribunal Central de Instancia. f) Audiencia Nacional. g) Tribunal Supremo\"</span>. El Tribunal Constitucional no está en la lista: no forma parte del Poder Judicial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 32 EXOF ✱","q":[{"i":"8-261","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Partidos judiciales. La modificación de partidos se realizará, en su caso, en función:","o":["Del número de asuntos, de las características de la población, medios de comunicación y comarcas naturales.","Del número de asuntos y de la población, con independencia de los medios de comunicación existentes, salvo que el órgano competente acuerde otra cosa de forma motivada.","De las características de la población y de la extensión del territorio provincial únicamente.","Del número de asuntos, de las comarcas naturales y de las cargas de trabajo de los Juzgados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Del número de asuntos, de las características de la población, medios de comunicación y comarcas naturales</mark></span>El <span class=\"ref-norma\">art. 32.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2. La modificación de partidos se realizará, en su caso, en función del número de asuntos, de las características de la población, medios de comunicación y comarcas naturales.\"</span>"},{"i":"8-ia-8180","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Partido judicial. El partido es la unidad territorial integrada por uno o más municipios limítrofes, pertenecientes a una misma provincia, y su modificación se realizará, en su caso, en función del número de asuntos, de las características de la población, medios de comunicación y:","o":["límites provinciales.","extensión del territorio.","carga económica.","comarcas naturales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">comarcas naturales</mark></span>El <span class=\"ref-norma\">art. 32 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"medios de comunicación y comarcas naturales\"</span>. El último criterio son las comarcas naturales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 55 bis ✱","q":[{"i":"8-264","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Supremo. Las Salas de lo Civil y de lo Penal del Tribunal Supremo conocerán de la tramitación y enjuiciamiento de las acciones civiles y penales, respectivamente, dirigidas contra:","o":["El Rey o la Reina en ejercicio, su consorte y el Príncipe o Princesa de Asturias.","La Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte.","La Reina consorte, el consorte de la Reina y los miembros de la Familia Real, con exclusión del Heredero, sin perjuicio de lo que establezcan los tratados internacionales.","El Rey o Reina que hubiere abdicado, con exclusión de su consorte, y el Príncipe o Princesa de Asturias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte</mark></span>El <span class=\"ref-norma\">art. 55 bis de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"dichas Salas conocerán de la tramitación y enjuiciamiento de las acciones civiles y penales, respectivamente, dirigidas contra la Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte.\"</span>"},{"i":"8-ia-8305","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Consorte y familia real. Además de las competencias atribuidas a las Salas de lo Civil y de lo Penal del Tribunal Supremo, dichas Salas conocerán de la tramitación y enjuiciamiento de las acciones civiles y penales, respectivamente, dirigidas contra:","o":["la Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte.","el Rey o Reina que hubiere abdicado y su consorte, con exclusión del Príncipe de Asturias, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes.","los miembros de la Familia Real hasta el segundo grado de parentesco con el Rey.","la Reina consorte o el consorte de la Reina y los hijos del Rey."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte</mark></span>El <span class=\"ref-norma\">art. 55 bis de LOPJ</span> dispone: <span class=\"ref-concepto\">\"dirigidas contra la Reina consorte o el consorte de la Reina, la Princesa o Príncipe de Asturias y su consorte, así como contra el Rey o Reina que hubiere abdicado y su consorte\"</span>. Se enumeran los consortes, el heredero y su consorte y quien hubiere abdicado y su consorte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 86 ✱","q":[{"i":"8-279","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Familia, Infancia y Capacidad. En los partidos judiciales en que exista un Tribunal de Instancia con Sección Única integrada por una sola plaza judicial, el juez o jueza que la ocupe asumirá el conocimiento de los asuntos de familia:","o":["Cuando la Sala de Gobierno así lo acuerde de forma motivada.","Aunque se hubiere creado una Sección de Familia, Infancia y Capacidad en el partido.","Cuando no se hubiere creado una Sección de Familia, Infancia y Capacidad.","Cuando el Consejo General del Poder Judicial no haya creado una Sección de Violencia sobre la Mujer."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuando no se hubiere creado una Sección de Familia, Infancia y Capacidad</mark></span>El <span class=\"ref-norma\">art. 86.4 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"4. En los partidos judiciales en que exista un Tribunal de Instancia con Sección Única integrada por una sola plaza judicial, el juez o jueza que la ocupe será quien asuma el conocimiento de los asuntos de familia cuando no se hubiere creado una Sección de Familia, Infancia y Capacidad.\"</span>"},{"i":"8-280","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Familia, Infancia y Capacidad. Las Secciones de Familia, Infancia y Capacidad conocerán de cuantas cuestiones se susciten en materia de familia en los términos previstos en las leyes. En todo caso, su jurisdicción será exclusiva y excluyente en las siguientes materias:","o":["Las relativas a la sucesión hereditaria y a las donaciones entre parientes, entre otras previstas en la ley.","Las relativas al matrimonio y a su régimen económico matrimonial, entre otras previstas en la ley.","Las relativas a los arrendamientos de vivienda habitual y a las ejecuciones hipotecarias.","Las relativas a la responsabilidad penal de los menores, entre otras previstas en la ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las relativas al matrimonio y a su régimen económico matrimonial, entre otras previstas en la ley</mark></span>El <span class=\"ref-norma\">art. 86.5 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Las relativas al matrimonio y a su régimen económico matrimonial y las que tengan por objeto la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho.\"</span>"},{"i":"8-294","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Familia, Infancia y Capacidad. La jurisdicción de las Secciones de Familia, Infancia y Capacidad será exclusiva y excluyente, entre otras, en las materias que:","o":["Versen sobre la sucesión hereditaria y las donaciones entre parientes dentro del cuarto grado, sin perjuicio de lo que establezcan los tratados internacionales, en los términos que determine la ley orgánica correspondiente.","Versen exclusivamente sobre guarda y custodia de hijos o hijas menores o sobre alimentos reclamados por un progenitor contra el otro en nombre de los hijos o hijas menores.","Versen sobre alimentos reclamados por los padres contra los hijos mayores de edad.","Versen sobre la responsabilidad penal de los menores de dieciocho años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Versen exclusivamente sobre guarda y custodia de hijos o hijas menores o sobre alimentos reclamados por un progenitor contra el otro en nombre de los hijos o hijas menores</mark></span>El <span class=\"ref-norma\">art. 86.5 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"5. Las Secciones de Familia, Infancia y Capacidad conocerán de cuantas cuestiones se susciten en materia de familia en los términos previstos en las leyes. En todo caso, la jurisdicción de estas Secciones será exclusiva y excluyente en las siguientes materias:\"</span>"},{"i":"8-ia-8611","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. En los partidos judiciales en que exista un Tribunal de Instancia con Sección Única integrada por una sola plaza judicial, el juez o jueza que la ocupe será quien asuma el conocimiento de los asuntos de familia cuando:","o":["lo acuerde la Sala de Gobierno.","exista Sección de Violencia sobre la Mujer en el partido, salvo que la ley disponga otra cosa.","no se hubiere creado una Sección de Familia, Infancia y Capacidad.","el Gobierno no haya dictado real decreto."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no se hubiere creado una Sección de Familia, Infancia y Capacidad</mark></span>El <span class=\"ref-norma\">art. 86.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"el juez o jueza que la ocupe será quien asuma el conocimiento de los asuntos de familia cuando no se hubiere creado una Sección de Familia, Infancia y Capacidad\"</span>. Solo si no se creó la Sección de Familia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8612","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. Las Secciones de Familia, Infancia y Capacidad conocerán de cuantas cuestiones se susciten en materia de familia en los términos previstos en las leyes. En todo caso, la jurisdicción de estas Secciones será:","o":["concurrente con la de las Secciones Civiles.","exclusiva y excluyente en las materias que enumera la ley.","subsidiaria respecto de la Sección Civil.","exclusiva, pero no excluyente, en las materias que enumera la ley."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">exclusiva y excluyente en las materias que enumera la ley</mark></span>El <span class=\"ref-norma\">art. 86.5 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En todo caso, la jurisdicción de estas Secciones será exclusiva y excluyente en las siguientes materias\"</span>. Exclusiva y excluyente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8613","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. Entre las materias en que la jurisdicción de las Secciones de Familia, Infancia y Capacidad es exclusiva y excluyente figuran las relativas al matrimonio y a su régimen económico matrimonial y las que tengan por objeto:","o":["la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho.","la liquidación de herencias y legados.","la adopción de medidas cautelares en procesos concursales.","la separación de bienes de los cónyuges en procesos penales, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho</mark></span>El <span class=\"ref-norma\">art. 86.5.a de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) Las relativas al matrimonio y a su régimen económico matrimonial y las que tengan por objeto la adopción o modificación de medidas de trascendencia familiar y otras acciones derivadas de la crisis matrimonial o de la unión de hecho\"</span>. Incluye crisis matrimonial o de la unión de hecho. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8614","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Familia, Infancia y Capacidad. Son de la jurisdicción exclusiva y excluyente de las Secciones de Familia, Infancia y Capacidad las que versen exclusivamente sobre guarda y custodia de hijos o hijas menores o sobre:","o":["alimentos entre parientes de cualquier grado.","alimentos reclamados por el hijo mayor de edad contra sus progenitores, en los términos que establezca la ley orgánica.","pensiones compensatorias entre excónyuges.","alimentos reclamados por un progenitor contra el otro en nombre de los hijos o hijas menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">alimentos reclamados por un progenitor contra el otro en nombre de los hijos o hijas menores</mark></span>El <span class=\"ref-norma\">art. 86.5.b de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las que versen exclusivamente sobre guarda y custodia de hijos o hijas menores o sobre alimentos reclamados por un progenitor contra el otro en nombre de los hijos o hijas menores\"</span>. Los alimentos entre parientes figuran aparte en otra letra. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 99 ✱","q":[{"i":"8-281","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jueces de paz. En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá:","o":["Un Juzgado de Primera Instancia e Instrucción.","Un juez o una jueza de paz.","Una Sección del Tribunal de Instancia del partido.","Un juez o una jueza de paz y un Secretario judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un juez o una jueza de paz</mark></span>El <span class=\"ref-norma\">art. 99 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz.\"</span>"},{"i":"8-ia-8913","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jueces de Paz. En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente:","o":["habrá un juez o una jueza de paz.","habrá una Sección de lo Civil.","habrá un Juzgado de Instrucción.","se podrá crear una Audiencia Provincial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">habrá un juez o una jueza de paz</mark></span>El <span class=\"ref-norma\">art. 99 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En cada municipio donde no exista Tribunal de Instancia, y con jurisdicción en el término correspondiente, habrá un juez o una jueza de paz\"</span>. Un juez de paz por municipio sin Tribunal de Instancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Del Poder Judicial","q":[{"i":"8-282","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Juzgados de Paz. Los Juzgados de Paz conocerán, en el orden civil, de la sustanciación en primera instancia, fallo y ejecución de los procesos que la ley determine y cumplirán también:","o":["Las demás funciones que la ley les atribuya.","Las funciones de instrucción de las causas por faltas que determine el Gobierno.","Las funciones que les delegue la Audiencia Provincial.","Las demás funciones que les atribuya el Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las demás funciones que la ley les atribuya</mark></span>El <span class=\"ref-norma\">art. 100.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"1. Los Juzgados de Paz conocerán, en el orden civil, de la sustanciación en primera instancia, fallo y ejecución de los procesos que la ley determine y cumplirán también las demás funciones que la ley les atribuya.\"</span>"},{"i":"8-291","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Procuradores. Por delegación del juez, jueza o tribunal, los procuradores podrán realizar las actuaciones materiales propias del proceso de ejecución, que en todo caso excluirán:","o":["Las ejecuciones hipotecarias de vivienda habitual, así como las derivadas de procesos en materia de familia y las de desahucio por impago de rentas en viviendas habituales.","Las ejecuciones de sentencias dictadas en procesos de reclamación de cantidad inferior a seis mil euros, salvo que el órgano competente acuerde otra cosa de forma motivada, conforme al procedimiento que reglamentariamente se establezca.","Las ejecuciones hipotecarias de cualquier vivienda y las derivadas de procesos penales.","Los lanzamientos de ocupantes de finca anteriores a la subasta y los desahucios por precario."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las ejecuciones hipotecarias de vivienda habitual, así como las derivadas de procesos en materia de familia y las de desahucio por impago de rentas en viviendas habituales</mark></span>El <span class=\"ref-norma\">art. 543.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Por delegación del juez, jueza o tribunal, podrán también realizar las actuaciones materiales propias del proceso de ejecución en los términos establecidos legalmente que, en todo caso, excluirán las ejecuciones hipotecarias de vivienda habitual, así como las derivadas de procesos en materia de familia, las de desahucio por impago de rentas o cantidades debidas en viviendas habituales\"</span>"},{"i":"8-303","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia contra la Infancia y la Adolescencia. Si los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia corresponderá en todo caso:","o":["A la última.","A la primera.","A la que primero hubiera iniciado las diligencias.","A la que determine la Sala de Gobierno del Tribunal Superior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A la última</mark></span>El <span class=\"ref-norma\">art. 89 bis.7 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"En caso de que los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia le corresponderá en todo caso a la última.\"</span>"},{"i":"8-308","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias de los Jueces de Paz. En el orden penal, los Juzgados de Paz conocerán en primera instancia de los procesos por delito leve que les atribuya la ley y podrán intervenir, igualmente:","o":["En actuaciones penales de prevención, o por delegación, y en aquellas otras que señalen las leyes.","En la instrucción de delitos menos graves, por delegación del Ministerio Fiscal, y en las que señalen los reglamentos.","En actuaciones penales de prevención, pero nunca por delegación de otro órgano judicial.","En la ejecución de las sentencias penales firmes del partido judicial en que ejerzan su jurisdicción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En actuaciones penales de prevención, o por delegación, y en aquellas otras que señalen las leyes</mark></span>El <span class=\"ref-norma\">art. 100.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Podrán intervenir, igualmente, en actuaciones penales de prevención, o por delegación, y en aquellas otras que señalen las leyes.\"</span> Prevención, delegación y las que señalen las leyes."}]},{"a":"Artículo 378 ✱","q":[{"i":"8-283","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inamovilidad. Los jueces y magistrados que hayan sido nombrados por plazo determinado gozarán de inamovilidad:","o":["Hasta la jubilación forzosa.","Por un período máximo de cinco años, prorrogable una vez.","Durante todo el tiempo que dure su carrera judicial.","Sólo por ese tiempo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Sólo por ese tiempo</mark></span>El <span class=\"ref-norma\">art. 378.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"2. Los que hayan sido nombrados por plazo determinado gozarán de inamovilidad sólo por ese tiempo.\"</span>"},{"i":"8-ia-8924","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inamovilidad. Los Jueces y Magistrados que hayan sido nombrados por plazo determinado gozarán de inamovilidad:","o":["hasta su jubilación.","sólo por ese tiempo.","mientras no sean trasladados.","durante un plazo máximo de seis años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sólo por ese tiempo</mark></span>El <span class=\"ref-norma\">art. 378 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los que hayan sido nombrados por plazo determinado gozarán de inamovilidad sólo por ese tiempo\"</span>. Inamovilidad solo por el plazo del nombramiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8925","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inamovilidad. Los casos de renuncia, excedencia, traslado y promoción de Jueces y Magistrados se regirán:","o":["por sus normas específicas establecidas en esta ley.","por el Reglamento del Consejo General del Poder Judicial.","por el Estatuto Básico del Empleado Público.","por lo que acuerde la Sala de Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por sus normas específicas establecidas en esta ley</mark></span>El <span class=\"ref-norma\">art. 378 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los casos de renuncia, excedencia, traslado y promoción se regirán por sus normas específicas establecidas en esta ley\"</span>. Por sus normas específicas de la LOPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 550 ✱ R22","q":[{"i":"8-293","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Policía Judicial. Los funcionarios de Policía Judicial a quienes se hubiera encomendado una actuación o investigación concreta no podrán ser removidos o apartados hasta que finalice la misma o, en todo caso, la fase del procedimiento judicial que la originó, si no es:","o":["Por decisión de su superior jerárquico, previa comunicación al juez o fiscal.","Por acuerdo del Consejo General del Poder Judicial.","Por decisión o con la autorización del juez o fiscal competente.","Por decisión del Ministro del Interior o con autorización del Delegado del Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por decisión o con la autorización del juez o fiscal competente</mark></span>El <span class=\"ref-norma\">art. 550.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"si no es por decisión o con la autorización del juez o fiscal competente.\"</span>"},{"i":"8-ia-9105","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Dirección de la Policía Judicial. Los funcionarios de Policía Judicial a quienes se hubiera encomendado una actuación o investigación concreta no podrán ser removidos o apartados hasta que finalice la misma o, en todo caso, la fase del procedimiento judicial que la originó, si no es:","o":["por decisión del Ministerio del Interior.","por decisión de su superior jerárquico, previo aviso al juez, salvo que la ley disponga otra cosa.","por decisión o con la autorización del juez o fiscal competente.","por acuerdo de la Sala de Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por decisión o con la autorización del juez o fiscal competente</mark></span>El <span class=\"ref-norma\">art. 550.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"no podrán ser removidos o apartados hasta que finalice la misma o, en todo caso, la fase del procedimiento judicial que la originó, si no es por decisión o con la autorización del juez o fiscal competente\"</span>. Solo por decisión o con autorización del juez o fiscal competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 bis EXOF EX ✱ R6","q":[{"i":"8-295","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sumisión. Se entenderá por acuerdo de sumisión expresa aquel pacto por el cual las partes deciden atribuir a los Tribunales españoles el conocimiento de ciertas o todas las controversias que hayan surgido o puedan surgir entre ellas respecto de una determinada relación jurídica, contractual o no contractual. La competencia establecida por sumisión expresa:","o":["No alcanzará a la validez del acuerdo de sumisión, que se juzgará por el Derecho extranjero.","Se limitará a las controversias ya surgidas, sin alcanzar a las futuras.","Se extenderá a la propia validez del acuerdo de sumisión.","Excluirá la competencia de los órganos judiciales exclusivamente competentes conforme al artículo 22."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Se extenderá a la propia validez del acuerdo de sumisión</mark></span>El <span class=\"ref-norma\">art. 22 bis.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Se entenderá por acuerdo de sumisión expresa aquel pacto por el cual las partes deciden atribuir a los Tribunales españoles el conocimiento de ciertas o todas las controversias que hayan surgido o puedan surgir entre ellas respecto de una determinada relación jurídica, contractual o no contractual. La competencia establecida por sumisión expresa se extenderá a la propia validez del acuerdo de sumisión.\"</span>"},{"i":"8-ia-8059","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sumisión tácita. Con independencia de los casos en los que su competencia resulte de otras disposiciones, serán competentes los Tribunales españoles cuando comparezca ante ellos el demandado. Esta regla:","o":["será de aplicación aunque la comparecencia tenga por objeto impugnar la competencia.","solo se aplica si el demandado comparece asistido de abogado y procurador.","no será de aplicación si la comparecencia tiene por objeto impugnar la competencia.","no será de aplicación a los procesos de familia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no será de aplicación si la comparecencia tiene por objeto impugnar la competencia</mark></span>El <span class=\"ref-norma\">art. 22 bis.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"serán competentes los Tribunales españoles cuando comparezca ante ellos el demandado. Esta regla no será de aplicación si la comparecencia tiene por objeto impugnar la competencia\"</span>. Si se comparece solo para impugnar la competencia, no hay sumisión tácita. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 410 EX","q":[{"i":"8-307","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad penal. Si se formula querella contra el juez o magistrado que deba resolver en un proceso, con carácter previo a la admisión de ésta el órgano competente para su instrucción podrá recabar los antecedentes que considere oportunos a fin de determinar:","o":["La procedencia de la suspensión cautelar del juez y la gravedad de la infracción disciplinaria, salvo que el órgano competente acuerde otra cosa de forma motivada.","Su propia competencia, así como la existencia de responsabilidad civil subsidiaria del Estado.","Su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación.","La relevancia penal de los hechos y la competencia del Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación</mark></span>El <span class=\"ref-norma\">art. 410 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"con carácter previo a la admisión de ésta el órgano competente para su instrucción podrá recabar los antecedentes que considere oportunos a fin de determinar su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación.\"</span>"},{"i":"8-ia-9086","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Querella contra el juez. En el caso de que alguna de las partes en un proceso, o persona que tuviese interés en él, formulasen querella contra el juez o magistrado que deba resolver en dicho proceso, con carácter previo a la admisión de ésta el órgano competente para su instrucción podrá:","o":["inadmitirla a trámite en todo caso.","recabar los antecedentes que considere oportunos a fin de determinar su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación.","remitirla al Consejo General del Poder Judicial.","suspender el proceso principal hasta resolver sobre ella, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">recabar los antecedentes que considere oportunos a fin de determinar su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación</mark></span>El <span class=\"ref-norma\">art. 410 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"con carácter previo a la admisión de ésta el órgano competente para su instrucción podrá recabar los antecedentes que considere oportunos a fin de determinar su propia competencia así como la relevancia penal de los hechos objeto de la misma o la verosimilitud de la imputación\"</span>. Puede recabar antecedentes para comprobar competencia, relevancia penal y verosimilitud. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Poder Judicial","q":[{"i":"8-ia-8017","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Control de la Administración. Los Tribunales controlan la potestad reglamentaria y la legalidad de la actuación administrativa, así como:","o":["el sometimiento de ésta a los fines que la justifican.","su sometimiento a los criterios de oportunidad que la justifican.","el fin que la justifica y su coste económico.","su adecuación a las instrucciones de la Administración jerárquicamente superior."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el sometimiento de ésta a los fines que la justifican</mark></span>El <span class=\"ref-norma\">art. 8 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"así como el sometimiento de ésta a los fines que la justifican\"</span>. Control de legalidad y de sometimiento a los fines que justifican la actuación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8027","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Improrrogabilidad de la jurisdicción. La jurisdicción es improrrogable. Los órganos judiciales apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma con audiencia:","o":["de las partes exclusivamente.","del Ministerio Fiscal exclusivamente.","de las partes y del Ministerio Fiscal.","de las partes y del Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de las partes y del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 9.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los órganos judiciales apreciarán de oficio la falta de jurisdicción y resolverán sobre la misma con audiencia de las partes y del Ministerio Fiscal\"</span>. Se oye a las partes y al Ministerio Fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8029","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuestiones prejudiciales. La existencia de una cuestión prejudicial penal de la que no pueda prescindirse para la debida decisión o que condicione directamente el contenido de ésta determinará:","o":["la suspensión del procedimiento mientras aquélla no sea resuelta por los órganos penales a quienes corresponda, salvo las excepciones que la ley establezca.","la inhibición del órgano en favor del orden penal, sin posibilidad de excepciones.","la continuación del procedimiento, quedando la sentencia sujeta a lo que resuelva el órgano penal, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","el archivo del procedimiento hasta que sea firme la resolución penal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la suspensión del procedimiento mientras aquélla no sea resuelta por los órganos penales a quienes corresponda, salvo las excepciones que la ley establezca</mark></span>El <span class=\"ref-norma\">art. 10 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"determinará la suspensión del procedimiento mientras aquélla no sea resuelta por los órganos penales a quienes corresponda, salvo las excepciones que la ley establezca\"</span>. Procede la suspensión del procedimiento, no la inhibición ni el archivo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8030","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuestiones prejudiciales. A los solos efectos prejudiciales, cada orden jurisdiccional podrá conocer:","o":["de asuntos atribuidos a otro orden jurisdiccional con autorización de éste.","de asuntos de otros órdenes jurisdiccionales, salvo del penal.","de asuntos atribuidos al Tribunal Supremo.","de asuntos que no le estén atribuidos privativamente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de asuntos que no le estén atribuidos privativamente</mark></span>El <span class=\"ref-norma\">art. 10 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"A los solos efectos prejudiciales, cada orden jurisdiccional podrá conocer de asuntos que no le estén atribuidos privativamente\"</span>. Puede conocer de asuntos no atribuidos privativamente, solo a efectos prejudiciales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8039","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inamovilidad. Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados sino:","o":["por las causas previstas en la Constitución y con autorización del Consejo General del Poder Judicial.","por sentencia firme dictada por el Tribunal Supremo.","por alguna de las causas y con las garantías previstas en esta Ley.","por alguna de las causas previstas en esta Ley y con la autorización del Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por alguna de las causas y con las garantías previstas en esta Ley</mark></span>El <span class=\"ref-norma\">art. 15 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"no podrán ser separados, suspendidos, trasladados ni jubilados sino por alguna de las causas y con las garantías previstas en esta Ley\"</span>. Reserva de ley: causas y garantías previstas en la LOPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8040","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad. Los Jueces y Magistrados responderán penal y civilmente en los casos y en la forma determinada en las leyes, y disciplinariamente:","o":["en los términos que determine el Consejo General del Poder Judicial.","de conformidad con lo establecido en esta Ley.","conforme al Estatuto General de la Función Pública.","según lo previsto en el Código Penal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de conformidad con lo establecido en esta Ley</mark></span>El <span class=\"ref-norma\">art. 16 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"responderán penal y civilmente en los casos y en la forma determinada en las leyes, y disciplinariamente de conformidad con lo establecido en esta Ley\"</span>. La responsabilidad disciplinaria se rige por la LOPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8050","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Justicia gratuita. No podrán exigirse fianzas que por su inadecuación impidan el ejercicio de la acción popular, que será:","o":["gratuita en los supuestos que establezca la ley.","gratuita únicamente para las personas físicas.","gratuita cuando se acredite insuficiencia de recursos.","siempre gratuita."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">siempre gratuita</mark></span>El <span class=\"ref-norma\">art. 20 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"No podrán exigirse fianzas que por su inadecuación impidan el ejercicio de la acción popular, que será siempre gratuita\"</span>. La acción popular es siempre gratuita; la justicia en general lo es en los supuestos que establezca la ley. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8051","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Justicia gratuita. Se regulará por ley un sistema de justicia gratuita que dé efectividad al derecho declarado en los artículos 24 y 119 de la Constitución, en los casos de:","o":["carencia de recursos económicos acreditada por el Colegio de Abogados.","especial vulnerabilidad de la persona.","insuficiencia de recursos para litigar.","cuantía inferior al salario mínimo interprofesional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">insuficiencia de recursos para litigar</mark></span>El <span class=\"ref-norma\">art. 20.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"que de efectividad al derecho declarado en los artículos 24 y 119 de la Constitución, en los casos de insuficiencia de recursos para litigar\"</span>. La justicia gratuita se reconoce en caso de insuficiencia de recursos para litigar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8067","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Medidas provisionales. Los Tribunales españoles serán competentes cuando se trate de adoptar medidas provisionales o de aseguramiento respecto de personas o bienes que se hallen en territorio español y deban cumplirse en España. Serán también competentes para adoptar estas medidas:","o":["aunque no lo sean para conocer del asunto principal.","siempre que lo soliciten ambas partes.","si lo son para conocer del asunto principal.","si el demandado tiene su domicilio en el extranjero."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">si lo son para conocer del asunto principal</mark></span>El <span class=\"ref-norma\">art. 22 sexies de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Serán también competentes para adoptar estas medidas si lo son para conocer del asunto principal\"</span>. También lo son si son competentes sobre el fondo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8177","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Numeración de Secciones y plazas. Cuando las Salas de los Tribunales se dividan en Secciones y hubiere dos o más, se designarán por numeración ordinal. Las plazas judiciales que integran los Tribunales de Instancia y el Tribunal Central de Instancia se designarán:","o":["por numeración ordinal dentro de la misma Sala.","por orden alfabético dentro de la misma Sección, sin perjuicio de lo dispuesto en otras leyes.","por numeración cardinal dentro de la misma Sección.","por numeración romana dentro del mismo Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por numeración cardinal dentro de la misma Sección</mark></span>El <span class=\"ref-norma\">art. 27 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se designarán por numeración cardinal dentro de la misma Sección\"</span>. Las Secciones: ordinal; las plazas: cardinal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8195","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Planteamiento del conflicto. Suscitado el conflicto de competencia en escrito razonado, el Juez o Tribunal, oídas las partes y el Ministerio Fiscal por plazo común de diez días, decidirá:","o":["por medio de auto si procede declinar el conocimiento del asunto o requerir al órgano jurisdiccional que esté conociendo para que deje de hacerlo.","por medio de providencia si procede elevar las actuaciones al Tribunal Supremo.","por medio de sentencia si procede o no el conflicto planteado.","por medio de auto si procede suspender el procedimiento hasta resolver la competencia, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por medio de auto si procede declinar el conocimiento del asunto o requerir al órgano jurisdiccional que esté conociendo para que deje de hacerlo</mark></span>El <span class=\"ref-norma\">art. 45 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"oídas las partes y el Ministerio Fiscal por plazo común de diez días, decidirá por medio de auto si procede declinar el conocimiento del asunto o requerir al órgano jurisdiccional que esté conociendo para que deje de hacerlo\"</span>. Decide por auto, previa audiencia por diez días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8198","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recursos. Las resoluciones recaídas en la tramitación de los conflictos de competencia:","o":["solo serán susceptibles de recurso de reposición.","no serán susceptibles de recurso alguno, ordinario o extraordinario.","serán recurribles en casación ante la Sala Primera.","podrán recurrirse en amparo ante el Tribunal Constitucional únicamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no serán susceptibles de recurso alguno, ordinario o extraordinario</mark></span>El <span class=\"ref-norma\">art. 49 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las resoluciones recaídas en la tramitación de los conflictos de competencia no serán susceptibles de recurso alguno, ordinario o extraordinario\"</span>. Irrecurribles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8199","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recurso por defecto de jurisdicción. Contra la resolución firme en que el órgano del orden jurisdiccional indicado declare su falta de jurisdicción en un proceso cuyos sujetos y pretensiones fuesen los mismos, podrá interponerse recurso por defecto de jurisdicción en el plazo de:","o":["diez días.","cinco días.","veinte días.","un mes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">diez días</mark></span>El <span class=\"ref-norma\">art. 50 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"declare su falta de jurisdicción en un proceso cuyos sujetos y pretensiones fuesen los mismos, podrá interponerse en el plazo de diez días recurso por defecto de jurisdicción\"</span>. El plazo es de diez días y se interpone ante el órgano que dictó la resolución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8201","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuestiones de competencia. No podrán suscitarse cuestiones de competencia entre Jueces y Tribunales subordinados entre sí. El Juez o Tribunal Superior fijará, en todo caso, y sin ulterior recurso, su propia competencia, oídas las partes y el Ministerio Fiscal por plazo común de:","o":["cinco días.","quince días.","diez días.","veinte días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">diez días</mark></span>El <span class=\"ref-norma\">art. 52 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"oídas las partes y el Ministerio Fiscal por plazo común de diez días\"</span>. Plazo común de diez días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8301","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Supremo. El Tribunal Supremo, con sede en la villa de Madrid, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de:","o":["garantías Constitucionales.","derecho civil foral o especial.","competencia entre órdenes jurisdiccionales.","responsabilidad de los miembros del Gobierno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">garantías Constitucionales</mark></span>El <span class=\"ref-norma\">art. 53 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías Constitucionales\"</span>. La salvedad es la materia de garantías constitucionales, que corresponde al Tribunal Constitucional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8302","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunal Supremo. El Tribunal Supremo tendrá jurisdicción en toda España y:","o":["su sede podrá fijarse por el Consejo General del Poder Judicial.","su Presidente lo será también del Consejo General del Poder Judicial.","ningún otro Tribunal podrá conocer de recursos de casación.","ningún otro podrá tener el título de Supremo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ningún otro podrá tener el título de Supremo</mark></span>El <span class=\"ref-norma\">art. 53 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Tendrá jurisdicción en toda España y ningún otro podrá tener el título de Supremo\"</span>. Ningún otro Tribunal puede tener el título de Supremo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8333","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Audiencia Nacional. La Audiencia Nacional, con sede en la villa de Madrid:","o":["tiene jurisdicción en toda España.","tiene jurisdicción en la Comunidad de Madrid y en las ciudades de Ceuta y Melilla.","extiende su jurisdicción a las provincias de la península.","tiene jurisdicción solo en materia penal y contencioso-administrativa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tiene jurisdicción en toda España</mark></span>El <span class=\"ref-norma\">art. 62 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Audiencia Nacional, con sede en la villa de Madrid, tiene jurisdicción en toda España\"</span>. Su jurisdicción alcanza a toda España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8473","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Social del TSJ. La Sala de lo Social del Tribunal Superior de Justicia conocerá de las cuestiones de competencia que se susciten:","o":["entre las Salas de lo Social de distintas comunidades autónomas.","entre las Secciones de lo Social y las de lo Mercantil de un mismo Tribunal, en los términos que establezca la ley orgánica.","entre las Secciones de lo Social de los Tribunales de Instancia de la comunidad autónoma.","entre los Tribunales de Instancia y la Audiencia Nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">entre las Secciones de lo Social de los Tribunales de Instancia de la comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 75 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"De las cuestiones de competencia que se susciten entre las Secciones de lo Social de los Tribunales de Instancia de la comunidad autónoma\"</span>. Entre Secciones de lo Social de la comunidad autónoma. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8474","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recusaciones en el TSJ. Cada una de las Salas del Tribunal Superior de Justicia conocerá de las recusaciones que se formulen contra sus Magistrados:","o":["siempre, sin excepciones.","cuando la competencia no corresponda a la Sala especial a que se refiere el artículo siguiente.","cuando la recusación se refiera a su Presidente.","cuando sean más de dos los magistrados recusados, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando la competencia no corresponda a la Sala especial a que se refiere el artículo siguiente</mark></span>El <span class=\"ref-norma\">art. 76 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Cada una de las Salas del Tribunal Superior de Justicia conocerá de las recusaciones que se formulen contra sus Magistrados cuando la competencia no corresponda a la Sala a que se refiere el artículo siguiente\"</span>. Salvo que corresponda a la Sala especial del artículo siguiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8475","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala especial de recusaciones del TSJ. Una Sala constituida por el Presidente del Tribunal Superior de Justicia, los Presidentes de Sala y el Magistrado más moderno de cada una de ellas conocerá de las recusaciones formuladas contra el Presidente, los Presidentes de Sala o de Audiencias Provinciales con sede en la Comunidad Autónoma o de:","o":["dos o más Magistrados de una Sala o Sección o de una Audiencia Provincial.","más de dos Magistrados de una Sala.","cualquier Magistrado de una Audiencia Provincial, sin perjuicio de lo dispuesto en otras leyes.","tres o más Magistrados de una misma Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dos o más Magistrados de una Sala o Sección o de una Audiencia Provincial</mark></span>El <span class=\"ref-norma\">art. 77 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"o de dos o más Magistrados de una Sala o Sección o de una Audiencia Provincial\"</span>. Aquí son dos o más (en el Tribunal Supremo y en la Audiencia Nacional, más de dos). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8476","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Salas con jurisdicción limitada. Cuando el número de asuntos procedentes de determinadas provincias u otras circunstancias lo requieran podrán crearse, con carácter excepcional, Salas de lo Contencioso-Administrativo o de lo Social con jurisdicción limitada a una o varias provincias de la misma Comunidad Autónoma, en cuya capital tendrán su sede. Dichas Salas estarán formadas, como mínimo:","o":["por un Presidente y dos Magistrados.","por tres Magistrados del Tribunal Superior de Justicia.","por su Presidente y un Magistrado de la Audiencia Nacional, en los términos que establezca la ley orgánica.","por su Presidente, y se completarán, en su caso, con Magistrados de la Audiencia Provincial de su sede."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por su Presidente, y se completarán, en su caso, con Magistrados de la Audiencia Provincial de su sede</mark></span>El <span class=\"ref-norma\">art. 78 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Dichas Salas estarán formadas, como mínimo, por su Presidente, y se completarán, en su caso, con Magistrados de la Audiencia Provincial de su sede\"</span>. Mínimo, el Presidente, completado con magistrados de la Audiencia Provincial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8477","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ley de planta. La Ley de planta podrá, en aquellos Tribunales Superiores de Justicia en que el número de asuntos lo justifique:","o":["aumentar el de Salas, hasta un máximo de cinco.","suprimir alguna de las Salas por acuerdo del Consejo General del Poder Judicial, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","reducir el de Magistrados, quedando compuestas las Salas por su respectivo Presidente y por los Presidentes y Magistrados, en su caso, que aquélla determine.","crear Secciones desplazadas fuera de la capital de la comunidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">reducir el de Magistrados, quedando compuestas las Salas por su respectivo Presidente y por los Presidentes y Magistrados, en su caso, que aquélla determine</mark></span>El <span class=\"ref-norma\">art. 79 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La Ley de planta podrá, en aquellos Tribunales Superiores de Justicia en que el número de asuntos lo justifique, reducir el de Magistrados\"</span>. La Ley de planta puede reducir el número de magistrados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8760","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Violencia sobre la Mujer · penal. Las Secciones de Violencia sobre la Mujer conocerán de la instrucción de los procesos para exigir responsabilidad penal por cualquier delito contra las relaciones familiares, cuando:","o":["el autor sea cónyuge o expareja de la víctima, con independencia de quién sea la víctima.","la pena prevista sea superior a tres años.","exista una orden de protección en vigor.","la víctima sea alguna de las personas señaladas en la letra anterior."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la víctima sea alguna de las personas señaladas en la letra anterior</mark></span>El <span class=\"ref-norma\">art. 89.5.b de LOPJ</span> dispone: <span class=\"ref-concepto\">\"b) De la instrucción de los procesos para exigir responsabilidad penal por cualquier delito contra las relaciones familiares, cuando la víctima sea alguna de las personas señaladas en la letra anterior\"</span>. La víctima debe ser alguna de las personas de la letra a). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8778","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Concurrencia de competencias. En caso de que los hechos objeto de instrucción por la Sección de Violencia contra la Infancia y Adolescencia también pudieran ser conocidos por la Sección de Violencia sobre la Mujer, la competencia corresponderá:","o":["a la Sección de Violencia contra la Infancia y la Adolescencia.","en todo caso a la Sección de Violencia sobre la Mujer.","a la que primero haya conocido de los hechos.","a la que designe el Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en todo caso a la Sección de Violencia sobre la Mujer</mark></span>El <span class=\"ref-norma\">art. 89 bis.7 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"la competencia le corresponderá en todo caso a la última\"</span>. Prevalece la Sección de Violencia sobre la Mujer. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8784","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Menores. Las Secciones de Menores que se establezcan con jurisdicción distinta de la provincia:","o":["tomarán el nombre de la provincia en la que se integren, en los términos que establezca la ley orgánica.","tomarán el nombre de la comunidad autónoma.","se denominarán con un número ordinal.","tomarán su nombre de la población donde radique su sede."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tomarán su nombre de la población donde radique su sede</mark></span>El <span class=\"ref-norma\">art. 91.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Tomarán su nombre de la población donde radique su sede\"</span>. Toman el nombre de la población de su sede. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8785","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Menores. Corresponde a las Secciones de Menores de los Tribunales de Instancia el ejercicio de las funciones que establezcan las leyes para con los menores que hubieren incurrido en conductas tipificadas por la ley como:","o":["delito grave exclusivamente.","infracción administrativa o penal.","delito o delito leve.","delito, con exclusión de los delitos leves."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">delito o delito leve</mark></span>El <span class=\"ref-norma\">art. 91.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"las funciones que establezcan las leyes para con los menores que hubieren incurrido en conductas tipificadas por la ley como delito o delito leve\"</span>. Delito o delito leve. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8794","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de lo Social. Las Secciones de lo Social de los Tribunales de Instancia podrán excepcionalmente extender su jurisdicción a dos o más provincias dentro de la misma comunidad autónoma y conocerán, en primera o única instancia:","o":["de los procesos de Seguridad Social exclusivamente.","de los procesos sobre materias propias de este orden jurisdiccional que no estén atribuidos a otros órganos del mismo.","de los conflictos colectivos de ámbito autonómico.","de los recursos de suplicación contra las sentencias del orden social, conforme al procedimiento que establezcan las leyes procesales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de los procesos sobre materias propias de este orden jurisdiccional que no estén atribuidos a otros órganos del mismo</mark></span>El <span class=\"ref-norma\">art. 94 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Las Secciones de lo Social conocerán, en primera o única instancia, de los procesos sobre materias propias de este orden jurisdiccional que no estén atribuidos a otros órganos del mismo\"</span>. Tienen competencia residual en el orden social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8914","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias de los Jueces de Paz. Los Juzgados de Paz conocerán, en el orden civil, de la sustanciación en primera instancia, fallo y ejecución de:","o":["todos los procesos de cuantía inferior a mil quinientos euros, salvo que la ley disponga otra cosa.","los procesos de familia y capacidad.","las diligencias preliminares y la jurisdicción voluntaria.","los procesos que la ley determine y cumplirán también las demás funciones que la ley les atribuya."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los procesos que la ley determine y cumplirán también las demás funciones que la ley les atribuya</mark></span>El <span class=\"ref-norma\">art. 100.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Juzgados de Paz conocerán, en el orden civil, de la sustanciación en primera instancia, fallo y ejecución de los procesos que la ley determine y cumplirán también las demás funciones que la ley les atribuya\"</span>. Los procesos que la ley determine. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8915","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Competencias de los Jueces de Paz. En el orden penal, los Juzgados de Paz conocerán en primera instancia de los procesos por delito leve que les atribuya la ley y podrán intervenir, igualmente:","o":["en la instrucción de delitos menos graves por delegación del Fiscal, conforme al procedimiento que establezcan las leyes procesales.","en la ejecución de sentencias penales firmes.","en actuaciones penales de prevención, o por delegación, y en aquellas otras que señalen las leyes.","en las diligencias de investigación de la Policía Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en actuaciones penales de prevención, o por delegación, y en aquellas otras que señalen las leyes</mark></span>El <span class=\"ref-norma\">art. 100.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Podrán intervenir, igualmente, en actuaciones penales de prevención, o por delegación, y en aquellas otras que señalen las leyes\"</span>. Actuaciones de prevención, por delegación y las que señalen las leyes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8922","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Requisitos de los Jueces de Paz. Podrán ser nombrados Jueces de Paz, tanto titular como sustituto, quienes, aun no siendo licenciados en Derecho, reúnan los requisitos establecidos en esta ley para el ingreso en la Carrera Judicial, y no estén incursos en causas de incapacidad o de incompatibilidad, a excepción:","o":["del ejercicio de cargos de elección popular.","del ejercicio de la Abogacía y la Procuraduría.","del desempeño de cargos políticos de libre designación, salvo que la ley disponga otra cosa.","del ejercicio de actividades profesionales o mercantiles."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">del ejercicio de actividades profesionales o mercantiles</mark></span>El <span class=\"ref-norma\">art. 102 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"no estén incursos en ninguna de las causas de incapacidad o de incompatibilidad previstas para el desempeño de las funciones judiciales, a excepción del ejercicio de actividades profesionales o mercantiles\"</span>. Se exceptúa el ejercicio de actividades profesionales o mercantiles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8923","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Estatuto de los Jueces de Paz. Los Jueces de Paz y los sustitutos, en su caso, cesarán:","o":["por acuerdo del Ayuntamiento que los eligió.","por cumplir sesenta y cinco años.","por el transcurso de su mandato y por las mismas causas que los Jueces de carrera en cuanto les sean de aplicación.","por decisión del Juez de Primera Instancia e Instrucción, conforme al procedimiento que establezcan las leyes procesales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por el transcurso de su mandato y por las mismas causas que los Jueces de carrera en cuanto les sean de aplicación</mark></span>El <span class=\"ref-norma\">art. 103 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Jueces de Paz y los sustitutos, en su caso, cesarán por el transcurso de su mandato y por las mismas causas que los Jueces de carrera en cuanto les sean de aplicación\"</span>. Por el transcurso del mandato y las causas aplicables a los jueces de carrera. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8937","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jubilación por incapacidad. Cuando en un Juez o Magistrado se apreciare incapacidad permanente, la Sala de Gobierno respectiva, por sí, a instancia del Ministerio Fiscal o del interesado:","o":["formulará propuesta de jubilación al Consejo General del Poder Judicial.","acordará la jubilación directamente.","remitirá el expediente al Tribunal Supremo, sin perjuicio de lo dispuesto en otras leyes.","suspenderá provisionalmente al Juez."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">formulará propuesta de jubilación al Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 387 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"la Sala de Gobierno respectiva, por sí, a instancia del Ministerio Fiscal o del interesado, formulará propuesta de jubilación al Consejo General del Poder Judicial\"</span>. Formula propuesta; resuelve el CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8938","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Jubilación por incapacidad. Los jubilados por incapacidad permanente:","o":["no podrán volver al servicio activo en ningún caso.","podrán volver al servicio activo transcurridos cinco años, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","podrán ser rehabilitados con autorización del Gobierno.","podrán ser rehabilitados y volver al servicio activo si acreditaren haber desaparecido la causa que hubiere motivado la jubilación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">podrán ser rehabilitados y volver al servicio activo si acreditaren haber desaparecido la causa que hubiere motivado la jubilación</mark></span>El <span class=\"ref-norma\">art. 387.3 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los jubilados por incapacidad permanente podrán ser rehabilitados y volver al servicio activo si acreditaren haber desaparecido la causa que hubiere motivado la jubilación\"</span>. Pueden rehabilitarse si desaparece la causa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8939","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Procedimientos. Los procedimientos de separación, traslado, jubilación por incapacidad permanente y rehabilitación se formarán con audiencia del interesado e informe del Ministerio Fiscal y de la Sala de Gobierno respectiva y se resolverán por:","o":["el Tribunal Supremo.","la Sala de Gobierno respectiva, conforme al procedimiento que establezcan las leyes procesales.","el Consejo General del Poder Judicial.","el Ministerio de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 388 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se formarán con audiencia del interesado e informe del Ministerio Fiscal y de la Sala de Gobierno respectiva, sin perjuicio de las demás justificaciones que procedan, y se resolverán por el Consejo General del Poder Judicial\"</span>. Resuelve el CGPJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9056","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidad en el nombramiento. Cuando un nombramiento dé lugar a una situación de incompatibilidad de las previstas en los artículos anteriores:","o":["se destinará al Juez a otro cargo con carácter voluntario.","se suspenderá el nombramiento hasta que cese la incompatibilidad.","se anulará el nombramiento y se declarará la pérdida de la condición de Juez, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","quedará el mismo sin efecto y se destinará con carácter forzoso al Juez o Magistrado, sin perjuicio de la responsabilidad disciplinaria en que hubiera podido incurrirse."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">quedará el mismo sin efecto y se destinará con carácter forzoso al Juez o Magistrado, sin perjuicio de la responsabilidad disciplinaria en que hubiera podido incurrirse</mark></span>El <span class=\"ref-norma\">art. 394.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Cuando un nombramiento dé lugar a una situación de incompatibilidad de las previstas en los artículos anteriores quedará el mismo sin efecto y se destinará con carácter forzoso al Juez o Magistrado, sin perjuicio de la responsabilidad disciplinaria en que hubiera podido incurrirse\"</span>. El nombramiento queda sin efecto y se destina con carácter forzoso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9057","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Incompatibilidad sobrevenida. Cuando la situación de incompatibilidad apareciere en virtud de circunstancias sobrevenidas, el Consejo General del Poder Judicial procederá al traslado forzoso del Juez o Magistrado. El destino forzoso será a cargo que no implique cambio de residencia si existiera vacante, y en tal caso ésta:","o":["se anunciará a concurso de provisión en el plazo de un mes.","se cubrirá con carácter provisional.","no será anunciada a concurso de provisión.","se declarará de libre designación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no será anunciada a concurso de provisión</mark></span>El <span class=\"ref-norma\">art. 394.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El destino forzoso será a cargo que no implique cambio de residencia si existiera vacante, y en tal caso ésta no será anunciada a concurso de provisión\"</span>. La vacante no se anuncia a concurso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9060","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Deber de reserva. Los Jueces y Magistrados no podrán revelar los hechos o noticias referentes a personas físicas o jurídicas:","o":["que consten en procedimientos con declaración de secreto de sumario exclusivamente.","cuya publicación pueda perjudicar a las partes.","que hayan conocido en su vida privada.","de los que hayan tenido conocimiento en el ejercicio de sus funciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de los que hayan tenido conocimiento en el ejercicio de sus funciones</mark></span>El <span class=\"ref-norma\">art. 396 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Los Jueces y Magistrados no podrán revelar los hechos o noticias referentes a personas físicas o jurídicas de los que hayan tenido conocimiento en el ejercicio de sus funciones\"</span>. Deber de reserva respecto de lo conocido en el ejercicio de sus funciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9064","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Inmunidad judicial. Las autoridades civiles y militares se abstendrán de intimar a los Jueces y Magistrados y de citarlos para que comparezcan a su presencia. Cuando una Autoridad civil o militar precise de datos o declaraciones que pueda facilitar un Juez o Magistrado, y que no se refieran a su cargo o función:","o":["se solicitarán a través del Consejo General del Poder Judicial, salvo que la ley disponga otra cosa.","se recibirán en la sede de la autoridad solicitante.","se solicitarán mediante oficio al Presidente del Tribunal.","se solicitarán por escrito o se recibirán en el despacho oficial de aquél, previo aviso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se solicitarán por escrito o se recibirán en el despacho oficial de aquél, previo aviso</mark></span>El <span class=\"ref-norma\">art. 399.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"se solicitarán por escrito o se recibirán en el despacho oficial de aquél, previo aviso\"</span>. Por escrito o en el despacho del Juez, previo aviso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9065","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Auxilio y cooperación. Cuando se trate de auxilio o cooperación por razón del cargo o de la función jurisdiccional, se prestará sin tardanza, salvo que el acto a ejecutar no esté legalmente permitido o se perjudique la competencia propia del Juez o Tribunal. La denegación:","o":["se comunicará al Consejo General del Poder Judicial, conforme al procedimiento que establezcan las leyes procesales.","no necesitará ser motivada.","se comunicará a la autoridad peticionaria con expresión suficiente de la razón que la justifique.","se notificará al Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se comunicará a la autoridad peticionaria con expresión suficiente de la razón que la justifique</mark></span>El <span class=\"ref-norma\">art. 399.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La denegación se comunicará a la autoridad peticionaria con expresión suficiente de la razón que la justifique\"</span>. Se comunica motivadamente a la autoridad peticionaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9066","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Declaración de Jueces y Magistrados. Cuando en la instrucción de una causa penal fuere necesaria la declaración de un Juez o Magistrado, y esta pudiera prestarse legalmente, no podrá excusarse aquél de hacerlo. Si la autoridad judicial que hubiera de recibir la declaración fuere de categoría inferior:","o":["citará al Juez o Magistrado en su sede.","acudirá al despacho oficial del Juez o Magistrado, previo aviso, señalándose día y hora.","solicitará al Presidente del Tribunal que designe a otro juez, sin perjuicio de lo dispuesto en otras leyes.","recibirá la declaración por escrito."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">acudirá al despacho oficial del Juez o Magistrado, previo aviso, señalándose día y hora</mark></span>El <span class=\"ref-norma\">art. 400 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Si la autoridad judicial que hubiera de recibir la declaración fuere de categoría inferior, acudirá al despacho oficial del Juez o Magistrado, previo aviso, señalándose día y hora\"</span>. La autoridad inferior acude al despacho oficial, previo aviso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9067","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Asociación profesional. De acuerdo con lo establecido en el artículo 127 de la Constitución, se reconoce el derecho de libre asociación profesional de jueces y magistrados integrantes de la Carrera Judicial. Las asociaciones de jueces y magistrados tendrán personalidad jurídica y plena capacidad para el cumplimiento de sus fines, y podrán tener como fines lícitos la defensa de los intereses profesionales de sus miembros y:","o":["la realización de actividades encaminadas al servicio de la Justicia en general.","la representación del Poder Judicial ante las Cortes Generales, en los términos que establezca la ley orgánica.","la defensa de los intereses políticos de sus miembros.","la negociación colectiva de las retribuciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la realización de actividades encaminadas al servicio de la Justicia en general</mark></span>El <span class=\"ref-norma\">art. 401 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Podrán tener como fines lícitos la defensa de los intereses profesionales de sus miembros en todos los aspectos y la realización de actividades encaminadas al servicio de la Justicia en general\"</span>. No podrán llevar a cabo actividades políticas ni tener vinculaciones con partidos o sindicatos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9068","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Asociación profesional. Las asociaciones de jueces y magistrados deberán tener ámbito nacional, sin perjuicio de la existencia de:","o":["secciones provinciales con personalidad jurídica propia, salvo que la ley disponga otra cosa.","delegaciones en cada partido judicial.","federaciones de asociaciones autonómicas.","secciones cuyo ámbito coincida con el de un Tribunal Superior de Justicia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">secciones cuyo ámbito coincida con el de un Tribunal Superior de Justicia</mark></span>El <span class=\"ref-norma\">art. 401 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"deberán tener ámbito nacional, sin perjuicio de la existencia de secciones cuyo ámbito coincida con el de un Tribunal Superior de Justicia\"</span>. Ámbito nacional, con secciones coincidentes con un TSJ. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9073","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Asociación profesional. La suspensión o disolución de las asociaciones profesionales de jueces y magistrados quedará sometida:","o":["a la decisión del Consejo General del Poder Judicial, sin perjuicio de lo dispuesto en otras leyes.","al régimen disciplinario de la Carrera Judicial.","al régimen establecido para el derecho de asociación en general.","a la autorización previa del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al régimen establecido para el derecho de asociación en general</mark></span>El <span class=\"ref-norma\">art. 401 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"La suspensión o disolución de las asociaciones profesionales quedará sometida al régimen establecido para el derecho de asociación en general\"</span>. Se rige por el régimen general del derecho de asociación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9074","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Independencia económica. El Estado garantiza la independencia económica de los Jueces y Magistrados mediante una retribución adecuada a la dignidad de la función jurisdiccional. También garantizará:","o":["una pensión de jubilación equivalente al último sueldo, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa.","un régimen de Seguridad Social que proteja a los Jueces y Magistrados y a sus familiares durante el servicio activo y la jubilación.","un régimen de mutualismo administrativo exclusivo.","la exención de impuestos sobre sus retribuciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un régimen de Seguridad Social que proteja a los Jueces y Magistrados y a sus familiares durante el servicio activo y la jubilación</mark></span>El <span class=\"ref-norma\">art. 402 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"También garantizará un régimen de Seguridad Social que proteja a los Jueces y Magistrados y a sus familiares durante el servicio activo y la jubilación\"</span>. Régimen de Seguridad Social durante el servicio activo y la jubilación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9075","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Retribuciones. El régimen de retribuciones de los jueces y magistrados se inspirará en los principios de objetividad, equidad, transparencia y estabilidad, atendiendo para su fijación a la dedicación a la función jurisdiccional, a la categoría y:","o":["al tiempo de prestación de servicios.","a la carga de trabajo del órgano, conforme al procedimiento que establezcan las leyes procesales.","a la antigüedad en el escalafón.","a los resultados obtenidos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al tiempo de prestación de servicios</mark></span>El <span class=\"ref-norma\">art. 403.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"atendiendo para su fijación a la dedicación a la función jurisdiccional, a la categoría y al tiempo de prestación de servicios\"</span>. Dedicación, categoría y tiempo de servicios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9079","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Presupuestos. Los Presupuestos Generales del Estado contendrán, junto a las demás partidas correspondientes a retribuciones de jueces y magistrados, una consignación anual para la dotación de:","o":["los jueces y juezas de paz, otras atenciones de personal judicial y demás exigencias de la Administración de Justicia.","los Letrados de la Administración de Justicia y los fiscales, conforme al procedimiento que establezcan las leyes procesales.","los Tribunales Superiores de Justicia en exclusiva.","el Consejo General del Poder Judicial y el Tribunal Supremo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los jueces y juezas de paz, otras atenciones de personal judicial y demás exigencias de la Administración de Justicia</mark></span>El <span class=\"ref-norma\">art. 404 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"los Presupuestos Generales del Estado contendrán una consignación anual para la dotación de los jueces y juezas de paz, otras atenciones de personal judicial a que den lugar los preceptos de esta ley y demás exigencias de la Administración de Justicia\"</span>. Incluye a los jueces de paz. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9084","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Responsabilidad penal. Cuando otras Autoridades judiciales tuvieren conocimiento, a través de las actuaciones en que intervinieren, de la posible comisión de un delito o falta por un Juez o Magistrado en el ejercicio de su cargo, lo comunicarán al Juez o Tribunal competente:","o":["sin oír al Ministerio Fiscal, con remisión de testimonio.","previa autorización del Consejo General del Poder Judicial, sin perjuicio de lo dispuesto en otras leyes.","tras dar audiencia al Juez afectado.","oído el Ministerio Fiscal, con remisión de los antecedentes necesarios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">oído el Ministerio Fiscal, con remisión de los antecedentes necesarios</mark></span>El <span class=\"ref-norma\">art. 408 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"lo comunicarán al Juez o Tribunal competente, oído el Ministerio Fiscal, con remisión de los antecedentes necesarios\"</span>. Oído el Ministerio Fiscal y con remisión de antecedentes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9093","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Procuradores. Corresponde exclusivamente a los procuradores la representación de las partes en todo tipo de procesos, salvo:","o":["cuando la parte comparezca asistida de abogado.","cuando la cuantía sea inferior a seis mil euros.","cuando la ley autorice otra cosa.","cuando se trate de procesos penales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuando la ley autorice otra cosa</mark></span>El <span class=\"ref-norma\">art. 543.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"Corresponde exclusivamente a los procuradores la representación de las partes en todo tipo de procesos, salvo cuando la ley autorice otra cosa\"</span>. Salvo que la ley autorice otra cosa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9094","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Procuradores. Por delegación del juez, jueza o tribunal, los procuradores podrán también realizar las actuaciones materiales propias del proceso de ejecución en los términos establecidos legalmente que, en todo caso, excluirán:","o":["las ejecuciones de sentencias penales y las de resoluciones administrativas, en los términos que establezca la ley orgánica, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","las ejecuciones hipotecarias de vivienda habitual, las derivadas de procesos en materia de familia, las de desahucio por impago de rentas o cantidades debidas en viviendas habituales y los lanzamientos de ocupantes de finca con posterioridad a la subasta si esta es vivienda habitual.","las ejecuciones de cuantía superior a seis mil euros.","las ejecuciones dinerarias de entidades públicas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las ejecuciones hipotecarias de vivienda habitual, las derivadas de procesos en materia de familia, las de desahucio por impago de rentas o cantidades debidas en viviendas habituales y los lanzamientos de ocupantes de finca con posterioridad a la subasta si esta es vivienda habitual</mark></span>El <span class=\"ref-norma\">art. 543.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"que, en todo caso, excluirán las ejecuciones hipotecarias de vivienda habitual, así como las derivadas de procesos en materia de familia, las de desahucio por impago de rentas o cantidades debidas en viviendas habituales y los lanzamientos de ocupantes de finca con posterioridad a la subasta de la misma si esta es vivienda habitual\"</span>. Quedan excluidas las ejecuciones sobre vivienda habitual y las de familia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9095","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Procuradores. En el ejercicio de su profesión los procuradores podrán ser sustituidos por otro procurador. También, para los actos y en la forma que se determine reglamentariamente, podrán ser sustituidos:","o":["por oficial habilitado.","por abogado colegiado.","por Letrado de la Administración de Justicia.","por un graduado social."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por oficial habilitado</mark></span>El <span class=\"ref-norma\">art. 543.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"También para los actos y en la forma que se determine reglamentariamente podrán ser sustituidos por oficial habilitado\"</span>. Por oficial habilitado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9102","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Funciones de la Policía Judicial. Corresponden específicamente a las unidades de Policía Judicial, entre otras funciones, la averiguación acerca de los responsables y circunstancias de los hechos delictivos y la detención de los primeros, dando cuenta seguidamente:","o":["al Ministerio del Interior, conforme a la normativa, conforme al procedimiento que establezcan las leyes procesales.","a la autoridad judicial y fiscal, conforme a lo dispuesto en las leyes.","al Presidente del Tribunal Superior de Justicia.","a la Sala de Gobierno del Tribunal Supremo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la autoridad judicial y fiscal, conforme a lo dispuesto en las leyes</mark></span>El <span class=\"ref-norma\">art. 549.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"a) La averiguación acerca de los responsables y circunstancias de los hechos delictivos y la detención de los primeros, dando cuenta seguidamente a la autoridad judicial y fiscal, conforme a lo dispuesto en las leyes\"</span>. Se da cuenta a la autoridad judicial y fiscal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9103","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Funciones de la Policía Judicial. En ningún caso podrán encomendarse a los miembros de las unidades de Policía Judicial:","o":["la práctica de actuaciones que no sean las propias de la Policía Judicial o las derivadas de las mismas.","actuaciones fuera de su sede en auxilio de la autoridad judicial.","la detención de los responsables de hechos delictivos.","la garantía del cumplimiento de las órdenes de la autoridad fiscal, sin perjuicio de lo dispuesto en otras leyes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la práctica de actuaciones que no sean las propias de la Policía Judicial o las derivadas de las mismas</mark></span>El <span class=\"ref-norma\">art. 549.2 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En ningún caso podrán encomendarse a los miembros de dichas unidades la práctica de actuaciones que no sean las propias de la Policía Judicial o las derivadas de las mismas\"</span>. Solo actuaciones propias de la Policía Judicial o derivadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 quinquies","q":[{"i":"8-ia-8064","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Foros especiales. En defecto de sumisión expresa o tácita y aunque el demandado no tuviera su domicilio en España, los Tribunales españoles serán competentes en materia de obligaciones contractuales, cuando la obligación objeto de la demanda:","o":["haya sido contraída por un español.","se haya cumplido o deba cumplirse en España.","se haya contraído en territorio español, conforme al procedimiento que establezcan las leyes procesales.","se refiera a bienes situados en España."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se haya cumplido o deba cumplirse en España</mark></span>El <span class=\"ref-norma\">art. 22 quinquies de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En materia de obligaciones contractuales, cuando la obligación objeto de la demanda se haya cumplido o deba cumplirse en España\"</span>. El foro es el lugar de cumplimiento de la obligación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8065","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Foros especiales. En materia de obligaciones extracontractuales, los Tribunales españoles serán competentes, aunque el demandado no tuviera su domicilio en España y en defecto de sumisión, cuando:","o":["el hecho dañoso se haya producido en territorio español.","el perjudicado tenga su residencia habitual en España.","el autor del daño sea de nacionalidad española.","el daño se haya producido a un bien español, con independencia del lugar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el hecho dañoso se haya producido en territorio español</mark></span>El <span class=\"ref-norma\">art. 22 quinquies de LOPJ</span> dispone: <span class=\"ref-concepto\">\"En materia de obligaciones extracontractuales, cuando el hecho dañoso se haya producido en territorio español\"</span>. El foro es el lugar donde se produjo el hecho dañoso. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8066","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Foros especiales. En materia de contratos celebrados por consumidores, estos podrán litigar en España si tienen su residencia habitual en territorio español o si lo tuviera la otra parte contratante; esta última solo podrá litigar en España:","o":["si el consumidor tiene su domicilio en España o el contrato se celebró en España.","si ambas partes tienen su residencia habitual en territorio español.","si el consumidor ha aceptado expresamente la jurisdicción española.","si el consumidor tiene su residencia habitual en territorio español."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">si el consumidor tiene su residencia habitual en territorio español</mark></span>El <span class=\"ref-norma\">art. 22 quinquies.d de LOPJ</span> dispone: <span class=\"ref-concepto\">\"esta última solo podrá litigar en España si el consumidor tiene su residencia habitual en territorio español\"</span>. La contraparte solo puede litigar en España si el consumidor reside habitualmente en España. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9112","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Obligaciones contractuales. En defecto de sumisión y aunque el demandado no tuviera su domicilio en España, los Tribunales españoles serán competentes en materia de obligaciones contractuales cuando la obligación objeto de la demanda:","o":["se haya cumplido o deba cumplirse en España.","se haya contraído entre españoles.","tenga por objeto bienes situados en España, en los términos que determine la ley orgánica correspondiente.","se haya firmado ante notario español."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">se haya cumplido o deba cumplirse en España</mark></span>El <span class=\"ref-norma\">art. 22 quinquies.a) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando la obligación objeto de la demanda se haya cumplido o deba cumplirse en España.\"</span> Cumplida o por cumplir en España."},{"i":"8-ia-9113","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Obligaciones extracontractuales. En materia de obligaciones extracontractuales, los Tribunales españoles serán competentes cuando:","o":["el demandante tenga su domicilio en España, salvo que el órgano competente acuerde otra cosa de forma motivada.","el responsable sea español.","la víctima sea española.","el hecho dañoso se haya producido en territorio español."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el hecho dañoso se haya producido en territorio español</mark></span>El <span class=\"ref-norma\">art. 22 quinquies.b) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando el hecho dañoso se haya producido en territorio español.\"</span> Hecho dañoso en España."},{"i":"8-ia-9114","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sucursales. En las acciones relativas a la explotación de una sucursal, agencia o establecimiento mercantil, los Tribunales españoles serán competentes cuando éste:","o":["pertenezca a una sociedad española.","se encuentre en territorio español.","tenga más de diez empleados.","esté inscrito en el Registro Mercantil Central."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se encuentre en territorio español</mark></span>El <span class=\"ref-norma\">art. 22 quinquies.c) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando éste se encuentre en territorio español.\"</span> Establecimiento en territorio español."}]},{"a":"Artículo 39 ✱","q":[{"i":"8-ia-8190","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de Conflictos de Jurisdicción. Los conflictos de jurisdicción entre los Juzgados o Tribunales de cualquier orden jurisdiccional de la jurisdicción ordinaria y los órganos judiciales militares serán resueltos por la Sala de Conflictos de Jurisdicción, compuesta por el Presidente del Tribunal Supremo, que la presidirá, dos Magistrados de la Sala del Tribunal Supremo del orden jurisdiccional en conflicto y:","o":["un Magistrado de la Sala de lo Militar y un Consejero Permanente de Estado.","dos Magistrados de la Sala de lo Militar, todos ellos designados por el Pleno del Consejo General del Poder Judicial.","tres Magistrados de la Sala de lo Penal designados por la Sala de Gobierno.","dos Fiscales de la Sala de lo Militar designados por el Fiscal General del Estado, salvo que la ley disponga otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dos Magistrados de la Sala de lo Militar, todos ellos designados por el Pleno del Consejo General del Poder Judicial</mark></span>El <span class=\"ref-norma\">art. 39 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"dos Magistrados de la Sala del Tribunal Supremo del orden jurisdiccional en conflicto y dos Magistrados de la Sala de lo Militar, todos ellos designados por el Pleno del Consejo General del Poder Judicial\"</span>. Dos magistrados de la Sala en conflicto y dos de la Sala de lo Militar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 87 EX","q":[{"i":"8-ia-8342","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Penal de la Audiencia Nacional. La Sala de lo Penal de la Audiencia Nacional conocerá de los delitos atribuidos a la Fiscalía Europea en los artículos 22 y 25 del Reglamento (UE) 2017/1939 del Consejo, de 12 de octubre de 2017, cuando:","o":["lo solicite el Fiscal General del Estado.","el delito afecte a intereses financieros de más de un Estado miembro.","el Tribunal Supremo no sea competente.","aquella hubiera decidido ejercer su competencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">aquella hubiera decidido ejercer su competencia</mark></span>El <span class=\"ref-norma\">art. 65 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando aquella hubiera decidido ejercer su competencia\"</span>. Basta que la Fiscalía Europea decida ejercer su competencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 67 EXOF","q":[{"i":"8-ia-8350","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Social de la Audiencia Nacional. La Sala de lo Social de la Audiencia Nacional conocerá en única instancia de los procesos especiales de impugnación de convenios colectivos cuyo ámbito territorial de aplicación sea:","o":["superior al territorio de una provincia.","nacional exclusivamente.","superior al territorio de dos Comunidades Autónomas.","superior al territorio de una Comunidad Autónoma."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">superior al territorio de una Comunidad Autónoma</mark></span>El <span class=\"ref-norma\">art. 67 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"conocerá en única instancia: 1.º De los procesos especiales de impugnación de convenios colectivos cuyo ámbito territorial de aplicación sea superior al territorio de una Comunidad Autónoma\"</span>. El umbral es superar el territorio de una Comunidad Autónoma. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8472","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Social del TSJ. La Sala de lo Social del Tribunal Superior de Justicia conocerá en única instancia de los procesos que la ley establezca sobre controversias que afecten a intereses de los trabajadores y empresarios en ámbito superior al de una Sección de lo Social del Tribunal de Instancia y:","o":["no superior al de la provincia.","superior al de la comunidad autónoma.","no superior al de dos comunidades autónomas.","no superior al de la comunidad autónoma."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no superior al de la comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 75 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"en ámbito superior al de una Sección de lo Social del Tribunal de Instancia y no superior al de la comunidad autónoma\"</span>. Si supera el ámbito autonómico, corresponde a la Audiencia Nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-9137","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sala de lo Social. La Sala de lo Social del Tribunal Superior de Justicia conocerá en única instancia de los procesos que la ley establezca sobre controversias que afecten a intereses de los trabajadores y empresarios en ámbito superior al de una Sección de lo Social del Tribunal de Instancia y:","o":["no superior al nacional.","no superior al de la provincia.","no superior al del partido judicial, sin perjuicio de lo que establezcan los tratados internacionales.","no superior al de la comunidad autónoma."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no superior al de la comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 75.1.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"en ámbito superior al de una Sección de lo Social del Tribunal de Instancia y no superior al de la comunidad autónoma.\"</span> Hasta el ámbito de la comunidad autónoma."}]},{"a":"Artículo 70 EXOF","q":[{"i":"8-ia-8352","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales Superiores de Justicia. El Tribunal Superior de Justicia de la Comunidad Autónoma culminará la organización judicial en el ámbito territorial de aquélla, sin perjuicio de:","o":["las competencias de la Audiencia Nacional.","la jurisdicción que corresponde al Tribunal Supremo.","las atribuciones del Consejo General del Poder Judicial.","las competencias de la Comunidad Autónoma en materia de justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la jurisdicción que corresponde al Tribunal Supremo</mark></span>El <span class=\"ref-norma\">art. 70 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"culminará la organización judicial en el ámbito territorial de aquélla, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo\"</span>. Sin perjuicio de la jurisdicción del Tribunal Supremo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 71 EXOF","q":[{"i":"8-ia-8353","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Tribunales Superiores de Justicia. El Tribunal Superior de Justicia:","o":["tomará el nombre de la Comunidad Autónoma y extenderá su jurisdicción al ámbito territorial de ésta.","tomará el nombre de la capital de la Comunidad Autónoma y extenderá su jurisdicción a las provincias de ésta.","tendrá su sede en Madrid y jurisdicción en todo el territorio autonómico.","tomará el nombre de la Comunidad Autónoma y su jurisdicción será provincial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">tomará el nombre de la Comunidad Autónoma y extenderá su jurisdicción al ámbito territorial de ésta</mark></span>El <span class=\"ref-norma\">art. 71 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Superior de Justicia tomará el nombre de la Comunidad Autónoma y extenderá su jurisdicción al ámbito territorial de ésta\"</span>. Toma el nombre de la Comunidad Autónoma y su jurisdicción es autonómica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 88 EXOF EX ✱","q":[{"i":"8-ia-8640","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Instrucción. Con carácter general, en los Tribunales de Instancia, las Secciones de Instrucción o las Secciones Únicas extenderán su jurisdicción a un partido judicial. Estas Secciones conocerán, en el orden penal, de la instrucción de las causas por delito cuyo enjuiciamiento corresponda a las Audiencias Provinciales y a las Secciones de lo Penal de los Tribunales de Instancia, excepto de aquellas causas que sean competencia de:","o":["las Secciones de Menores y de Vigilancia Penitenciaria.","las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia.","la Audiencia Nacional y los Tribunales Superiores de Justicia, conforme al procedimiento que establezcan las leyes procesales.","las Secciones de lo Penal de la capital de provincia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia</mark></span>El <span class=\"ref-norma\">art. 88.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"excepto de la instrucción de aquellas causas que sean competencia de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia\"</span>. Se exceptúan las de Violencia sobre la Mujer y de Violencia contra la Infancia y la Adolescencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8641","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Instrucción. Las Secciones de Instrucción de los Tribunales de Instancia conocerán, en el orden penal, de la adopción de la orden de protección a las víctimas de violencia sobre la mujer, infancia y adolescencia cuando esté desarrollando funciones de guardia, siempre que:","o":["no pueda ser adoptada por el juez de la Sección de Violencia sobre la Mujer o de la Sección correspondiente que asuma el conocimiento de estos asuntos.","lo solicite el Ministerio Fiscal en el plazo de 24 horas.","la víctima haya presentado denuncia ante la Policía Judicial, sin perjuicio de lo dispuesto en otras leyes, en los términos que establezca la ley orgánica.","no esté personado el presunto agresor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no pueda ser adoptada por el juez de la Sección de Violencia sobre la Mujer o de la Sección correspondiente que asuma el conocimiento de estos asuntos</mark></span>El <span class=\"ref-norma\">art. 88.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"siempre que no pueda ser adoptada por el juez, la jueza, el magistrado o la magistrada de la Sección de Violencia sobre la Mujer o de la Sección correspondiente que asuma el conocimiento de estos asuntos\"</span>. Solo si no puede adoptarla el juez de la Sección de Violencia competente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8642","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Secciones de Instrucción. Las Secciones de Instrucción de los Tribunales de Instancia conocerán, en el orden penal, del conocimiento y fallo de los juicios por delito leve, salvo los que sean competencia de:","o":["las Audiencias Provinciales o las Secciones de lo Penal.","los Tribunales Superiores de Justicia o la Audiencia Nacional.","las Secciones de Menores o los Letrados de la Administración de Justicia, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales.","los jueces y juezas de paz o de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los jueces y juezas de paz o de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia</mark></span>El <span class=\"ref-norma\">art. 88.1 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"c) Del conocimiento y fallo de los juicios por delito leve, salvo los que sean competencia de los jueces y juezas de paz o de las Secciones de Violencia sobre la Mujer o de la Sección de Violencia contra la Infancia y la Adolescencia\"</span>. Salvo los de los jueces de paz y las Secciones de Violencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8646","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Agrupación de Secciones de Instrucción. Excepcionalmente, el Consejo General del Poder Judicial, con informe de la Fiscalía General del Estado, podrá acordar la agrupación de las Secciones de Instrucción y de las Secciones Únicas de varios partidos judiciales limítrofes, dentro de una misma provincia, siempre que se produzca un destacado aumento en el volumen de asuntos penales por razón del incremento de las actividades delictivas de organizaciones criminales vinculadas:","o":["al tráfico de armas o al blanqueo de capitales.","al terrorismo o a la corrupción pública.","a los delitos informáticos o contra la propiedad intelectual.","al tráfico de drogas o personas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al tráfico de drogas o personas</mark></span>El <span class=\"ref-norma\">art. 88.4 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"por razón del incremento de las actividades delictivas de organizaciones criminales vinculadas al tráfico de drogas o personas, se produzca un destacado aumento en el volumen de asuntos penales de esta naturaleza\"</span>. Tráfico de drogas o personas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"8-ia-8753","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Agrupación de Secciones de Instrucción. El reparto de asuntos entre las diferentes Secciones agrupadas se realizará por:","o":["el Presidente de la Audiencia Provincial.","el Fiscal Jefe de la provincia.","el letrado o la letrada directores del Servicio Común General del Tribunal de Instancia con mayor número de habitantes de entre los que componen la agrupación.","el juez decano de la capital de la provincia, salvo que la ley disponga otra cosa, conforme al procedimiento que establezcan las leyes procesales, sin perjuicio de lo dispuesto en otras leyes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el letrado o la letrada directores del Servicio Común General del Tribunal de Instancia con mayor número de habitantes de entre los que componen la agrupación</mark></span>El <span class=\"ref-norma\">art. 88.6 de LOPJ</span> dispone: <span class=\"ref-concepto\">\"El reparto de asuntos entre las diferentes Secciones se realizará por el letrado o la letrada directores del Servicio Común General del Tribunal de Instancia con mayor número de habitantes de entre los que componen la agrupación\"</span>. El reparto lo hace el letrado director del Servicio Común General del Tribunal con más habitantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"De la colaboración con los Juzgados y Tribunales","q":[{"i":"8-ia-9107","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Deber de colaboración. Todas las personas y entidades públicas y privadas están obligadas a prestar la colaboración requerida por los Jueces y Tribunales en el curso del proceso y en la ejecución de lo resuelto, sin perjuicio:","o":["de la prioridad de los asuntos de la Administración.","del resarcimiento de los gastos y del abono de las remuneraciones debidas que procedan conforme a la ley.","de la libertad de los requeridos para negarse a ello, sin perjuicio de lo que establezcan los tratados internacionales.","de la autorización previa del Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del resarcimiento de los gastos y del abono de las remuneraciones debidas que procedan conforme a la ley</mark></span>El <span class=\"ref-norma\">art. 17.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"y sin perjuicio del resarcimiento de los gastos y del abono de las remuneraciones debidas que procedan conforme a la ley.\"</span> Se resarcen los gastos y se abonan las remuneraciones."},{"i":"8-ia-9108","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cumplimiento de las resoluciones. Las Administraciones Públicas, las autoridades y funcionarios y los particulares respetarán y cumplirán las sentencias y demás resoluciones judiciales:","o":["que hayan ganado firmeza o sean ejecutables de acuerdo con las leyes.","únicamente cuando hayan ganado firmeza.","cuando lo autorice el Ministerio Fiscal.","una vez publicadas en el boletín oficial, en los términos que determine la ley orgánica correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">que hayan ganado firmeza o sean ejecutables de acuerdo con las leyes</mark></span>El <span class=\"ref-norma\">art. 17.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"que hayan ganado firmeza o sean ejecutables de acuerdo con las leyes.\"</span> Firmes o ejecutables."}]},{"a":"De la competencia internacional","q":[{"i":"8-ia-9110","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Domicilio de la persona física. A los efectos de la competencia internacional, se entenderá que una persona física está domiciliada en España cuando tenga en ella:","o":["su nacionalidad.","su residencia habitual.","su lugar de trabajo.","su inscripción en el padrón durante un año."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">su residencia habitual</mark></span>El <span class=\"ref-norma\">art. 22 ter.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"una persona física está domiciliada en España cuando tenga en ella su residencia habitual.\"</span> Residencia habitual."},{"i":"8-ia-9111","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Pluralidad de demandados. En caso de pluralidad de demandados, serán competentes los Tribunales españoles cuando:","o":["todos ellos tengan su domicilio en España, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","la mayoría tenga su domicilio en España.","al menos uno de ellos tenga su domicilio en España, siempre que se ejercite una sola acción o varias entre las que exista un nexo.","el demandante sea español."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al menos uno de ellos tenga su domicilio en España, siempre que se ejercite una sola acción o varias entre las que exista un nexo</mark></span>El <span class=\"ref-norma\">art. 22 ter.3 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"serán competentes los Tribunales españoles cuando al menos uno de ellos tenga su domicilio en España\"</span> Basta que uno tenga domicilio en España."},{"i":"8-ia-9115","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Medidas provisionales. Los Tribunales españoles serán competentes para adoptar medidas provisionales o de aseguramiento cuando se trate de personas o bienes que:","o":["sean de nacionalidad española.","hayan sido objeto de un procedimiento en España, conforme al procedimiento que reglamentariamente se establezca.","se hallen en territorio español y deban cumplirse en España.","pertenezcan a la Administración."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se hallen en territorio español y deban cumplirse en España</mark></span>El <span class=\"ref-norma\">art. 22 sexies de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"respecto de personas o bienes que se hallen en territorio español y deban cumplirse en España.\"</span> Personas o bienes en España y cumplimiento en España."},{"i":"8-ia-9116","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Materia concursal. En materia concursal y demás procedimientos de insolvencia, la competencia internacional se estará a lo que disponga:","o":["su legislación reguladora.","el Tribunal Supremo.","la Ley de Enjuiciamiento Civil.","el Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su legislación reguladora</mark></span>El <span class=\"ref-norma\">art. 22 septies de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se estará a lo que disponga su legislación reguladora.\"</span> Su legislación reguladora."},{"i":"8-ia-9117","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Litispendencia y conexidad. Las excepciones de litispendencia y de conexidad internacionales se alegarán y tramitarán con arreglo a:","o":["las normas de la Unión Europea exclusivamente, sin perjuicio de lo que establezcan los tratados internacionales.","las normas del Tribunal Supremo.","lo que decida el Juez en cada caso.","las normas generales que regulen las leyes procesales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las normas generales que regulen las leyes procesales</mark></span>El <span class=\"ref-norma\">art. 22 nonies de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se alegarán y tramitarán con arreglo a las normas generales que regulen las leyes procesales.\"</span> Normas generales de las leyes procesales."}]},{"a":"De las Secciones y plazas judiciales","q":[{"i":"8-ia-9118","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Designación de Secciones. Cuando las Salas de los Tribunales se dividan en Secciones y hubiere dos o más, estas se designarán por:","o":["numeración cardinal.","numeración ordinal.","el nombre de su Presidente.","letras del alfabeto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">numeración ordinal</mark></span>El <span class=\"ref-norma\">art. 27.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se designarán por numeración ordinal.\"</span> Numeración ordinal."},{"i":"8-ia-9119","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Plazas judiciales. Las plazas judiciales que integran los Tribunales de Instancia y el Tribunal Central de Instancia se designarán por:","o":["numeración ordinal dentro de cada partido, en los términos que determine la ley orgánica correspondiente.","el nombre del Juez titular.","numeración cardinal dentro de la misma Sección.","letras dentro de cada Sección."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">numeración cardinal dentro de la misma Sección</mark></span>El <span class=\"ref-norma\">art. 27.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se designarán por numeración cardinal dentro de la misma Sección.\"</span> Numeración cardinal dentro de la Sección."}]},{"a":"De la demarcación judicial","q":[{"i":"8-ia-9120","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. El municipio. En la demarcación judicial, el municipio se corresponde:","o":["con la demarcación administrativa del mismo nombre.","con el partido judicial.","con la circunscripción de los Juzgados de Paz, salvo que el órgano competente acuerde otra cosa de forma motivada.","con la provincia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con la demarcación administrativa del mismo nombre</mark></span>El <span class=\"ref-norma\">art. 31 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"El municipio se corresponde con la demarcación administrativa del mismo nombre.\"</span> Demarcación administrativa del mismo nombre."},{"i":"8-ia-9121","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. La provincia. La provincia, como demarcación judicial, se ajustará:","o":["a los partidos judiciales que determine la Ley de planta, conforme al procedimiento que reglamentariamente se establezca.","a la decisión del Consejo General del Poder Judicial.","al número de habitantes.","a los límites territoriales de la demarcación administrativa del mismo nombre."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a los límites territoriales de la demarcación administrativa del mismo nombre</mark></span>El <span class=\"ref-norma\">art. 33 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"La provincia se ajustará a los límites territoriales de la demarcación administrativa del mismo nombre.\"</span> Límites de la provincia administrativa."}]},{"a":"De los medios materiales","q":[{"i":"8-ia-9123","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Medios para los juzgados. Corresponde proveer a los juzgados y tribunales de los medios precisos para el desarrollo de su función con independencia y eficacia:","o":["al Consejo General del Poder Judicial, en los términos que determine la ley orgánica correspondiente, salvo que el órgano competente acuerde otra cosa de forma motivada.","al Ministerio del Interior.","al Ministerio de Justicia o al órgano competente de la comunidad autónoma con competencias en materia de justicia.","a cada Presidente de Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Ministerio de Justicia o al órgano competente de la comunidad autónoma con competencias en materia de justicia</mark></span>El <span class=\"ref-norma\">art. 37.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Corresponde al Ministerio de Justicia o al órgano competente de la comunidad autónoma con competencias en materia de justicia proveer a los juzgados y tribunales\"</span> Ministerio de Justicia o la comunidad autónoma competente."}]},{"a":"De los órganos colegiados","q":[{"i":"8-ia-9125","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Renovación anual. Anualmente se renovarán los componentes de:","o":["el Pleno del Tribunal Supremo, conforme al procedimiento que reglamentariamente se establezca.","las Salas de Gobierno.","las Audiencias Provinciales.","los órganos colegiados decisorios previstos en los dos artículos anteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los órganos colegiados decisorios previstos en los dos artículos anteriores</mark></span>El <span class=\"ref-norma\">art. 40 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Anualmente se renovarán los componentes de los órganos colegiados decisorios previstos en los dos artículos anteriores.\"</span> Los órganos colegiados decisorios."}]},{"a":"De los conflictos de competencia","q":[{"i":"8-ia-9127","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Conflictos de competencia. Los conflictos de competencia, tanto positivos como negativos, podrán ser promovidos de oficio o a instancia de parte o del Ministerio Fiscal, mientras el proceso no haya concluido:","o":["por resolución firme del Juzgado.","por auto de la Audiencia.","por sentencia firme, salvo que el conflicto se refiera a la ejecución del fallo.","por sentencia dictada en primera instancia, sin perjuicio de lo que establezcan los tratados internacionales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por sentencia firme, salvo que el conflicto se refiera a la ejecución del fallo</mark></span>El <span class=\"ref-norma\">art. 43 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"mientras el proceso no haya concluido por sentencia firme, salvo que el conflicto se refiera a la ejecución del fallo.\"</span> Hasta sentencia firme, salvo que afecte a la ejecución."},{"i":"8-ia-9128","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Requerimiento de inhibición. Al requerimiento de inhibición se acompañará testimonio:","o":["del auto dictado por el Juez o Tribunal requirente, de los escritos de las partes y del Ministerio Fiscal.","de la sentencia dictada por el Juez requirente.","del informe del Ministerio Fiscal exclusivamente.","del acuerdo del Consejo General del Poder Judicial, en los términos que determine la ley orgánica correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del auto dictado por el Juez o Tribunal requirente, de los escritos de las partes y del Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 46.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Al requerimiento de inhibición se acompañará testimonio del auto dictado por el Juez o Tribunal requirente\"</span> Testimonio del auto del requirente y de los escritos."},{"i":"8-ia-9129","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Resolución del requerido. El requerido, con audiencia del Ministerio Fiscal y de las partes por plazo común de diez días, dictará:","o":["sentencia resolviendo sobre su competencia.","providencia sobre su competencia.","decreto resolviendo sobre su competencia.","auto resolviendo sobre su competencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">auto resolviendo sobre su competencia</mark></span>El <span class=\"ref-norma\">art. 46.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"por plazo común de diez días, dictará auto resolviendo sobre su competencia.\"</span> Auto, tras audiencia de diez días."},{"i":"8-ia-9130","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Suspensión del procedimiento. Desde que se dicte el auto declinando la competencia o acordando el requerimiento, y desde que se tenga conocimiento de este por el Juez o Tribunal requerido, se suspenderá:","o":["la ejecución de la sentencia.","el procedimiento en el asunto a que se refiere aquél.","el plazo para recurrir.","la actividad del Ministerio Fiscal, salvo que el órgano competente acuerde otra cosa de forma motivada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el procedimiento en el asunto a que se refiere aquél</mark></span>El <span class=\"ref-norma\">art. 48.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se suspenderá el procedimiento en el asunto a que se refiere aquél.\"</span> Se suspende el procedimiento."},{"i":"8-ia-9131","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Excepciones a la suspensión. La suspensión del procedimiento por el conflicto de competencia no alcanzará:","o":["a las pruebas periciales.","a las actuaciones de las partes, conforme al procedimiento que reglamentariamente se establezca, sin perjuicio de lo que establezcan los tratados internacionales.","a las actuaciones preventivas o preparatorias ni a las cautelares que tengan carácter urgente o necesario.","a las diligencias de ejecución."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a las actuaciones preventivas o preparatorias ni a las cautelares que tengan carácter urgente o necesario</mark></span>El <span class=\"ref-norma\">art. 48.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"la suspensión no alcanzará a las actuaciones preventivas o preparatorias ni a las cautelares\"</span> Las actuaciones preventivas, preparatorias y cautelares urgentes."},{"i":"8-ia-9132","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recursos. Las resoluciones recaídas en la tramitación de los conflictos de competencia:","o":["no serán susceptibles de recurso alguno, ordinario o extraordinario.","serán recurribles en reposición.","serán recurribles en casación.","serán recurribles ante el Consejo General del Poder Judicial, en los términos que determine la ley orgánica correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no serán susceptibles de recurso alguno, ordinario o extraordinario</mark></span>El <span class=\"ref-norma\">art. 49 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"no serán susceptibles de recurso alguno, ordinario o extraordinario.\"</span> Irrecurribles."}]},{"a":"De la Audiencia Nacional","q":[{"i":"8-ia-9135","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recusaciones. Cada una de las Salas de la Audiencia Nacional conocerá de las recusaciones que se interpusieren contra:","o":["los Jueces Centrales.","los Fiscales de la Audiencia.","los Magistrados que las compongan.","los Presidentes de Sala exclusivamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los Magistrados que las compongan</mark></span>El <span class=\"ref-norma\">art. 68.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"las recusaciones que se interpusieren contra los Magistrados que las compongan.\"</span> Los Magistrados que las componen."}]},{"a":"De los Tribunales Superiores de Justicia","q":[{"i":"8-ia-9138","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Cuestiones de competencia. La Sala de lo Social del Tribunal Superior de Justicia conocerá de las cuestiones de competencia que se susciten entre:","o":["los Juzgados de Paz de la comunidad autónoma, en los términos que determine la ley orgánica correspondiente.","las Secciones de lo Social de los Tribunales de Instancia de la comunidad autónoma.","las Audiencias Provinciales.","las Salas del propio Tribunal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las Secciones de lo Social de los Tribunales de Instancia de la comunidad autónoma</mark></span>El <span class=\"ref-norma\">art. 75.3.º de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"De las cuestiones de competencia que se susciten entre las Secciones de lo Social de los Tribunales de Instancia de la comunidad autónoma.\"</span> Entre Secciones de lo Social."},{"i":"8-ia-9139","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Recusaciones en las Salas. Cada una de las Salas del Tribunal Superior de Justicia conocerá de las recusaciones que se formulen contra sus Magistrados cuando la competencia no corresponda a:","o":["la Sala de Gobierno.","el Pleno del Tribunal Supremo, salvo que el órgano competente acuerde otra cosa de forma motivada.","la Sala a que se refiere el artículo siguiente.","el Presidente del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Sala a que se refiere el artículo siguiente</mark></span>El <span class=\"ref-norma\">art. 76 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"cuando la competencia no corresponda a la Sala a que se refiere el artículo siguiente.\"</span> Salvo la Sala del artículo 77."},{"i":"8-ia-9140","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Ley de planta. La Ley de planta podrá, en aquellos Tribunales Superiores de Justicia en que el número de asuntos lo justifique:","o":["reducir el de Magistrados.","suprimir alguna Sala.","aumentar el número de Salas.","trasladar la sede del Tribunal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">reducir el de Magistrados</mark></span>El <span class=\"ref-norma\">art. 79 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"podrá, en aquellos Tribunales Superiores de Justicia en que el número de asuntos lo justifique, reducir el de Magistrados\"</span> Reducir el número de Magistrados."}]},{"a":"De los Juzgados de Menores","q":[{"i":"8-ia-9141","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Sección de Menores. Con carácter general, en el Tribunal de Instancia con sede en la capital de cada provincia y con jurisdicción en toda ella existirá:","o":["una Sección de lo Mercantil.","una Sección de Vigilancia Penitenciaria.","una Sección de Violencia sobre la Mujer.","una Sección de Menores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una Sección de Menores</mark></span>El <span class=\"ref-norma\">art. 91.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"existirá una Sección de Menores.\"</span> Una Sección de Menores."},{"i":"8-ia-9142","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Funciones de las Secciones de Menores. Corresponde a las Secciones de Menores de los Tribunales de Instancia el ejercicio de las funciones que establezcan las leyes para con los menores que hubieren incurrido en conductas tipificadas por la ley como:","o":["infracción administrativa.","delito o delito leve.","falta de respeto a la autoridad.","delito grave únicamente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">delito o delito leve</mark></span>El <span class=\"ref-norma\">art. 91.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"conductas tipificadas por la ley como delito o delito leve\"</span> Delito o delito leve."}]},{"a":"De los Jueces de Paz","q":[{"i":"8-ia-9143","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Nombramiento de Jueces de Paz. Podrán ser nombrados Jueces de Paz, tanto titular como sustituto, quienes aun no siendo licenciados en Derecho reúnan los requisitos para el ingreso en la Carrera Judicial y no estén incursos en causas de incapacidad o de incompatibilidad, a excepción:","o":["del ejercicio de cargos públicos.","de la pertenencia a partidos políticos, conforme al procedimiento que reglamentariamente se establezca.","del ejercicio de actividades profesionales o mercantiles.","del desempeño de funciones docentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">del ejercicio de actividades profesionales o mercantiles</mark></span>El <span class=\"ref-norma\">art. 102 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"a excepción del ejercicio de actividades profesionales o mercantiles.\"</span> Actividades profesionales o mercantiles."}]},{"a":"Rehabilitación","q":[{"i":"8-ia-9145","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Destino del rehabilitado. El Juez o Magistrado que hubiere sido rehabilitado será destinado:","o":["a su plaza anterior en todo caso, en los términos que determine la ley orgánica correspondiente.","a la plaza que elija.","a la vacante de mayor antigüedad.","con arreglo a lo dispuesto en esta ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con arreglo a lo dispuesto en esta ley</mark></span>El <span class=\"ref-norma\">art. 382 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"será destinado con arreglo a lo dispuesto en esta ley.\"</span> Conforme a la ley."}]},{"a":"Asociaciones profesionales","q":[{"i":"8-ia-9149","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Afiliación. Ningún juez o magistrado podrá estar afiliado:","o":["a ninguna asociación profesional.","a una asociación de ámbito autonómico.","a asociaciones internacionales.","a más de una asociación profesional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a más de una asociación profesional</mark></span>El <span class=\"ref-norma\">art. 401 (regla 5.ª) de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"Ningún juez o magistrado podrá estar afiliado a más de una asociación profesional.\"</span> A más de una asociación."}]},{"a":"Retribuciones","q":[{"i":"8-ia-9150","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Independencia económica. El Estado garantiza la independencia económica de los Jueces y Magistrados mediante:","o":["una retribución fijada por el Consejo General del Poder Judicial, conforme al procedimiento que reglamentariamente se establezca.","una retribución adecuada a la dignidad de la función jurisdiccional.","un sistema de trienios exclusivamente.","una asignación equivalente a la de los altos cargos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">una retribución adecuada a la dignidad de la función jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 402.1 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"mediante una retribución adecuada a la dignidad de la función jurisdiccional.\"</span> Retribución adecuada a la dignidad de la función."},{"i":"8-ia-9151","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Seguridad Social. El Estado garantizará un régimen de Seguridad Social que proteja a los Jueces y Magistrados y a sus familiares:","o":["solo durante el servicio activo.","solo tras la jubilación.","durante el servicio activo y la jubilación.","solo en caso de enfermedad profesional, sin perjuicio de lo que establezcan los tratados internacionales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">durante el servicio activo y la jubilación</mark></span>El <span class=\"ref-norma\">art. 402.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"que proteja a los Jueces y Magistrados y a sus familiares durante el servicio activo y la jubilación.\"</span> Servicio activo y jubilación."},{"i":"8-ia-9152","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Presupuestos. Los Presupuestos Generales del Estado contendrán una consignación anual para la dotación de:","o":["los jueces y juezas de paz y otras atenciones de personal judicial.","los Letrados de la Administración de Justicia exclusivamente, en los términos que determine la ley orgánica correspondiente.","los Magistrados del Tribunal Supremo exclusivamente.","los miembros del Consejo General del Poder Judicial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los jueces y juezas de paz y otras atenciones de personal judicial</mark></span>El <span class=\"ref-norma\">art. 404 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"contendrán una consignación anual para la dotación de los jueces y juezas de paz\"</span> Jueces de paz y otras atenciones de personal judicial."},{"i":"8-ia-9153","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Magistrados del Tribunal Supremo. Las remuneraciones de los Magistrados del Tribunal Supremo se establecerán en cuantía similar a las de:","o":["los Fiscales de Sala.","los Ministros del Gobierno.","los miembros de las Cortes Generales, salvo que el órgano competente acuerde otra cosa de forma motivada.","los titulares de otros altos Órganos Constitucionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los titulares de otros altos Órganos Constitucionales</mark></span>El <span class=\"ref-norma\">art. 404 bis de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"se establecerán en cuantía similar a las de los titulares de otros altos Órganos Constitucionales\"</span> Como otros altos órganos constitucionales."}]},{"a":"Policía Judicial","q":[{"i":"8-ia-9158","p":"Ley Orgánica 6/1985, de 1 de julio, del Poder Judicial. Límite de funciones. En ningún caso podrán encomendarse a los miembros de las unidades de Policía Judicial:","o":["actuaciones de averiguación de delitos.","actuaciones que no sean las propias de la Policía Judicial o las derivadas de las mismas.","actuaciones de auxilio a la autoridad fiscal, conforme al procedimiento que reglamentariamente se establezca.","actuaciones de detención."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">actuaciones que no sean las propias de la Policía Judicial o las derivadas de las mismas</mark></span>El <span class=\"ref-norma\">art. 549.2 de la LOPJ</span> dispone: <span class=\"ref-concepto\">\"En ningún caso podrán encomendarse a los miembros de dichas unidades la práctica de actuaciones que no sean las propias de la Policía Judicial o las derivadas de las mismas.\"</span> Solo funciones propias de Policía Judicial."}]}];
